window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G09"] = {"bang":[{"i":0,"tieu_de_bang":"Trung Quốc – Quảng Châu","tieu_de":"Đất Trung Hoa trên hành trình của Người: lớp học bên sông Châu Giang, đường về Tổ quốc và mười ba tháng lao tù","sapo":"Người đến đất Trung Hoa nhiều lần, và mỗi lần mang một cái tên khác: Lý Thụy, Hồ Quang, rồi Hồ Chí Minh. Có lần Người đến trong vai một phiên dịch viên, có lần trong bộ quân phục Bát lộ quân, có lần bị trói tay giải qua mười tám nhà lao. Vậy mà lần nào, mọi toan tính của Người cũng hướng về cùng một phía: con đường trở về Tổ quốc.","bia":{"src":"textures/bai/G09_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một phiên dịch viên ở thành phố cách mạng","text":"Ngày 11/11/1924, một người đàn ông Á Đông ba mươi tư tuổi đặt chân tới Quảng Châu. Giấy tờ ghi tên Lý Thụy, công việc là phiên dịch trong phái bộ cố vấn của Mikhail Borodin, người được Liên Xô cử sang giúp chính phủ Tôn Trung Sơn. Rất ít người trong thành phố biết rằng người phiên dịch ít nói ấy chính là Nguyễn Ái Quốc, cái tên mà mật thám Pháp đã theo dõi ráo riết từ Paris tới Mátxcơva.\n\nQuảng Châu khi ấy là căn cứ của chính phủ cách mạng do Tôn Trung Sơn đứng đầu. Từ đầu năm 1924, Quốc dân Đảng và Đảng Cộng sản Trung Quốc bắt tay hợp tác, với sự giúp đỡ của các cố vấn Liên Xô. Phía đông thành phố, trên đảo Trường Châu, Trường Quân sự Hoàng Phố vừa khai giảng khóa đầu tiên. Nhiều nhà cách mạng châu Á và không ít thanh niên Việt Nam lưu vong cũng tìm về đây. Với Nguyễn Ái Quốc, đó là mảnh đất hiếm có để bắt tay vào điều Người ấp ủ từ lâu: gây dựng một tổ chức cách mạng thực sự của người Việt Nam, ngay sát cửa ngõ Tổ quốc.","doc":1},{"loai":"doan","tieu_de":"Vì sao là đất Trung Hoa","text":"Ở Mátxcơva, Nguyễn Ái Quốc nhiều lần đề nghị Quốc tế Cộng sản cho Người về phương Đông, càng gần Tổ quốc càng tốt. Trung Quốc đáp ứng đúng mong muốn đó. Hai nước có chung một đường biên giới dài, núi liền núi, sông liền sông. Tàu biển từ Hải Phòng tới Hồng Kông, Quảng Châu chỉ mất vài ngày; tuyến đường sắt Hải Phòng – Lào Cai nối thẳng lên Côn Minh. Người Việt ở đây dễ hòa vào cộng đồng người Hoa, dễ tìm việc làm, dễ ẩn mình trước con mắt của mật thám.\n\nTrung Quốc cũng là nơi các nhà yêu nước Việt Nam đã tìm đến từ trước. Năm 1912, Phan Bội Châu lập Việt Nam Quang phục Hội ngay trên đất Quảng Đông. Đầu những năm 1920, ở Quảng Châu vẫn có những nhóm thanh niên Việt Nam sống lưu vong, chờ thời cơ hành động. Điều họ thiếu không phải lòng yêu nước, mà là một con đường đúng. Riêng Nguyễn Ái Quốc còn có một lợi thế ít người có: Người đọc thông chữ Hán từ thuở nhỏ, khi học bên người cha là cụ Phó bảng Nguyễn Sinh Sắc, nên có thể sống, làm việc và viết lách giữa lòng xã hội Trung Hoa.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trung Quốc – Quảng Châu”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chặng thứ nhất: gieo hạt trên phố Văn Minh (1924 – 1927)","text":"Không lâu sau khi tới Quảng Châu, Người tìm gặp nhóm thanh niên Tâm tâm xã, những đồng chí của liệt sĩ Phạm Hồng Thái, người đã ném bom mưu sát Toàn quyền Đông Dương Merlin trên đảo Sa Diện mấy tháng trước (xem chuyên đề Từ tiếng bom Sa Diện đến Hội Thanh niên). Tháng 2/1925, từ những người tích cực nhất, Người lập nhóm Cộng sản đoàn làm hạt nhân bí mật. Tháng 6/1925, Hội Việt Nam Cách mạng Thanh niên ra đời; ngày 21/6/1925, báo Thanh Niên ra số đầu tiên.\n\nTừ năm 1925 đến năm 1927, trong ngôi nhà trên đường Văn Minh, Người mở các lớp huấn luyện chính trị cho khoảng 75 thanh niên từ trong nước bí mật sang học (xem chuyên đề Nhà số 248 – 250 đường Văn Minh). Một số học viên được giới thiệu vào Trường Quân sự Hoàng Phố, một số được gửi sang Liên Xô học tiếp. Năm 1927, các bài giảng được in thành cuốn Đường Kách mệnh. Chưa đầy ba năm, nhưng đó là ba năm đặt nền móng cho cả một thế hệ cách mạng.","doc":3},{"loai":"trich","text":"Cách mệnh trước hết phải có cái gì? Trước hết phải có đảng cách mệnh, để trong thì vận động và tổ chức dân chúng, ngoài thì liên lạc với dân tộc bị áp bức và vô sản giai cấp mọi nơi. Đảng có vững cách mệnh mới thành công, cũng như người cầm lái có vững thuyền mới chạy.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Đường Kách mệnh (1927), in trong Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia","doc":4},{"loai":"doan","tieu_de":"Những con người bước ra từ lớp học","text":"Giá trị của chặng Quảng Châu được đo bằng con người. Trần Phú sang Quảng Châu dự lớp huấn luyện năm 1926, về sau là Tổng Bí thư đầu tiên của Đảng. Phạm Văn Đồng cũng dự lớp năm 1926, sau này đứng đầu Chính phủ hơn ba mươi năm. Lê Hồng Phong học Trường Quân sự Hoàng Phố rồi sang Liên Xô, trở thành một trong những lãnh đạo chủ chốt của Đảng những năm 1930. Hồ Tùng Mậu và Lê Hồng Sơn cùng Người đứng trong Tổng bộ của Hội.\n\nNhững học viên trở về đã gây dựng cơ sở của Hội ở cả Bắc Kỳ, Trung Kỳ, Nam Kỳ và trong cộng đồng người Việt ở Xiêm. Năm 1928, Hội phát động phong trào “vô sản hóa”, đưa hội viên vào hầm mỏ, nhà máy, đồn điền để cùng sống, cùng làm với công nhân. Đến năm 1929, Hội có khoảng 1.700 hội viên. Từ trong lòng Hội, những tổ chức cộng sản đầu tiên ra đời năm 1929, để rồi được hợp nhất tại hội nghị họp từ ngày 6/1 đến 7/2/1930 ở Cửu Long (Hương Cảng).","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","chu_thich":"Cổng Trường Quân sự Hoàng Phố trên đảo Trường Châu, Quảng Châu (ảnh chụp năm 2009). Nhiều học viên các lớp huấn luyện của Nguyễn Ái Quốc đã được giới thiệu vào học ở ngôi trường này.","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Tháng Tư năm 1927 và hơn mười một năm xa cách","text":"Mặt trận hợp tác Quốc – Cộng không bền lâu. Ngày 12/4/1927, Tưởng Giới Thạch làm chính biến ở Thượng Hải, quay sang đàn áp những người cộng sản; chỉ ít ngày sau, cuộc khủng bố lan tới Quảng Châu. Các cơ sở cách mạng bị lùng sục, những người cách mạng nước ngoài trở thành đối tượng bị truy bắt. Đầu tháng 5/1927, Nguyễn Ái Quốc bí mật rời Quảng Châu sang Hồng Kông, rồi tìm đường trở lại Mátxcơva.\n\nHơn mười một năm sau đó là một chuỗi hành trình dài: sang châu Âu, về Xiêm sống giữa bà con Việt kiều trong hai năm 1928 – 1929, chủ trì hội nghị hợp nhất đầu năm 1930, bị cảnh sát Anh bắt ở Hồng Kông năm 1931, rồi trở lại Liên Xô học tập và làm việc từ năm 1934 (xem các gian Thái Lan, Hồng Kông và Liên Xô). Trong những năm ấy, những học trò ở Quảng Châu năm nào đã trở thành lực lượng nòng cốt của phong trào trong nước. Hạt giống gieo trên phố Văn Minh đã tự bén rễ trên đất nhà.","doc":6},{"loai":"ban_co_biet","text":"Trên đất Trung Hoa, Người nhiều lần đổi tên: Lý Thụy ở Quảng Châu những năm 1924 – 1927, Hồ Quang khi khoác quân phục Bát lộ quân những năm 1938 – 1940. Từ tháng 8/1942, Người mang tên Hồ Chí Minh; đó cũng là cái tên ghi trên giấy tờ khi Người bị bắt ở Quảng Tây, rồi gắn với Người suốt cuộc đời.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":7},{"loai":"doan","tieu_de":"Chặng thứ hai: người sĩ quan Bát lộ quân tên Hồ Quang (1938 – 1940)","text":"Mùa thu năm 1938, Người rời Mátxcơva trở lại Trung Quốc. Lúc ấy cuộc kháng chiến chống Nhật của nhân dân Trung Quốc đã lan rộng, Quốc dân Đảng và Đảng Cộng sản Trung Quốc lại hợp tác lần thứ hai. Người tới Diên An, căn cứ của Đảng Cộng sản Trung Quốc, rồi xuống Quế Lâm (Quảng Tây), làm việc ở Văn phòng Bát lộ quân trong vai một sĩ quan tên Hồ Quang. Năm 1939, Người công tác tại lớp huấn luyện du kích ở Hồ Nam do tướng Diệp Kiếm Anh phụ trách.\n\nĐầu năm 1940, Người tới Côn Minh, nơi cuối tuyến đường sắt từ Hải Phòng lên Vân Nam, bắt liên lạc với Ban Hải ngoại của Đảng và qua đó nối lại mạch liên hệ với trong nước (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Người nhận định thời cơ đã đến, gấp rút chuẩn bị về nước. Cuối năm ấy, Người xuống vùng biên giới Quảng Tây giáp Cao Bằng, mở lớp huấn luyện cho cán bộ từ trong nước sang. Ngày 28/1/1941, Người vượt qua cột mốc 108, về tới Pác Bó.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_former_residence_of_ho_chi_minh_kunmi.jpg","chu_thich":"Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam (ảnh chụp năm 2025). Đầu năm 1940, từ thành phố này, Người nối lại liên lạc với phong trào cách mạng trong nước.","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Chặng thứ ba: mười ba tháng không bản án (1942 – 1943)","text":"Tháng 8/1942, lần đầu tiên mang tên Hồ Chí Minh, Người rời Pác Bó sang Trung Quốc. Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt; Người muốn tới Trùng Khánh, thủ đô thời chiến của Trung Hoa Dân quốc, để tranh thủ sự ủng hộ của phe Đồng minh cho cách mạng Việt Nam. Ngày 29/8/1942, khi tới phố Túc Vinh (Quảng Tây), Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ vì bị nghi là gián điệp.\n\nKhông có phiên tòa, cũng không có bản án. Theo Giáo sư Song Thành, nguyên Viện trưởng Viện Hồ Chí Minh, người tù bị giải qua mười ba huyện, mười tám nhà lao của tỉnh Quảng Tây, từ Tĩnh Tây, Thiên Bảo, Long An tới Nam Ninh, Liễu Châu, Quế Lâm. Ngày 10/9/1943, Người được trả tự do nhưng còn ở lại Liễu Châu gần một năm, đến tháng 9/1944 mới về tới Pác Bó. Trong những tháng ngày tù đày ấy, hơn một trăm bài thơ chữ Hán đã ra đời, về sau được biết đến với tên Nhật ký trong tù (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây).","doc":9},{"loai":"anh","src":"textures/bang_w/G09_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trung Quốc – Quảng Châu”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Sợi chỉ đỏ nối ba chặng đường","text":"Đặt ba chặng cạnh nhau, ta thấy một điều nhất quán. Ở Quảng Châu, Người đào tạo cán bộ để gửi về nước. Ở Quế Lâm, Côn Minh, Người kiên trì tìm đường liên lạc, tiến dần về biên giới để tự mình trở về. Chuyến đi năm 1942 cũng nhằm tìm sự giúp đỡ quốc tế cho cuộc đấu tranh trong nước. Trung Quốc chưa bao giờ là đích đến của Người; đó là bàn đạp, là trạm tiếp sức trên con đường về Tổ quốc.\n\nĐất Trung Hoa cũng cho Người nhiều bài học. Người thấy sức mạnh của một mặt trận đoàn kết rộng rãi, và cả cái giá phải trả khi mặt trận ấy đổ vỡ năm 1927. Người sống giữa cuộc kháng chiến chống Nhật, trực tiếp tìm hiểu cách huấn luyện du kích. Người nếm trải nhà tù của một chính quyền vừa đứng trong phe chống phát xít, vừa nghi kỵ người cách mạng. Những trải nghiệm ấy về sau hiện diện trong cách Người xây dựng Mặt trận Việt Minh, tổ chức lực lượng vũ trang và ứng xử mềm dẻo với các thế lực nước ngoài trong những năm 1945 – 1946.","doc":10},{"loai":"ban_co_biet","text":"Cuốn Đường Kách mệnh không in dưới tên một nhà xuất bản Việt Nam. Sách do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ấn hành ở Quảng Châu năm 1927; đó là tổ chức mà Nguyễn Ái Quốc cùng các nhà cách mạng châu Á lập ra tháng 7/1925.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":11},{"loai":"anh","src":"textures/bang_w/G09_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trung Quốc – Quảng Châu”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Đi trong gian trưng bày","text":"Gian trưng bày được sắp theo ba chặng ấy. Hai bài câu chuyện đưa khách đi từ tiếng bom Sa Diện tới sự ra đời của Hội Việt Nam Cách mạng Thanh niên, rồi theo người tù Hồ Chí Minh qua các nhà lao Quảng Tây. Bảng mốc thời gian xếp gần hai mươi năm hoạt động trên đất Trung Hoa thành một dòng liền mạch. Những bức ảnh tư liệu cho thấy gương mặt Nguyễn Ái Quốc năm 1924, cánh cổng Trường Quân sự Hoàng Phố, nhà lưu niệm ở Côn Minh và những trang bản thảo Nhật ký trong tù.\n\nMột bảng khác dành cho câu nói “Không có gì quý hơn độc lập, tự do” trong Lời kêu gọi ngày 17/7/1966 (xem chuyên đề Không có gì quý hơn độc lập, tự do). Các hiện vật dựng trong gian, từ dãy nhà kỵ lâu, ngôi nhà trên đường Văn Minh đến Trường Quân sự Hoàng Phố, đều có câu chuyện riêng. Khách có thể bắt đầu từ bất cứ bảng nào. Nhưng nếu đi theo thứ tự thời gian, ta sẽ thấy rõ hơn sự kiên nhẫn phi thường của một người suốt ba mươi năm bôn ba vẫn không lúc nào thôi tìm đường trở về quê hương.","doc":12},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Nhiều địa điểm gắn với Người trên đất Trung Quốc vẫn được gìn giữ. Ở Quảng Châu, ngôi nhà số 248 – 250 đường Văn Minh, nơi Hội Việt Nam Cách mạng Thanh niên làm việc và mở lớp, được bảo tồn làm di tích, thường đón các đoàn khách Việt Nam. Trên đảo Trường Châu, khu di tích Trường Quân sự Hoàng Phố đã được phục dựng thành nhà kỷ niệm. Trong nghĩa trang Hoàng Hoa Cương, mộ liệt sĩ Phạm Hồng Thái vẫn nằm giữa những người con ưu tú của cách mạng Trung Quốc. Ở Côn Minh, ngôi nhà gắn với thời gian Người hoạt động năm 1940 nay là nhà lưu niệm.\n\nCòn cuốn sổ nhỏ ghi Nhật ký trong tù đã trở về Việt Nam, được công nhận là Bảo vật quốc gia năm 2012 và đang được lưu giữ tại Bảo tàng Lịch sử quốc gia ở Hà Nội. Trong không gian 3D của gian này, khách tham quan đi giữa dãy nhà kỵ lâu của phố thị Quảng Châu những năm 1920, bước vào lớp học với ghế băng, bàn giảng và tấm bảng đen, rồi dừng trước những trang bản thảo viết trong ngục. Ba chặng đường, gần hai mươi năm, được thu lại trong một gian trưng bày.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 2 (Đường Kách mệnh), NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","GS. Song Thành, “Số phận kỳ lạ của bản thảo tập thơ Ngục trung nhật ký”, NXB Chính trị quốc gia Sự thật: https://www.nxbctqg.org.vn/s-phn-k-l-ca-bn-tho-tp-th-qngc-trung-nht-kyq.html","Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)"],"doc":[{"t":"Đất Trung Hoa trên hành trình của Người: lớp học bên sông Châu Giang, đường về Tổ quốc và mười ba tháng lao tù. Người đến đất Trung Hoa nhiều lần, và mỗi lần mang một cái tên khác: Lý Thụy, Hồ Quang, rồi Hồ Chí Minh. Có lần Người đến trong vai một phiên dịch viên, có lần trong bộ quân phục Bát lộ quân, có lần bị trói tay giải qua mười tám nhà lao. Vậy mà lần nào, mọi toan tính của Người cũng hướng về cùng một phía: con đường trở về Tổ quốc."},{"t":"Một phiên dịch viên ở thành phố cách mạng. Ngày 11/11/1924, một người đàn ông Á Đông ba mươi tư tuổi đặt chân tới Quảng Châu. Giấy tờ ghi tên Lý Thụy, công việc là phiên dịch trong phái bộ cố vấn của Mikhail Borodin, người được Liên Xô cử sang giúp chính phủ Tôn Trung Sơn. Rất ít người trong thành phố biết rằng người phiên dịch ít nói ấy chính là Nguyễn Ái Quốc, cái tên mà mật thám Pháp đã theo dõi ráo riết từ Paris tới Mátxcơva. Quảng Châu khi ấy là căn cứ của chính phủ cách mạng do Tôn Trung Sơn đứng đầu. Từ đầu năm 1924, Quốc dân Đảng và Đảng Cộng sản Trung Quốc bắt tay hợp tác, với sự giúp đỡ của các cố vấn Liên Xô. Phía đông thành phố, trên đảo Trường Châu, Trường Quân sự Hoàng Phố vừa khai giảng khóa đầu tiên. Nhiều nhà cách mạng châu Á và không ít thanh niên Việt Nam lưu vong cũng tìm về đây. Với Nguyễn Ái Quốc, đó là mảnh đất hiếm có để bắt tay vào điều Người ấp ủ từ lâu: gây dựng một tổ chức cách mạng thực sự của người Việt Nam, ngay sát cửa ngõ Tổ quốc."},{"t":"Vì sao là đất Trung Hoa. Ở Mátxcơva, Nguyễn Ái Quốc nhiều lần đề nghị Quốc tế Cộng sản cho Người về phương Đông, càng gần Tổ quốc càng tốt. Trung Quốc đáp ứng đúng mong muốn đó. Hai nước có chung một đường biên giới dài, núi liền núi, sông liền sông. Tàu biển từ Hải Phòng tới Hồng Kông, Quảng Châu chỉ mất vài ngày; tuyến đường sắt Hải Phòng – Lào Cai nối thẳng lên Côn Minh. Người Việt ở đây dễ hòa vào cộng đồng người Hoa, dễ tìm việc làm, dễ ẩn mình trước con mắt của mật thám. Trung Quốc cũng là nơi các nhà yêu nước Việt Nam đã tìm đến từ trước. Năm 1912, Phan Bội Châu lập Việt Nam Quang phục Hội ngay trên đất Quảng Đông. Đầu những năm 1920, ở Quảng Châu vẫn có những nhóm thanh niên Việt Nam sống lưu vong, chờ thời cơ hành động. Điều họ thiếu không phải lòng yêu nước, mà là một con đường đúng. Riêng Nguyễn Ái Quốc còn có một lợi thế ít người có: Người đọc thông chữ Hán từ thuở nhỏ, khi học bên người cha là cụ Phó bảng Nguyễn Sinh Sắc, nên có thể sống, làm việc và viết lách giữa lòng xã hội Trung Hoa."},{"t":"Chặng thứ nhất: gieo hạt trên phố Văn Minh (1924 – 1927). Không lâu sau khi tới Quảng Châu, Người tìm gặp nhóm thanh niên Tâm tâm xã, những đồng chí của liệt sĩ Phạm Hồng Thái, người đã ném bom mưu sát Toàn quyền Đông Dương Merlin trên đảo Sa Diện mấy tháng trước (xem chuyên đề Từ tiếng bom Sa Diện đến Hội Thanh niên). Tháng 2/1925, từ những người tích cực nhất, Người lập nhóm Cộng sản đoàn làm hạt nhân bí mật. Tháng 6/1925, Hội Việt Nam Cách mạng Thanh niên ra đời; ngày 21/6/1925, báo Thanh Niên ra số đầu tiên. Từ năm 1925 đến năm 1927, trong ngôi nhà trên đường Văn Minh, Người mở các lớp huấn luyện chính trị cho khoảng 75 thanh niên từ trong nước bí mật sang học (xem chuyên đề Nhà số 248 – 250 đường Văn Minh). Một số học viên được giới thiệu vào Trường Quân sự Hoàng Phố, một số được gửi sang Liên Xô học tiếp. Năm 1927, các bài giảng được in thành cuốn Đường Kách mệnh. Chưa đầy ba năm, nhưng đó là ba năm đặt nền móng cho cả một thế hệ cách mạng."},{"t":"Cách mệnh trước hết phải có cái gì? Trước hết phải có đảng cách mệnh, để trong thì vận động và tổ chức dân chúng, ngoài thì liên lạc với dân tộc bị áp bức và vô sản giai cấp mọi nơi. Đảng có vững cách mệnh mới thành công, cũng như người cầm lái có vững thuyền mới chạy. — Nguyễn Ái Quốc"},{"t":"Những con người bước ra từ lớp học. Giá trị của chặng Quảng Châu được đo bằng con người. Trần Phú sang Quảng Châu dự lớp huấn luyện năm 1926, về sau là Tổng Bí thư đầu tiên của Đảng. Phạm Văn Đồng cũng dự lớp năm 1926, sau này đứng đầu Chính phủ hơn ba mươi năm. Lê Hồng Phong học Trường Quân sự Hoàng Phố rồi sang Liên Xô, trở thành một trong những lãnh đạo chủ chốt của Đảng những năm 1930. Hồ Tùng Mậu và Lê Hồng Sơn cùng Người đứng trong Tổng bộ của Hội. Những học viên trở về đã gây dựng cơ sở của Hội ở cả Bắc Kỳ, Trung Kỳ, Nam Kỳ và trong cộng đồng người Việt ở Xiêm. Năm 1928, Hội phát động phong trào “vô sản hóa”, đưa hội viên vào hầm mỏ, nhà máy, đồn điền để cùng sống, cùng làm với công nhân. Đến năm 1929, Hội có khoảng 1.700 hội viên. Từ trong lòng Hội, những tổ chức cộng sản đầu tiên ra đời năm 1929, để rồi được hợp nhất tại hội nghị họp từ ngày 6/1 đến 7/2/1930 ở Cửu Long (Hương Cảng)."},{"t":"Tháng Tư năm 1927 và hơn mười một năm xa cách. Mặt trận hợp tác Quốc – Cộng không bền lâu. Ngày 12/4/1927, Tưởng Giới Thạch làm chính biến ở Thượng Hải, quay sang đàn áp những người cộng sản; chỉ ít ngày sau, cuộc khủng bố lan tới Quảng Châu. Các cơ sở cách mạng bị lùng sục, những người cách mạng nước ngoài trở thành đối tượng bị truy bắt. Đầu tháng 5/1927, Nguyễn Ái Quốc bí mật rời Quảng Châu sang Hồng Kông, rồi tìm đường trở lại Mátxcơva. Hơn mười một năm sau đó là một chuỗi hành trình dài: sang châu Âu, về Xiêm sống giữa bà con Việt kiều trong hai năm 1928 – 1929, chủ trì hội nghị hợp nhất đầu năm 1930, bị cảnh sát Anh bắt ở Hồng Kông năm 1931, rồi trở lại Liên Xô học tập và làm việc từ năm 1934 (xem các gian Thái Lan, Hồng Kông và Liên Xô). Trong những năm ấy, những học trò ở Quảng Châu năm nào đã trở thành lực lượng nòng cốt của phong trào trong nước. Hạt giống gieo trên phố Văn Minh đã tự bén rễ trên đất nhà."},{"t":"Bạn có biết? Trên đất Trung Hoa, Người nhiều lần đổi tên: Lý Thụy ở Quảng Châu những năm 1924 – 1927, Hồ Quang khi khoác quân phục Bát lộ quân những năm 1938 – 1940. Từ tháng 8/1942, Người mang tên Hồ Chí Minh; đó cũng là cái tên ghi trên giấy tờ khi Người bị bắt ở Quảng Tây, rồi gắn với Người suốt cuộc đời."},{"t":"Chặng thứ hai: người sĩ quan Bát lộ quân tên Hồ Quang (1938 – 1940). Mùa thu năm 1938, Người rời Mátxcơva trở lại Trung Quốc. Lúc ấy cuộc kháng chiến chống Nhật của nhân dân Trung Quốc đã lan rộng, Quốc dân Đảng và Đảng Cộng sản Trung Quốc lại hợp tác lần thứ hai. Người tới Diên An, căn cứ của Đảng Cộng sản Trung Quốc, rồi xuống Quế Lâm (Quảng Tây), làm việc ở Văn phòng Bát lộ quân trong vai một sĩ quan tên Hồ Quang. Năm 1939, Người công tác tại lớp huấn luyện du kích ở Hồ Nam do tướng Diệp Kiếm Anh phụ trách. Đầu năm 1940, Người tới Côn Minh, nơi cuối tuyến đường sắt từ Hải Phòng lên Vân Nam, bắt liên lạc với Ban Hải ngoại của Đảng và qua đó nối lại mạch liên hệ với trong nước (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Người nhận định thời cơ đã đến, gấp rút chuẩn bị về nước. Cuối năm ấy, Người xuống vùng biên giới Quảng Tây giáp Cao Bằng, mở lớp huấn luyện cho cán bộ từ trong nước sang. Ngày 28/1/1941, Người vượt qua cột mốc 108, về tới Pác Bó."},{"t":"Chặng thứ ba: mười ba tháng không bản án (1942 – 1943). Tháng 8/1942, lần đầu tiên mang tên Hồ Chí Minh, Người rời Pác Bó sang Trung Quốc. Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt; Người muốn tới Trùng Khánh, thủ đô thời chiến của Trung Hoa Dân quốc, để tranh thủ sự ủng hộ của phe Đồng minh cho cách mạng Việt Nam. Ngày 29/8/1942, khi tới phố Túc Vinh (Quảng Tây), Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ vì bị nghi là gián điệp. Không có phiên tòa, cũng không có bản án. Theo Giáo sư Song Thành, nguyên Viện trưởng Viện Hồ Chí Minh, người tù bị giải qua mười ba huyện, mười tám nhà lao của tỉnh Quảng Tây, từ Tĩnh Tây, Thiên Bảo, Long An tới Nam Ninh, Liễu Châu, Quế Lâm. Ngày 10/9/1943, Người được trả tự do nhưng còn ở lại Liễu Châu gần một năm, đến tháng 9/1944 mới về tới Pác Bó. Trong những tháng ngày tù đày ấy, hơn một trăm bài thơ chữ Hán đã ra đời, về sau được biết đến với tên Nhật ký trong tù (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây)."},{"t":"Sợi chỉ đỏ nối ba chặng đường. Đặt ba chặng cạnh nhau, ta thấy một điều nhất quán. Ở Quảng Châu, Người đào tạo cán bộ để gửi về nước. Ở Quế Lâm, Côn Minh, Người kiên trì tìm đường liên lạc, tiến dần về biên giới để tự mình trở về. Chuyến đi năm 1942 cũng nhằm tìm sự giúp đỡ quốc tế cho cuộc đấu tranh trong nước. Trung Quốc chưa bao giờ là đích đến của Người; đó là bàn đạp, là trạm tiếp sức trên con đường về Tổ quốc. Đất Trung Hoa cũng cho Người nhiều bài học. Người thấy sức mạnh của một mặt trận đoàn kết rộng rãi, và cả cái giá phải trả khi mặt trận ấy đổ vỡ năm 1927. Người sống giữa cuộc kháng chiến chống Nhật, trực tiếp tìm hiểu cách huấn luyện du kích. Người nếm trải nhà tù của một chính quyền vừa đứng trong phe chống phát xít, vừa nghi kỵ người cách mạng. Những trải nghiệm ấy về sau hiện diện trong cách Người xây dựng Mặt trận Việt Minh, tổ chức lực lượng vũ trang và ứng xử mềm dẻo với các thế lực nước ngoài trong những năm 1945 – 1946."},{"t":"Bạn có biết? Cuốn Đường Kách mệnh không in dưới tên một nhà xuất bản Việt Nam. Sách do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ấn hành ở Quảng Châu năm 1927; đó là tổ chức mà Nguyễn Ái Quốc cùng các nhà cách mạng châu Á lập ra tháng 7/1925."},{"t":"Đi trong gian trưng bày. Gian trưng bày được sắp theo ba chặng ấy. Hai bài câu chuyện đưa khách đi từ tiếng bom Sa Diện tới sự ra đời của Hội Việt Nam Cách mạng Thanh niên, rồi theo người tù Hồ Chí Minh qua các nhà lao Quảng Tây. Bảng mốc thời gian xếp gần hai mươi năm hoạt động trên đất Trung Hoa thành một dòng liền mạch. Những bức ảnh tư liệu cho thấy gương mặt Nguyễn Ái Quốc năm 1924, cánh cổng Trường Quân sự Hoàng Phố, nhà lưu niệm ở Côn Minh và những trang bản thảo Nhật ký trong tù. Một bảng khác dành cho câu nói “Không có gì quý hơn độc lập, tự do” trong Lời kêu gọi ngày 17/7/1966 (xem chuyên đề Không có gì quý hơn độc lập, tự do). Các hiện vật dựng trong gian, từ dãy nhà kỵ lâu, ngôi nhà trên đường Văn Minh đến Trường Quân sự Hoàng Phố, đều có câu chuyện riêng. Khách có thể bắt đầu từ bất cứ bảng nào. Nhưng nếu đi theo thứ tự thời gian, ta sẽ thấy rõ hơn sự kiên nhẫn phi thường của một người suốt ba mươi năm bôn ba vẫn không lúc nào thôi tìm đường trở về quê hương."},{"t":"Dấu tích hôm nay. Nhiều địa điểm gắn với Người trên đất Trung Quốc vẫn được gìn giữ. Ở Quảng Châu, ngôi nhà số 248 – 250 đường Văn Minh, nơi Hội Việt Nam Cách mạng Thanh niên làm việc và mở lớp, được bảo tồn làm di tích, thường đón các đoàn khách Việt Nam. Trên đảo Trường Châu, khu di tích Trường Quân sự Hoàng Phố đã được phục dựng thành nhà kỷ niệm. Trong nghĩa trang Hoàng Hoa Cương, mộ liệt sĩ Phạm Hồng Thái vẫn nằm giữa những người con ưu tú của cách mạng Trung Quốc. Ở Côn Minh, ngôi nhà gắn với thời gian Người hoạt động năm 1940 nay là nhà lưu niệm. Còn cuốn sổ nhỏ ghi Nhật ký trong tù đã trở về Việt Nam, được công nhận là Bảo vật quốc gia năm 2012 và đang được lưu giữ tại Bảo tàng Lịch sử quốc gia ở Hà Nội. Trong không gian 3D của gian này, khách tham quan đi giữa dãy nhà kỵ lâu của phố thị Quảng Châu những năm 1920, bước vào lớp học với ghế băng, bàn giảng và tấm bảng đen, rồi dừng trước những trang bản thảo viết trong ngục. Ba chặng đường, gần hai mươi năm, được thu lại trong một gian trưng bày."}],"so_chu":2280},{"i":1,"tieu_de_bang":"Từ tiếng bom Sa Diện đến Hội Thanh niên","tieu_de":"Tiếng bom Sa Diện và một con đường khác: từ Tâm tâm xã đến Hội Việt Nam Cách mạng Thanh niên","sapo":"Tối 19/6/1924, một tiếng nổ vang lên giữa bữa tiệc giới chức Pháp chiêu đãi Toàn quyền Đông Dương trên đảo Sa Diện, Quảng Châu. Người ném bom là một thanh niên xứ Nghệ, và chỉ ít lâu sau anh đã nằm lại dưới dòng Châu Giang. Năm tháng sau, một người phiên dịch tên Lý Thụy tới thành phố này, tìm gặp những đồng chí của anh và chỉ cho họ một con đường khác. Con đường ấy dẫn tới sự ra đời của Hội Việt Nam Cách mạng Thanh niên.","bia":{"src":"textures/bai/G09_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Buổi tiệc trên đảo Sa Diện","text":"Sa Diện là một dải đất nhỏ nằm giữa sông Châu Giang, sát trung tâm Quảng Châu. Từ những năm 1860, hòn đảo trở thành tô giới của người Anh và người Pháp, với những con đường rợp bóng cây, dinh thự kiểu châu Âu, ngân hàng và lãnh sự quán. Người Trung Quốc muốn qua cầu vào đảo phải chịu sự kiểm soát của cảnh sát tô giới. Đó là một góc châu Âu thu nhỏ, yên bình và kiêu hãnh, giữa lòng một thành phố Trung Hoa đang sục sôi cách mạng.\n\nTháng 6/1924, Toàn quyền Đông Dương Martial Merlin có chuyến dừng chân ở Quảng Châu. Tối 19/6/1924, cộng đồng người Pháp ở Sa Diện mở tiệc chiêu đãi ông tại khách sạn Victoria trên đảo. Giữa bữa tiệc, một quả bom được ném vào phòng ăn. Tiếng nổ làm một số người dự tiệc thiệt mạng và bị thương, nhưng Merlin thoát chết. Người ném bom là Phạm Hồng Thái, một thanh niên Việt Nam quê Nghệ An. Bị truy đuổi gắt gao, anh chạy ra bờ sông, lao mình xuống dòng Châu Giang và hy sinh.","doc":1},{"loai":"doan","tieu_de":"Người thanh niên xứ Nghệ","text":"Phạm Hồng Thái tên thật là Phạm Thành Tích, quê huyện Hưng Nguyên, tỉnh Nghệ An, vùng đất đã sinh ra nhiều thế hệ những người yêu nước. Cũng như bao thanh niên cùng thời, anh lớn lên trong cảnh nước mất nhà tan, chứng kiến các phong trào Đông Du, Duy Tân lần lượt bị dập tắt. Anh rời quê hương sang Trung Quốc, tìm tới nhóm thanh niên Việt Nam yêu nước đang hoạt động ở Quảng Châu, và tự nguyện nhận phần việc hiểm nguy nhất.\n\nSự hy sinh của anh gây xúc động lớn trong dư luận Quảng Châu. Chính quyền Quảng Châu cho an táng anh tại nghĩa trang Hoàng Hoa Cương, nơi yên nghỉ của bảy mươi hai liệt sĩ đã ngã xuống trong cuộc khởi nghĩa Quảng Châu năm 1911 chống triều Mãn Thanh. Một người Việt Nam được nằm lại giữa những liệt sĩ cách mạng Trung Hoa, đó là sự tôn vinh hiếm có. Tin về người thanh niên hy sinh trên dòng Châu Giang cũng vượt biên giới về trong nước, khích lệ lòng yêu nước của lớp người trẻ.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ tiếng bom Sa Diện đến Hội Thanh niên”, nhìn từ xa."},{"loai":"doan","tieu_de":"Tâm tâm xã, những con người quả cảm","text":"Phạm Hồng Thái là thành viên của Tâm tâm xã, một tổ chức của thanh niên Việt Nam yêu nước lập ở Quảng Châu năm 1923, trong đó có Lê Hồng Sơn và Hồ Tùng Mậu. Nhiều người trong họ là con em xứ Nghệ, từng theo chân các bậc tiền bối như Phan Bội Châu sang Trung Quốc tìm đường cứu nước. Tên gọi Tâm tâm xã, nghĩa là hội của những tấm lòng, nói lên khát vọng của họ: đồng tâm, cùng một lòng vì nước.\n\nNhưng phương pháp của họ vẫn là phương pháp của thế hệ trước. Năm 1913, Việt Nam Quang phục Hội của Phan Bội Châu đã tổ chức những vụ ném bom ở Thái Bình, Hà Nội, nhằm vào quan chức thực dân và những kẻ làm tay sai. Mỗi tiếng bom gây chấn động một thời gian, rồi kéo theo những đợt khủng bố, bắt bớ, tù đày khốc liệt. Bộ máy cai trị vẫn đứng vững, còn phong trào thì tổn thất nặng nề. Tiếng bom Sa Diện là đỉnh cao của lối hành động ấy: dũng cảm, quyết liệt, nhưng vẫn chỉ là hành động của một nhóm nhỏ, chưa có quần chúng đứng phía sau.","doc":3},{"loai":"doan","tieu_de":"Tiếng vang và giới hạn của một tiếng bom","text":"Tiếng bom Sa Diện nhanh chóng được báo chí trong và ngoài Trung Quốc đưa tin. Chính Toàn quyền Merlin sau đó đã viết một bản báo cáo riêng về vụ mưu sát ở Quảng Châu. Nhà cầm quyền Pháp tăng cường theo dõi những người Việt Nam hoạt động ở Hoa Nam; mật thám Pháp và cảnh sát tô giới ráo riết lùng sục các nhóm lưu vong ở Quảng Châu, Hồng Kông.\n\nVới người Việt Nam, tiếng bom là lời khẳng định rằng dân tộc mình chưa chịu khuất phục. Nhưng xét cho cùng, bộ máy thuộc địa ở Đông Dương không vì một tiếng bom mà lay chuyển. Một viên toàn quyền có thể bị thay thế, còn chế độ cai trị thì vẫn nguyên vẹn. Câu hỏi đặt ra cho những người đồng chí của Phạm Hồng Thái vì thế vẫn chưa có lời đáp: làm thế nào để giải phóng cả một dân tộc, chứ không chỉ trừng trị một kẻ cầm quyền? Câu trả lời sẽ đến từ một người vừa rời Mátxcơva, đang trên đường xuống phương Nam.","doc":4},{"loai":"ban_co_biet","text":"Tiếng bom Sa Diện còn để lại một hệ quả ít được biết đến ở Việt Nam. Sau vụ nổ, nhà cầm quyền tô giới trên đảo ban hành những quy định mới hạn chế người Trung Quốc ra vào Sa Diện. Chính các quy định ấy đã làm bùng lên cuộc bãi công của công nhân Trung Quốc làm việc trên đảo từ ngày 15/7/1924, buộc nhà cầm quyền tô giới phải bãi bỏ chúng.","nguon_ten":"Tư liệu lịch sử Đảng của Thành ủy Quảng Châu về cuộc bãi công Sa Diện năm 1924","doc":5},{"loai":"doan","tieu_de":"Người phiên dịch tên Lý Thụy","text":"Ngày 11/11/1924, năm tháng sau tiếng bom Sa Diện, Nguyễn Ái Quốc tới Quảng Châu với tên Lý Thụy. Công việc công khai của Người là phiên dịch trong phái bộ cố vấn Liên Xô do Borodin đứng đầu. Danh nghĩa ấy cho Người một chỗ đứng hợp pháp giữa thành phố đầy tai mắt của mật thám, đồng thời mở ra mối quan hệ với nhiều nhà cách mạng Trung Quốc và quốc tế.\n\nKhông lâu sau, Người bắt liên lạc được với những thanh niên Tâm tâm xã. Người trân trọng lòng dũng cảm của họ và sự hy sinh của Phạm Hồng Thái, nhưng đặt ra một vấn đề căn bản: vài người anh hùng không thể thay cho sức mạnh của cả dân tộc. Muốn giải phóng đất nước, phải giác ngộ và tổ chức được đông đảo quần chúng; muốn vậy phải có lý luận soi đường, có tổ chức chặt chẽ, có đội ngũ cán bộ được huấn luyện. Những suy nghĩ ấy về sau được Người viết thành những trang giản dị, dễ hiểu trong cuốn Đường Kách mệnh.","doc":6},{"loai":"trich","text":"Cách mệnh là việc chung cả dân chúng chứ không phải việc một hai người.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Đường Kách mệnh (1927), in trong Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","chu_thich":"Nguyễn Ái Quốc năm 1924, năm Người tới Quảng Châu với tên Lý Thụy.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cộng sản đoàn: hạt nhân bí mật","text":"Tháng 2/1925, Người chọn một số thanh niên tích cực nhất trong Tâm tâm xã, trong đó có Lê Hồng Sơn và Hồ Tùng Mậu, lập ra nhóm Cộng sản đoàn. Đây là một nhóm nhỏ, hoạt động hoàn toàn bí mật, được Người trực tiếp bồi dưỡng về lý luận và phương pháp tổ chức. Nhiệm vụ của nhóm là làm hạt nhân lãnh đạo cho một tổ chức rộng lớn hơn sắp ra đời.\n\nCách làm ấy thể hiện một tư duy tổ chức mới mẻ đối với phong trào yêu nước Việt Nam lúc bấy giờ. Thay vì lập một hội kín dựa trên lòng hăng hái và lời thề, Người xây dựng từ một hạt nhân đã được giác ngộ, có kỷ luật, rồi từ đó mở rộng dần ra. Người cũng sớm tính đến việc gửi những thanh niên ưu tú sang Liên Xô học tập, để phong trào có những cán bộ được đào tạo bài bản. Những người Tâm tâm xã năm nào, từ chỗ sẵn sàng hy sinh trong một vụ ném bom, giờ trở thành những người đi gây dựng một phong trào lâu dài.","doc":8},{"loai":"doan","tieu_de":"Tháng 6/1925: Hội Việt Nam Cách mạng Thanh niên ra đời","text":"Tháng 6/1925, trên cơ sở nhóm Cộng sản đoàn, Hội Việt Nam Cách mạng Thanh niên chính thức ra đời. Tổng bộ của Hội gồm Nguyễn Ái Quốc, Hồ Tùng Mậu và Lê Hồng Sơn. Mục đích của Hội được xác định rõ: trước hết làm cách mạng dân tộc, đánh đổ ách thống trị của thực dân Pháp, giành độc lập cho đất nước; sau đó làm cách mạng thế giới. Ngày 21/6/1925, báo Thanh Niên ra số đầu tiên, làm cơ quan tuyên truyền của Hội.\n\nTên Hội có chữ “thanh niên” không phải ngẫu nhiên. Người đặt niềm tin vào lớp trẻ, những người chưa bị ràng buộc bởi lối hành động cũ và sẵn sàng tiếp thu cái mới. Hội tuyển chọn hội viên kỹ lưỡng, tổ chức theo hệ thống từ Tổng bộ xuống kỳ bộ, tỉnh bộ, huyện bộ và chi bộ. Thanh niên từ trong nước được đưa sang Quảng Châu theo nhiều ngả đường bí mật, học xong lại trở về hoạt động. Ngôi nhà trên đường Văn Minh trở thành nơi làm việc của Hội, nơi mở lớp và làm báo (xem chuyên đề Nhà số 248 – 250 đường Văn Minh).","doc":9},{"loai":"ban_co_biet","text":"Ngày báo Thanh Niên ra số đầu tiên, 21/6/1925, được chọn làm Ngày Báo chí Việt Nam từ năm 1985; từ năm 2000, ngày này được gọi là Ngày Báo chí cách mạng Việt Nam.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; Hội Nhà báo Việt Nam","doc":10},{"loai":"anh","src":"textures/bang_w/G09_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ tiếng bom Sa Diện đến Hội Thanh niên”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Khi một thế hệ khép lại","text":"Cũng trong mùa hè năm 1925, phong trào yêu nước Việt Nam chứng kiến một biến cố lớn. Phan Bội Châu, bậc tiền bối mà nhiều thanh niên Tâm tâm xã từng đi theo, bị mật thám Pháp bắt ở Thượng Hải rồi giải về Hà Nội xét xử. Khắp trong nước dấy lên phong trào đòi ân xá cho cụ. Cuối cùng, nhà cầm quyền thực dân buộc phải tha án, nhưng đưa cụ về an trí ở Huế, nơi cụ sống những năm cuối đời dưới sự canh giữ ngặt nghèo.\n\nSự kiện ấy như khép lại một chặng đường của phong trào giải phóng dân tộc theo khuynh hướng cũ. Cũng vào lúc đó, ở Quảng Châu, một tổ chức theo con đường mới vừa ra đời. Những thanh niên từng lớn lên trong ảnh hưởng của Phan Bội Châu, như Hồ Tùng Mậu, Lê Hồng Sơn, nay là cán bộ nòng cốt của Hội Việt Nam Cách mạng Thanh niên. Cuộc chuyển giao ấy không diễn ra bằng sự phủ định, mà bằng sự kế thừa. Lòng yêu nước và tinh thần hy sinh của lớp người đi trước được đặt vào một con đường có lý luận, có tổ chức và có quần chúng.","doc":11},{"loai":"doan","tieu_de":"Từ Hội Thanh niên đến Đảng Cộng sản","text":"Chỉ trong vài năm, Hội Việt Nam Cách mạng Thanh niên đã có cơ sở ở cả ba kỳ và trong cộng đồng người Việt ở Xiêm. Báo Thanh Niên được bí mật chuyển về nước, chuyền tay nhau đọc. Năm 1928, Hội phát động phong trào “vô sản hóa”: hội viên vào làm thợ ở hầm mỏ, nhà máy, đồn điền, vừa lao động vừa tuyên truyền, tổ chức công nhân. Đến năm 1929, Hội có khoảng 1.700 hội viên.\n\nTừ phong trào ấy, năm 1929, những tổ chức cộng sản đầu tiên lần lượt ra đời trong nước. Đầu năm 1930, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức ấy thành Đảng Cộng sản Việt Nam. Hội nghị họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng (xem gian Hồng Kông – Thành lập Đảng). Từ tiếng bom Sa Diện năm 1924 đến ngày thành lập Đảng chưa đầy sáu năm. Trong khoảng thời gian ngắn ngủi ấy, phong trào yêu nước Việt Nam đã đi một bước dài, từ hành động của một nhóm nhỏ tới một đảng cách mạng có đường lối và có quần chúng.","doc":12},{"loai":"anh","src":"textures/bang_w/G09_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ tiếng bom Sa Diện đến Hội Thanh niên”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, đảo Sa Diện là một khu phố yên tĩnh của Quảng Châu, còn giữ được nhiều công trình kiến trúc châu Âu từ thời tô giới, thu hút du khách tới dạo bộ, chụp ảnh. Ít ai trong dòng người ấy biết rằng trên hòn đảo này từng vang lên tiếng bom của một thanh niên Việt Nam. Trong khu nghĩa trang Hoàng Hoa Cương, mộ liệt sĩ Phạm Hồng Thái vẫn được gìn giữ; các đoàn đại biểu và người Việt Nam đến Quảng Châu thường ghé thắp hương tưởng niệm anh.\n\nỞ Việt Nam, tên Phạm Hồng Thái được đặt cho nhiều đường phố, trường học. Ngôi nhà trên đường Văn Minh, nơi Hội Việt Nam Cách mạng Thanh niên làm việc, nay là di tích lịch sử. Trong gian trưng bày 3D này, khách tham quan có thể đi từ bảng kể về tiếng bom Sa Diện sang không gian lớp học, như đi lại con đường mà những đồng chí của Phạm Hồng Thái đã đi: từ lòng quả cảm của một người đến sức mạnh có tổ chức của cả một dân tộc.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 2 (Đường Kách mệnh), NXB Chính trị quốc gia","M. Merlin, báo cáo “Vụ ám sát Cách mạng ngày 19 tháng 6, 1924 ở Quảng Châu”, giới thiệu trên nghiencuulichsu.com (2021)","Tư liệu lịch sử Đảng của Thành ủy Quảng Châu về cuộc bãi công Sa Diện năm 1924","Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)"],"doc":[{"t":"Tiếng bom Sa Diện và một con đường khác: từ Tâm tâm xã đến Hội Việt Nam Cách mạng Thanh niên. Tối 19/6/1924, một tiếng nổ vang lên giữa bữa tiệc giới chức Pháp chiêu đãi Toàn quyền Đông Dương trên đảo Sa Diện, Quảng Châu. Người ném bom là một thanh niên xứ Nghệ, và chỉ ít lâu sau anh đã nằm lại dưới dòng Châu Giang. Năm tháng sau, một người phiên dịch tên Lý Thụy tới thành phố này, tìm gặp những đồng chí của anh và chỉ cho họ một con đường khác. Con đường ấy dẫn tới sự ra đời của Hội Việt Nam Cách mạng Thanh niên."},{"t":"Buổi tiệc trên đảo Sa Diện. Sa Diện là một dải đất nhỏ nằm giữa sông Châu Giang, sát trung tâm Quảng Châu. Từ những năm 1860, hòn đảo trở thành tô giới của người Anh và người Pháp, với những con đường rợp bóng cây, dinh thự kiểu châu Âu, ngân hàng và lãnh sự quán. Người Trung Quốc muốn qua cầu vào đảo phải chịu sự kiểm soát của cảnh sát tô giới. Đó là một góc châu Âu thu nhỏ, yên bình và kiêu hãnh, giữa lòng một thành phố Trung Hoa đang sục sôi cách mạng. Tháng 6/1924, Toàn quyền Đông Dương Martial Merlin có chuyến dừng chân ở Quảng Châu. Tối 19/6/1924, cộng đồng người Pháp ở Sa Diện mở tiệc chiêu đãi ông tại khách sạn Victoria trên đảo. Giữa bữa tiệc, một quả bom được ném vào phòng ăn. Tiếng nổ làm một số người dự tiệc thiệt mạng và bị thương, nhưng Merlin thoát chết. Người ném bom là Phạm Hồng Thái, một thanh niên Việt Nam quê Nghệ An. Bị truy đuổi gắt gao, anh chạy ra bờ sông, lao mình xuống dòng Châu Giang và hy sinh."},{"t":"Người thanh niên xứ Nghệ. Phạm Hồng Thái tên thật là Phạm Thành Tích, quê huyện Hưng Nguyên, tỉnh Nghệ An, vùng đất đã sinh ra nhiều thế hệ những người yêu nước. Cũng như bao thanh niên cùng thời, anh lớn lên trong cảnh nước mất nhà tan, chứng kiến các phong trào Đông Du, Duy Tân lần lượt bị dập tắt. Anh rời quê hương sang Trung Quốc, tìm tới nhóm thanh niên Việt Nam yêu nước đang hoạt động ở Quảng Châu, và tự nguyện nhận phần việc hiểm nguy nhất. Sự hy sinh của anh gây xúc động lớn trong dư luận Quảng Châu. Chính quyền Quảng Châu cho an táng anh tại nghĩa trang Hoàng Hoa Cương, nơi yên nghỉ của bảy mươi hai liệt sĩ đã ngã xuống trong cuộc khởi nghĩa Quảng Châu năm 1911 chống triều Mãn Thanh. Một người Việt Nam được nằm lại giữa những liệt sĩ cách mạng Trung Hoa, đó là sự tôn vinh hiếm có. Tin về người thanh niên hy sinh trên dòng Châu Giang cũng vượt biên giới về trong nước, khích lệ lòng yêu nước của lớp người trẻ."},{"t":"Tâm tâm xã, những con người quả cảm. Phạm Hồng Thái là thành viên của Tâm tâm xã, một tổ chức của thanh niên Việt Nam yêu nước lập ở Quảng Châu năm 1923, trong đó có Lê Hồng Sơn và Hồ Tùng Mậu. Nhiều người trong họ là con em xứ Nghệ, từng theo chân các bậc tiền bối như Phan Bội Châu sang Trung Quốc tìm đường cứu nước. Tên gọi Tâm tâm xã, nghĩa là hội của những tấm lòng, nói lên khát vọng của họ: đồng tâm, cùng một lòng vì nước. Nhưng phương pháp của họ vẫn là phương pháp của thế hệ trước. Năm 1913, Việt Nam Quang phục Hội của Phan Bội Châu đã tổ chức những vụ ném bom ở Thái Bình, Hà Nội, nhằm vào quan chức thực dân và những kẻ làm tay sai. Mỗi tiếng bom gây chấn động một thời gian, rồi kéo theo những đợt khủng bố, bắt bớ, tù đày khốc liệt. Bộ máy cai trị vẫn đứng vững, còn phong trào thì tổn thất nặng nề. Tiếng bom Sa Diện là đỉnh cao của lối hành động ấy: dũng cảm, quyết liệt, nhưng vẫn chỉ là hành động của một nhóm nhỏ, chưa có quần chúng đứng phía sau."},{"t":"Tiếng vang và giới hạn của một tiếng bom. Tiếng bom Sa Diện nhanh chóng được báo chí trong và ngoài Trung Quốc đưa tin. Chính Toàn quyền Merlin sau đó đã viết một bản báo cáo riêng về vụ mưu sát ở Quảng Châu. Nhà cầm quyền Pháp tăng cường theo dõi những người Việt Nam hoạt động ở Hoa Nam; mật thám Pháp và cảnh sát tô giới ráo riết lùng sục các nhóm lưu vong ở Quảng Châu, Hồng Kông. Với người Việt Nam, tiếng bom là lời khẳng định rằng dân tộc mình chưa chịu khuất phục. Nhưng xét cho cùng, bộ máy thuộc địa ở Đông Dương không vì một tiếng bom mà lay chuyển. Một viên toàn quyền có thể bị thay thế, còn chế độ cai trị thì vẫn nguyên vẹn. Câu hỏi đặt ra cho những người đồng chí của Phạm Hồng Thái vì thế vẫn chưa có lời đáp: làm thế nào để giải phóng cả một dân tộc, chứ không chỉ trừng trị một kẻ cầm quyền? Câu trả lời sẽ đến từ một người vừa rời Mátxcơva, đang trên đường xuống phương Nam."},{"t":"Bạn có biết? Tiếng bom Sa Diện còn để lại một hệ quả ít được biết đến ở Việt Nam. Sau vụ nổ, nhà cầm quyền tô giới trên đảo ban hành những quy định mới hạn chế người Trung Quốc ra vào Sa Diện. Chính các quy định ấy đã làm bùng lên cuộc bãi công của công nhân Trung Quốc làm việc trên đảo từ ngày 15/7/1924, buộc nhà cầm quyền tô giới phải bãi bỏ chúng."},{"t":"Người phiên dịch tên Lý Thụy. Ngày 11/11/1924, năm tháng sau tiếng bom Sa Diện, Nguyễn Ái Quốc tới Quảng Châu với tên Lý Thụy. Công việc công khai của Người là phiên dịch trong phái bộ cố vấn Liên Xô do Borodin đứng đầu. Danh nghĩa ấy cho Người một chỗ đứng hợp pháp giữa thành phố đầy tai mắt của mật thám, đồng thời mở ra mối quan hệ với nhiều nhà cách mạng Trung Quốc và quốc tế. Không lâu sau, Người bắt liên lạc được với những thanh niên Tâm tâm xã. Người trân trọng lòng dũng cảm của họ và sự hy sinh của Phạm Hồng Thái, nhưng đặt ra một vấn đề căn bản: vài người anh hùng không thể thay cho sức mạnh của cả dân tộc. Muốn giải phóng đất nước, phải giác ngộ và tổ chức được đông đảo quần chúng; muốn vậy phải có lý luận soi đường, có tổ chức chặt chẽ, có đội ngũ cán bộ được huấn luyện. Những suy nghĩ ấy về sau được Người viết thành những trang giản dị, dễ hiểu trong cuốn Đường Kách mệnh."},{"t":"Cách mệnh là việc chung cả dân chúng chứ không phải việc một hai người. — Nguyễn Ái Quốc"},{"t":"Cộng sản đoàn: hạt nhân bí mật. Tháng 2/1925, Người chọn một số thanh niên tích cực nhất trong Tâm tâm xã, trong đó có Lê Hồng Sơn và Hồ Tùng Mậu, lập ra nhóm Cộng sản đoàn. Đây là một nhóm nhỏ, hoạt động hoàn toàn bí mật, được Người trực tiếp bồi dưỡng về lý luận và phương pháp tổ chức. Nhiệm vụ của nhóm là làm hạt nhân lãnh đạo cho một tổ chức rộng lớn hơn sắp ra đời. Cách làm ấy thể hiện một tư duy tổ chức mới mẻ đối với phong trào yêu nước Việt Nam lúc bấy giờ. Thay vì lập một hội kín dựa trên lòng hăng hái và lời thề, Người xây dựng từ một hạt nhân đã được giác ngộ, có kỷ luật, rồi từ đó mở rộng dần ra. Người cũng sớm tính đến việc gửi những thanh niên ưu tú sang Liên Xô học tập, để phong trào có những cán bộ được đào tạo bài bản. Những người Tâm tâm xã năm nào, từ chỗ sẵn sàng hy sinh trong một vụ ném bom, giờ trở thành những người đi gây dựng một phong trào lâu dài."},{"t":"Tháng 6/1925: Hội Việt Nam Cách mạng Thanh niên ra đời. Tháng 6/1925, trên cơ sở nhóm Cộng sản đoàn, Hội Việt Nam Cách mạng Thanh niên chính thức ra đời. Tổng bộ của Hội gồm Nguyễn Ái Quốc, Hồ Tùng Mậu và Lê Hồng Sơn. Mục đích của Hội được xác định rõ: trước hết làm cách mạng dân tộc, đánh đổ ách thống trị của thực dân Pháp, giành độc lập cho đất nước; sau đó làm cách mạng thế giới. Ngày 21/6/1925, báo Thanh Niên ra số đầu tiên, làm cơ quan tuyên truyền của Hội. Tên Hội có chữ “thanh niên” không phải ngẫu nhiên. Người đặt niềm tin vào lớp trẻ, những người chưa bị ràng buộc bởi lối hành động cũ và sẵn sàng tiếp thu cái mới. Hội tuyển chọn hội viên kỹ lưỡng, tổ chức theo hệ thống từ Tổng bộ xuống kỳ bộ, tỉnh bộ, huyện bộ và chi bộ. Thanh niên từ trong nước được đưa sang Quảng Châu theo nhiều ngả đường bí mật, học xong lại trở về hoạt động. Ngôi nhà trên đường Văn Minh trở thành nơi làm việc của Hội, nơi mở lớp và làm báo (xem chuyên đề Nhà số 248 – 250 đường Văn Minh)."},{"t":"Bạn có biết? Ngày báo Thanh Niên ra số đầu tiên, 21/6/1925, được chọn làm Ngày Báo chí Việt Nam từ năm 1985; từ năm 2000, ngày này được gọi là Ngày Báo chí cách mạng Việt Nam."},{"t":"Khi một thế hệ khép lại. Cũng trong mùa hè năm 1925, phong trào yêu nước Việt Nam chứng kiến một biến cố lớn. Phan Bội Châu, bậc tiền bối mà nhiều thanh niên Tâm tâm xã từng đi theo, bị mật thám Pháp bắt ở Thượng Hải rồi giải về Hà Nội xét xử. Khắp trong nước dấy lên phong trào đòi ân xá cho cụ. Cuối cùng, nhà cầm quyền thực dân buộc phải tha án, nhưng đưa cụ về an trí ở Huế, nơi cụ sống những năm cuối đời dưới sự canh giữ ngặt nghèo. Sự kiện ấy như khép lại một chặng đường của phong trào giải phóng dân tộc theo khuynh hướng cũ. Cũng vào lúc đó, ở Quảng Châu, một tổ chức theo con đường mới vừa ra đời. Những thanh niên từng lớn lên trong ảnh hưởng của Phan Bội Châu, như Hồ Tùng Mậu, Lê Hồng Sơn, nay là cán bộ nòng cốt của Hội Việt Nam Cách mạng Thanh niên. Cuộc chuyển giao ấy không diễn ra bằng sự phủ định, mà bằng sự kế thừa. Lòng yêu nước và tinh thần hy sinh của lớp người đi trước được đặt vào một con đường có lý luận, có tổ chức và có quần chúng."},{"t":"Từ Hội Thanh niên đến Đảng Cộng sản. Chỉ trong vài năm, Hội Việt Nam Cách mạng Thanh niên đã có cơ sở ở cả ba kỳ và trong cộng đồng người Việt ở Xiêm. Báo Thanh Niên được bí mật chuyển về nước, chuyền tay nhau đọc. Năm 1928, Hội phát động phong trào “vô sản hóa”: hội viên vào làm thợ ở hầm mỏ, nhà máy, đồn điền, vừa lao động vừa tuyên truyền, tổ chức công nhân. Đến năm 1929, Hội có khoảng 1.700 hội viên. Từ phong trào ấy, năm 1929, những tổ chức cộng sản đầu tiên lần lượt ra đời trong nước. Đầu năm 1930, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức ấy thành Đảng Cộng sản Việt Nam. Hội nghị họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng (xem gian Hồng Kông – Thành lập Đảng). Từ tiếng bom Sa Diện năm 1924 đến ngày thành lập Đảng chưa đầy sáu năm. Trong khoảng thời gian ngắn ngủi ấy, phong trào yêu nước Việt Nam đã đi một bước dài, từ hành động của một nhóm nhỏ tới một đảng cách mạng có đường lối và có quần chúng."},{"t":"Dấu tích hôm nay. Ngày nay, đảo Sa Diện là một khu phố yên tĩnh của Quảng Châu, còn giữ được nhiều công trình kiến trúc châu Âu từ thời tô giới, thu hút du khách tới dạo bộ, chụp ảnh. Ít ai trong dòng người ấy biết rằng trên hòn đảo này từng vang lên tiếng bom của một thanh niên Việt Nam. Trong khu nghĩa trang Hoàng Hoa Cương, mộ liệt sĩ Phạm Hồng Thái vẫn được gìn giữ; các đoàn đại biểu và người Việt Nam đến Quảng Châu thường ghé thắp hương tưởng niệm anh. Ở Việt Nam, tên Phạm Hồng Thái được đặt cho nhiều đường phố, trường học. Ngôi nhà trên đường Văn Minh, nơi Hội Việt Nam Cách mạng Thanh niên làm việc, nay là di tích lịch sử. Trong gian trưng bày 3D này, khách tham quan có thể đi từ bảng kể về tiếng bom Sa Diện sang không gian lớp học, như đi lại con đường mà những đồng chí của Phạm Hồng Thái đã đi: từ lòng quả cảm của một người đến sức mạnh có tổ chức của cả một dân tộc."}],"so_chu":2166},{"i":2,"tieu_de_bang":"Mười ba tháng trong các nhà lao Quảng Tây","tieu_de":"Mười ba tháng xiềng xích: người tù Hồ Chí Minh qua mười tám nhà lao Quảng Tây (1942 – 1943)","sapo":"Tháng 8/1942, một người Việt Nam ngoài năm mươi tuổi, giấy tờ mang một cái tên chưa ai biết là Hồ Chí Minh, vượt biên giới sang Trung Quốc để tìm đồng minh. Chỉ mười mấy ngày sau, ông bị bắt vì bị nghi là gián điệp. Không phiên tòa, không bản án, người tù bị giải qua mười ba huyện, mười tám nhà lao, có lúc tin dữ về ông còn truyền về tận Pác Bó. Đây là câu chuyện của mười ba tháng ấy.","bia":{"src":"textures/bai/G09_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Rời Pác Bó, mùa thu năm 1942","text":"Hơn một năm sau ngày vượt cột mốc 108 về nước, phong trào ở Cao Bằng đã lớn mạnh. Tháng 5/1941, tại Pác Bó, Hội nghị Trung ương lần thứ tám do Người chủ trì quyết định thành lập Mặt trận Việt Minh. Nhưng Người hiểu rằng cách mạng Việt Nam không thể đứng một mình. Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt; phát xít Nhật chiếm đóng Đông Dương, còn Trung Quốc là một thành viên của phe Đồng minh chống phát xít.\n\nNgười quyết định sang Trùng Khánh, thủ đô thời chiến của Trung Hoa Dân quốc, để liên lạc với các lực lượng Đồng minh và tranh thủ sự ủng hộ quốc tế cho cuộc đấu tranh của nhân dân Việt Nam. Giữa tháng 8/1942, Người lên đường, với tư cách đại biểu của Việt Minh. Trên giấy tờ mang theo, lần đầu tiên xuất hiện cái tên Hồ Chí Minh. Không ai ngờ rằng cái tên ấy sẽ đi qua mười ba tháng lao tù trước khi được cả thế giới biết đến.","doc":1},{"loai":"doan","tieu_de":"Phố Túc Vinh, ngày 29/8/1942","text":"Ngày 29/8/1942, khi tới phố Túc Vinh thuộc tỉnh Quảng Tây, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ. Thời chiến, vùng biên giới đầy những nghi kỵ: một người nước ngoài lạ mặt, mang giấy tờ của một tổ chức chưa ai biết, lại từ phía Đông Dương do Nhật chiếm đóng sang, dễ bị coi là gián điệp. Mọi lời giải thích đều không được nghe.\n\nTrong bài thơ viết về phố Túc Vinh, người tù bày tỏ nỗi uất ức: nơi này đã làm lỡ bước đường của mình và gán cho mình tiếng gián điệp vô cớ. Từ đó, người đi tìm đồng minh trở thành một phạm nhân không có bản án. Người không bị đưa ra tòa, cũng không biết mình sẽ bị giam bao lâu. Mỗi lần bị giải đi, người tù lại không biết nhà lao tiếp theo ở đâu, và liệu con đường ấy có dẫn tới tự do hay không. Chuyến đi ấy rốt cuộc kéo dài hơn hai năm, trước khi Người trở lại được Pác Bó.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mười ba tháng trong các nhà lao Quảng Tây”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mười ba huyện, mười tám nhà lao","text":"Theo Giáo sư Song Thành, nguyên Viện trưởng Viện Hồ Chí Minh, người tù bị giải qua mười ba huyện, mười tám nhà lao của tỉnh Quảng Tây. Lộ trình đi từ Tĩnh Tây, Thiên Bảo, Quả Đức, Long An, Đồng Chính tới Nam Ninh, rồi lên Liễu Châu, Quế Lâm, có chặng lại bị giải ngược trở về. Mỗi lần chuyển trại là một chặng đường dài giữa núi non Quảng Tây, phần nhiều phải đi bộ, hai tay bị trói, có lúc bị xiềng xích.\n\nNhững chặng đường ấy hiện lên rõ nét trong thơ. Có bài tả cảnh bị giải đi từ lúc gà mới gáy, trời còn chưa sáng, gió thu lạnh buốt táp vào mặt. Có bài kể cảnh lính áp giải khiêng một con lợn đi cùng: con lợn được khiêng trên vai, còn con người thì bị trói dắt đi. Giọng thơ nhẹ nhàng, hóm hỉnh, nhưng đằng sau là nỗi đau của một thân phận bị coi rẻ hơn con vật. Từ những trang thơ, các nhà nghiên cứu có thể lần lại từng chặng đường của người tù trên đất Quảng Tây.","doc":3},{"loai":"trich","text":"Đi đường mới biết gian lao, / Núi cao rồi lại núi cao trập trùng; / Núi cao lên đến tận cùng, / Thu vào tầm mắt muôn trùng nước non.","nguoi":"Hồ Chí Minh (bản dịch thơ của Nam Trân)","nguon_ten":"Bài “Đi đường” (Tẩu lộ), tập Nhật ký trong tù, 1942 – 1943","doc":4},{"loai":"doan","tieu_de":"Đời sống trong xà lim","text":"Các nhà lao dọc đường giải phần nhiều chật chội, tối tăm, ẩm thấp. Ban đêm, chân người tù bị cùm; mùa đông không có chăn đệm, cái lạnh vùng núi thấm vào tận xương. Cơm tù ít ỏi, muốn có thêm chút thức ăn phải tự lo liệu. Ghẻ lở, rận rệp là chuyện thường ngày. Đã ngoài năm mươi tuổi, Người nhiều lần ốm đau trong những tháng ấy.\n\nThơ Người ghi lại tất cả, không che giấu: có bài viết về ghẻ lở khắp mình, có bài về đêm lạnh không chăn, có bài về những trận ốm. Người cũng viết về những bất công của chế độ nhà lao, về thói tham nhũng, hà hiếp của những kẻ coi ngục. Nhưng lạ thay, ít khi thấy một lời than thân. Người tù nhìn cảnh khổ của mình bằng con mắt tỉnh táo, đôi khi hài hước, như thể đứng ngoài nhìn vào. Chính thái độ ấy đã giữ cho tinh thần Người không bị những bức tường nhà lao đè nặng.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_to_cuoi_tap_tho_nhat_ky_trong_tu.jpg","chu_thich":"Tờ cuối bản thảo Nhật ký trong tù, cuốn sổ nhỏ Người mang theo qua các nhà lao Quảng Tây (1942 – 1943).","credit":"Ảnh: 7ieulong · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những người bạn tù","text":"Trong các nhà lao, Người sống chung với đủ hạng người: những nông dân nghèo không nộp nổi thuế, những người lính đào ngũ, những con bạc, những kẻ bị bắt vì những lý do chẳng ai rõ. Người quan sát họ bằng tấm lòng cảm thông của một người cùng cảnh ngộ. Nhiều bài thơ trong tập nhật ký được viết về chính những con người ấy.\n\nỞ nhà lao Tân Dương, Người gặp một em bé theo mẹ vào tù; bài thơ về cháu bé ấy vừa ngây thơ vừa xót xa, vì đứa trẻ chưa biết đời mà đã phải nếm mùi tù ngục. Có đêm, tiếng sáo của một bạn tù vẳng lên, gợi nỗi nhớ quê trong lòng những người xa xứ. Có lần, một bạn tù qua đời trong cảnh thiếu thốn, và Người ghi lại nỗi xót thương ấy bằng thơ. Người tù chính trị không đặt mình cao hơn những bạn tù thường phạm; Người nhìn thấy ở họ nạn nhân của một xã hội bất công, và từ nỗi khổ của họ mà nghĩ tới nỗi khổ của bao người lao động khác.","doc":6},{"loai":"ban_co_biet","text":"Bài thơ mở đầu tập nhật ký cho biết vì sao người tù làm thơ: “Ngâm thơ ta vốn không ham, / Nhưng vì trong ngục biết làm chi đây; / Ngày dài ngâm ngợi cho khuây, / Vừa ngâm vừa đợi đến ngày tự do.”","nguon_ten":"Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học)","doc":7},{"loai":"doan","tieu_de":"Tin dữ truyền về Pác Bó","text":"Trong khi người tù bị giải hết nhà lao này đến nhà lao khác, ở Cao Bằng, các đồng chí của Người hoàn toàn mất liên lạc. Nhiều tháng trôi qua không một tin tức. Phong trào Việt Minh vẫn phát triển, các đội vũ trang tiếp tục mở rộng địa bàn, nhưng ai nấy đều canh cánh một nỗi lo: Người ở đâu, còn sống hay đã mất?\n\nTheo hồi ký của Đại tướng Võ Nguyên Giáp, có lúc tin Người đã mất trong tù truyền về, khiến mọi người vô cùng đau đớn. Những người từng được Người dìu dắt cảm thấy như mất đi chỗ dựa lớn nhất. Ít lâu sau, tin tức do chính Người gửi về cho biết Người vẫn còn sống, và nỗi đau chuyển thành niềm vui khôn tả. Câu chuyện ấy cho thấy những người ở nhà gắn bó với Người sâu sắc đến nhường nào. Nó cũng cho thấy hoàn cảnh hiểm nghèo của những tháng ngày bị giam cầm, khi số phận một con người có thể lặng lẽ khép lại ở một nhà lao hẻo lánh mà không ai hay biết.","doc":8},{"loai":"anh","src":"textures/bang_w/G09_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mười ba tháng trong các nhà lao Quảng Tây”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Liễu Châu và cánh cửa hé mở","text":"Cuối cùng, người tù được giải về Liễu Châu, nơi đặt bộ tư lệnh Đệ tứ chiến khu của quân đội Trung Hoa Dân quốc do tướng Trương Phát Khuê chỉ huy. Cũng tại Liễu Châu, từ mùa thu năm 1942, Việt Nam Cách mạng Đồng minh Hội được thành lập, tập hợp những người Việt Nam lưu vong ở Hoa Nam dưới sự bảo trợ của phía Trung Quốc. Nhưng tổ chức này yếu ớt, thiếu cơ sở trong nước, chia rẽ bởi những toan tính riêng.\n\nDần dần, phía Trung Quốc nhận ra uy tín và năng lực của người tù mang tên Hồ Chí Minh, cũng như lực lượng Việt Minh mà Người đại diện. Ngày 10/9/1943, Người được trả tự do. Mười ba tháng lao tù khép lại. Nhưng Người chưa thể về nước ngay: Người ở lại Liễu Châu, sống tại trụ sở của Việt Nam Cách mạng Đồng minh Hội trên phố Ngư Phong, tham gia củng cố tổ chức này, tranh thủ sự giúp đỡ của phía Trung Quốc cho cách mạng Việt Nam và chuẩn bị cán bộ cho ngày trở về.","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_s_prison_diary_in_2016.jpg","chu_thich":"Bản thảo Nhật ký trong tù, nay là Bảo vật quốc gia, lưu giữ tại Bảo tàng Lịch sử quốc gia ở Hà Nội.","credit":"Ảnh: Cookie Nguyen · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Tập leo núi sau ngày ra tù","text":"Những ngày đầu ra tù, sức khỏe của Người suy kiệt sau hơn một năm bị giam cầm, đôi chân yếu hẳn đi. Một bài thơ Người viết trong thời gian ấy có nhan đề “Mới ra tù, tập leo núi”. Trong bài thơ, người vừa thoát khỏi xiềng xích một mình dạo bước trên núi Tây Phong, ngắm mây ôm núi, lòng sông trong như gương, rồi ngoảnh về phương Nam mà nhớ những người bạn cũ.\n\nTháng 9/1944, gần một năm sau ngày ra tù, Người về tới Pác Bó. Chưa đầy một năm sau đó, Người cùng Trung ương Đảng lãnh đạo toàn dân tộc làm nên Cách mạng Tháng Tám, và ngày 2/9/1945 đọc bản Tuyên ngôn Độc lập tại Quảng trường Ba Đình. Người tù không bản án ở Quảng Tây năm nào đã trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Nhìn lại, mười ba tháng lao tù làm lỡ nhiều dự định, nhưng không làm lệch con đường Người đã chọn.","doc":10},{"loai":"doan","tieu_de":"Ý nghĩa của mười ba tháng","text":"Mười ba tháng ở Quảng Tây là một trong những thử thách khắc nghiệt nhất trong cuộc đời hoạt động của Người. Người mất tự do đúng vào lúc phong trào trong nước cần Người nhất, phải chịu đói rét, bệnh tật, sự nghi kỵ và sỉ nhục. Vậy mà từ những tháng ngày ấy, dân tộc Việt Nam lại nhận được một di sản tinh thần quý giá: hơn một trăm bài thơ chữ Hán viết trên một cuốn sổ nhỏ, ghi lại hành trình khổ ải bằng tâm hồn của một chiến sĩ và một thi sĩ (xem chuyên đề Tờ cuối bản thảo Nhật ký trong tù).\n\nNhững tháng ngày ấy cũng cho thấy một phẩm chất đặc biệt của Người: sự bền bỉ. Không phải sự bền bỉ của người chỉ biết chịu đựng, mà của người biết giữ cho mình tỉnh táo, biết quan sát, biết cảm thông, biết tìm niềm vui ngay trong nghịch cảnh. Trong bài “Tự khuyên mình” của tập nhật ký, Người viết rằng không có cảnh đông tàn thì cũng không có cảnh huy hoàng ngày xuân; nghĩ mình trong bước gian truân, Người coi tai ương là thứ rèn luyện cho tinh thần thêm hăng hái.","doc":11},{"loai":"ban_co_biet","text":"Nhan đề tập thơ nhắc tới “nhật ký”, và người tù quả thật đã ghi chép như viết nhật ký: nhiều bài thơ mang tên các nhà lao, các chặng giải đi hay những sự việc xảy ra trong ngày, nhờ đó người đọc hôm nay có thể lần theo hành trình của Người qua các huyện của Quảng Tây.","nguon_ten":"Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học); GS. Song Thành, NXB Chính trị quốc gia Sự thật","doc":12},{"loai":"anh","src":"textures/bang_w/G09_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mười ba tháng trong các nhà lao Quảng Tây”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Cuốn sổ nhỏ chứa những bài thơ viết trong ngục đã vượt qua bao biến cố để trở về Việt Nam. Ngày nay, bản thảo Nhật ký trong tù được công nhận là Bảo vật quốc gia, lưu giữ tại Bảo tàng Lịch sử quốc gia ở Hà Nội (xem chuyên đề Bản thảo Nhật ký trong tù – Bảo vật quốc gia). Nhiều bài thơ trong tập được đưa vào sách giáo khoa, được học sinh Việt Nam thuộc lòng qua nhiều thế hệ.\n\nỞ Quảng Tây, những địa danh như Túc Vinh, Tĩnh Tây, Thiên Bảo, Nam Ninh, Liễu Châu, Quế Lâm vẫn còn đó, gắn với một chặng đời gian khổ của Người. Trong gian trưng bày 3D này, bảng kể về mười ba tháng lao tù được đặt cạnh những trang bản thảo, để khách tham quan hình dung con đường mà người tù đã đi: từ phố Túc Vinh ngày 29/8/1942 tới ngày được trả tự do 10/9/1943, qua mười tám nhà lao, với một cuốn sổ nhỏ và một tinh thần không gì giam hãm được.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học), NXB Văn học","Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký), NXB Quân đội nhân dân","GS. Song Thành, “Số phận kỳ lạ của bản thảo tập thơ Ngục trung nhật ký”, NXB Chính trị quốc gia Sự thật: https://www.nxbctqg.org.vn/s-phn-k-l-ca-bn-tho-tp-th-qngc-trung-nht-kyq.html","Bảo tàng Lịch sử Quốc gia, “Cách đây 71 năm (29/8/1942 – 29/8/2013): Hồ Chí Minh bị chính quyền Tưởng Giới Thạch bắt giữ” (baotanglichsu.vn)","Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)"],"doc":[{"t":"Mười ba tháng xiềng xích: người tù Hồ Chí Minh qua mười tám nhà lao Quảng Tây (1942 – 1943). Tháng 8/1942, một người Việt Nam ngoài năm mươi tuổi, giấy tờ mang một cái tên chưa ai biết là Hồ Chí Minh, vượt biên giới sang Trung Quốc để tìm đồng minh. Chỉ mười mấy ngày sau, ông bị bắt vì bị nghi là gián điệp. Không phiên tòa, không bản án, người tù bị giải qua mười ba huyện, mười tám nhà lao, có lúc tin dữ về ông còn truyền về tận Pác Bó. Đây là câu chuyện của mười ba tháng ấy."},{"t":"Rời Pác Bó, mùa thu năm 1942. Hơn một năm sau ngày vượt cột mốc 108 về nước, phong trào ở Cao Bằng đã lớn mạnh. Tháng 5/1941, tại Pác Bó, Hội nghị Trung ương lần thứ tám do Người chủ trì quyết định thành lập Mặt trận Việt Minh. Nhưng Người hiểu rằng cách mạng Việt Nam không thể đứng một mình. Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt; phát xít Nhật chiếm đóng Đông Dương, còn Trung Quốc là một thành viên của phe Đồng minh chống phát xít. Người quyết định sang Trùng Khánh, thủ đô thời chiến của Trung Hoa Dân quốc, để liên lạc với các lực lượng Đồng minh và tranh thủ sự ủng hộ quốc tế cho cuộc đấu tranh của nhân dân Việt Nam. Giữa tháng 8/1942, Người lên đường, với tư cách đại biểu của Việt Minh. Trên giấy tờ mang theo, lần đầu tiên xuất hiện cái tên Hồ Chí Minh. Không ai ngờ rằng cái tên ấy sẽ đi qua mười ba tháng lao tù trước khi được cả thế giới biết đến."},{"t":"Phố Túc Vinh, ngày 29/8/1942. Ngày 29/8/1942, khi tới phố Túc Vinh thuộc tỉnh Quảng Tây, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ. Thời chiến, vùng biên giới đầy những nghi kỵ: một người nước ngoài lạ mặt, mang giấy tờ của một tổ chức chưa ai biết, lại từ phía Đông Dương do Nhật chiếm đóng sang, dễ bị coi là gián điệp. Mọi lời giải thích đều không được nghe. Trong bài thơ viết về phố Túc Vinh, người tù bày tỏ nỗi uất ức: nơi này đã làm lỡ bước đường của mình và gán cho mình tiếng gián điệp vô cớ. Từ đó, người đi tìm đồng minh trở thành một phạm nhân không có bản án. Người không bị đưa ra tòa, cũng không biết mình sẽ bị giam bao lâu. Mỗi lần bị giải đi, người tù lại không biết nhà lao tiếp theo ở đâu, và liệu con đường ấy có dẫn tới tự do hay không. Chuyến đi ấy rốt cuộc kéo dài hơn hai năm, trước khi Người trở lại được Pác Bó."},{"t":"Mười ba huyện, mười tám nhà lao. Theo Giáo sư Song Thành, nguyên Viện trưởng Viện Hồ Chí Minh, người tù bị giải qua mười ba huyện, mười tám nhà lao của tỉnh Quảng Tây. Lộ trình đi từ Tĩnh Tây, Thiên Bảo, Quả Đức, Long An, Đồng Chính tới Nam Ninh, rồi lên Liễu Châu, Quế Lâm, có chặng lại bị giải ngược trở về. Mỗi lần chuyển trại là một chặng đường dài giữa núi non Quảng Tây, phần nhiều phải đi bộ, hai tay bị trói, có lúc bị xiềng xích. Những chặng đường ấy hiện lên rõ nét trong thơ. Có bài tả cảnh bị giải đi từ lúc gà mới gáy, trời còn chưa sáng, gió thu lạnh buốt táp vào mặt. Có bài kể cảnh lính áp giải khiêng một con lợn đi cùng: con lợn được khiêng trên vai, còn con người thì bị trói dắt đi. Giọng thơ nhẹ nhàng, hóm hỉnh, nhưng đằng sau là nỗi đau của một thân phận bị coi rẻ hơn con vật. Từ những trang thơ, các nhà nghiên cứu có thể lần lại từng chặng đường của người tù trên đất Quảng Tây."},{"t":"Đi đường mới biết gian lao, / Núi cao rồi lại núi cao trập trùng; / Núi cao lên đến tận cùng, / Thu vào tầm mắt muôn trùng nước non. — Hồ Chí Minh (bản dịch thơ của Nam Trân)"},{"t":"Đời sống trong xà lim. Các nhà lao dọc đường giải phần nhiều chật chội, tối tăm, ẩm thấp. Ban đêm, chân người tù bị cùm; mùa đông không có chăn đệm, cái lạnh vùng núi thấm vào tận xương. Cơm tù ít ỏi, muốn có thêm chút thức ăn phải tự lo liệu. Ghẻ lở, rận rệp là chuyện thường ngày. Đã ngoài năm mươi tuổi, Người nhiều lần ốm đau trong những tháng ấy. Thơ Người ghi lại tất cả, không che giấu: có bài viết về ghẻ lở khắp mình, có bài về đêm lạnh không chăn, có bài về những trận ốm. Người cũng viết về những bất công của chế độ nhà lao, về thói tham nhũng, hà hiếp của những kẻ coi ngục. Nhưng lạ thay, ít khi thấy một lời than thân. Người tù nhìn cảnh khổ của mình bằng con mắt tỉnh táo, đôi khi hài hước, như thể đứng ngoài nhìn vào. Chính thái độ ấy đã giữ cho tinh thần Người không bị những bức tường nhà lao đè nặng."},{"t":"Những người bạn tù. Trong các nhà lao, Người sống chung với đủ hạng người: những nông dân nghèo không nộp nổi thuế, những người lính đào ngũ, những con bạc, những kẻ bị bắt vì những lý do chẳng ai rõ. Người quan sát họ bằng tấm lòng cảm thông của một người cùng cảnh ngộ. Nhiều bài thơ trong tập nhật ký được viết về chính những con người ấy. Ở nhà lao Tân Dương, Người gặp một em bé theo mẹ vào tù; bài thơ về cháu bé ấy vừa ngây thơ vừa xót xa, vì đứa trẻ chưa biết đời mà đã phải nếm mùi tù ngục. Có đêm, tiếng sáo của một bạn tù vẳng lên, gợi nỗi nhớ quê trong lòng những người xa xứ. Có lần, một bạn tù qua đời trong cảnh thiếu thốn, và Người ghi lại nỗi xót thương ấy bằng thơ. Người tù chính trị không đặt mình cao hơn những bạn tù thường phạm; Người nhìn thấy ở họ nạn nhân của một xã hội bất công, và từ nỗi khổ của họ mà nghĩ tới nỗi khổ của bao người lao động khác."},{"t":"Bạn có biết? Bài thơ mở đầu tập nhật ký cho biết vì sao người tù làm thơ: “Ngâm thơ ta vốn không ham, / Nhưng vì trong ngục biết làm chi đây; / Ngày dài ngâm ngợi cho khuây, / Vừa ngâm vừa đợi đến ngày tự do.”"},{"t":"Tin dữ truyền về Pác Bó. Trong khi người tù bị giải hết nhà lao này đến nhà lao khác, ở Cao Bằng, các đồng chí của Người hoàn toàn mất liên lạc. Nhiều tháng trôi qua không một tin tức. Phong trào Việt Minh vẫn phát triển, các đội vũ trang tiếp tục mở rộng địa bàn, nhưng ai nấy đều canh cánh một nỗi lo: Người ở đâu, còn sống hay đã mất? Theo hồi ký của Đại tướng Võ Nguyên Giáp, có lúc tin Người đã mất trong tù truyền về, khiến mọi người vô cùng đau đớn. Những người từng được Người dìu dắt cảm thấy như mất đi chỗ dựa lớn nhất. Ít lâu sau, tin tức do chính Người gửi về cho biết Người vẫn còn sống, và nỗi đau chuyển thành niềm vui khôn tả. Câu chuyện ấy cho thấy những người ở nhà gắn bó với Người sâu sắc đến nhường nào. Nó cũng cho thấy hoàn cảnh hiểm nghèo của những tháng ngày bị giam cầm, khi số phận một con người có thể lặng lẽ khép lại ở một nhà lao hẻo lánh mà không ai hay biết."},{"t":"Liễu Châu và cánh cửa hé mở. Cuối cùng, người tù được giải về Liễu Châu, nơi đặt bộ tư lệnh Đệ tứ chiến khu của quân đội Trung Hoa Dân quốc do tướng Trương Phát Khuê chỉ huy. Cũng tại Liễu Châu, từ mùa thu năm 1942, Việt Nam Cách mạng Đồng minh Hội được thành lập, tập hợp những người Việt Nam lưu vong ở Hoa Nam dưới sự bảo trợ của phía Trung Quốc. Nhưng tổ chức này yếu ớt, thiếu cơ sở trong nước, chia rẽ bởi những toan tính riêng. Dần dần, phía Trung Quốc nhận ra uy tín và năng lực của người tù mang tên Hồ Chí Minh, cũng như lực lượng Việt Minh mà Người đại diện. Ngày 10/9/1943, Người được trả tự do. Mười ba tháng lao tù khép lại. Nhưng Người chưa thể về nước ngay: Người ở lại Liễu Châu, sống tại trụ sở của Việt Nam Cách mạng Đồng minh Hội trên phố Ngư Phong, tham gia củng cố tổ chức này, tranh thủ sự giúp đỡ của phía Trung Quốc cho cách mạng Việt Nam và chuẩn bị cán bộ cho ngày trở về."},{"t":"Tập leo núi sau ngày ra tù. Những ngày đầu ra tù, sức khỏe của Người suy kiệt sau hơn một năm bị giam cầm, đôi chân yếu hẳn đi. Một bài thơ Người viết trong thời gian ấy có nhan đề “Mới ra tù, tập leo núi”. Trong bài thơ, người vừa thoát khỏi xiềng xích một mình dạo bước trên núi Tây Phong, ngắm mây ôm núi, lòng sông trong như gương, rồi ngoảnh về phương Nam mà nhớ những người bạn cũ. Tháng 9/1944, gần một năm sau ngày ra tù, Người về tới Pác Bó. Chưa đầy một năm sau đó, Người cùng Trung ương Đảng lãnh đạo toàn dân tộc làm nên Cách mạng Tháng Tám, và ngày 2/9/1945 đọc bản Tuyên ngôn Độc lập tại Quảng trường Ba Đình. Người tù không bản án ở Quảng Tây năm nào đã trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Nhìn lại, mười ba tháng lao tù làm lỡ nhiều dự định, nhưng không làm lệch con đường Người đã chọn."},{"t":"Ý nghĩa của mười ba tháng. Mười ba tháng ở Quảng Tây là một trong những thử thách khắc nghiệt nhất trong cuộc đời hoạt động của Người. Người mất tự do đúng vào lúc phong trào trong nước cần Người nhất, phải chịu đói rét, bệnh tật, sự nghi kỵ và sỉ nhục. Vậy mà từ những tháng ngày ấy, dân tộc Việt Nam lại nhận được một di sản tinh thần quý giá: hơn một trăm bài thơ chữ Hán viết trên một cuốn sổ nhỏ, ghi lại hành trình khổ ải bằng tâm hồn của một chiến sĩ và một thi sĩ (xem chuyên đề Tờ cuối bản thảo Nhật ký trong tù). Những tháng ngày ấy cũng cho thấy một phẩm chất đặc biệt của Người: sự bền bỉ. Không phải sự bền bỉ của người chỉ biết chịu đựng, mà của người biết giữ cho mình tỉnh táo, biết quan sát, biết cảm thông, biết tìm niềm vui ngay trong nghịch cảnh. Trong bài “Tự khuyên mình” của tập nhật ký, Người viết rằng không có cảnh đông tàn thì cũng không có cảnh huy hoàng ngày xuân; nghĩ mình trong bước gian truân, Người coi tai ương là thứ rèn luyện cho tinh thần thêm hăng hái."},{"t":"Bạn có biết? Nhan đề tập thơ nhắc tới “nhật ký”, và người tù quả thật đã ghi chép như viết nhật ký: nhiều bài thơ mang tên các nhà lao, các chặng giải đi hay những sự việc xảy ra trong ngày, nhờ đó người đọc hôm nay có thể lần theo hành trình của Người qua các huyện của Quảng Tây."},{"t":"Dấu tích hôm nay. Cuốn sổ nhỏ chứa những bài thơ viết trong ngục đã vượt qua bao biến cố để trở về Việt Nam. Ngày nay, bản thảo Nhật ký trong tù được công nhận là Bảo vật quốc gia, lưu giữ tại Bảo tàng Lịch sử quốc gia ở Hà Nội (xem chuyên đề Bản thảo Nhật ký trong tù – Bảo vật quốc gia). Nhiều bài thơ trong tập được đưa vào sách giáo khoa, được học sinh Việt Nam thuộc lòng qua nhiều thế hệ. Ở Quảng Tây, những địa danh như Túc Vinh, Tĩnh Tây, Thiên Bảo, Nam Ninh, Liễu Châu, Quế Lâm vẫn còn đó, gắn với một chặng đời gian khổ của Người. Trong gian trưng bày 3D này, bảng kể về mười ba tháng lao tù được đặt cạnh những trang bản thảo, để khách tham quan hình dung con đường mà người tù đã đi: từ phố Túc Vinh ngày 29/8/1942 tới ngày được trả tự do 10/9/1943, qua mười tám nhà lao, với một cuốn sổ nhỏ và một tinh thần không gì giam hãm được."}],"so_chu":2087},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Hai mươi năm trên đất Trung Hoa: dòng thời gian từ Quảng Châu đến ngục Quảng Tây (1924 – 1944)","sapo":"Ba mươi mốc thời gian, trải trên hai mươi năm và hàng nghìn cây số đường đất Trung Hoa. Nếu đặt chúng lên bản đồ, ta sẽ thấy một đường đi kỳ lạ: từ Mátxcơva xuống Quảng Châu, rồi rời xa, rồi quay lại, mỗi lần một gần hơn biên giới Việt Nam. Dòng thời gian này giúp khách tham quan đọc ra quy luật ấy.","bia":{"src":"textures/bai/G09_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Ba chặng, một hướng về","text":"Những hoạt động của Người trên đất Trung Quốc chia thành ba chặng rõ rệt. Chặng thứ nhất ở Quảng Châu, từ tháng 11/1924 đến tháng 5/1927, là thời kỳ gieo hạt: lập tổ chức, ra báo, đào tạo cán bộ. Chặng thứ hai, từ cuối năm 1938 đến đầu năm 1941, là hành trình tìm đường về nước qua Diên An, Quế Lâm, Hồ Nam, Côn Minh và vùng biên giới. Chặng thứ ba, từ tháng 8/1942 đến tháng 9/1944, là mười ba tháng lao tù và gần một năm ở Liễu Châu.\n\nGiữa chặng thứ nhất và chặng thứ hai là một khoảng lặng hơn mười một năm, khi Người hoạt động ở những nơi khác. Nhìn tổng thể, cả ba chặng có chung một điểm: tất cả đều hướng về trong nước. Trung Quốc là nơi Người chuẩn bị, liên lạc và chờ thời, còn đích đến bao giờ cũng là quê hương. Dòng thời gian dưới đây được sắp theo trật tự ấy, kèm một số mốc của lịch sử Trung Quốc và Việt Nam để người xem hiểu bối cảnh.","doc":1},{"loai":"moc","items":[["1/1924","Đại hội I Quốc dân Đảng Trung Quốc họp ở Quảng Châu, mở ra thời kỳ hợp tác Quốc – Cộng lần thứ nhất với sự giúp đỡ của Liên Xô"],["16/6/1924","Trường Quân sự Hoàng Phố khai giảng khóa đầu tiên trên đảo Trường Châu, Quảng Châu"],["19/6/1924","Phạm Hồng Thái ném bom mưu sát Toàn quyền Đông Dương Merlin tại khách sạn Victoria trên đảo Sa Diện, rồi hy sinh trên sông Châu Giang"],["10/1924","Nguyễn Ái Quốc rời Mátxcơva, lên đường sang Trung Quốc theo quyết định của Quốc tế Cộng sản"],["11/11/1924","Đến Quảng Châu với tên Lý Thụy, làm phiên dịch trong phái bộ cố vấn Liên Xô của Borodin"],["2/1925","Chọn những thanh niên tích cực nhất của Tâm tâm xã, lập nhóm Cộng sản đoàn làm hạt nhân bí mật"],["6/1925","Thành lập Hội Việt Nam Cách mạng Thanh niên; Tổng bộ gồm Nguyễn Ái Quốc, Hồ Tùng Mậu, Lê Hồng Sơn"],["21/6/1925","Báo Thanh Niên ra số đầu tiên; ngày này nay là Ngày Báo chí cách mạng Việt Nam"],["Giữa năm 1925","Phan Bội Châu bị mật thám Pháp bắt ở Thượng Hải, giải về nước xét xử, sau bị an trí ở Huế"],["7/1925","Cùng các nhà cách mạng châu Á lập Hội Liên hiệp các dân tộc bị áp bức ở Á Đông"],["1925 – 1927","Mở các lớp huấn luyện chính trị tại đường Văn Minh cho khoảng 75 học viên; nhiều người được gửi vào Trường Quân sự Hoàng Phố hoặc sang Liên Xô học"],["1926","Trần Phú, Phạm Văn Đồng sang Quảng Châu dự lớp huấn luyện do Nguyễn Ái Quốc tổ chức"],["1927","Các bài giảng được in thành sách Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ấn hành"],["12/4/1927","Tưởng Giới Thạch làm chính biến ở Thượng Hải, quay sang đàn áp những người cộng sản; ít ngày sau cuộc khủng bố lan tới Quảng Châu"],["Đầu tháng 5/1927","Nguyễn Ái Quốc bí mật rời Quảng Châu sang Hồng Kông, rồi trở lại Mátxcơva"],["1928","Hội Việt Nam Cách mạng Thanh niên phát động phong trào vô sản hóa, đưa hội viên vào hầm mỏ, nhà máy, đồn điền"],["6/1 – 7/2/1930","Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam tại Cửu Long, Hương Cảng"],["Mùa thu 1938","Rời Mátxcơva trở lại Trung Quốc, tới Diên An, căn cứ của Đảng Cộng sản Trung Quốc"],["Cuối năm 1938","Đến Quế Lâm, làm việc tại Văn phòng Bát lộ quân trong vai một sĩ quan tên Hồ Quang"],["1939","Công tác tại lớp huấn luyện du kích ở Hồ Nam do tướng Diệp Kiếm Anh phụ trách"],["Đầu năm 1940","Đến Côn Minh, bắt liên lạc với Ban Hải ngoại của Đảng và qua đó với cơ sở trong nước"],["6/1940","Nước Pháp đầu hàng phát xít Đức; tại Côn Minh, Người gặp Phạm Văn Đồng, Võ Nguyên Giáp và quyết định gấp rút về nước"],["Cuối năm 1940","Xuống vùng biên giới Quảng Tây giáp Cao Bằng, mở lớp huấn luyện cho cán bộ từ trong nước sang"],["28/1/1941","Vượt cột mốc 108 về nước, đến Pác Bó, Cao Bằng"],["5/1941","Chủ trì Hội nghị Trung ương lần thứ tám ở Pác Bó; Mặt trận Việt Minh được thành lập ngày 19/5/1941"],["Giữa tháng 8/1942","Lấy tên Hồ Chí Minh, lên đường sang Trung Quốc với tư cách đại biểu của Việt Minh"],["29/8/1942","Bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ ở phố Túc Vinh, Quảng Tây, vì bị nghi là gián điệp"],["8/1942 – 9/1943","Bị giải qua mười ba huyện, mười tám nhà lao của Quảng Tây; hơn một trăm bài thơ Nhật ký trong tù ra đời"],["10/9/1943","Được trả tự do; ở lại Liễu Châu, hoạt động trong Việt Nam Cách mạng Đồng minh Hội"],["9/1944","Trở về Pác Bó, tiếp tục trực tiếp lãnh đạo cách mạng trong nước"]],"doc":2},{"loai":"anh","src":"textures/bang_w/G09_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chặng Quảng Châu: nhịp nhanh của những năm gieo hạt","text":"Hãy để ý khoảng cách giữa các mốc ở chặng thứ nhất. Từ ngày Người đặt chân tới Quảng Châu đến khi nhóm Cộng sản đoàn ra đời chỉ khoảng ba tháng. Bốn tháng sau nữa, Hội Việt Nam Cách mạng Thanh niên thành lập, báo Thanh Niên ra số đầu, và Hội Liên hiệp các dân tộc bị áp bức ở Á Đông cũng hình thành. Trong vòng chưa đầy chín tháng, Người đã dựng xong cả bộ khung cho một phong trào.\n\nNhịp nhanh ấy không phải ngẫu nhiên. Người đến Quảng Châu với một kế hoạch đã chín muồi từ những năm ở Paris và Mátxcơva, lại gặp đúng thời điểm thuận lợi: Quốc – Cộng đang hợp tác, chính quyền Quảng Châu cởi mở với những người cách mạng châu Á, và nhóm Tâm tâm xã đã sẵn có những thanh niên nhiệt huyết. Các mốc về Trường Quân sự Hoàng Phố và tiếng bom Sa Diện được đặt vào dòng thời gian để nhắc rằng Người không bắt đầu từ con số không, mà biết kế thừa những gì đã có.","doc":3},{"loai":"ban_co_biet","text":"Mặt trận Việt Minh được thành lập ngày 19/5/1941, trong Hội nghị Trung ương lần thứ tám họp ở Pác Bó do Người chủ trì. Ngày ấy trùng với ngày sinh của Người, chưa đầy bốn tháng sau khi Người vượt cột mốc 108 trở về Tổ quốc.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia; Hồ Chí Minh – Biên niên tiểu sử","doc":4},{"loai":"doan","tieu_de":"Những mốc cần đọc cho đúng","text":"Một số mốc thường bị nhớ nhầm. Hội Việt Nam Cách mạng Thanh niên được thành lập trong tháng 6/1925; báo Thanh Niên ra số đầu ngày 21/6/1925. Con số khoảng 75 học viên các lớp huấn luyện ở Quảng Châu là con số ước tính, được nhiều tài liệu nêu. Sách Đường Kách mệnh in năm 1927 từ các bài giảng, không phải một tác phẩm viết riêng để xuất bản. Hội nghị hợp nhất các tổ chức cộng sản họp từ ngày 6/1 đến ngày 7/2/1930 tại Cửu Long, Hương Cảng, không phải ở Quảng Châu.\n\nVề tên gọi, cần nhớ rằng ở Quảng Châu Người mang tên Lý Thụy, ở Quế Lâm là Hồ Quang; tên Hồ Chí Minh chỉ được dùng từ tháng 8/1942. Vì vậy, khi đọc tài liệu về những năm 1924 – 1941, không nên gọi Người là Hồ Chí Minh như một bí danh đương thời. Cuối cùng, mười ba tháng lao tù được tính từ ngày bị bắt 29/8/1942 đến ngày được trả tự do 10/9/1943; còn ngày Người về tới Pác Bó là tháng 9/1944, gần một năm sau đó.","doc":5},{"loai":"doan","tieu_de":"Khoảng lặng 1927 – 1938","text":"Trên dòng thời gian của gian này, sau tháng 5/1927 là một bước nhảy dài tới mùa thu năm 1938. Khoảng trống ấy không phải những năm Người ngừng hoạt động. Người trở lại Mátxcơva, sang châu Âu, rồi về Xiêm sống giữa bà con Việt kiều trong hai năm 1928 – 1929 (xem gian Thái Lan – Thầu Chín). Đầu năm 1930, Người chủ trì hội nghị hợp nhất thành lập Đảng; năm 1931 bị cảnh sát Anh bắt ở Hồng Kông (xem gian Hồng Kông – Thành lập Đảng). Từ năm 1934 đến năm 1938, Người học tập và làm việc ở Liên Xô (xem gian Liên Xô – Petrograd và Mátxcơva).\n\nTrong những năm ấy, những học trò ở Quảng Châu năm nào đã trưởng thành. Mốc năm 1928 về phong trào vô sản hóa và mốc năm 1930 về hội nghị hợp nhất được đặt vào đây để cho thấy kết quả của chặng thứ nhất: hạt giống gieo ở Quảng Châu đã nảy mầm trên đất nhà, ngay cả khi người gieo hạt đang ở rất xa.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_interior_of_ho_chi_minh_s_former_resi.jpg","chu_thich":"Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh (ảnh chụp năm 2025). Đầu năm 1940, từ Côn Minh, Người nối lại liên lạc với phong trào trong nước.","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"1938 – 1941: đường về ngắn dần","text":"Chặng thứ hai nên được đọc cùng bản đồ. Mùa thu năm 1938, Người rời Mátxcơva, cách Việt Nam hàng vạn cây số. Cuối năm ấy, Người đã ở Quế Lâm, thủ phủ tỉnh Quảng Tây. Năm 1939, Người công tác ở Hồ Nam. Đầu năm 1940, Người tới Côn Minh, nơi có đường sắt nối thẳng về Hải Phòng. Cuối năm 1940, Người đã ở vùng biên giới Quảng Tây, chỉ cách Cao Bằng một chặng đường núi. Ngày 28/1/1941, Người bước qua cột mốc 108.\n\nMỗi mốc là một bước tiến gần hơn về Tổ quốc. Bước ngoặt nằm ở mốc tháng 6/1940: khi nước Pháp đầu hàng phát xít Đức, Người nhận định thời cơ đã đến và quyết định phải về nước ngay. Từ đó, nhịp các mốc dồn dập hẳn lên. Chưa đầy bốn tháng sau ngày về Pác Bó, Mặt trận Việt Minh ra đời, mở đầu thời kỳ Người trực tiếp lãnh đạo cách mạng trong nước.","doc":7},{"loai":"anh","src":"textures/bang_w/G09_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"1942 – 1944: một năm mất, một năm chờ","text":"Chặng thứ ba ngắn về khoảng cách địa lý nhưng dài về thời gian. Người rời Pác Bó giữa tháng 8/1942, chỉ đi được khoảng nửa tháng thì bị bắt ở phố Túc Vinh. Từ đó đến ngày được trả tự do là hơn một năm, trong đó người tù bị giải qua mười ba huyện, mười tám nhà lao (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Sau khi ra tù, Người còn ở lại Liễu Châu gần một năm nữa.\n\nNếu chỉ nhìn con số, đây là hai năm tưởng như bị mất. Nhưng dòng thời gian cũng cho thấy mặt khác. Trong tù, tập thơ Nhật ký trong tù ra đời. Ở Liễu Châu, Người tranh thủ được sự giúp đỡ của phía Trung Quốc và chuẩn bị cán bộ. Và chỉ khoảng một năm sau ngày trở về Pác Bó tháng 9/1944, Cách mạng Tháng Tám thành công.","doc":8},{"loai":"ban_co_biet","text":"Ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó, đã gần ba mươi năm trôi qua kể từ ngày người thanh niên Nguyễn Tất Thành rời bến Nhà Rồng (5/6/1911).","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":9},{"loai":"anh","src":"textures/bang_w/G09_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dòng thời gian trong gian trưng bày","text":"Trong không gian 3D, bảng mốc thời gian được đặt giữa các bảng câu chuyện và các bảng ảnh tư liệu, như một sợi chỉ nối chúng lại với nhau. Khách tham quan có thể đối chiếu từng mốc với hiện vật và hình ảnh trong gian: mốc năm 1925 với ngôi nhà trên đường Văn Minh và dãy nhà kỵ lâu; mốc năm 1924 với cánh cổng Trường Quân sự Hoàng Phố; mốc năm 1940 với nhà lưu niệm ở Côn Minh; mốc năm 1942 – 1943 với những trang bản thảo Nhật ký trong tù.\n\nDòng thời gian cũng gợi mở những câu hỏi để khách tự tìm hiểu tiếp. Vì sao Người luôn chọn những nơi gần biên giới? Vì sao nhịp hoạt động có lúc dồn dập, có lúc lặng đi hàng chục năm? Câu trả lời nằm ở sự kiên nhẫn chờ thời cơ và sự nhạy bén nắm lấy thời cơ, hai phẩm chất mà cả hai mươi năm trên đất Trung Hoa đều cho thấy rõ.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Võ Nguyên Giáp, Những chặng đường lịch sử (hồi ký), NXB Chính trị quốc gia","GS. Song Thành, “Số phận kỳ lạ của bản thảo tập thơ Ngục trung nhật ký”, NXB Chính trị quốc gia Sự thật: https://www.nxbctqg.org.vn/s-phn-k-l-ca-bn-tho-tp-th-qngc-trung-nht-kyq.html","Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)"],"doc":[{"t":"Hai mươi năm trên đất Trung Hoa: dòng thời gian từ Quảng Châu đến ngục Quảng Tây (1924 – 1944). Ba mươi mốc thời gian, trải trên hai mươi năm và hàng nghìn cây số đường đất Trung Hoa. Nếu đặt chúng lên bản đồ, ta sẽ thấy một đường đi kỳ lạ: từ Mátxcơva xuống Quảng Châu, rồi rời xa, rồi quay lại, mỗi lần một gần hơn biên giới Việt Nam. Dòng thời gian này giúp khách tham quan đọc ra quy luật ấy."},{"t":"Ba chặng, một hướng về. Những hoạt động của Người trên đất Trung Quốc chia thành ba chặng rõ rệt. Chặng thứ nhất ở Quảng Châu, từ tháng 11/1924 đến tháng 5/1927, là thời kỳ gieo hạt: lập tổ chức, ra báo, đào tạo cán bộ. Chặng thứ hai, từ cuối năm 1938 đến đầu năm 1941, là hành trình tìm đường về nước qua Diên An, Quế Lâm, Hồ Nam, Côn Minh và vùng biên giới. Chặng thứ ba, từ tháng 8/1942 đến tháng 9/1944, là mười ba tháng lao tù và gần một năm ở Liễu Châu. Giữa chặng thứ nhất và chặng thứ hai là một khoảng lặng hơn mười một năm, khi Người hoạt động ở những nơi khác. Nhìn tổng thể, cả ba chặng có chung một điểm: tất cả đều hướng về trong nước. Trung Quốc là nơi Người chuẩn bị, liên lạc và chờ thời, còn đích đến bao giờ cũng là quê hương. Dòng thời gian dưới đây được sắp theo trật tự ấy, kèm một số mốc của lịch sử Trung Quốc và Việt Nam để người xem hiểu bối cảnh."},{"t":"Các mốc thời gian. 1/1924: Đại hội I Quốc dân Đảng Trung Quốc họp ở Quảng Châu, mở ra thời kỳ hợp tác Quốc – Cộng lần thứ nhất với sự giúp đỡ của Liên Xô. 16/6/1924: Trường Quân sự Hoàng Phố khai giảng khóa đầu tiên trên đảo Trường Châu, Quảng Châu. 19/6/1924: Phạm Hồng Thái ném bom mưu sát Toàn quyền Đông Dương Merlin tại khách sạn Victoria trên đảo Sa Diện, rồi hy sinh trên sông Châu Giang. 10/1924: Nguyễn Ái Quốc rời Mátxcơva, lên đường sang Trung Quốc theo quyết định của Quốc tế Cộng sản. 11/11/1924: Đến Quảng Châu với tên Lý Thụy, làm phiên dịch trong phái bộ cố vấn Liên Xô của Borodin. 2/1925: Chọn những thanh niên tích cực nhất của Tâm tâm xã, lập nhóm Cộng sản đoàn làm hạt nhân bí mật. 6/1925: Thành lập Hội Việt Nam Cách mạng Thanh niên; Tổng bộ gồm Nguyễn Ái Quốc, Hồ Tùng Mậu, Lê Hồng Sơn. 21/6/1925: Báo Thanh Niên ra số đầu tiên; ngày này nay là Ngày Báo chí cách mạng Việt Nam. Giữa năm 1925: Phan Bội Châu bị mật thám Pháp bắt ở Thượng Hải, giải về nước xét xử, sau bị an trí ở Huế. 7/1925: Cùng các nhà cách mạng châu Á lập Hội Liên hiệp các dân tộc bị áp bức ở Á Đông. 1925 – 1927: Mở các lớp huấn luyện chính trị tại đường Văn Minh cho khoảng 75 học viên; nhiều người được gửi vào Trường Quân sự Hoàng Phố hoặc sang Liên Xô học. 1926: Trần Phú, Phạm Văn Đồng sang Quảng Châu dự lớp huấn luyện do Nguyễn Ái Quốc tổ chức. 1927: Các bài giảng được in thành sách Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ấn hành. 12/4/1927: Tưởng Giới Thạch làm chính biến ở Thượng Hải, quay sang đàn áp những người cộng sản; ít ngày sau cuộc khủng bố lan tới Quảng Châu. Đầu tháng 5/1927: Nguyễn Ái Quốc bí mật rời Quảng Châu sang Hồng Kông, rồi trở lại Mátxcơva. 1928: Hội Việt Nam Cách mạng Thanh niên phát động phong trào vô sản hóa, đưa hội viên vào hầm mỏ, nhà máy, đồn điền. 6/1 – 7/2/1930: Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam tại Cửu Long, Hương Cảng. Mùa thu 1938: Rời Mátxcơva trở lại Trung Quốc, tới Diên An, căn cứ của Đảng Cộng sản Trung Quốc. Cuối năm 1938: Đến Quế Lâm, làm việc tại Văn phòng Bát lộ quân trong vai một sĩ quan tên Hồ Quang. 1939: Công tác tại lớp huấn luyện du kích ở Hồ Nam do tướng Diệp Kiếm Anh phụ trách. Đầu năm 1940: Đến Côn Minh, bắt liên lạc với Ban Hải ngoại của Đảng và qua đó với cơ sở trong nước. 6/1940: Nước Pháp đầu hàng phát xít Đức; tại Côn Minh, Người gặp Phạm Văn Đồng, Võ Nguyên Giáp và quyết định gấp rút về nước. Cuối năm 1940: Xuống vùng biên giới Quảng Tây giáp Cao Bằng, mở lớp huấn luyện cho cán bộ từ trong nước sang. 28/1/1941: Vượt cột mốc 108 về nước, đến Pác Bó, Cao Bằng. 5/1941: Chủ trì Hội nghị Trung ương lần thứ tám ở Pác Bó; Mặt trận Việt Minh được thành lập ngày 19/5/1941. Giữa tháng 8/1942: Lấy tên Hồ Chí Minh, lên đường sang Trung Quốc với tư cách đại biểu của Việt Minh. 29/8/1942: Bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ ở phố Túc Vinh, Quảng Tây, vì bị nghi là gián điệp. 8/1942 – 9/1943: Bị giải qua mười ba huyện, mười tám nhà lao của Quảng Tây; hơn một trăm bài thơ Nhật ký trong tù ra đời. 10/9/1943: Được trả tự do; ở lại Liễu Châu, hoạt động trong Việt Nam Cách mạng Đồng minh Hội. 9/1944: Trở về Pác Bó, tiếp tục trực tiếp lãnh đạo cách mạng trong nước."},{"t":"Chặng Quảng Châu: nhịp nhanh của những năm gieo hạt. Hãy để ý khoảng cách giữa các mốc ở chặng thứ nhất. Từ ngày Người đặt chân tới Quảng Châu đến khi nhóm Cộng sản đoàn ra đời chỉ khoảng ba tháng. Bốn tháng sau nữa, Hội Việt Nam Cách mạng Thanh niên thành lập, báo Thanh Niên ra số đầu, và Hội Liên hiệp các dân tộc bị áp bức ở Á Đông cũng hình thành. Trong vòng chưa đầy chín tháng, Người đã dựng xong cả bộ khung cho một phong trào. Nhịp nhanh ấy không phải ngẫu nhiên. Người đến Quảng Châu với một kế hoạch đã chín muồi từ những năm ở Paris và Mátxcơva, lại gặp đúng thời điểm thuận lợi: Quốc – Cộng đang hợp tác, chính quyền Quảng Châu cởi mở với những người cách mạng châu Á, và nhóm Tâm tâm xã đã sẵn có những thanh niên nhiệt huyết. Các mốc về Trường Quân sự Hoàng Phố và tiếng bom Sa Diện được đặt vào dòng thời gian để nhắc rằng Người không bắt đầu từ con số không, mà biết kế thừa những gì đã có."},{"t":"Bạn có biết? Mặt trận Việt Minh được thành lập ngày 19/5/1941, trong Hội nghị Trung ương lần thứ tám họp ở Pác Bó do Người chủ trì. Ngày ấy trùng với ngày sinh của Người, chưa đầy bốn tháng sau khi Người vượt cột mốc 108 trở về Tổ quốc."},{"t":"Những mốc cần đọc cho đúng. Một số mốc thường bị nhớ nhầm. Hội Việt Nam Cách mạng Thanh niên được thành lập trong tháng 6/1925; báo Thanh Niên ra số đầu ngày 21/6/1925. Con số khoảng 75 học viên các lớp huấn luyện ở Quảng Châu là con số ước tính, được nhiều tài liệu nêu. Sách Đường Kách mệnh in năm 1927 từ các bài giảng, không phải một tác phẩm viết riêng để xuất bản. Hội nghị hợp nhất các tổ chức cộng sản họp từ ngày 6/1 đến ngày 7/2/1930 tại Cửu Long, Hương Cảng, không phải ở Quảng Châu. Về tên gọi, cần nhớ rằng ở Quảng Châu Người mang tên Lý Thụy, ở Quế Lâm là Hồ Quang; tên Hồ Chí Minh chỉ được dùng từ tháng 8/1942. Vì vậy, khi đọc tài liệu về những năm 1924 – 1941, không nên gọi Người là Hồ Chí Minh như một bí danh đương thời. Cuối cùng, mười ba tháng lao tù được tính từ ngày bị bắt 29/8/1942 đến ngày được trả tự do 10/9/1943; còn ngày Người về tới Pác Bó là tháng 9/1944, gần một năm sau đó."},{"t":"Khoảng lặng 1927 – 1938. Trên dòng thời gian của gian này, sau tháng 5/1927 là một bước nhảy dài tới mùa thu năm 1938. Khoảng trống ấy không phải những năm Người ngừng hoạt động. Người trở lại Mátxcơva, sang châu Âu, rồi về Xiêm sống giữa bà con Việt kiều trong hai năm 1928 – 1929 (xem gian Thái Lan – Thầu Chín). Đầu năm 1930, Người chủ trì hội nghị hợp nhất thành lập Đảng; năm 1931 bị cảnh sát Anh bắt ở Hồng Kông (xem gian Hồng Kông – Thành lập Đảng). Từ năm 1934 đến năm 1938, Người học tập và làm việc ở Liên Xô (xem gian Liên Xô – Petrograd và Mátxcơva). Trong những năm ấy, những học trò ở Quảng Châu năm nào đã trưởng thành. Mốc năm 1928 về phong trào vô sản hóa và mốc năm 1930 về hội nghị hợp nhất được đặt vào đây để cho thấy kết quả của chặng thứ nhất: hạt giống gieo ở Quảng Châu đã nảy mầm trên đất nhà, ngay cả khi người gieo hạt đang ở rất xa."},{"t":"1938 – 1941: đường về ngắn dần. Chặng thứ hai nên được đọc cùng bản đồ. Mùa thu năm 1938, Người rời Mátxcơva, cách Việt Nam hàng vạn cây số. Cuối năm ấy, Người đã ở Quế Lâm, thủ phủ tỉnh Quảng Tây. Năm 1939, Người công tác ở Hồ Nam. Đầu năm 1940, Người tới Côn Minh, nơi có đường sắt nối thẳng về Hải Phòng. Cuối năm 1940, Người đã ở vùng biên giới Quảng Tây, chỉ cách Cao Bằng một chặng đường núi. Ngày 28/1/1941, Người bước qua cột mốc 108. Mỗi mốc là một bước tiến gần hơn về Tổ quốc. Bước ngoặt nằm ở mốc tháng 6/1940: khi nước Pháp đầu hàng phát xít Đức, Người nhận định thời cơ đã đến và quyết định phải về nước ngay. Từ đó, nhịp các mốc dồn dập hẳn lên. Chưa đầy bốn tháng sau ngày về Pác Bó, Mặt trận Việt Minh ra đời, mở đầu thời kỳ Người trực tiếp lãnh đạo cách mạng trong nước."},{"t":"1942 – 1944: một năm mất, một năm chờ. Chặng thứ ba ngắn về khoảng cách địa lý nhưng dài về thời gian. Người rời Pác Bó giữa tháng 8/1942, chỉ đi được khoảng nửa tháng thì bị bắt ở phố Túc Vinh. Từ đó đến ngày được trả tự do là hơn một năm, trong đó người tù bị giải qua mười ba huyện, mười tám nhà lao (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Sau khi ra tù, Người còn ở lại Liễu Châu gần một năm nữa. Nếu chỉ nhìn con số, đây là hai năm tưởng như bị mất. Nhưng dòng thời gian cũng cho thấy mặt khác. Trong tù, tập thơ Nhật ký trong tù ra đời. Ở Liễu Châu, Người tranh thủ được sự giúp đỡ của phía Trung Quốc và chuẩn bị cán bộ. Và chỉ khoảng một năm sau ngày trở về Pác Bó tháng 9/1944, Cách mạng Tháng Tám thành công."},{"t":"Bạn có biết? Ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó, đã gần ba mươi năm trôi qua kể từ ngày người thanh niên Nguyễn Tất Thành rời bến Nhà Rồng (5/6/1911)."},{"t":"Dòng thời gian trong gian trưng bày. Trong không gian 3D, bảng mốc thời gian được đặt giữa các bảng câu chuyện và các bảng ảnh tư liệu, như một sợi chỉ nối chúng lại với nhau. Khách tham quan có thể đối chiếu từng mốc với hiện vật và hình ảnh trong gian: mốc năm 1925 với ngôi nhà trên đường Văn Minh và dãy nhà kỵ lâu; mốc năm 1924 với cánh cổng Trường Quân sự Hoàng Phố; mốc năm 1940 với nhà lưu niệm ở Côn Minh; mốc năm 1942 – 1943 với những trang bản thảo Nhật ký trong tù. Dòng thời gian cũng gợi mở những câu hỏi để khách tự tìm hiểu tiếp. Vì sao Người luôn chọn những nơi gần biên giới? Vì sao nhịp hoạt động có lúc dồn dập, có lúc lặng đi hàng chục năm? Câu trả lời nằm ở sự kiên nhẫn chờ thời cơ và sự nhạy bén nắm lấy thời cơ, hai phẩm chất mà cả hai mươi năm trên đất Trung Hoa đều cho thấy rõ."}],"so_chu":1382},{"i":4,"tieu_de_bang":"Nguyễn Ái Quốc năm 1924","tieu_de":"Gương mặt năm 1924: Nguyễn Ái Quốc giữa Mátxcơva và Quảng Châu","sapo":"Một tấm ảnh đen trắng, không rõ người chụp, chỉ ghi năm 1924. Người trong ảnh vừa bước sang tuổi ba mươi tư, đã nổi tiếng trên báo chí Paris, nhưng gương mặt thì mật thám Pháp vẫn phải săn tìm. Chỉ trong năm ấy, Người đi từ giá rét Mátxcơva đến cái nắng Quảng Châu, từ diễn đàn Quốc tế Cộng sản đến một cái tên mới: Lý Thụy.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tấm ảnh chỉ ghi một con số","text":"Dưới tấm chân dung đặt ở gian Quảng Châu, dòng ghi chú rất ngắn: không rõ người chụp, chụp năm 1924, ảnh thuộc phạm vi công cộng. Không có tên hiệu ảnh, không có ngày tháng cụ thể. Nhưng con số 1924 đủ để đặt gương mặt ấy vào một trong những năm đổi thay lớn nhất của cuộc đời Nguyễn Ái Quốc.\n\nNăm ấy Người tròn ba mươi tư tuổi. Cái tên Nguyễn Ái Quốc đã khiến nhà cầm quyền Pháp chú ý từ năm 1919, khi bản Yêu sách của nhân dân An Nam được gửi tới Hội nghị Versailles; rồi đến tờ Người cùng khổ và hàng loạt bài báo tố cáo chế độ thực dân. Tên tuổi thì nhiều người biết, còn gương mặt thật thì ít ai được thấy. Những tấm ảnh chụp Người ở giai đoạn này còn lại rất ít. Vì vậy, mỗi tấm đều là một mảnh ghép quý cho ai muốn hình dung con người đứng sau cái tên đã làm chính quyền thuộc địa bất an.","doc":1},{"loai":"doan","tieu_de":"Chuyến đi bí mật mùa hè 1923","text":"Câu chuyện của tấm ảnh bắt đầu từ một năm trước. Ngày 13/6/1923, Nguyễn Ái Quốc lặng lẽ rời Paris, nơi Người đã sống và hoạt động nhiều năm dưới con mắt theo dõi thường trực của mật thám. Chuyến đi được chuẩn bị kín đáo để tránh sự chú ý. Ngày 30/6/1923, Người tới Pêtrôgrát, rồi lên tàu hỏa về Mátxcơva.\n\nVới người thanh niên đã ra đi từ bến Nhà Rồng năm 1911, đây là lần đầu đặt chân lên đất nước của Lênin. Ba năm trước, ở Paris, Người đã đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, và tìm thấy ở đó lời giải đáp mình kiếm tìm bấy lâu. Giờ đây, Người đến tận nơi để học tập, để làm việc, và để tìm cách đưa những tư tưởng ấy về gần Tổ quốc.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc năm 1924”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mùa thu đầu tiên ở Mátxcơva","text":"Những tháng đầu ở Mátxcơva, Người hòa ngay vào nhịp làm việc của các tổ chức quốc tế. Từ ngày 12 đến 15/10/1923, Người dự Đại hội lần thứ nhất của Quốc tế Nông dân, phát biểu về tình cảnh người nông dân ở các nước thuộc địa, và được bầu vào Ban Chấp hành của tổ chức này. Với một người lớn lên ở làng quê xứ Nghệ, nói về người nông dân Đông Dương không phải là chuyện lý thuyết xa xôi.\n\nCuối năm 1923, Người theo học một lớp ngắn hạn ở Trường Đại học Phương Đông, ngôi trường đào tạo cán bộ cho các dân tộc châu Á. Cũng trong những tháng ấy, nhà thơ Nga Ôxíp Manđenxtam tìm đến gặp Người. Bài phỏng vấn của ông đăng trên tạp chí Ngọn lửa nhỏ, tức Ogoniok, số ra ngày 23/12/1923. Đó là một trong những bức chân dung bằng chữ sớm nhất về Nguyễn Ái Quốc, do một nghệ sĩ lớn của văn học Nga viết.","doc":3},{"loai":"trich","text":"Từ Nguyễn Ái Quốc đã tỏa ra một thứ văn hóa, không phải văn hóa châu Âu, mà có lẽ là một nền văn hóa tương lai.","nguoi":"Nhà thơ Ôxíp Manđenxtam","nguon_ten":"Bài phỏng vấn Nguyễn Ái Quốc trên tạp chí Ogoniok, Mátxcơva, ngày 23/12/1923 (bản dịch tiếng Việt)","doc":4},{"loai":"doan","tieu_de":"Mùa đông Lênin mất","text":"Người đến Mátxcơva với mong ước được gặp Lênin. Nhưng khi ấy Lênin đã ốm nặng nhiều tháng và không còn tiếp khách. Ngày 21/1/1924, Lênin qua đời. Tin dữ đến giữa mùa đông khắc nghiệt của nước Nga. Suốt những ngày sau đó, dòng người nối nhau trong giá rét vào viếng vị lãnh tụ, cho tới lễ tang ngày 27/1/1924.\n\nTheo lời kể trong sách của Trần Dân Tiên, Nguyễn Ái Quốc cũng đứng trong dòng người ấy, chịu cái rét buốt mà một người quen khí hậu nhiệt đới khó hình dung, đến mức bị tê cóng. Ít ngày sau, báo Sự thật đăng bài Người viết về Lênin. Với Người, Lênin là người đã chỉ ra con đường giải phóng cho các dân tộc thuộc địa. Không kịp gặp mặt, Người tiếp nối con đường ấy bằng việc làm, và suốt đời vẫn nhắc đến Lênin như người thầy của cách mạng ở các nước thuộc địa.","doc":5},{"loai":"ban_co_biet","text":"Năm 1924, Nguyễn Ái Quốc còn viết bài Hành hình kiểu Linsơ, tố cáo nạn người da đen bị hành hình không qua xét xử ở Mỹ, đăng trên tờ Thư tín quốc tế của Quốc tế Cộng sản. Những năm trước đó, Người từng sống và làm việc một thời gian ở Mỹ.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","chu_thich":"Chân dung Nguyễn Ái Quốc năm 1924, năm Người rời Mátxcơva sang Quảng Châu với tên Lý Thụy. Không rõ người chụp; ảnh thuộc phạm vi công cộng.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cán bộ Ban Phương Đông","text":"Ngày 14/4/1924, Nguyễn Ái Quốc chính thức được xác nhận là cán bộ Ban Phương Đông của Quốc tế Cộng sản, bộ phận theo dõi phong trào cách mạng ở các nước châu Á. Công việc hằng ngày của Người là nghiên cứu, viết báo và soạn báo cáo về tình hình các thuộc địa. Năm 1924, Người viết Báo cáo về Bắc Kỳ, Trung Kỳ và Nam Kỳ, trình bày với Quốc tế Cộng sản về đời sống xã hội và phong trào yêu nước ở ba kỳ.\n\nCùng năm, Người viết Trung Quốc và thanh niên Trung Quốc, bàn về những chuyển động của nước láng giềng rộng lớn. Những trang tố cáo chế độ thuộc địa mà Người tích lũy từ những năm ở Paris cũng dần được hoàn thiện; năm 1925, chúng được in thành cuốn Bản án chế độ thực dân Pháp tại Paris. Nhìn lại, năm 1924 là năm Người tổng kết những gì đã thấy, đã viết, trước khi bước sang một công việc khác hẳn: trực tiếp tổ chức.","doc":7},{"loai":"doan","tieu_de":"Tiếng nói của thuộc địa tại Đại hội V","text":"Từ ngày 17/6 đến 8/7/1924, Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva. Nguyễn Ái Quốc dự đại hội và nhiều lần lên diễn đàn, trong đó có bài phát biểu tại phiên họp thứ tám, ngày 23/6/1924. Người nói thẳng rằng các đảng cộng sản ở những nước có thuộc địa như Pháp, Anh chưa quan tâm đúng mức đến phong trào giải phóng của các dân tộc bị áp bức.\n\nLập luận của Người rất rõ: chủ nghĩa tư bản ở chính quốc sống nhờ bóc lột thuộc địa, nên muốn đánh đổ nó thì không thể bỏ quên thuộc địa. Người dẫn ra những sự việc cụ thể về đời sống của người dân dưới ách cai trị thực dân. Giữa một đại hội mà phần đông đại biểu đến từ châu Âu, tiếng nói ấy nhắc mọi người rằng số phận của hàng trăm triệu người ở châu Á, châu Phi cũng là một phần của cuộc đấu tranh chung.","doc":8},{"loai":"trich","text":"Nọc độc và sức sống của con rắn độc tư bản chủ nghĩa đang tập trung ở các thuộc địa hơn là ở chính quốc.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Phát biểu tại Đại hội lần thứ V Quốc tế Cộng sản, năm 1924 – Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":9},{"loai":"anh","src":"textures/bang_w/G09_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc năm 1924”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Xin về phương Đông","text":"Mátxcơva mở ra cho Người một tầm nhìn rộng, nhưng lại cách Tổ quốc hàng nghìn cây số. Ngay trong những tháng ở đây, Người nhiều lần bày tỏ mong muốn được về hoạt động ở phương Đông, gần Đông Dương hơn. Thời cơ đến từ phía Quảng Châu. Từ đầu năm 1924, Quốc dân Đảng và Đảng Cộng sản Trung Quốc hợp tác, chính quyền Tôn Trung Sơn có đoàn cố vấn Liên Xô bên cạnh.\n\nTháng 6/1924, tiếng bom Sa Diện của Phạm Hồng Thái cho thấy ở thành phố ấy đã có những thanh niên Việt Nam sẵn sàng hy sinh (xem chuyên đề Từ tiếng bom Sa Diện đến Hội Thanh niên). Quốc tế Cộng sản quyết định cử Người sang Quảng Châu. Cuối tháng 10/1924, Người rời Mátxcơva, bắt đầu chặng đường dài sang phương Đông. Trong đầu Người là một kế hoạch đã chín muồi: tìm những thanh niên yêu nước, huấn luyện họ, và lập nên một tổ chức cách mạng của người Việt Nam.","doc":10},{"loai":"moc","items":[["13/6/1923","Bí mật rời Paris sang Liên Xô"],["30/6/1923","Đến Pêtrôgrát, rồi lên Mátxcơva"],["12 – 15/10/1923","Dự Đại hội I Quốc tế Nông dân, được bầu vào Ban Chấp hành"],["Cuối năm 1923","Học lớp ngắn hạn tại Trường Đại học Phương Đông"],["23/12/1923","Tạp chí Ogoniok đăng bài phỏng vấn của nhà thơ Manđenxtam"],["21/1/1924","Lênin qua đời"],["Cuối tháng 1/1924","Báo Sự thật đăng bài Người viết về Lênin"],["14/4/1924","Được xác nhận là cán bộ Ban Phương Đông của Quốc tế Cộng sản"],["17/6 – 8/7/1924","Dự Đại hội V Quốc tế Cộng sản; phát biểu tại phiên họp thứ tám ngày 23/6"],["Cuối tháng 10/1924","Rời Mátxcơva sang phương Đông"],["11/11/1924","Đến Quảng Châu với tên Lý Thụy"]],"doc":11},{"loai":"doan","tieu_de":"Từ Nguyễn Ái Quốc đến Lý Thụy","text":"Ngày 11/11/1924, Người tới Quảng Châu. Giấy tờ mang tên Lý Thụy, công việc công khai là phiên dịch trong đoàn cố vấn của Borodin. Từ đây, cái tên Nguyễn Ái Quốc vẫn xuất hiện trên sách báo, nhưng con người thật đứng sau nó hoạt động dưới những bí danh khác nhau. Mật thám Pháp biết Nguyễn Ái Quốc là ai, nhưng rất khó biết Người đang ở đâu và mang tên gì.\n\nVì thế, những tấm ảnh chụp Người năm 1924 càng thêm giá trị. Chúng lưu lại gương mặt của một nhà cách mạng mà suốt nhiều năm sau, bộ máy mật thám thuộc địa vẫn ráo riết truy tìm khắp châu Á. Với người xem hôm nay, tấm ảnh là điểm nối giữa hai chặng đời. Phía trước là những năm viết báo, diễn thuyết ở Paris và Mátxcơva. Phía sau là những năm lặng lẽ đào tạo cán bộ, gây dựng tổ chức ngay sát cửa ngõ Tổ quốc.","doc":12},{"loai":"ban_co_biet","text":"Theo Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, khi tới Pêtrôgrát ngày 30/6/1923, Nguyễn Ái Quốc là người Việt Nam đầu tiên có mặt trên đất nước của Lênin. Để giữ bí mật, Người đi với giấy tờ mang tên Chen Vang.","nguon_ten":"Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch (nhasanbacho.vn); Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":13},{"loai":"anh","src":"textures/bang_w/G09_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc năm 1924”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Trong gian Quảng Châu của Bảo tàng Hành trình 3D, tấm chân dung năm 1924 như một lời chào ở ngưỡng cửa: gương mặt Nguyễn Ái Quốc ngay trước khi trở thành Lý Thụy. Bước tiếp vào dãy nhà kỵ lâu và lớp học phục dựng trên phố Văn Minh, khách tham quan có thể nhớ rằng người thầy của lớp học ấy vừa đi qua một năm học tập và làm việc dày đặc ở Mátxcơva.\n\nDấu vết của năm 1924 vẫn còn ở nhiều nơi. Các bài báo, bài phát biểu của Người năm ấy được in trong tập 1 bộ Hồ Chí Minh Toàn tập. Kho lưu trữ của Quốc tế Cộng sản, nay thuộc Lưu trữ Quốc gia Nga về lịch sử chính trị – xã hội ở Mátxcơva, còn giữ nhiều tài liệu về những năm Người làm việc tại đây. Mátxcơva hôm nay có quảng trường mang tên Hồ Chí Minh, với tượng đài Người khánh thành năm 1990. Ở Hà Nội, Bảo tàng Hồ Chí Minh giới thiệu chặng đường này bằng hiện vật, ảnh và tài liệu.","doc":14}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924)”: https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)"],"doc":[{"t":"Gương mặt năm 1924: Nguyễn Ái Quốc giữa Mátxcơva và Quảng Châu. Một tấm ảnh đen trắng, không rõ người chụp, chỉ ghi năm 1924. Người trong ảnh vừa bước sang tuổi ba mươi tư, đã nổi tiếng trên báo chí Paris, nhưng gương mặt thì mật thám Pháp vẫn phải săn tìm. Chỉ trong năm ấy, Người đi từ giá rét Mátxcơva đến cái nắng Quảng Châu, từ diễn đàn Quốc tế Cộng sản đến một cái tên mới: Lý Thụy."},{"t":"Tấm ảnh chỉ ghi một con số. Dưới tấm chân dung đặt ở gian Quảng Châu, dòng ghi chú rất ngắn: không rõ người chụp, chụp năm 1924, ảnh thuộc phạm vi công cộng. Không có tên hiệu ảnh, không có ngày tháng cụ thể. Nhưng con số 1924 đủ để đặt gương mặt ấy vào một trong những năm đổi thay lớn nhất của cuộc đời Nguyễn Ái Quốc. Năm ấy Người tròn ba mươi tư tuổi. Cái tên Nguyễn Ái Quốc đã khiến nhà cầm quyền Pháp chú ý từ năm 1919, khi bản Yêu sách của nhân dân An Nam được gửi tới Hội nghị Versailles; rồi đến tờ Người cùng khổ và hàng loạt bài báo tố cáo chế độ thực dân. Tên tuổi thì nhiều người biết, còn gương mặt thật thì ít ai được thấy. Những tấm ảnh chụp Người ở giai đoạn này còn lại rất ít. Vì vậy, mỗi tấm đều là một mảnh ghép quý cho ai muốn hình dung con người đứng sau cái tên đã làm chính quyền thuộc địa bất an."},{"t":"Chuyến đi bí mật mùa hè 1923. Câu chuyện của tấm ảnh bắt đầu từ một năm trước. Ngày 13/6/1923, Nguyễn Ái Quốc lặng lẽ rời Paris, nơi Người đã sống và hoạt động nhiều năm dưới con mắt theo dõi thường trực của mật thám. Chuyến đi được chuẩn bị kín đáo để tránh sự chú ý. Ngày 30/6/1923, Người tới Pêtrôgrát, rồi lên tàu hỏa về Mátxcơva. Với người thanh niên đã ra đi từ bến Nhà Rồng năm 1911, đây là lần đầu đặt chân lên đất nước của Lênin. Ba năm trước, ở Paris, Người đã đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, và tìm thấy ở đó lời giải đáp mình kiếm tìm bấy lâu. Giờ đây, Người đến tận nơi để học tập, để làm việc, và để tìm cách đưa những tư tưởng ấy về gần Tổ quốc."},{"t":"Mùa thu đầu tiên ở Mátxcơva. Những tháng đầu ở Mátxcơva, Người hòa ngay vào nhịp làm việc của các tổ chức quốc tế. Từ ngày 12 đến 15/10/1923, Người dự Đại hội lần thứ nhất của Quốc tế Nông dân, phát biểu về tình cảnh người nông dân ở các nước thuộc địa, và được bầu vào Ban Chấp hành của tổ chức này. Với một người lớn lên ở làng quê xứ Nghệ, nói về người nông dân Đông Dương không phải là chuyện lý thuyết xa xôi. Cuối năm 1923, Người theo học một lớp ngắn hạn ở Trường Đại học Phương Đông, ngôi trường đào tạo cán bộ cho các dân tộc châu Á. Cũng trong những tháng ấy, nhà thơ Nga Ôxíp Manđenxtam tìm đến gặp Người. Bài phỏng vấn của ông đăng trên tạp chí Ngọn lửa nhỏ, tức Ogoniok, số ra ngày 23/12/1923. Đó là một trong những bức chân dung bằng chữ sớm nhất về Nguyễn Ái Quốc, do một nghệ sĩ lớn của văn học Nga viết."},{"t":"Từ Nguyễn Ái Quốc đã tỏa ra một thứ văn hóa, không phải văn hóa châu Âu, mà có lẽ là một nền văn hóa tương lai. — Nhà thơ Ôxíp Manđenxtam"},{"t":"Mùa đông Lênin mất. Người đến Mátxcơva với mong ước được gặp Lênin. Nhưng khi ấy Lênin đã ốm nặng nhiều tháng và không còn tiếp khách. Ngày 21/1/1924, Lênin qua đời. Tin dữ đến giữa mùa đông khắc nghiệt của nước Nga. Suốt những ngày sau đó, dòng người nối nhau trong giá rét vào viếng vị lãnh tụ, cho tới lễ tang ngày 27/1/1924. Theo lời kể trong sách của Trần Dân Tiên, Nguyễn Ái Quốc cũng đứng trong dòng người ấy, chịu cái rét buốt mà một người quen khí hậu nhiệt đới khó hình dung, đến mức bị tê cóng. Ít ngày sau, báo Sự thật đăng bài Người viết về Lênin. Với Người, Lênin là người đã chỉ ra con đường giải phóng cho các dân tộc thuộc địa. Không kịp gặp mặt, Người tiếp nối con đường ấy bằng việc làm, và suốt đời vẫn nhắc đến Lênin như người thầy của cách mạng ở các nước thuộc địa."},{"t":"Bạn có biết? Năm 1924, Nguyễn Ái Quốc còn viết bài Hành hình kiểu Linsơ, tố cáo nạn người da đen bị hành hình không qua xét xử ở Mỹ, đăng trên tờ Thư tín quốc tế của Quốc tế Cộng sản. Những năm trước đó, Người từng sống và làm việc một thời gian ở Mỹ."},{"t":"Cán bộ Ban Phương Đông. Ngày 14/4/1924, Nguyễn Ái Quốc chính thức được xác nhận là cán bộ Ban Phương Đông của Quốc tế Cộng sản, bộ phận theo dõi phong trào cách mạng ở các nước châu Á. Công việc hằng ngày của Người là nghiên cứu, viết báo và soạn báo cáo về tình hình các thuộc địa. Năm 1924, Người viết Báo cáo về Bắc Kỳ, Trung Kỳ và Nam Kỳ, trình bày với Quốc tế Cộng sản về đời sống xã hội và phong trào yêu nước ở ba kỳ. Cùng năm, Người viết Trung Quốc và thanh niên Trung Quốc, bàn về những chuyển động của nước láng giềng rộng lớn. Những trang tố cáo chế độ thuộc địa mà Người tích lũy từ những năm ở Paris cũng dần được hoàn thiện; năm 1925, chúng được in thành cuốn Bản án chế độ thực dân Pháp tại Paris. Nhìn lại, năm 1924 là năm Người tổng kết những gì đã thấy, đã viết, trước khi bước sang một công việc khác hẳn: trực tiếp tổ chức."},{"t":"Tiếng nói của thuộc địa tại Đại hội V. Từ ngày 17/6 đến 8/7/1924, Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva. Nguyễn Ái Quốc dự đại hội và nhiều lần lên diễn đàn, trong đó có bài phát biểu tại phiên họp thứ tám, ngày 23/6/1924. Người nói thẳng rằng các đảng cộng sản ở những nước có thuộc địa như Pháp, Anh chưa quan tâm đúng mức đến phong trào giải phóng của các dân tộc bị áp bức. Lập luận của Người rất rõ: chủ nghĩa tư bản ở chính quốc sống nhờ bóc lột thuộc địa, nên muốn đánh đổ nó thì không thể bỏ quên thuộc địa. Người dẫn ra những sự việc cụ thể về đời sống của người dân dưới ách cai trị thực dân. Giữa một đại hội mà phần đông đại biểu đến từ châu Âu, tiếng nói ấy nhắc mọi người rằng số phận của hàng trăm triệu người ở châu Á, châu Phi cũng là một phần của cuộc đấu tranh chung."},{"t":"Nọc độc và sức sống của con rắn độc tư bản chủ nghĩa đang tập trung ở các thuộc địa hơn là ở chính quốc. — Nguyễn Ái Quốc"},{"t":"Xin về phương Đông. Mátxcơva mở ra cho Người một tầm nhìn rộng, nhưng lại cách Tổ quốc hàng nghìn cây số. Ngay trong những tháng ở đây, Người nhiều lần bày tỏ mong muốn được về hoạt động ở phương Đông, gần Đông Dương hơn. Thời cơ đến từ phía Quảng Châu. Từ đầu năm 1924, Quốc dân Đảng và Đảng Cộng sản Trung Quốc hợp tác, chính quyền Tôn Trung Sơn có đoàn cố vấn Liên Xô bên cạnh. Tháng 6/1924, tiếng bom Sa Diện của Phạm Hồng Thái cho thấy ở thành phố ấy đã có những thanh niên Việt Nam sẵn sàng hy sinh (xem chuyên đề Từ tiếng bom Sa Diện đến Hội Thanh niên). Quốc tế Cộng sản quyết định cử Người sang Quảng Châu. Cuối tháng 10/1924, Người rời Mátxcơva, bắt đầu chặng đường dài sang phương Đông. Trong đầu Người là một kế hoạch đã chín muồi: tìm những thanh niên yêu nước, huấn luyện họ, và lập nên một tổ chức cách mạng của người Việt Nam."},{"t":"Các mốc thời gian. 13/6/1923: Bí mật rời Paris sang Liên Xô. 30/6/1923: Đến Pêtrôgrát, rồi lên Mátxcơva. 12 – 15/10/1923: Dự Đại hội I Quốc tế Nông dân, được bầu vào Ban Chấp hành. Cuối năm 1923: Học lớp ngắn hạn tại Trường Đại học Phương Đông. 23/12/1923: Tạp chí Ogoniok đăng bài phỏng vấn của nhà thơ Manđenxtam. 21/1/1924: Lênin qua đời. Cuối tháng 1/1924: Báo Sự thật đăng bài Người viết về Lênin. 14/4/1924: Được xác nhận là cán bộ Ban Phương Đông của Quốc tế Cộng sản. 17/6 – 8/7/1924: Dự Đại hội V Quốc tế Cộng sản; phát biểu tại phiên họp thứ tám ngày 23/6. Cuối tháng 10/1924: Rời Mátxcơva sang phương Đông. 11/11/1924: Đến Quảng Châu với tên Lý Thụy."},{"t":"Từ Nguyễn Ái Quốc đến Lý Thụy. Ngày 11/11/1924, Người tới Quảng Châu. Giấy tờ mang tên Lý Thụy, công việc công khai là phiên dịch trong đoàn cố vấn của Borodin. Từ đây, cái tên Nguyễn Ái Quốc vẫn xuất hiện trên sách báo, nhưng con người thật đứng sau nó hoạt động dưới những bí danh khác nhau. Mật thám Pháp biết Nguyễn Ái Quốc là ai, nhưng rất khó biết Người đang ở đâu và mang tên gì. Vì thế, những tấm ảnh chụp Người năm 1924 càng thêm giá trị. Chúng lưu lại gương mặt của một nhà cách mạng mà suốt nhiều năm sau, bộ máy mật thám thuộc địa vẫn ráo riết truy tìm khắp châu Á. Với người xem hôm nay, tấm ảnh là điểm nối giữa hai chặng đời. Phía trước là những năm viết báo, diễn thuyết ở Paris và Mátxcơva. Phía sau là những năm lặng lẽ đào tạo cán bộ, gây dựng tổ chức ngay sát cửa ngõ Tổ quốc."},{"t":"Bạn có biết? Theo Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, khi tới Pêtrôgrát ngày 30/6/1923, Nguyễn Ái Quốc là người Việt Nam đầu tiên có mặt trên đất nước của Lênin. Để giữ bí mật, Người đi với giấy tờ mang tên Chen Vang."},{"t":"Dấu tích hôm nay. Trong gian Quảng Châu của Bảo tàng Hành trình 3D, tấm chân dung năm 1924 như một lời chào ở ngưỡng cửa: gương mặt Nguyễn Ái Quốc ngay trước khi trở thành Lý Thụy. Bước tiếp vào dãy nhà kỵ lâu và lớp học phục dựng trên phố Văn Minh, khách tham quan có thể nhớ rằng người thầy của lớp học ấy vừa đi qua một năm học tập và làm việc dày đặc ở Mátxcơva. Dấu vết của năm 1924 vẫn còn ở nhiều nơi. Các bài báo, bài phát biểu của Người năm ấy được in trong tập 1 bộ Hồ Chí Minh Toàn tập. Kho lưu trữ của Quốc tế Cộng sản, nay thuộc Lưu trữ Quốc gia Nga về lịch sử chính trị – xã hội ở Mátxcơva, còn giữ nhiều tài liệu về những năm Người làm việc tại đây. Mátxcơva hôm nay có quảng trường mang tên Hồ Chí Minh, với tượng đài Người khánh thành năm 1990. Ở Hà Nội, Bảo tàng Hồ Chí Minh giới thiệu chặng đường này bằng hiện vật, ảnh và tài liệu."}],"so_chu":1749},{"i":5,"tieu_de_bang":"Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam","tieu_de":"Số 89 – 91 phố Nam Hoa Sơn: ngôi nhà ở ga cuối đường sắt, nơi mở đầu đường về","sapo":"Trên một con phố ở khu trung tâm cũ của Côn Minh, hai số nhà 89 và 91 nay mang tên nhà lưu niệm Hồ Chí Minh. Hơn tám mươi năm trước, thành phố cao nguyên này là ga cuối của tuyến đường sắt từ Hải Phòng lên Vân Nam, và là nơi một nhà cách mạng Việt Nam ở tuổi năm mươi âm thầm nối lại sợi dây với Tổ quốc. Vì sao lại là Côn Minh, và ngôi nhà ấy đã đi qua những gì trước khi hiện lên trong tấm ảnh chụp đầu năm 2025?","bia":{"src":"textures/ht/ht_anh_2025_02_05_former_residence_of_ho_chi_minh_kunmi.jpg","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một tấm ảnh chụp đầu năm 2025","text":"Tấm ảnh được một người dùng Wikimedia Commons chụp ngày 5/2/2025 và chia sẻ theo giấy phép mở. Ống kính hướng vào mặt tiền một ngôi nhà vừa được tu bổ trên phố Nam Hoa Sơn, quận Ngũ Hoa, khu trung tâm lâu đời của thành phố Côn Minh, thủ phủ tỉnh Vân Nam. Theo báo Nhân Dân, di tích trải trên hai số nhà 89 và 91, diện tích mặt đất khoảng 121,5 mét vuông, diện tích xây dựng 263 mét vuông. Người Trung Quốc gọi nơi này là Côn Minh Hồ Chí Minh cựu cư, tức nơi ở cũ của Hồ Chí Minh ở Côn Minh. Báo chí Việt Nam thường gọi là Khu di tích Chủ tịch Hồ Chí Minh tại Côn Minh.\n\nQuy mô ấy rất khiêm tốn so với những công trình cao tầng quanh nó hôm nay. Nhưng với người Việt Nam, ngôi nhà đánh dấu một chặng không thể thiếu trên hành trình ba mươi năm tìm đường cứu nước. Đó là năm 1940, khi Người ở Côn Minh, kiên trì nối lại liên lạc với phong trào trong nước sau nhiều năm xa cách, và chuẩn bị cho ngày trở về.","doc":1},{"loai":"doan","tieu_de":"Thành phố mùa xuân ở cuối đường ray","text":"Côn Minh nằm trên cao nguyên Vân Nam, ở độ cao khoảng 1.900 mét, bên bờ hồ Điền Trì rộng lớn. Khí hậu ôn hòa quanh năm khiến thành phố có biệt danh Xuân Thành, nghĩa là thành phố mùa xuân. Đầu thế kỷ XX, Côn Minh còn là một đô thị xa xôi của miền Tây Nam Trung Hoa, cách biệt với các thành phố lớn ven biển bởi hàng nghìn dặm núi non. Con đường ngắn nhất để ra biển lại đi qua đất Việt Nam.\n\nNăm 1910, tuyến đường sắt Hải Phòng – Hà Nội – Lào Cai – Côn Minh do người Pháp xây dựng thông tuyến. Đường ray khổ một mét men theo thung lũng sông Hồng lên Lào Cai, vượt sang Hà Khẩu rồi leo dần lên cao nguyên qua rất nhiều cầu và đường hầm. Đoạn trên đất Vân Nam được xây dựng trong điều kiện vô cùng gian khổ, hàng vạn phu phen đã bỏ mạng trên công trường. Từ đó, hàng hóa, hành khách và tin tức đi lại giữa Vân Nam và Bắc Kỳ nhanh chóng hơn bao giờ hết.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người Việt dọc đường ray","text":"Theo con tàu, nhiều người Việt Nam lên Vân Nam làm thợ, làm công nhân đường sắt, buôn bán nhỏ. Ở Côn Minh và các thị trấn dọc tuyến đường dần hình thành những cộng đồng Việt kiều. Với những người cách mạng phải hoạt động ở nước ngoài, đó là chỗ dựa quý giá: có người che giấu, có nơi ăn ở, có đường dây đưa thư từ, sách báo qua biên giới. Vì thế, vào cuối những năm 1930, Côn Minh trở thành một địa bàn hoạt động quan trọng của các tổ chức Đảng ở ngoài nước.\n\nChính quyền thuộc địa cũng hiểu rõ điều đó. Pháp đặt lãnh sự quán ở Côn Minh, và mật thám Pháp luôn để mắt tới cộng đồng người Việt ở Vân Nam. Tuyến đường sắt vừa là mạch máu kinh tế, vừa là cánh cửa để những tư tưởng và con người mà nhà cầm quyền coi là nguy hiểm đi về. Người cách mạng muốn trụ lại nơi đây phải hòa mình vào đời thường của cộng đồng, bằng những nghề nghiệp bình dị, dưới những cái tên không ai để ý.","doc":3},{"loai":"doan","tieu_de":"Hậu phương của một nước Trung Hoa đang kháng chiến","text":"Từ năm 1937, khi Nhật Bản phát động chiến tranh xâm lược toàn diện Trung Quốc, vị thế của Côn Minh thay đổi hẳn. Các thành phố lớn miền Đông lần lượt thất thủ; chính phủ Quốc dân Đảng dời về Trùng Khánh, còn Côn Minh trở thành một hậu phương lớn ở miền Tây Nam. Năm 1938, ba trường đại học danh tiếng là Bắc Kinh, Thanh Hoa và Nam Khai sơ tán về đây, lập nên Đại học Liên hợp Tây Nam. Cũng từ cuối năm 1938, con đường bộ nối Côn Minh với Miến Điện được mở. Cùng với tuyến đường sắt qua Bắc Kỳ, nó trở thành ngả tiếp tế quan trọng từ bên ngoài vào Trung Quốc.\n\nThành phố cao nguyên vì thế đông đúc hẳn lên. Người tản cư, sinh viên, trí thức, thương nhân, nhà báo và nhân viên nước ngoài đổ về, mang theo tin tức của cả một thế giới đang bước vào chiến tranh. Với một người đang tìm cách nắm bắt tình hình quốc tế và bắt liên lạc với quê nhà, hiếm nơi nào thuận lợi hơn: vừa gần biên giới Việt Nam, vừa là ngã ba của những luồng thông tin lớn.","doc":4},{"loai":"doan","tieu_de":"Chặng đường đến Côn Minh","text":"Người trở lại Trung Quốc từ cuối năm 1938, sau nhiều năm ở Liên Xô. Người qua Diên An, xuống Quế Lâm làm việc ở Văn phòng Bát lộ quân với tên Hồ Quang, rồi năm 1939 công tác tại lớp huấn luyện du kích ở Hồ Nam (xem chuyên đề Mốc thời gian). Suốt thời gian ấy, mối bận tâm lớn nhất vẫn là làm sao nối được liên lạc với Đảng ở trong nước. Chiến tranh thế giới thứ hai bùng nổ tháng 9/1939 càng khiến việc ấy trở nên cấp bách.\n\nỞ Đông Dương, chính quyền thuộc địa lập tức chuyển sang đàn áp gắt gao, thủ tiêu những quyền tự do ít ỏi mà phong trào dân chủ những năm trước giành được. Các tổ chức Đảng phải rút vào hoạt động bí mật. Tháng 11/1939, Hội nghị Trung ương Đảng họp ở Bà Điểm, Hóc Môn, do Tổng Bí thư Nguyễn Văn Cừ chủ trì, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Muốn theo sát những chuyển biến như thế, Người cần một chỗ đứng gần biên giới, có đường dây tin cậy. Đầu năm 1940, Người đến Côn Minh.","doc":5},{"loai":"ban_co_biet","text":"Ngôi nhà mang tên Hồ Chí Minh, nhưng khi ở Côn Minh năm 1940, Người chưa dùng tên ấy. Tên Hồ Chí Minh chỉ được dùng từ tháng 8/1942; trước đó, trên đất Trung Hoa, Người hoạt động dưới nhiều bí danh khác nhau, như Hồ Quang khi ở Quế Lâm.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_former_residence_of_ho_chi_minh_kunmi.jpg","chu_thich":"Nhà lưu niệm Hồ Chí Minh ở số 89 – 91 phố Nam Hoa Sơn, quận Ngũ Hoa, Côn Minh, sau đợt trùng tu 2022 – 2023; ảnh chụp tháng 2/2025.","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Nối lại sợi dây với trong nước","text":"Ở Côn Minh, Người sống và làm việc bí mật, giữ mối liên hệ với Ban Hải ngoại của Đảng. Trong số những cán bộ hoạt động ở đây có Phùng Chí Kiên, người từng học ở Quảng Châu những năm 1920 (xem chuyên đề Trường Quân sự Hoàng Phố). Qua đường dây của Ban Hải ngoại và những cơ sở trong cộng đồng Việt kiều, Người nắm tình hình trong nước, gặp những cán bộ mới vượt biên và tìm hiểu con đường an toàn nhất để trở về.\n\nSau nhiều năm hoạt động ở nước ngoài, có lúc đứt liên lạc, đây là dịp Người được trực tiếp nghe những người vừa rời quê nhà kể về phong trào. Mùa hè năm ấy, cũng tại Côn Minh, Người gặp những cán bộ trẻ từ Hà Nội sang và quyết định phải về nước ngay; câu chuyện ấy được kể trong chuyên đề Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh. Những gì bắt đầu ở thành phố này dẫn thẳng tới ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó.","doc":7},{"loai":"doan","tieu_de":"Lần trở lại mùa xuân năm 1945","text":"Côn Minh còn xuất hiện thêm một lần trong hành trình của Người. Mùa xuân năm 1945, khi Chiến tranh thế giới thứ hai bước vào giai đoạn cuối, Người lại sang Côn Minh để bắt liên lạc với lực lượng Đồng minh. Thành phố lúc ấy là căn cứ của Tập đoàn không quân số 14 của Mỹ do tướng Claire Chennault chỉ huy, đồng thời là nơi đặt cơ quan của nhiều tổ chức tình báo Đồng minh. Theo nhà sử học William J. Duiker, Người đã gặp tướng Chennault tại đây.\n\nTrước đó, cuối năm 1944, lực lượng Việt Minh ở Cao Bằng đã cứu giúp một phi công Mỹ bị rơi máy bay. Việc làm ấy mở ra những cuộc tiếp xúc với người Mỹ ở Côn Minh, và về sau là sự phối hợp giữa Việt Minh với một nhóm tình báo Mỹ trong những tháng trước Cách mạng Tháng Tám. Như vậy, Côn Minh hai lần làm chiếc cầu nối: năm 1940 nối Người với phong trào trong nước, năm 1945 nối cách mạng Việt Nam với thế giới bên ngoài.","doc":8},{"loai":"ban_co_biet","text":"Theo nhà sử học William J. Duiker, sau cuộc gặp ở Côn Minh năm 1945, Người đề nghị và được tướng Claire Chennault tặng một bức ảnh chân dung có chữ ký. Về sau, bức ảnh được Người dùng như một bằng chứng cho thấy Việt Minh có quan hệ với phe Đồng minh.","nguon_ten":"William J. Duiker, Ho Chi Minh: A Life (2000)","doc":9},{"loai":"anh","src":"textures/bang_w/G09_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ngôi nhà được đánh thức","text":"Trải qua nhiều biến đổi của đô thị Côn Minh, ngôi nhà cũ dần xuống cấp. Ngày 19/5/2022, đúng dịp kỷ niệm 132 năm ngày sinh của Người, lễ khởi công trùng tu di tích được tổ chức. Theo báo Nhân Dân, công trình là kết quả phối hợp giữa Tổng Lãnh sự quán Việt Nam tại Côn Minh với Tỉnh ủy và chính quyền tỉnh Vân Nam. Song song với việc tu bổ, các cơ quan liên quan phối hợp thiết kế nội dung và sưu tầm hiện vật trưng bày. Theo Vân Nam nhật báo, cuối tháng 3/2023, nhà lưu niệm chính thức mở cửa đón khách.\n\nViệc chọn ngày 19/5 để khởi công cho thấy ý nghĩa mà cả hai phía dành cho di tích. Ngôi nhà không chỉ ghi dấu một chặng hoạt động của Người, mà còn là chứng tích của những năm tháng cách mạng hai nước dựa vào nhau. Từ đó, nơi này trở thành điểm đến quen thuộc của các đoàn đại biểu Việt Nam khi tới Vân Nam, cũng như của du khách muốn tìm hiểu một trang sử chung.","doc":10},{"loai":"anh","src":"textures/bang_w/G09_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Đọc tấm ảnh hôm nay","text":"Đứng trước tấm ảnh, người xem nên nhớ rằng mặt tiền trong ảnh là diện mạo sau đợt trùng tu 2022 – 2023, không phải hình ảnh nguyên vẹn của năm 1940. Giá trị của di tích nằm ở vị trí, ở câu chuyện và ở những gì nó gợi nhắc. Từ Côn Minh, đường về Tổ quốc chỉ còn chưa đầy một năm: cuối năm 1940 Người rời thành phố, và cuối tháng 1/1941 đã đặt chân lên đất Cao Bằng.\n\nTrong gian trưng bày của Bảo tàng Hành trình, tấm ảnh nằm giữa những câu chuyện về Quảng Châu những năm 1920 và nhà lao Quảng Tây những năm 1942 – 1943. Đặt cạnh nhau, chúng cho thấy một mạch liền. Ở Quảng Châu, Người đào tạo những cán bộ đầu tiên; ở Côn Minh, Người tìm lại họ và cùng họ chuẩn bị cho ngày về; ở Quảng Tây, Người trả giá bằng hơn một năm tù đày cho chuyến đi tìm đồng minh. Ga cuối của tuyến đường sắt thuộc địa, thật trớ trêu, lại trở thành nơi mở đầu con đường về để giải phóng chính xứ thuộc địa ấy.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Báo Nhân Dân – “Trùng tu di tích nơi ở cũ của Chủ tịch Hồ Chí Minh tại Côn Minh, Trung Quốc” – https://nhandan.vn/trung-tu-di-tich-noi-o-cu-cua-chu-tich-ho-chi-minh-tai-con-minh-trung-quoc-post698117.html","Vân Nam nhật báo (云南日报) – tin “Nhà lưu niệm Hồ Chí Minh ở Côn Minh chính thức mở cửa”, 25/3/2023","William J. Duiker, Ho Chi Minh: A Life (2000)"],"doc":[{"t":"Số 89 – 91 phố Nam Hoa Sơn: ngôi nhà ở ga cuối đường sắt, nơi mở đầu đường về. Trên một con phố ở khu trung tâm cũ của Côn Minh, hai số nhà 89 và 91 nay mang tên nhà lưu niệm Hồ Chí Minh. Hơn tám mươi năm trước, thành phố cao nguyên này là ga cuối của tuyến đường sắt từ Hải Phòng lên Vân Nam, và là nơi một nhà cách mạng Việt Nam ở tuổi năm mươi âm thầm nối lại sợi dây với Tổ quốc. Vì sao lại là Côn Minh, và ngôi nhà ấy đã đi qua những gì trước khi hiện lên trong tấm ảnh chụp đầu năm 2025?"},{"t":"Một tấm ảnh chụp đầu năm 2025. Tấm ảnh được một người dùng Wikimedia Commons chụp ngày 5/2/2025 và chia sẻ theo giấy phép mở. Ống kính hướng vào mặt tiền một ngôi nhà vừa được tu bổ trên phố Nam Hoa Sơn, quận Ngũ Hoa, khu trung tâm lâu đời của thành phố Côn Minh, thủ phủ tỉnh Vân Nam. Theo báo Nhân Dân, di tích trải trên hai số nhà 89 và 91, diện tích mặt đất khoảng 121,5 mét vuông, diện tích xây dựng 263 mét vuông. Người Trung Quốc gọi nơi này là Côn Minh Hồ Chí Minh cựu cư, tức nơi ở cũ của Hồ Chí Minh ở Côn Minh. Báo chí Việt Nam thường gọi là Khu di tích Chủ tịch Hồ Chí Minh tại Côn Minh. Quy mô ấy rất khiêm tốn so với những công trình cao tầng quanh nó hôm nay. Nhưng với người Việt Nam, ngôi nhà đánh dấu một chặng không thể thiếu trên hành trình ba mươi năm tìm đường cứu nước. Đó là năm 1940, khi Người ở Côn Minh, kiên trì nối lại liên lạc với phong trào trong nước sau nhiều năm xa cách, và chuẩn bị cho ngày trở về."},{"t":"Thành phố mùa xuân ở cuối đường ray. Côn Minh nằm trên cao nguyên Vân Nam, ở độ cao khoảng 1.900 mét, bên bờ hồ Điền Trì rộng lớn. Khí hậu ôn hòa quanh năm khiến thành phố có biệt danh Xuân Thành, nghĩa là thành phố mùa xuân. Đầu thế kỷ XX, Côn Minh còn là một đô thị xa xôi của miền Tây Nam Trung Hoa, cách biệt với các thành phố lớn ven biển bởi hàng nghìn dặm núi non. Con đường ngắn nhất để ra biển lại đi qua đất Việt Nam. Năm 1910, tuyến đường sắt Hải Phòng – Hà Nội – Lào Cai – Côn Minh do người Pháp xây dựng thông tuyến. Đường ray khổ một mét men theo thung lũng sông Hồng lên Lào Cai, vượt sang Hà Khẩu rồi leo dần lên cao nguyên qua rất nhiều cầu và đường hầm. Đoạn trên đất Vân Nam được xây dựng trong điều kiện vô cùng gian khổ, hàng vạn phu phen đã bỏ mạng trên công trường. Từ đó, hàng hóa, hành khách và tin tức đi lại giữa Vân Nam và Bắc Kỳ nhanh chóng hơn bao giờ hết."},{"t":"Người Việt dọc đường ray. Theo con tàu, nhiều người Việt Nam lên Vân Nam làm thợ, làm công nhân đường sắt, buôn bán nhỏ. Ở Côn Minh và các thị trấn dọc tuyến đường dần hình thành những cộng đồng Việt kiều. Với những người cách mạng phải hoạt động ở nước ngoài, đó là chỗ dựa quý giá: có người che giấu, có nơi ăn ở, có đường dây đưa thư từ, sách báo qua biên giới. Vì thế, vào cuối những năm 1930, Côn Minh trở thành một địa bàn hoạt động quan trọng của các tổ chức Đảng ở ngoài nước. Chính quyền thuộc địa cũng hiểu rõ điều đó. Pháp đặt lãnh sự quán ở Côn Minh, và mật thám Pháp luôn để mắt tới cộng đồng người Việt ở Vân Nam. Tuyến đường sắt vừa là mạch máu kinh tế, vừa là cánh cửa để những tư tưởng và con người mà nhà cầm quyền coi là nguy hiểm đi về. Người cách mạng muốn trụ lại nơi đây phải hòa mình vào đời thường của cộng đồng, bằng những nghề nghiệp bình dị, dưới những cái tên không ai để ý."},{"t":"Hậu phương của một nước Trung Hoa đang kháng chiến. Từ năm 1937, khi Nhật Bản phát động chiến tranh xâm lược toàn diện Trung Quốc, vị thế của Côn Minh thay đổi hẳn. Các thành phố lớn miền Đông lần lượt thất thủ; chính phủ Quốc dân Đảng dời về Trùng Khánh, còn Côn Minh trở thành một hậu phương lớn ở miền Tây Nam. Năm 1938, ba trường đại học danh tiếng là Bắc Kinh, Thanh Hoa và Nam Khai sơ tán về đây, lập nên Đại học Liên hợp Tây Nam. Cũng từ cuối năm 1938, con đường bộ nối Côn Minh với Miến Điện được mở. Cùng với tuyến đường sắt qua Bắc Kỳ, nó trở thành ngả tiếp tế quan trọng từ bên ngoài vào Trung Quốc. Thành phố cao nguyên vì thế đông đúc hẳn lên. Người tản cư, sinh viên, trí thức, thương nhân, nhà báo và nhân viên nước ngoài đổ về, mang theo tin tức của cả một thế giới đang bước vào chiến tranh. Với một người đang tìm cách nắm bắt tình hình quốc tế và bắt liên lạc với quê nhà, hiếm nơi nào thuận lợi hơn: vừa gần biên giới Việt Nam, vừa là ngã ba của những luồng thông tin lớn."},{"t":"Chặng đường đến Côn Minh. Người trở lại Trung Quốc từ cuối năm 1938, sau nhiều năm ở Liên Xô. Người qua Diên An, xuống Quế Lâm làm việc ở Văn phòng Bát lộ quân với tên Hồ Quang, rồi năm 1939 công tác tại lớp huấn luyện du kích ở Hồ Nam (xem chuyên đề Mốc thời gian). Suốt thời gian ấy, mối bận tâm lớn nhất vẫn là làm sao nối được liên lạc với Đảng ở trong nước. Chiến tranh thế giới thứ hai bùng nổ tháng 9/1939 càng khiến việc ấy trở nên cấp bách. Ở Đông Dương, chính quyền thuộc địa lập tức chuyển sang đàn áp gắt gao, thủ tiêu những quyền tự do ít ỏi mà phong trào dân chủ những năm trước giành được. Các tổ chức Đảng phải rút vào hoạt động bí mật. Tháng 11/1939, Hội nghị Trung ương Đảng họp ở Bà Điểm, Hóc Môn, do Tổng Bí thư Nguyễn Văn Cừ chủ trì, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Muốn theo sát những chuyển biến như thế, Người cần một chỗ đứng gần biên giới, có đường dây tin cậy. Đầu năm 1940, Người đến Côn Minh."},{"t":"Bạn có biết? Ngôi nhà mang tên Hồ Chí Minh, nhưng khi ở Côn Minh năm 1940, Người chưa dùng tên ấy. Tên Hồ Chí Minh chỉ được dùng từ tháng 8/1942; trước đó, trên đất Trung Hoa, Người hoạt động dưới nhiều bí danh khác nhau, như Hồ Quang khi ở Quế Lâm."},{"t":"Nối lại sợi dây với trong nước. Ở Côn Minh, Người sống và làm việc bí mật, giữ mối liên hệ với Ban Hải ngoại của Đảng. Trong số những cán bộ hoạt động ở đây có Phùng Chí Kiên, người từng học ở Quảng Châu những năm 1920 (xem chuyên đề Trường Quân sự Hoàng Phố). Qua đường dây của Ban Hải ngoại và những cơ sở trong cộng đồng Việt kiều, Người nắm tình hình trong nước, gặp những cán bộ mới vượt biên và tìm hiểu con đường an toàn nhất để trở về. Sau nhiều năm hoạt động ở nước ngoài, có lúc đứt liên lạc, đây là dịp Người được trực tiếp nghe những người vừa rời quê nhà kể về phong trào. Mùa hè năm ấy, cũng tại Côn Minh, Người gặp những cán bộ trẻ từ Hà Nội sang và quyết định phải về nước ngay; câu chuyện ấy được kể trong chuyên đề Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh. Những gì bắt đầu ở thành phố này dẫn thẳng tới ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó."},{"t":"Lần trở lại mùa xuân năm 1945. Côn Minh còn xuất hiện thêm một lần trong hành trình của Người. Mùa xuân năm 1945, khi Chiến tranh thế giới thứ hai bước vào giai đoạn cuối, Người lại sang Côn Minh để bắt liên lạc với lực lượng Đồng minh. Thành phố lúc ấy là căn cứ của Tập đoàn không quân số 14 của Mỹ do tướng Claire Chennault chỉ huy, đồng thời là nơi đặt cơ quan của nhiều tổ chức tình báo Đồng minh. Theo nhà sử học William J. Duiker, Người đã gặp tướng Chennault tại đây. Trước đó, cuối năm 1944, lực lượng Việt Minh ở Cao Bằng đã cứu giúp một phi công Mỹ bị rơi máy bay. Việc làm ấy mở ra những cuộc tiếp xúc với người Mỹ ở Côn Minh, và về sau là sự phối hợp giữa Việt Minh với một nhóm tình báo Mỹ trong những tháng trước Cách mạng Tháng Tám. Như vậy, Côn Minh hai lần làm chiếc cầu nối: năm 1940 nối Người với phong trào trong nước, năm 1945 nối cách mạng Việt Nam với thế giới bên ngoài."},{"t":"Bạn có biết? Theo nhà sử học William J. Duiker, sau cuộc gặp ở Côn Minh năm 1945, Người đề nghị và được tướng Claire Chennault tặng một bức ảnh chân dung có chữ ký. Về sau, bức ảnh được Người dùng như một bằng chứng cho thấy Việt Minh có quan hệ với phe Đồng minh."},{"t":"Ngôi nhà được đánh thức. Trải qua nhiều biến đổi của đô thị Côn Minh, ngôi nhà cũ dần xuống cấp. Ngày 19/5/2022, đúng dịp kỷ niệm 132 năm ngày sinh của Người, lễ khởi công trùng tu di tích được tổ chức. Theo báo Nhân Dân, công trình là kết quả phối hợp giữa Tổng Lãnh sự quán Việt Nam tại Côn Minh với Tỉnh ủy và chính quyền tỉnh Vân Nam. Song song với việc tu bổ, các cơ quan liên quan phối hợp thiết kế nội dung và sưu tầm hiện vật trưng bày. Theo Vân Nam nhật báo, cuối tháng 3/2023, nhà lưu niệm chính thức mở cửa đón khách. Việc chọn ngày 19/5 để khởi công cho thấy ý nghĩa mà cả hai phía dành cho di tích. Ngôi nhà không chỉ ghi dấu một chặng hoạt động của Người, mà còn là chứng tích của những năm tháng cách mạng hai nước dựa vào nhau. Từ đó, nơi này trở thành điểm đến quen thuộc của các đoàn đại biểu Việt Nam khi tới Vân Nam, cũng như của du khách muốn tìm hiểu một trang sử chung."},{"t":"Đọc tấm ảnh hôm nay. Đứng trước tấm ảnh, người xem nên nhớ rằng mặt tiền trong ảnh là diện mạo sau đợt trùng tu 2022 – 2023, không phải hình ảnh nguyên vẹn của năm 1940. Giá trị của di tích nằm ở vị trí, ở câu chuyện và ở những gì nó gợi nhắc. Từ Côn Minh, đường về Tổ quốc chỉ còn chưa đầy một năm: cuối năm 1940 Người rời thành phố, và cuối tháng 1/1941 đã đặt chân lên đất Cao Bằng. Trong gian trưng bày của Bảo tàng Hành trình, tấm ảnh nằm giữa những câu chuyện về Quảng Châu những năm 1920 và nhà lao Quảng Tây những năm 1942 – 1943. Đặt cạnh nhau, chúng cho thấy một mạch liền. Ở Quảng Châu, Người đào tạo những cán bộ đầu tiên; ở Côn Minh, Người tìm lại họ và cùng họ chuẩn bị cho ngày về; ở Quảng Tây, Người trả giá bằng hơn một năm tù đày cho chuyến đi tìm đồng minh. Ga cuối của tuyến đường sắt thuộc địa, thật trớ trêu, lại trở thành nơi mở đầu con đường về để giải phóng chính xứ thuộc địa ấy."}],"so_chu":1946},{"i":6,"tieu_de_bang":"Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh","tieu_de":"Mùa hè 1940 ở Côn Minh: khi thời cơ gõ cửa","sapo":"Bước qua ngưỡng cửa ngôi nhà trên phố Nam Hoa Sơn, người xem được đưa về những tháng ngày Người làm việc bí mật ở Côn Minh. Chính tại thành phố này, mùa hè năm 1940, hai trí thức trẻ từ Hà Nội tìm sang gặp Người, đúng lúc tin nước Pháp thất trận dội về từ châu Âu. Một nhận định của Người trong những ngày ấy về sau được nhắc lại như bài học kinh điển về nắm bắt thời cơ.","bia":{"src":"textures/ht/ht_anh_2025_02_05_interior_of_ho_chi_minh_s_former_resi.jpg","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Căn phòng trong ảnh","text":"Tấm ảnh chụp bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh ngày 5/2/2025, cùng ngày với tấm ảnh mặt tiền của di tích (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Sau đợt trùng tu khởi công ngày 19/5/2022, các căn phòng của ngôi nhà số 89 – 91 phố Nam Hoa Sơn được bài trí thành không gian trưng bày. Nơi đây giới thiệu thời gian Người hoạt động ở Côn Minh bằng hình ảnh và tư liệu. Theo báo Nhân Dân, Tổng Lãnh sự quán Việt Nam tại Côn Minh đã cùng phía Vân Nam tham gia thiết kế nội dung và sưu tầm hiện vật cho di tích.\n\nKhông gian ấy nhỏ, đúng với quy mô một ngôi nhà phố. Nhưng câu chuyện nó kể lại thuộc về một trong những khúc quanh lớn của lịch sử Việt Nam thế kỷ XX. Bởi chính ở Côn Minh, trong mùa hè năm 1940, Người gặp những người sẽ cùng mình làm nên Cách mạng Tháng Tám, và quyết định rằng giờ về nước đã điểm.","doc":1},{"loai":"doan","tieu_de":"Hai người khách từ Hà Nội","text":"Tháng 5/1940, theo sự bố trí của tổ chức Đảng, hai trí thức trẻ rời Hà Nội sang Trung Quốc. Người lớn tuổi hơn là Phạm Văn Đồng, sinh năm 1906 ở Quảng Ngãi. Ông từng dự lớp huấn luyện của Nguyễn Ái Quốc ở Quảng Châu năm 1926, rồi bị thực dân Pháp giam ở Côn Đảo nhiều năm. Người kia là Võ Nguyên Giáp, sinh năm 1911 ở Quảng Bình, khi ấy là thầy giáo dạy sử ở trường tư thục Thăng Long và là cây bút quen thuộc của báo chí công khai ở Hà Nội.\n\nChuyến đi đòi hỏi những hy sinh lặng lẽ. Võ Nguyên Giáp để lại Hà Nội người vợ là bà Nguyễn Thị Quang Thái cùng con gái mới vài tháng tuổi. Ít lâu sau, bà Quang Thái bị thực dân bắt và hy sinh trong nhà tù Hỏa Lò năm 1944. Những người ra đi năm ấy biết rằng con đường họ chọn có thể không có ngày trở lại. Điều họ chưa biết là ở Côn Minh, một cuộc gặp sẽ định hướng cả cuộc đời mình.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_interior_of_ho_chi_minh_s_former_resi.jpg","chu_thich":"Không gian trưng bày bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh; ảnh chụp tháng 2/2025.","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bên hồ Thúy Hồ","text":"Tháng 6/1940, tại Côn Minh, hai ông được gặp Người. Theo hồi ký của Đại tướng Võ Nguyên Giáp, lần đầu tiên ông gặp Người là bên hồ Thúy Hồ, mặt hồ xanh giữa lòng thành phố. Với Phạm Văn Đồng, đó là cuộc gặp lại sau mười bốn năm, kể từ lớp học trên phố Văn Minh ở Quảng Châu. Với Võ Nguyên Giáp, cái tên Nguyễn Ái Quốc vốn đã quen thuộc qua sách báo và lời kể của những người đi trước. Giờ đây ông được trực tiếp nghe Người hỏi han tình hình trong nước và phân tích thời cuộc.\n\nTừ cuộc gặp ấy, hai người trở thành những học trò gần gũi của Người trong gần ba mươi năm. Phạm Văn Đồng về sau đứng đầu Chính phủ suốt nhiều thập kỷ; Võ Nguyên Giáp trở thành Đại tướng, Tổng Tư lệnh Quân đội nhân dân Việt Nam. Cuộc gặp bên một mặt hồ ở Côn Minh vì thế được xem như điểm khởi đầu của một mối gắn bó đặc biệt trong lịch sử cách mạng Việt Nam.","doc":3},{"loai":"ban_co_biet","text":"Thúy Hồ (翠湖, nghĩa là hồ xanh biếc) là hồ nước giữa trung tâm Côn Minh. Bên bờ hồ có Giảng Võ Đường Vân Nam, trường quân sự lập từ cuối đời Thanh, nơi Chu Đức, về sau là Nguyên soái của Trung Quốc, từng theo học.","nguon_ten":"Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký); tư liệu di tích Giảng Võ Đường Vân Nam, Côn Minh","doc":4},{"loai":"anh","src":"textures/bang_w/G09_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Tin dữ từ Paris","text":"Cũng trong tháng 6/1940, tin tức từ châu Âu dồn dập đổ về. Ngày 14/6, quân Đức tiến vào Paris. Ngày 22/6, nước Pháp ký hiệp định đình chiến, chấp nhận thất bại; chính phủ của thống chế Pétain dời về Vichy và hợp tác với phát xít Đức. Cái mẫu quốc từng tự nhận sứ mệnh khai hóa cho các dân tộc thuộc địa, chỉ trong vài tuần, đã gục ngã trước kẻ thù.\n\nỞ Viễn Đông, Nhật Bản lập tức lợi dụng thời cơ. Ngay trong tháng 6/1940, Nhật ép chính quyền Pháp ở Đông Dương đóng tuyến đường sắt Hải Phòng – Côn Minh, không cho hàng tiếp tế đi qua để vào Trung Quốc. Tuyến đường từng nối Côn Minh với biển cả bỗng chốc bị chặn lại. Với những người Việt Nam yêu nước đang ở thành phố này, câu hỏi đặt ra thật cấp bách: sự sụp đổ của nước Pháp có ý nghĩa gì với dân tộc mình, và phải hành động ra sao?","doc":5},{"loai":"doan","tieu_de":"Đọc ra thời cơ","text":"Theo hồi ức của Đại tướng Võ Nguyên Giáp, khi nhiều người còn bàng hoàng trước tin Pháp bại trận, Người đã nhìn ngay ra ý nghĩa của sự kiện ấy đối với Đông Dương. Người yêu cầu mọi người gấp rút chuẩn bị về nước. Diễn biến sau đó cho thấy nhận định ấy sắc sảo đến mức nào. Ngày 22/9/1940, quân Nhật đánh vào Lạng Sơn, bắt đầu chiếm đóng Đông Dương. Chính quyền thực dân Pháp phải chia quyền thống trị với phát xít Nhật, và nhân dân Việt Nam rơi vào cảnh một cổ hai tròng.\n\nNgay trong những tháng ấy, khởi nghĩa Bắc Sơn nổ ra ngày 27/9/1940, rồi khởi nghĩa Nam Kỳ ngày 23/11/1940. Cả hai đều bị đàn áp đẫm máu, nhưng cho thấy sức phản kháng đang dâng lên và đòi hỏi một sự lãnh đạo thống nhất, sát với thực tiễn. Lời Người nói ở Côn Minh được Đại tướng ghi lại, về sau trở thành một dẫn chứng quen thuộc khi các nhà nghiên cứu bàn về nghệ thuật nắm bắt thời cơ của Hồ Chí Minh.","doc":6},{"loai":"trich","text":"Việc Pháp mất nước là một cơ hội rất thuận lợi cho cách mạng Việt Nam. Ta phải tìm mọi cách về nước ngay để tranh thủ thời cơ. Chậm trễ lúc này là có tội với cách mạng.","nguoi":"Nguyễn Ái Quốc, theo hồi ký của Đại tướng Võ Nguyên Giáp","nguon_ten":"Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký)","doc":7},{"loai":"doan","tieu_de":"Đổi hướng một chuyến đi","text":"Nhận định ấy lập tức biến thành hành động. Trước đó, theo kế hoạch, Phạm Văn Đồng và Võ Nguyên Giáp sẽ được đưa đi Diên An, căn cứ của Đảng Cộng sản Trung Quốc, để học tập. Theo hồi ký của Đại tướng, dự định ấy được thay đổi: thay vì đi học xa, hai ông ở lại cùng Người chuẩn bị cho việc về nước. Mọi công việc từ đó dồn vào một mục tiêu: chuẩn bị cán bộ, tìm nơi đứng chân sát biên giới và nối đường dây với các tỉnh miền núi phía Bắc.\n\nCuối năm 1940, Người rời Côn Minh, qua Quế Lâm rồi xuống vùng biên giới Quảng Tây giáp Cao Bằng. Tại đây, Người mở lớp huấn luyện cho những cán bộ từ Cao Bằng sang. Ngày 28/1/1941, Người vượt cột mốc 108 trở về Tổ quốc. Tính từ mùa hè ở Côn Minh, cuộc trở về chỉ mất khoảng bảy tháng, một khoảng thời gian rất ngắn so với gần ba mươi năm Người đã sống xa quê hương.","doc":8},{"loai":"anh","src":"textures/bang_w/G09_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh”, nhìn theo hướng ngược lại."},{"loai":"moc","items":[["Đầu năm 1940","Người đến Côn Minh, bắt liên lạc với Ban Hải ngoại của Đảng và cơ sở trong nước"],["5/1940","Phạm Văn Đồng và Võ Nguyên Giáp rời Hà Nội sang Trung Quốc"],["6/1940","Tại Côn Minh, hai ông được gặp Người; Võ Nguyên Giáp gặp Người lần đầu bên hồ Thúy Hồ"],["14/6/1940","Quân Đức tiến vào Paris"],["22/6/1940","Pháp ký hiệp định đình chiến với Đức, chấp nhận thất bại"],["6/1940","Nhật buộc chính quyền Pháp ở Đông Dương đóng tuyến đường sắt Hải Phòng – Côn Minh đối với hàng tiếp tế cho Trung Quốc"],["Mùa hè 1940","Người nhận định việc Pháp mất nước là thời cơ, quyết định gấp rút chuẩn bị về nước"],["22/9/1940","Quân Nhật đánh vào Lạng Sơn, bắt đầu chiếm đóng Đông Dương"],["27/9/1940","Khởi nghĩa Bắc Sơn"],["23/11/1940","Khởi nghĩa Nam Kỳ"],["Cuối năm 1940","Người rời Côn Minh, qua Quế Lâm xuống vùng biên giới Quảng Tây giáp Cao Bằng"],["28/1/1941","Người vượt cột mốc 108 về Pác Bó, Cao Bằng"]],"doc":9},{"loai":"ban_co_biet","text":"Hiệp định đình chiến ngày 22/6/1940 được ký trong một toa tàu ở rừng Compiègne, đúng toa tàu nơi nước Đức bại trận đã phải ký đình chiến năm 1918. Hitler chọn địa điểm ấy để biến thất bại của nước Pháp thành một sự trả đũa đầy tính biểu tượng.","nguon_ten":"William L. Shirer, The Rise and Fall of the Third Reich (1960)","doc":10},{"loai":"anh","src":"textures/bang_w/G09_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Côn Minh trong trí nhớ hôm nay","text":"Tháng 11/2024, nhân chuyến công tác tại Vân Nam, Thủ tướng Phạm Minh Chính đến thăm nơi ở cũ của Người ở Côn Minh. Tháng 6/2025, Phó Thủ tướng Trần Hồng Hà cũng tới thăm khu di tích. Những chuyến thăm như vậy, cùng dòng người Việt Nam đến Côn Minh học tập, làm ăn, du lịch, đã biến ngôi nhà nhỏ thành một địa chỉ quen thuộc, nơi người Việt ở xa tìm về một dấu mốc của lịch sử dân tộc.\n\nNhững tấm ảnh và tư liệu trong nhà lưu niệm không thể tái hiện hết không khí của mùa hè năm 1940: những cuộc hẹn gặp bí mật, những bản tin chiến sự, những buổi bàn bạc về con đường phía trước. Nhưng chúng giúp người xem hình dung một điều cốt lõi. Quyết định về nước năm 1940 không phải là một bước đi may rủi, mà là kết quả của một tầm nhìn biết đọc thời cuộc thế giới để tìm ra cơ hội cho dân tộc mình.","doc":11},{"loai":"doan","tieu_de":"Từ Côn Minh đến Ba Đình","text":"Từ mùa hè năm 1940 ở Côn Minh đến ngày 2/9/1945 trên quảng trường Ba Đình là hơn năm năm. Trong khoảng thời gian ấy, Người về nước, chủ trì Hội nghị Trung ương tháng 5/1941 ở Pác Bó, thành lập Mặt trận Việt Minh. Người đi qua hơn một năm tù đày ở Quảng Tây, rồi cùng Trung ương Đảng lãnh đạo toàn dân giành chính quyền. Phạm Văn Đồng và Võ Nguyên Giáp, hai người khách từ Hà Nội năm nào, đồng hành cùng Người trong những bước đi ấy.\n\nVì thế, không gian nhỏ trong tấm ảnh mang một sức nặng lớn. Nó nhắc người xem rằng lịch sử đôi khi rẽ hướng ở những nơi rất bình thường: một mặt hồ giữa phố, một căn nhà nhỏ, một bản tin chiến sự từ nửa vòng trái đất. Điều làm nên khác biệt là con người biết nhận ra khoảnh khắc ấy và dám hành động ngay, không chần chừ.","doc":12}],"nguon":["Võ Nguyên Giáp, Từ nhân dân mà ra (hồi ký), NXB Quân đội nhân dân","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Báo Nhân Dân – “Trùng tu di tích nơi ở cũ của Chủ tịch Hồ Chí Minh tại Côn Minh, Trung Quốc” – https://nhandan.vn/trung-tu-di-tich-noi-o-cu-cua-chu-tich-ho-chi-minh-tai-con-minh-trung-quoc-post698117.html","Báo Dân trí – “Thủ tướng thăm nơi ở cũ của Chủ tịch Hồ Chí Minh tại Côn Minh, Trung Quốc”, 5/11/2024","Báo Điện tử Chính phủ – “Phó Thủ tướng Trần Hồng Hà thăm Khu di tích Chủ tịch Hồ Chí Minh tại TP. Côn Minh, tỉnh Vân Nam (Trung Quốc)”, 6/2025"],"doc":[{"t":"Mùa hè 1940 ở Côn Minh: khi thời cơ gõ cửa. Bước qua ngưỡng cửa ngôi nhà trên phố Nam Hoa Sơn, người xem được đưa về những tháng ngày Người làm việc bí mật ở Côn Minh. Chính tại thành phố này, mùa hè năm 1940, hai trí thức trẻ từ Hà Nội tìm sang gặp Người, đúng lúc tin nước Pháp thất trận dội về từ châu Âu. Một nhận định của Người trong những ngày ấy về sau được nhắc lại như bài học kinh điển về nắm bắt thời cơ."},{"t":"Căn phòng trong ảnh. Tấm ảnh chụp bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh ngày 5/2/2025, cùng ngày với tấm ảnh mặt tiền của di tích (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Sau đợt trùng tu khởi công ngày 19/5/2022, các căn phòng của ngôi nhà số 89 – 91 phố Nam Hoa Sơn được bài trí thành không gian trưng bày. Nơi đây giới thiệu thời gian Người hoạt động ở Côn Minh bằng hình ảnh và tư liệu. Theo báo Nhân Dân, Tổng Lãnh sự quán Việt Nam tại Côn Minh đã cùng phía Vân Nam tham gia thiết kế nội dung và sưu tầm hiện vật cho di tích. Không gian ấy nhỏ, đúng với quy mô một ngôi nhà phố. Nhưng câu chuyện nó kể lại thuộc về một trong những khúc quanh lớn của lịch sử Việt Nam thế kỷ XX. Bởi chính ở Côn Minh, trong mùa hè năm 1940, Người gặp những người sẽ cùng mình làm nên Cách mạng Tháng Tám, và quyết định rằng giờ về nước đã điểm."},{"t":"Hai người khách từ Hà Nội. Tháng 5/1940, theo sự bố trí của tổ chức Đảng, hai trí thức trẻ rời Hà Nội sang Trung Quốc. Người lớn tuổi hơn là Phạm Văn Đồng, sinh năm 1906 ở Quảng Ngãi. Ông từng dự lớp huấn luyện của Nguyễn Ái Quốc ở Quảng Châu năm 1926, rồi bị thực dân Pháp giam ở Côn Đảo nhiều năm. Người kia là Võ Nguyên Giáp, sinh năm 1911 ở Quảng Bình, khi ấy là thầy giáo dạy sử ở trường tư thục Thăng Long và là cây bút quen thuộc của báo chí công khai ở Hà Nội. Chuyến đi đòi hỏi những hy sinh lặng lẽ. Võ Nguyên Giáp để lại Hà Nội người vợ là bà Nguyễn Thị Quang Thái cùng con gái mới vài tháng tuổi. Ít lâu sau, bà Quang Thái bị thực dân bắt và hy sinh trong nhà tù Hỏa Lò năm 1944. Những người ra đi năm ấy biết rằng con đường họ chọn có thể không có ngày trở lại. Điều họ chưa biết là ở Côn Minh, một cuộc gặp sẽ định hướng cả cuộc đời mình."},{"t":"Bên hồ Thúy Hồ. Tháng 6/1940, tại Côn Minh, hai ông được gặp Người. Theo hồi ký của Đại tướng Võ Nguyên Giáp, lần đầu tiên ông gặp Người là bên hồ Thúy Hồ, mặt hồ xanh giữa lòng thành phố. Với Phạm Văn Đồng, đó là cuộc gặp lại sau mười bốn năm, kể từ lớp học trên phố Văn Minh ở Quảng Châu. Với Võ Nguyên Giáp, cái tên Nguyễn Ái Quốc vốn đã quen thuộc qua sách báo và lời kể của những người đi trước. Giờ đây ông được trực tiếp nghe Người hỏi han tình hình trong nước và phân tích thời cuộc. Từ cuộc gặp ấy, hai người trở thành những học trò gần gũi của Người trong gần ba mươi năm. Phạm Văn Đồng về sau đứng đầu Chính phủ suốt nhiều thập kỷ; Võ Nguyên Giáp trở thành Đại tướng, Tổng Tư lệnh Quân đội nhân dân Việt Nam. Cuộc gặp bên một mặt hồ ở Côn Minh vì thế được xem như điểm khởi đầu của một mối gắn bó đặc biệt trong lịch sử cách mạng Việt Nam."},{"t":"Bạn có biết? Thúy Hồ (翠湖, nghĩa là hồ xanh biếc) là hồ nước giữa trung tâm Côn Minh. Bên bờ hồ có Giảng Võ Đường Vân Nam, trường quân sự lập từ cuối đời Thanh, nơi Chu Đức, về sau là Nguyên soái của Trung Quốc, từng theo học."},{"t":"Tin dữ từ Paris. Cũng trong tháng 6/1940, tin tức từ châu Âu dồn dập đổ về. Ngày 14/6, quân Đức tiến vào Paris. Ngày 22/6, nước Pháp ký hiệp định đình chiến, chấp nhận thất bại; chính phủ của thống chế Pétain dời về Vichy và hợp tác với phát xít Đức. Cái mẫu quốc từng tự nhận sứ mệnh khai hóa cho các dân tộc thuộc địa, chỉ trong vài tuần, đã gục ngã trước kẻ thù. Ở Viễn Đông, Nhật Bản lập tức lợi dụng thời cơ. Ngay trong tháng 6/1940, Nhật ép chính quyền Pháp ở Đông Dương đóng tuyến đường sắt Hải Phòng – Côn Minh, không cho hàng tiếp tế đi qua để vào Trung Quốc. Tuyến đường từng nối Côn Minh với biển cả bỗng chốc bị chặn lại. Với những người Việt Nam yêu nước đang ở thành phố này, câu hỏi đặt ra thật cấp bách: sự sụp đổ của nước Pháp có ý nghĩa gì với dân tộc mình, và phải hành động ra sao?"},{"t":"Đọc ra thời cơ. Theo hồi ức của Đại tướng Võ Nguyên Giáp, khi nhiều người còn bàng hoàng trước tin Pháp bại trận, Người đã nhìn ngay ra ý nghĩa của sự kiện ấy đối với Đông Dương. Người yêu cầu mọi người gấp rút chuẩn bị về nước. Diễn biến sau đó cho thấy nhận định ấy sắc sảo đến mức nào. Ngày 22/9/1940, quân Nhật đánh vào Lạng Sơn, bắt đầu chiếm đóng Đông Dương. Chính quyền thực dân Pháp phải chia quyền thống trị với phát xít Nhật, và nhân dân Việt Nam rơi vào cảnh một cổ hai tròng. Ngay trong những tháng ấy, khởi nghĩa Bắc Sơn nổ ra ngày 27/9/1940, rồi khởi nghĩa Nam Kỳ ngày 23/11/1940. Cả hai đều bị đàn áp đẫm máu, nhưng cho thấy sức phản kháng đang dâng lên và đòi hỏi một sự lãnh đạo thống nhất, sát với thực tiễn. Lời Người nói ở Côn Minh được Đại tướng ghi lại, về sau trở thành một dẫn chứng quen thuộc khi các nhà nghiên cứu bàn về nghệ thuật nắm bắt thời cơ của Hồ Chí Minh."},{"t":"Việc Pháp mất nước là một cơ hội rất thuận lợi cho cách mạng Việt Nam. Ta phải tìm mọi cách về nước ngay để tranh thủ thời cơ. Chậm trễ lúc này là có tội với cách mạng. — Nguyễn Ái Quốc, theo hồi ký của Đại tướng Võ Nguyên Giáp"},{"t":"Đổi hướng một chuyến đi. Nhận định ấy lập tức biến thành hành động. Trước đó, theo kế hoạch, Phạm Văn Đồng và Võ Nguyên Giáp sẽ được đưa đi Diên An, căn cứ của Đảng Cộng sản Trung Quốc, để học tập. Theo hồi ký của Đại tướng, dự định ấy được thay đổi: thay vì đi học xa, hai ông ở lại cùng Người chuẩn bị cho việc về nước. Mọi công việc từ đó dồn vào một mục tiêu: chuẩn bị cán bộ, tìm nơi đứng chân sát biên giới và nối đường dây với các tỉnh miền núi phía Bắc. Cuối năm 1940, Người rời Côn Minh, qua Quế Lâm rồi xuống vùng biên giới Quảng Tây giáp Cao Bằng. Tại đây, Người mở lớp huấn luyện cho những cán bộ từ Cao Bằng sang. Ngày 28/1/1941, Người vượt cột mốc 108 trở về Tổ quốc. Tính từ mùa hè ở Côn Minh, cuộc trở về chỉ mất khoảng bảy tháng, một khoảng thời gian rất ngắn so với gần ba mươi năm Người đã sống xa quê hương."},{"t":"Các mốc thời gian. Đầu năm 1940: Người đến Côn Minh, bắt liên lạc với Ban Hải ngoại của Đảng và cơ sở trong nước. 5/1940: Phạm Văn Đồng và Võ Nguyên Giáp rời Hà Nội sang Trung Quốc. 6/1940: Tại Côn Minh, hai ông được gặp Người; Võ Nguyên Giáp gặp Người lần đầu bên hồ Thúy Hồ. 14/6/1940: Quân Đức tiến vào Paris. 22/6/1940: Pháp ký hiệp định đình chiến với Đức, chấp nhận thất bại. 6/1940: Nhật buộc chính quyền Pháp ở Đông Dương đóng tuyến đường sắt Hải Phòng – Côn Minh đối với hàng tiếp tế cho Trung Quốc. Mùa hè 1940: Người nhận định việc Pháp mất nước là thời cơ, quyết định gấp rút chuẩn bị về nước. 22/9/1940: Quân Nhật đánh vào Lạng Sơn, bắt đầu chiếm đóng Đông Dương. 27/9/1940: Khởi nghĩa Bắc Sơn. 23/11/1940: Khởi nghĩa Nam Kỳ. Cuối năm 1940: Người rời Côn Minh, qua Quế Lâm xuống vùng biên giới Quảng Tây giáp Cao Bằng. 28/1/1941: Người vượt cột mốc 108 về Pác Bó, Cao Bằng."},{"t":"Bạn có biết? Hiệp định đình chiến ngày 22/6/1940 được ký trong một toa tàu ở rừng Compiègne, đúng toa tàu nơi nước Đức bại trận đã phải ký đình chiến năm 1918. Hitler chọn địa điểm ấy để biến thất bại của nước Pháp thành một sự trả đũa đầy tính biểu tượng."},{"t":"Côn Minh trong trí nhớ hôm nay. Tháng 11/2024, nhân chuyến công tác tại Vân Nam, Thủ tướng Phạm Minh Chính đến thăm nơi ở cũ của Người ở Côn Minh. Tháng 6/2025, Phó Thủ tướng Trần Hồng Hà cũng tới thăm khu di tích. Những chuyến thăm như vậy, cùng dòng người Việt Nam đến Côn Minh học tập, làm ăn, du lịch, đã biến ngôi nhà nhỏ thành một địa chỉ quen thuộc, nơi người Việt ở xa tìm về một dấu mốc của lịch sử dân tộc. Những tấm ảnh và tư liệu trong nhà lưu niệm không thể tái hiện hết không khí của mùa hè năm 1940: những cuộc hẹn gặp bí mật, những bản tin chiến sự, những buổi bàn bạc về con đường phía trước. Nhưng chúng giúp người xem hình dung một điều cốt lõi. Quyết định về nước năm 1940 không phải là một bước đi may rủi, mà là kết quả của một tầm nhìn biết đọc thời cuộc thế giới để tìm ra cơ hội cho dân tộc mình."},{"t":"Từ Côn Minh đến Ba Đình. Từ mùa hè năm 1940 ở Côn Minh đến ngày 2/9/1945 trên quảng trường Ba Đình là hơn năm năm. Trong khoảng thời gian ấy, Người về nước, chủ trì Hội nghị Trung ương tháng 5/1941 ở Pác Bó, thành lập Mặt trận Việt Minh. Người đi qua hơn một năm tù đày ở Quảng Tây, rồi cùng Trung ương Đảng lãnh đạo toàn dân giành chính quyền. Phạm Văn Đồng và Võ Nguyên Giáp, hai người khách từ Hà Nội năm nào, đồng hành cùng Người trong những bước đi ấy. Vì thế, không gian nhỏ trong tấm ảnh mang một sức nặng lớn. Nó nhắc người xem rằng lịch sử đôi khi rẽ hướng ở những nơi rất bình thường: một mặt hồ giữa phố, một căn nhà nhỏ, một bản tin chiến sự từ nửa vòng trái đất. Điều làm nên khác biệt là con người biết nhận ra khoảnh khắc ấy và dám hành động ngay, không chần chừ."}],"so_chu":1649},{"i":7,"tieu_de_bang":"Cổng Trường Quân sự Hoàng Phố, Quảng Châu","tieu_de":"Cánh cổng trên đảo Trường Châu và câu đối “tham sinh úy tử”","sapo":"Tấm ảnh chụp tháng 4/2009 dừng lại trước cổng một ngôi trường nay đã tròn một thế kỷ tuổi. Trên tấm biển là sáu chữ Hán “Lục quân quân quan học hiệu”; gắn với ngôi trường là câu đối răn kẻ tham sống sợ chết chớ bước qua cửa. Trong số những người từng qua cánh cổng ấy có những thanh niên Việt Nam đi theo con đường Nguyễn Ái Quốc vạch ra từ lớp học trên phố Văn Minh.","bia":{"src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Sáu chữ trên tấm biển","text":"Tấm ảnh do một người dùng Wikimedia Commons chụp ngày 18/4/2009. Trên cổng là tấm biển ghi sáu chữ Hán 陸軍軍官學校, đọc là “Lục quân quân quan học hiệu”, nghĩa là Trường Sĩ quan Lục quân. Tên gọi chính thức đầy đủ của trường là Trường Sĩ quan Lục quân của Quốc dân Đảng Trung Quốc. Còn người đời quen gọi theo địa danh: Trường Quân sự Hoàng Phố, vì trường đặt ở vùng Hoàng Phố, phía đông thành phố Quảng Châu.\n\nChính xác hơn, trường nằm trên đảo Trường Châu, một hòn đảo giữa dòng Châu Giang, trên đường thủy từ Quảng Châu ra cửa biển. Vị trí ấy vừa kín đáo, dễ phòng thủ, vừa thuận đường vào thành phố. Cánh cổng giản dị trong ảnh là hình ảnh quen thuộc nhất của trường, xuất hiện trên vô số sách báo, phim ảnh viết về lịch sử Trung Quốc hiện đại. Với người Việt Nam, cánh cổng ấy còn gắn với những học trò đầu tiên của Nguyễn Ái Quốc.","doc":1},{"loai":"doan","tieu_de":"Vì sao Tôn Trung Sơn cần một ngôi trường","text":"Để hiểu vì sao ngôi trường ra đời, phải trở lại Quảng Châu đầu những năm 1920. Tôn Trung Sơn, người lãnh đạo Cách mạng Tân Hợi năm 1911, nhiều lần dựng chính quyền ở phương Nam nhưng đều phải dựa vào quân đội của các tướng quân phiệt, những đồng minh sẵn sàng trở mặt. Năm 1922, chính viên tướng trấn giữ Quảng Đông là Trần Quýnh Minh nổi dậy, buộc Tôn Trung Sơn phải lánh lên một pháo hạm trên sông Châu Giang.\n\nBài học ấy cho thấy một chính đảng cách mạng cần có quân đội của riêng mình, được giáo dục về chính trị chứ không chỉ biết cầm súng. Tôn Trung Sơn tìm thấy sự giúp đỡ ở nước Nga Xô viết. Tháng 1/1924, Đại hội đại biểu toàn quốc lần thứ nhất của Quốc dân Đảng họp ở Quảng Châu, xác lập chính sách liên Nga, liên Cộng, mở ra thời kỳ hợp tác Quốc – Cộng lần thứ nhất. Việc lập một trường sĩ quan được xúc tiến ngay trong năm ấy, với tiền bạc, vũ khí và cố vấn từ Liên Xô.","doc":2},{"loai":"anh","src":"textures/bang_w/G09_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quân sự Hoàng Phố, Quảng Châu”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ngày khai giảng 16/6/1924","text":"Ngày 16/6/1924, Trường Quân sự Hoàng Phố làm lễ khai giảng khóa đầu tiên với khoảng năm trăm học viên. Tôn Trung Sơn đích thân đến đảo Trường Châu đọc diễn văn, kêu gọi các học viên trở thành nòng cốt của một đội quân cách mạng cứu nước. Hiệu trưởng nhà trường là Tưởng Giới Thạch, người trước đó được Tôn Trung Sơn cử sang Liên Xô khảo sát về quân đội. Đại diện của Quốc dân Đảng tại trường là Liêu Trọng Khải, một nhân vật cánh tả thân cận với Tôn Trung Sơn.\n\nMô hình Xô viết in dấu rõ nét trong cách tổ chức. Bên cạnh các môn chiến thuật, binh khí, học viên phải học chính trị, và trường có hẳn một bộ phận phụ trách công tác chính trị. Từ cuối năm 1924, người đứng đầu bộ phận này là Chu Ân Lai, khi ấy mới hai mươi sáu tuổi, vừa từ châu Âu trở về. Các cố vấn quân sự Liên Xô, trong đó có tướng Vasily Blyukher được biết với bí danh Galen, trực tiếp tham gia giảng dạy và chỉ đạo huấn luyện.","doc":3},{"loai":"doan","tieu_de":"Câu đối trên cửa trường","text":"Gắn liền với hình ảnh ngôi trường là một câu đối được lưu truyền rộng rãi: 升官發財請往他處，貪生畏死勿入斯門. Đọc theo âm Hán Việt là “Thăng quan phát tài thỉnh vãng tha xứ, tham sinh úy tử vật nhập tư môn”. Nghĩa là: ai muốn thăng quan phát tài xin mời đi nơi khác; kẻ tham sống sợ chết chớ vào cửa này. Bức hoành đi kèm có bốn chữ 革命者來, “Cách mạng giả lai”, tức là người cách mạng hãy đến đây.\n\nCâu đối nói lên điều mà ngôi trường muốn khác với các trường võ bị cũ. Thời quân phiệt, đi lính, làm quan võ thường là con đường tiến thân, làm giàu. Hoàng Phố muốn đào tạo một lớp sĩ quan có lý tưởng, sẵn sàng hy sinh vì mục tiêu chống đế quốc, chống quân phiệt. Khẩu hiệu của trường là bốn chữ “thân ái tinh thành”, đề cao tình đoàn kết và lòng chân thành giữa những người cùng chí hướng.","doc":4},{"loai":"ban_co_biet","text":"Lời huấn thị của Tôn Trung Sơn trong lễ khai giảng Trường Quân sự Hoàng Phố ngày 16/6/1924 về sau được dùng làm lời bài quốc ca của Trung Hoa Dân quốc, mở đầu bằng câu “Tam dân chủ nghĩa, ngô đảng sở tông”.","nguon_ten":"Tư liệu Nhà kỷ niệm di chỉ Trường Quân sự Hoàng Phố, Quảng Châu","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","chu_thich":"Cổng Trường Quân sự Hoàng Phố trên đảo Trường Châu, Quảng Châu, với tấm biển “Lục quân quân quan học hiệu”; ảnh chụp tháng 4/2009.","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ lớp học phố Văn Minh đến đảo Trường Châu","text":"Tháng 11/1924, khi Nguyễn Ái Quốc đến Quảng Châu với tên Lý Thụy, trường Hoàng Phố đã hoạt động được gần nửa năm. Làm việc trong phái bộ cố vấn của Borodin, Người ở ngay giữa mạng lưới quan hệ Xô – Trung đã góp phần dựng nên ngôi trường. Người sớm nhận ra đây là cơ hội hiếm có. Ở Đông Dương, thanh niên yêu nước không có con đường nào để học quân sự cho cách mạng; còn ở Quảng Châu, một trường sĩ quan hiện đại đang mở cửa cho những người cùng mục tiêu chống đế quốc.\n\nVì vậy, bên cạnh việc huấn luyện chính trị ở phố Văn Minh, Người lựa chọn một số học viên, giới thiệu vào học ở Hoàng Phố. Họ học chiến thuật, kỹ thuật quân sự cùng học viên Trung Quốc, trong kỷ luật nghiêm ngặt của một trường sĩ quan. Tên tuổi và số phận của những học viên Việt Nam ấy được kể riêng trong chuyên đề Trường Quân sự Hoàng Phố. Ở đây chỉ xin nhắc rằng, với họ, cánh cổng trong ảnh là cánh cổng mở vào nghề binh để một ngày phục vụ Tổ quốc.","doc":6},{"loai":"doan","tieu_de":"Năm 1927: một ngôi trường, hai ngả đường","text":"Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản, chấm dứt hợp tác Quốc – Cộng. Những học viên từng đứng chung hàng dưới câu đối “tham sinh úy tử” giờ chia về hai phía của cuộc nội chiến. Nhiều người tốt nghiệp Hoàng Phố trở thành tướng lĩnh chủ chốt của quân đội Quốc dân Đảng. Nhiều người khác trở thành những chỉ huy nổi tiếng của Hồng quân, về sau là Quân Giải phóng Nhân dân Trung Quốc.\n\nBản thân ngôi trường cũng rời đảo Trường Châu. Năm 1928, trường được chuyển lên Nam Kinh, trở thành Trường Sĩ quan Lục quân Trung ương; khu trường cũ ở Quảng Châu còn hoạt động thêm một thời gian ngắn như một phân hiệu. Theo bước chính quyền Quốc dân Đảng, trường về sau chuyển tới Thành Đô trong kháng chiến chống Nhật, rồi sang Đài Loan. Còn cánh cổng trên đảo Trường Châu ở lại với dòng Châu Giang, chứng kiến những năm tháng chiến tranh đi qua.","doc":7},{"loai":"anh","src":"textures/bang_w/G09_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quân sự Hoàng Phố, Quảng Châu”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bom đạn và những lần phục dựng","text":"Năm 1938, máy bay Nhật ném bom Quảng Châu, phần lớn công trình của trường cũ trên đảo Trường Châu bị phá hủy. Trong nhiều năm sau đó, nơi từng đào tạo hàng nghìn sĩ quan chỉ còn lại những dấu tích rải rác. Cánh cổng và một số công trình được tu bổ dần theo dáng cũ. Cuối thập niên 1980, di chỉ trường được Nhà nước Trung Quốc xếp hạng đơn vị bảo vệ văn vật trọng điểm cấp quốc gia. Giữa thập niên 1990, tòa nhà hiệu bộ được xây dựng lại trên nền cũ theo kiến trúc ban đầu.\n\nNgày nay, khu di tích là Nhà kỷ niệm di chỉ Trường Quân sự Hoàng Phố, mở cửa đón khách tham quan. Khách đến đảo đi qua cánh cổng trong ảnh, vào tòa nhà hiệu bộ với các phòng học, phòng ở của học viên được tái hiện. Khách có thể xem những phòng trưng bày về lịch sử nhà trường và thăm đài kỷ niệm Tôn Trung Sơn trên đảo. Tháng 6/2024, trường tròn một trăm năm kể từ ngày khai giảng khóa đầu tiên. Nhiều khách Việt Nam khi đến Quảng Châu cũng tìm về đây.","doc":8},{"loai":"ban_co_biet","text":"Sáu chữ 陸軍軍官學校 trên cổng trường Hoàng Phố đến nay vẫn là tên gọi của trường sĩ quan lục quân ở Phượng Sơn, Cao Hùng, Đài Loan. Ngôi trường ấy tự coi mình là hậu thân của Hoàng Phố, sau nhiều lần di chuyển theo chính quyền Quốc dân Đảng.","nguon_ten":"Tư liệu lịch sử Trường Sĩ quan Lục quân, Phượng Sơn, Cao Hùng","doc":9},{"loai":"anh","src":"textures/bang_w/G09_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quân sự Hoàng Phố, Quảng Châu”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Đọc tấm ảnh bằng con mắt người Việt","text":"Với khách Trung Quốc, cánh cổng Hoàng Phố gợi nhớ những trang sử của Cách mạng Tân Hợi, của cuộc Bắc phạt và thời kỳ hợp tác Quốc – Cộng. Với người Việt Nam, tấm ảnh còn mang một lớp nghĩa khác. Nó nhắc rằng ngay từ giữa những năm 1920, khi phong trào cách mạng trong nước còn rất non trẻ, Nguyễn Ái Quốc đã nghĩ tới việc đào tạo cán bộ quân sự. Người tận dụng mọi điều kiện quốc tế thuận lợi để chuẩn bị lực lượng cho ngày khởi nghĩa.\n\nTư duy kết hợp huấn luyện chính trị với rèn luyện quân sự ấy được Người tiếp tục vận dụng trên suốt chặng đường về sau. Hai mươi năm sau, giữa núi rừng Cao Bằng, Người chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Trong chỉ thị, Người giải thích tên gọi của đội có nghĩa là chính trị trọng hơn quân sự. Cánh cổng trên đảo Trường Châu vì thế là một chặng trên con đường dài dẫn tới Quân đội nhân dân Việt Nam.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, 12/1944)","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Tư liệu Nhà kỷ niệm di chỉ Trường Quân sự Hoàng Phố (黄埔军校旧址纪念馆), Quảng Châu"],"doc":[{"t":"Cánh cổng trên đảo Trường Châu và câu đối “tham sinh úy tử”. Tấm ảnh chụp tháng 4/2009 dừng lại trước cổng một ngôi trường nay đã tròn một thế kỷ tuổi. Trên tấm biển là sáu chữ Hán “Lục quân quân quan học hiệu”; gắn với ngôi trường là câu đối răn kẻ tham sống sợ chết chớ bước qua cửa. Trong số những người từng qua cánh cổng ấy có những thanh niên Việt Nam đi theo con đường Nguyễn Ái Quốc vạch ra từ lớp học trên phố Văn Minh."},{"t":"Sáu chữ trên tấm biển. Tấm ảnh do một người dùng Wikimedia Commons chụp ngày 18/4/2009. Trên cổng là tấm biển ghi sáu chữ Hán 陸軍軍官學校, đọc là “Lục quân quân quan học hiệu”, nghĩa là Trường Sĩ quan Lục quân. Tên gọi chính thức đầy đủ của trường là Trường Sĩ quan Lục quân của Quốc dân Đảng Trung Quốc. Còn người đời quen gọi theo địa danh: Trường Quân sự Hoàng Phố, vì trường đặt ở vùng Hoàng Phố, phía đông thành phố Quảng Châu. Chính xác hơn, trường nằm trên đảo Trường Châu, một hòn đảo giữa dòng Châu Giang, trên đường thủy từ Quảng Châu ra cửa biển. Vị trí ấy vừa kín đáo, dễ phòng thủ, vừa thuận đường vào thành phố. Cánh cổng giản dị trong ảnh là hình ảnh quen thuộc nhất của trường, xuất hiện trên vô số sách báo, phim ảnh viết về lịch sử Trung Quốc hiện đại. Với người Việt Nam, cánh cổng ấy còn gắn với những học trò đầu tiên của Nguyễn Ái Quốc."},{"t":"Vì sao Tôn Trung Sơn cần một ngôi trường. Để hiểu vì sao ngôi trường ra đời, phải trở lại Quảng Châu đầu những năm 1920. Tôn Trung Sơn, người lãnh đạo Cách mạng Tân Hợi năm 1911, nhiều lần dựng chính quyền ở phương Nam nhưng đều phải dựa vào quân đội của các tướng quân phiệt, những đồng minh sẵn sàng trở mặt. Năm 1922, chính viên tướng trấn giữ Quảng Đông là Trần Quýnh Minh nổi dậy, buộc Tôn Trung Sơn phải lánh lên một pháo hạm trên sông Châu Giang. Bài học ấy cho thấy một chính đảng cách mạng cần có quân đội của riêng mình, được giáo dục về chính trị chứ không chỉ biết cầm súng. Tôn Trung Sơn tìm thấy sự giúp đỡ ở nước Nga Xô viết. Tháng 1/1924, Đại hội đại biểu toàn quốc lần thứ nhất của Quốc dân Đảng họp ở Quảng Châu, xác lập chính sách liên Nga, liên Cộng, mở ra thời kỳ hợp tác Quốc – Cộng lần thứ nhất. Việc lập một trường sĩ quan được xúc tiến ngay trong năm ấy, với tiền bạc, vũ khí và cố vấn từ Liên Xô."},{"t":"Ngày khai giảng 16/6/1924. Ngày 16/6/1924, Trường Quân sự Hoàng Phố làm lễ khai giảng khóa đầu tiên với khoảng năm trăm học viên. Tôn Trung Sơn đích thân đến đảo Trường Châu đọc diễn văn, kêu gọi các học viên trở thành nòng cốt của một đội quân cách mạng cứu nước. Hiệu trưởng nhà trường là Tưởng Giới Thạch, người trước đó được Tôn Trung Sơn cử sang Liên Xô khảo sát về quân đội. Đại diện của Quốc dân Đảng tại trường là Liêu Trọng Khải, một nhân vật cánh tả thân cận với Tôn Trung Sơn. Mô hình Xô viết in dấu rõ nét trong cách tổ chức. Bên cạnh các môn chiến thuật, binh khí, học viên phải học chính trị, và trường có hẳn một bộ phận phụ trách công tác chính trị. Từ cuối năm 1924, người đứng đầu bộ phận này là Chu Ân Lai, khi ấy mới hai mươi sáu tuổi, vừa từ châu Âu trở về. Các cố vấn quân sự Liên Xô, trong đó có tướng Vasily Blyukher được biết với bí danh Galen, trực tiếp tham gia giảng dạy và chỉ đạo huấn luyện."},{"t":"Câu đối trên cửa trường. Gắn liền với hình ảnh ngôi trường là một câu đối được lưu truyền rộng rãi: 升官發財請往他處，貪生畏死勿入斯門. Đọc theo âm Hán Việt là “Thăng quan phát tài thỉnh vãng tha xứ, tham sinh úy tử vật nhập tư môn”. Nghĩa là: ai muốn thăng quan phát tài xin mời đi nơi khác; kẻ tham sống sợ chết chớ vào cửa này. Bức hoành đi kèm có bốn chữ 革命者來, “Cách mạng giả lai”, tức là người cách mạng hãy đến đây. Câu đối nói lên điều mà ngôi trường muốn khác với các trường võ bị cũ. Thời quân phiệt, đi lính, làm quan võ thường là con đường tiến thân, làm giàu. Hoàng Phố muốn đào tạo một lớp sĩ quan có lý tưởng, sẵn sàng hy sinh vì mục tiêu chống đế quốc, chống quân phiệt. Khẩu hiệu của trường là bốn chữ “thân ái tinh thành”, đề cao tình đoàn kết và lòng chân thành giữa những người cùng chí hướng."},{"t":"Bạn có biết? Lời huấn thị của Tôn Trung Sơn trong lễ khai giảng Trường Quân sự Hoàng Phố ngày 16/6/1924 về sau được dùng làm lời bài quốc ca của Trung Hoa Dân quốc, mở đầu bằng câu “Tam dân chủ nghĩa, ngô đảng sở tông”."},{"t":"Từ lớp học phố Văn Minh đến đảo Trường Châu. Tháng 11/1924, khi Nguyễn Ái Quốc đến Quảng Châu với tên Lý Thụy, trường Hoàng Phố đã hoạt động được gần nửa năm. Làm việc trong phái bộ cố vấn của Borodin, Người ở ngay giữa mạng lưới quan hệ Xô – Trung đã góp phần dựng nên ngôi trường. Người sớm nhận ra đây là cơ hội hiếm có. Ở Đông Dương, thanh niên yêu nước không có con đường nào để học quân sự cho cách mạng; còn ở Quảng Châu, một trường sĩ quan hiện đại đang mở cửa cho những người cùng mục tiêu chống đế quốc. Vì vậy, bên cạnh việc huấn luyện chính trị ở phố Văn Minh, Người lựa chọn một số học viên, giới thiệu vào học ở Hoàng Phố. Họ học chiến thuật, kỹ thuật quân sự cùng học viên Trung Quốc, trong kỷ luật nghiêm ngặt của một trường sĩ quan. Tên tuổi và số phận của những học viên Việt Nam ấy được kể riêng trong chuyên đề Trường Quân sự Hoàng Phố. Ở đây chỉ xin nhắc rằng, với họ, cánh cổng trong ảnh là cánh cổng mở vào nghề binh để một ngày phục vụ Tổ quốc."},{"t":"Năm 1927: một ngôi trường, hai ngả đường. Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản, chấm dứt hợp tác Quốc – Cộng. Những học viên từng đứng chung hàng dưới câu đối “tham sinh úy tử” giờ chia về hai phía của cuộc nội chiến. Nhiều người tốt nghiệp Hoàng Phố trở thành tướng lĩnh chủ chốt của quân đội Quốc dân Đảng. Nhiều người khác trở thành những chỉ huy nổi tiếng của Hồng quân, về sau là Quân Giải phóng Nhân dân Trung Quốc. Bản thân ngôi trường cũng rời đảo Trường Châu. Năm 1928, trường được chuyển lên Nam Kinh, trở thành Trường Sĩ quan Lục quân Trung ương; khu trường cũ ở Quảng Châu còn hoạt động thêm một thời gian ngắn như một phân hiệu. Theo bước chính quyền Quốc dân Đảng, trường về sau chuyển tới Thành Đô trong kháng chiến chống Nhật, rồi sang Đài Loan. Còn cánh cổng trên đảo Trường Châu ở lại với dòng Châu Giang, chứng kiến những năm tháng chiến tranh đi qua."},{"t":"Bom đạn và những lần phục dựng. Năm 1938, máy bay Nhật ném bom Quảng Châu, phần lớn công trình của trường cũ trên đảo Trường Châu bị phá hủy. Trong nhiều năm sau đó, nơi từng đào tạo hàng nghìn sĩ quan chỉ còn lại những dấu tích rải rác. Cánh cổng và một số công trình được tu bổ dần theo dáng cũ. Cuối thập niên 1980, di chỉ trường được Nhà nước Trung Quốc xếp hạng đơn vị bảo vệ văn vật trọng điểm cấp quốc gia. Giữa thập niên 1990, tòa nhà hiệu bộ được xây dựng lại trên nền cũ theo kiến trúc ban đầu. Ngày nay, khu di tích là Nhà kỷ niệm di chỉ Trường Quân sự Hoàng Phố, mở cửa đón khách tham quan. Khách đến đảo đi qua cánh cổng trong ảnh, vào tòa nhà hiệu bộ với các phòng học, phòng ở của học viên được tái hiện. Khách có thể xem những phòng trưng bày về lịch sử nhà trường và thăm đài kỷ niệm Tôn Trung Sơn trên đảo. Tháng 6/2024, trường tròn một trăm năm kể từ ngày khai giảng khóa đầu tiên. Nhiều khách Việt Nam khi đến Quảng Châu cũng tìm về đây."},{"t":"Bạn có biết? Sáu chữ 陸軍軍官學校 trên cổng trường Hoàng Phố đến nay vẫn là tên gọi của trường sĩ quan lục quân ở Phượng Sơn, Cao Hùng, Đài Loan. Ngôi trường ấy tự coi mình là hậu thân của Hoàng Phố, sau nhiều lần di chuyển theo chính quyền Quốc dân Đảng."},{"t":"Đọc tấm ảnh bằng con mắt người Việt. Với khách Trung Quốc, cánh cổng Hoàng Phố gợi nhớ những trang sử của Cách mạng Tân Hợi, của cuộc Bắc phạt và thời kỳ hợp tác Quốc – Cộng. Với người Việt Nam, tấm ảnh còn mang một lớp nghĩa khác. Nó nhắc rằng ngay từ giữa những năm 1920, khi phong trào cách mạng trong nước còn rất non trẻ, Nguyễn Ái Quốc đã nghĩ tới việc đào tạo cán bộ quân sự. Người tận dụng mọi điều kiện quốc tế thuận lợi để chuẩn bị lực lượng cho ngày khởi nghĩa. Tư duy kết hợp huấn luyện chính trị với rèn luyện quân sự ấy được Người tiếp tục vận dụng trên suốt chặng đường về sau. Hai mươi năm sau, giữa núi rừng Cao Bằng, Người chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Trong chỉ thị, Người giải thích tên gọi của đội có nghĩa là chính trị trọng hơn quân sự. Cánh cổng trên đảo Trường Châu vì thế là một chặng trên con đường dài dẫn tới Quân đội nhân dân Việt Nam."}],"so_chu":1650},{"i":8,"tieu_de_bang":"Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)","tieu_de":"Trăng, lò than hồng và chất thép: thơ viết trong ngục của Hồ Chí Minh","sapo":"Tấm ảnh ghi lại tờ cuối của cuốn sổ tay nhỏ, nơi người tù Hồ Chí Minh chép những bài thơ chữ Hán suốt hơn một năm bị giải qua các nhà lao Quảng Tây. Lật ngược từ trang cuối ấy, người đọc gặp vầng trăng qua khe cửa, cô gái xóm núi bên lò than, tiếng chày giã gạo và cả tiếng cười châm biếm nhắm vào bọn cai ngục. Điều gì khiến một tập thơ viết trong xiềng xích lại chan chứa ánh sáng đến thế?","bia":{"src":"textures/ht/ht_anh_to_cuoi_tap_tho_nhat_ky_trong_tu.jpg","credit":"Ảnh: 7ieulong · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Trang giấy khép lại một hành trình","text":"Tờ giấy trong ảnh là tờ cuối của bản thảo Nhật ký trong tù, cuốn sổ tay nhỏ Người mang theo trong những ngày bị giam giữ ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1943. Ảnh được chia sẻ trên Wikimedia Commons năm 2016, dưới dạng tư liệu thuộc phạm vi công cộng. Trên trang giấy đã ngả màu là những dòng chữ Hán viết tay của một người quen cầm bút từ thuở thiếu thời.\n\nGọi là nhật ký, nhưng cuốn sổ không ghi chép bằng văn xuôi. Mỗi chặng đường, mỗi nhà lao, mỗi cảnh đời được Người ghi lại bằng một bài thơ. Nhiều nhan đề là tên đất, tên nhà giam: bị bắt giữ ở phố Túc Vinh, vào nhà ngục huyện Tĩnh Tây, nhà lao Nam Ninh, Lai Tân, đến Quế Lâm. Lần theo các nhan đề ấy, người đọc có thể vẽ lại hành trình bị giải đi khắp tỉnh Quảng Tây (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Tờ cuối trong ảnh là nơi hành trình bằng thơ ấy khép lại.","doc":1},{"loai":"doan","tieu_de":"Vì sao là chữ Hán","text":"Người viết Nhật ký trong tù bằng chữ Hán, thứ chữ Người được học từ nhỏ. Thuở ấu thơ ở làng Kim Liên và ở Huế, cậu bé Nguyễn Sinh Cung học chữ Hán với người cha là cụ Phó bảng Nguyễn Sinh Sắc, rồi theo học thầy Vương Thúc Quý. Vốn Hán học ấy theo Người suốt cuộc đời hoạt động, giúp Người đọc, viết và giao tiếp dễ dàng trong những năm ở Trung Quốc.\n\nTrong nhà lao Quảng Tây, chữ Hán còn là ngôn ngữ của chính môi trường xung quanh, của bạn tù và của cai ngục. Tập thơ được viết chủ yếu theo thể thất ngôn tứ tuyệt của thơ Đường, mỗi bài bốn câu, mỗi câu bảy chữ. Đó là thể thơ đòi hỏi sự cô đọng cao độ: chỉ hai mươi tám chữ phải chứa cả một cảnh, một tình, một ý. Theo sách giáo khoa Ngữ văn, tập thơ gồm 133 bài, phần lớn theo thể tứ tuyệt. Mỗi bài như một trang nhật ký nén lại trong vài dòng.","doc":2},{"loai":"trich","text":"Ngục trung vô tửu diệc vô hoa, / Đối thử lương tiêu nại nhược hà? / Nhân hướng song tiền khán minh nguyệt, / Nguyệt tòng song khích khán thi gia. — Dịch thơ: Trong tù không rượu cũng không hoa, / Cảnh đẹp đêm nay khó hững hờ; / Người ngắm trăng soi ngoài cửa sổ, / Trăng nhòm khe cửa ngắm nhà thơ.","nguoi":"Hồ Chí Minh (bản dịch thơ của Nam Trân)","nguon_ten":"Bài “Vọng nguyệt” (Ngắm trăng), Nhật ký trong tù, 1942 – 1943","doc":3},{"loai":"doan","tieu_de":"Người ngắm trăng, trăng ngắm nhà thơ","text":"Bài Ngắm trăng là một ví dụ tiêu biểu. Câu đầu nêu một sự thiếu thốn: trong tù không rượu cũng không hoa, những thứ mà thi nhân xưa coi là bạn của đêm trăng. Câu thứ hai bộc lộ sự xao xuyến trước cảnh đẹp. Hai câu cuối dựng một hình ảnh đối xứng tuyệt đẹp: người từ sau song sắt hướng ra ngắm trăng, còn trăng thì từ khe cửa nhòm vào ngắm nhà thơ. Song sắt nhà tù vẫn ở đó, nhưng không ngăn được cuộc gặp gỡ giữa con người và thiên nhiên.\n\nNguyên tác chữ Hán cho thấy nghệ thuật ấy rõ hơn. Chữ “song”, tức cửa sổ, xuất hiện ở cả hai câu cuối; chữ “khán”, tức nhìn, ngắm, cũng vậy. Nhờ đó hai câu thơ tạo thành thế đối giữa “nhân” và “nguyệt”, giữa “minh nguyệt” và “thi gia”. Bản dịch thơ của Nam Trân giữ được tinh thần ấy, đưa Ngắm trăng trở thành một trong những bài thơ quen thuộc nhất với người đọc Việt Nam.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_to_cuoi_tap_tho_nhat_ky_trong_tu.jpg","chu_thich":"Tờ cuối bản thảo Nhật ký trong tù, cuốn sổ tay Người mang theo trong những ngày bị giam ở Quảng Tây (1942 – 1943).","credit":"Ảnh: 7ieulong · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Chiều tối: từ cánh chim đến lò than hồng","text":"Nếu Ngắm trăng là cuộc đối thoại với vầng trăng, thì bài Chiều tối là một bức tranh chuyển động. Trên đường bị giải đi, người tù nhìn thấy cánh chim mỏi bay về rừng tìm chốn ngủ, chòm mây lẻ trôi chầm chậm qua tầng không. Hai câu đầu mang đậm vẻ cổ điển của thơ Đường, với nỗi cô quạnh của buổi chiều nơi đất khách. Người đọc cảm được cả sự mệt mỏi của người tù sau một ngày đường.\n\nHai câu sau đột ngột chuyển về con người. Bản dịch của Nam Trân viết: “Cô em xóm núi xay ngô tối, / Xay hết, lò than đã rực hồng.” Hình ảnh cô gái lao động và ngọn lửa hồng làm ấm cả bài thơ. Thời gian trôi từ chiều sang tối, nhưng không gian lại sáng lên. Cách nhìn ấy lặp lại ở nhiều bài khác trong tập: dù bước chân đang bị xiềng, ánh mắt người tù luôn tìm đến sự sống, đến con người và đến ánh sáng.","doc":5},{"loai":"ban_co_biet","text":"Câu “Một ngày tù, nghìn thu ở ngoài” mà nhiều người Việt thuộc lòng có gốc từ bài Bốn tháng rồi trong Nhật ký trong tù. Nguyên tác mở đầu: “Nhất nhật tù, thiên thu tại ngoại, / Cổ nhân chi thoại bất sai ngoa”, nghĩa là lời người xưa nói quả không sai.","nguon_ten":"Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học)","doc":6},{"loai":"anh","src":"textures/bang_w/G09_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)”, nhìn từ xa."},{"loai":"doan","tieu_de":"“Nay ở trong thơ nên có thép”","text":"Không phải bài nào trong tập cũng êm đềm. Chính Người đã nêu quan niệm của mình trong bài Cảm tưởng đọc Thiên gia thi. Thiên gia thi là tuyển tập thơ Đường, Tống quen thuộc với người học chữ Hán thời trước, nơi thiên nhiên được ngợi ca qua mây, gió, trăng, hoa. Đọc lại tuyển tập ấy trong nhà lao, Người viết: “Xưa thơ yêu cảnh thiên nhiên đẹp, / Mây, gió, trăng, hoa, tuyết, núi, sông; / Nay ở trong thơ nên có thép, / Nhà thơ cũng phải biết xung phong.”\n\nChất thép ấy không phải là những lời hô hào. Nó nằm ở ý chí không khuất phục, ở cái nhìn tỉnh táo trước bất công, ở niềm tin vào ngày mai. Chữ “thép” trong nguyên tác là chữ “thiết”, gợi sự cứng rắn của sắt thép. Nhiều nhà nghiên cứu coi hai câu cuối của bài thơ là tuyên ngôn nghệ thuật của một nhà thơ chiến sĩ, người coi văn chương cũng là một mặt trận.","doc":7},{"loai":"doan","tieu_de":"Tiếng cười trong ngục","text":"Chất thép còn hiện ra qua tiếng cười. Bài Lai Tân chỉ có bốn câu mà vẽ trọn chân dung một bộ máy mục nát. Bản dịch viết: “Ban trưởng nhà lao chuyên đánh bạc, / Giải người, cảnh trưởng kiếm ăn quanh; / Chong đèn, huyện trưởng làm công việc, / Trời đất Lai Tân vẫn thái bình.” Ba câu đầu kể ba hạng người, mỗi người một thói; câu cuối kết lại bằng một lời khen nghe như thật, nhưng chính vì thế mà sâu cay.\n\nViệc huyện trưởng chong đèn nghe như chăm chỉ, nhưng người đọc thời ấy hiểu ngọn đèn kia là đèn thuốc phiện. Thái bình của Lai Tân, hóa ra, là thái bình của cờ bạc, ăn tiền và nghiện ngập. Tiếng cười nhẹ nhàng mà không khoan nhượng ấy cho thấy người tù không hề bị cảnh ngộ đè bẹp. Về tầm vóc tinh thần, ông vẫn đứng cao hơn hẳn những kẻ đang giam giữ mình.","doc":8},{"loai":"anh","src":"textures/bang_w/G09_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Gian nan rèn luyện mới thành công","text":"Bên cạnh vầng trăng và tiếng cười là những bài thơ đúc kết suy ngẫm về con người. Bài Nghe tiếng giã gạo mượn tiếng chày giã gạo để nói về lẽ sống. Bản dịch viết: “Gạo đem vào giã bao đau đớn, / Gạo giã xong rồi trắng tựa bông; / Sống ở trên đời người cũng vậy, / Gian nan rèn luyện mới thành công.” Hạt gạo phải chịu chày cối mới trắng; con người phải qua thử thách mới trưởng thành.\n\nNhững câu thơ giản dị ấy về sau được nhiều thế hệ học sinh thuộc lòng. Chúng ra đời trong hoàn cảnh chính người viết đang chịu cảnh chày cối của tù đày: bị trói, bị xích, bị giải đi trong mưa gió, nhiều lần ốm đau. Vì thế lời thơ không phải một bài học suông, mà là sự tự nhủ của một người đang sống đúng điều mình viết ra.","doc":9},{"loai":"doan","tieu_de":"Những phận người trong thơ","text":"Nhật ký trong tù còn là cuốn sổ ghi chép về những con người Người gặp. Có đứa trẻ còn ẵm ngửa phải theo mẹ vào nhà lao Tân Dương, khiến người tù đã ngoài năm mươi tuổi xót xa. Có những bạn tù nghèo khổ, có người chết trong cảnh giam cầm. Có những người dân phu, người nông dân Người bắt gặp dọc đường bị giải đi. Trong nhiều bài, nỗi đau của bản thân lùi lại phía sau, nhường chỗ cho niềm thương cảm với những số phận khác.\n\nỞ một số bài, Người để lộ nỗi nhớ quê hương, nhớ đồng chí, nỗi sốt ruột khi thời gian trôi qua mà việc lớn còn dang dở. Đó là tâm trạng rất thật của một nhà cách mạng bị tách khỏi phong trào đúng vào lúc thế giới đang chuyển mình. Chính sự chân thật ấy làm cho tập thơ gần gũi: người đọc thấy ở đó không phải một hình tượng xa vời, mà một con người biết đau, biết nhớ, biết cười.","doc":10},{"loai":"ban_co_biet","text":"Nhiều bài trong Nhật ký trong tù được đưa vào sách giáo khoa Ngữ văn của Việt Nam, như Ngắm trăng, Đi đường, Chiều tối. Bản dịch thơ quen thuộc của nhiều bài là của nhà thơ Nam Trân, người tham gia dịch tập thơ tại Viện Văn học.","nguon_ten":"Sách giáo khoa Ngữ văn, NXB Giáo dục Việt Nam","doc":11},{"loai":"anh","src":"textures/bang_w/G09_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Sau tờ cuối","text":"Tháng 9/1943, Người được trả tự do. Tờ cuối trong ảnh trở thành trang khép lại một chương đặc biệt trong đời Người. Nhưng với văn học Việt Nam, đó lại là trang mở đầu của một hành trình mới. Tập thơ vốn được viết để vơi đi những ngày dài trong ngục, về sau đến với đông đảo bạn đọc, được dịch ra nhiều thứ tiếng và trở thành đối tượng của vô số công trình nghiên cứu.\n\nNhìn tờ giấy cũ trong ảnh, người xem có thể hình dung người tù ngồi trong ánh sáng lờ mờ của nhà giam, chép từng câu thơ vào cuốn sổ nhỏ. Không song sắt nào giam được tinh thần ấy. Câu chuyện về cuốn sổ như một hiện vật, về việc nó được gìn giữ, dịch thuật và trở thành Bảo vật quốc gia, xin dành cho chuyên đề Bản thảo Nhật ký trong tù – Bảo vật quốc gia.","doc":12}],"nguon":["Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học), NXB Văn học, 1960","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Sách giáo khoa Ngữ văn, NXB Giáo dục Việt Nam"],"doc":[{"t":"Trăng, lò than hồng và chất thép: thơ viết trong ngục của Hồ Chí Minh. Tấm ảnh ghi lại tờ cuối của cuốn sổ tay nhỏ, nơi người tù Hồ Chí Minh chép những bài thơ chữ Hán suốt hơn một năm bị giải qua các nhà lao Quảng Tây. Lật ngược từ trang cuối ấy, người đọc gặp vầng trăng qua khe cửa, cô gái xóm núi bên lò than, tiếng chày giã gạo và cả tiếng cười châm biếm nhắm vào bọn cai ngục. Điều gì khiến một tập thơ viết trong xiềng xích lại chan chứa ánh sáng đến thế?"},{"t":"Trang giấy khép lại một hành trình. Tờ giấy trong ảnh là tờ cuối của bản thảo Nhật ký trong tù, cuốn sổ tay nhỏ Người mang theo trong những ngày bị giam giữ ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1943. Ảnh được chia sẻ trên Wikimedia Commons năm 2016, dưới dạng tư liệu thuộc phạm vi công cộng. Trên trang giấy đã ngả màu là những dòng chữ Hán viết tay của một người quen cầm bút từ thuở thiếu thời. Gọi là nhật ký, nhưng cuốn sổ không ghi chép bằng văn xuôi. Mỗi chặng đường, mỗi nhà lao, mỗi cảnh đời được Người ghi lại bằng một bài thơ. Nhiều nhan đề là tên đất, tên nhà giam: bị bắt giữ ở phố Túc Vinh, vào nhà ngục huyện Tĩnh Tây, nhà lao Nam Ninh, Lai Tân, đến Quế Lâm. Lần theo các nhan đề ấy, người đọc có thể vẽ lại hành trình bị giải đi khắp tỉnh Quảng Tây (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Tờ cuối trong ảnh là nơi hành trình bằng thơ ấy khép lại."},{"t":"Vì sao là chữ Hán. Người viết Nhật ký trong tù bằng chữ Hán, thứ chữ Người được học từ nhỏ. Thuở ấu thơ ở làng Kim Liên và ở Huế, cậu bé Nguyễn Sinh Cung học chữ Hán với người cha là cụ Phó bảng Nguyễn Sinh Sắc, rồi theo học thầy Vương Thúc Quý. Vốn Hán học ấy theo Người suốt cuộc đời hoạt động, giúp Người đọc, viết và giao tiếp dễ dàng trong những năm ở Trung Quốc. Trong nhà lao Quảng Tây, chữ Hán còn là ngôn ngữ của chính môi trường xung quanh, của bạn tù và của cai ngục. Tập thơ được viết chủ yếu theo thể thất ngôn tứ tuyệt của thơ Đường, mỗi bài bốn câu, mỗi câu bảy chữ. Đó là thể thơ đòi hỏi sự cô đọng cao độ: chỉ hai mươi tám chữ phải chứa cả một cảnh, một tình, một ý. Theo sách giáo khoa Ngữ văn, tập thơ gồm 133 bài, phần lớn theo thể tứ tuyệt. Mỗi bài như một trang nhật ký nén lại trong vài dòng."},{"t":"Ngục trung vô tửu diệc vô hoa, / Đối thử lương tiêu nại nhược hà? / Nhân hướng song tiền khán minh nguyệt, / Nguyệt tòng song khích khán thi gia. — Dịch thơ: Trong tù không rượu cũng không hoa, / Cảnh đẹp đêm nay khó hững hờ; / Người ngắm trăng soi ngoài cửa sổ, / Trăng nhòm khe cửa ngắm nhà thơ. — Hồ Chí Minh (bản dịch thơ của Nam Trân)"},{"t":"Người ngắm trăng, trăng ngắm nhà thơ. Bài Ngắm trăng là một ví dụ tiêu biểu. Câu đầu nêu một sự thiếu thốn: trong tù không rượu cũng không hoa, những thứ mà thi nhân xưa coi là bạn của đêm trăng. Câu thứ hai bộc lộ sự xao xuyến trước cảnh đẹp. Hai câu cuối dựng một hình ảnh đối xứng tuyệt đẹp: người từ sau song sắt hướng ra ngắm trăng, còn trăng thì từ khe cửa nhòm vào ngắm nhà thơ. Song sắt nhà tù vẫn ở đó, nhưng không ngăn được cuộc gặp gỡ giữa con người và thiên nhiên. Nguyên tác chữ Hán cho thấy nghệ thuật ấy rõ hơn. Chữ “song”, tức cửa sổ, xuất hiện ở cả hai câu cuối; chữ “khán”, tức nhìn, ngắm, cũng vậy. Nhờ đó hai câu thơ tạo thành thế đối giữa “nhân” và “nguyệt”, giữa “minh nguyệt” và “thi gia”. Bản dịch thơ của Nam Trân giữ được tinh thần ấy, đưa Ngắm trăng trở thành một trong những bài thơ quen thuộc nhất với người đọc Việt Nam."},{"t":"Chiều tối: từ cánh chim đến lò than hồng. Nếu Ngắm trăng là cuộc đối thoại với vầng trăng, thì bài Chiều tối là một bức tranh chuyển động. Trên đường bị giải đi, người tù nhìn thấy cánh chim mỏi bay về rừng tìm chốn ngủ, chòm mây lẻ trôi chầm chậm qua tầng không. Hai câu đầu mang đậm vẻ cổ điển của thơ Đường, với nỗi cô quạnh của buổi chiều nơi đất khách. Người đọc cảm được cả sự mệt mỏi của người tù sau một ngày đường. Hai câu sau đột ngột chuyển về con người. Bản dịch của Nam Trân viết: “Cô em xóm núi xay ngô tối, / Xay hết, lò than đã rực hồng.” Hình ảnh cô gái lao động và ngọn lửa hồng làm ấm cả bài thơ. Thời gian trôi từ chiều sang tối, nhưng không gian lại sáng lên. Cách nhìn ấy lặp lại ở nhiều bài khác trong tập: dù bước chân đang bị xiềng, ánh mắt người tù luôn tìm đến sự sống, đến con người và đến ánh sáng."},{"t":"Bạn có biết? Câu “Một ngày tù, nghìn thu ở ngoài” mà nhiều người Việt thuộc lòng có gốc từ bài Bốn tháng rồi trong Nhật ký trong tù. Nguyên tác mở đầu: “Nhất nhật tù, thiên thu tại ngoại, / Cổ nhân chi thoại bất sai ngoa”, nghĩa là lời người xưa nói quả không sai."},{"t":"“Nay ở trong thơ nên có thép”. Không phải bài nào trong tập cũng êm đềm. Chính Người đã nêu quan niệm của mình trong bài Cảm tưởng đọc Thiên gia thi. Thiên gia thi là tuyển tập thơ Đường, Tống quen thuộc với người học chữ Hán thời trước, nơi thiên nhiên được ngợi ca qua mây, gió, trăng, hoa. Đọc lại tuyển tập ấy trong nhà lao, Người viết: “Xưa thơ yêu cảnh thiên nhiên đẹp, / Mây, gió, trăng, hoa, tuyết, núi, sông; / Nay ở trong thơ nên có thép, / Nhà thơ cũng phải biết xung phong.” Chất thép ấy không phải là những lời hô hào. Nó nằm ở ý chí không khuất phục, ở cái nhìn tỉnh táo trước bất công, ở niềm tin vào ngày mai. Chữ “thép” trong nguyên tác là chữ “thiết”, gợi sự cứng rắn của sắt thép. Nhiều nhà nghiên cứu coi hai câu cuối của bài thơ là tuyên ngôn nghệ thuật của một nhà thơ chiến sĩ, người coi văn chương cũng là một mặt trận."},{"t":"Tiếng cười trong ngục. Chất thép còn hiện ra qua tiếng cười. Bài Lai Tân chỉ có bốn câu mà vẽ trọn chân dung một bộ máy mục nát. Bản dịch viết: “Ban trưởng nhà lao chuyên đánh bạc, / Giải người, cảnh trưởng kiếm ăn quanh; / Chong đèn, huyện trưởng làm công việc, / Trời đất Lai Tân vẫn thái bình.” Ba câu đầu kể ba hạng người, mỗi người một thói; câu cuối kết lại bằng một lời khen nghe như thật, nhưng chính vì thế mà sâu cay. Việc huyện trưởng chong đèn nghe như chăm chỉ, nhưng người đọc thời ấy hiểu ngọn đèn kia là đèn thuốc phiện. Thái bình của Lai Tân, hóa ra, là thái bình của cờ bạc, ăn tiền và nghiện ngập. Tiếng cười nhẹ nhàng mà không khoan nhượng ấy cho thấy người tù không hề bị cảnh ngộ đè bẹp. Về tầm vóc tinh thần, ông vẫn đứng cao hơn hẳn những kẻ đang giam giữ mình."},{"t":"Gian nan rèn luyện mới thành công. Bên cạnh vầng trăng và tiếng cười là những bài thơ đúc kết suy ngẫm về con người. Bài Nghe tiếng giã gạo mượn tiếng chày giã gạo để nói về lẽ sống. Bản dịch viết: “Gạo đem vào giã bao đau đớn, / Gạo giã xong rồi trắng tựa bông; / Sống ở trên đời người cũng vậy, / Gian nan rèn luyện mới thành công.” Hạt gạo phải chịu chày cối mới trắng; con người phải qua thử thách mới trưởng thành. Những câu thơ giản dị ấy về sau được nhiều thế hệ học sinh thuộc lòng. Chúng ra đời trong hoàn cảnh chính người viết đang chịu cảnh chày cối của tù đày: bị trói, bị xích, bị giải đi trong mưa gió, nhiều lần ốm đau. Vì thế lời thơ không phải một bài học suông, mà là sự tự nhủ của một người đang sống đúng điều mình viết ra."},{"t":"Những phận người trong thơ. Nhật ký trong tù còn là cuốn sổ ghi chép về những con người Người gặp. Có đứa trẻ còn ẵm ngửa phải theo mẹ vào nhà lao Tân Dương, khiến người tù đã ngoài năm mươi tuổi xót xa. Có những bạn tù nghèo khổ, có người chết trong cảnh giam cầm. Có những người dân phu, người nông dân Người bắt gặp dọc đường bị giải đi. Trong nhiều bài, nỗi đau của bản thân lùi lại phía sau, nhường chỗ cho niềm thương cảm với những số phận khác. Ở một số bài, Người để lộ nỗi nhớ quê hương, nhớ đồng chí, nỗi sốt ruột khi thời gian trôi qua mà việc lớn còn dang dở. Đó là tâm trạng rất thật của một nhà cách mạng bị tách khỏi phong trào đúng vào lúc thế giới đang chuyển mình. Chính sự chân thật ấy làm cho tập thơ gần gũi: người đọc thấy ở đó không phải một hình tượng xa vời, mà một con người biết đau, biết nhớ, biết cười."},{"t":"Bạn có biết? Nhiều bài trong Nhật ký trong tù được đưa vào sách giáo khoa Ngữ văn của Việt Nam, như Ngắm trăng, Đi đường, Chiều tối. Bản dịch thơ quen thuộc của nhiều bài là của nhà thơ Nam Trân, người tham gia dịch tập thơ tại Viện Văn học."},{"t":"Sau tờ cuối. Tháng 9/1943, Người được trả tự do. Tờ cuối trong ảnh trở thành trang khép lại một chương đặc biệt trong đời Người. Nhưng với văn học Việt Nam, đó lại là trang mở đầu của một hành trình mới. Tập thơ vốn được viết để vơi đi những ngày dài trong ngục, về sau đến với đông đảo bạn đọc, được dịch ra nhiều thứ tiếng và trở thành đối tượng của vô số công trình nghiên cứu. Nhìn tờ giấy cũ trong ảnh, người xem có thể hình dung người tù ngồi trong ánh sáng lờ mờ của nhà giam, chép từng câu thơ vào cuốn sổ nhỏ. Không song sắt nào giam được tinh thần ấy. Câu chuyện về cuốn sổ như một hiện vật, về việc nó được gìn giữ, dịch thuật và trở thành Bảo vật quốc gia, xin dành cho chuyên đề Bản thảo Nhật ký trong tù – Bảo vật quốc gia."}],"so_chu":1797},{"i":9,"tieu_de_bang":"Bản thảo Nhật ký trong tù – Bảo vật quốc gia","tieu_de":"Cuốn sổ 79 trang: bản thảo Nhật ký trong tù trở thành Bảo vật quốc gia","sapo":"Một cuốn sổ chỉ lớn hơn bàn tay một chút, 79 trang giấy ố vàng, gáy rách, mép sờn. Hơn tám mươi năm trước, nó theo người tù Hồ Chí Minh qua các nhà lao Quảng Tây; hôm nay nó thuộc hàng những hiện vật quý giá nhất của đất nước. Điều gì làm nên giá trị của một cuốn sổ cũ như thế, và vì sao nó được xếp vào hàng Bảo vật quốc gia?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_s_prison_diary_in_2016.jpg","credit":"Ảnh: Cookie Nguyen · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hồ sơ của một cuốn sổ","text":"Theo hồ sơ Bảo vật quốc gia do Cục Di sản văn hóa công bố, bản thảo Nhật ký trong tù là một cuốn sổ giấy gồm 79 trang, kích thước khoảng 9,5 × 12,5 cm, có niên đại 1942 – 1943. Hồ sơ ghi lại cả những thương tổn của thời gian: gáy sổ rách một đoạn khoảng 6 cm, mép giấy sờn, nhiều chỗ ố vàng, hai trang bị rách thủng. Nói cách khác, đây là một cuốn sổ tay đúng nghĩa, nhỏ gọn, đã được dùng trong những điều kiện hết sức thiếu thốn.\n\nChính kích thước khiêm tốn ấy làm người xem xúc động. Trên chưa đầy tám mươi trang giấy nhỏ, Người đã chép hơn một trăm bài thơ chữ Hán, ghi dấu hơn một năm bị giải qua hơn mười nhà lao của tỉnh Quảng Tây. Mỗi trang giấy vì thế vừa là tác phẩm văn học, vừa là một chứng cứ lịch sử, được xác thực bằng chính nét chữ của tác giả.","doc":1},{"loai":"doan","tieu_de":"Trang đầu: hai nắm tay bị xiềng","text":"Mở cuốn sổ, trang đầu ghi tên tập thơ, kèm hình vẽ hai nắm tay bị xiềng và bốn câu thơ chữ Hán, mỗi câu năm chữ. Bốn câu ấy là: “Thân thể tại ngục trung, / Tinh thần tại ngục ngoại; / Dục thành đại sự nghiệp, / Tinh thần cánh yếu đại.” Hình vẽ nói về hoàn cảnh; bốn câu thơ nói về thái độ của con người trước hoàn cảnh ấy.\n\nHai câu đầu tách bạch thân thể và tinh thần: thân thể ở trong ngục, tinh thần ở ngoài ngục. Hai câu sau nâng lên thành một nguyên tắc sống: muốn làm nên sự nghiệp lớn, tinh thần càng phải lớn. Đặt ngay ở trang mở đầu, bốn câu thơ như lời đề từ cho cả tập. Đó cũng là lời tự nhủ của người tù trước những tháng ngày chưa biết sẽ kéo dài bao lâu, và chưa biết sẽ kết thúc ra sao.","doc":2},{"loai":"trich","text":"Thân thể ở trong lao, / Tinh thần ở ngoài lao; / Muốn nên sự nghiệp lớn, / Tinh thần càng phải cao.","nguoi":"Hồ Chí Minh (bản dịch thơ)","nguon_ten":"Bốn câu đề ở trang đầu bản thảo Nhật ký trong tù, 1942 – 1943","doc":3},{"loai":"ban_co_biet","text":"Tên tập thơ theo nguyên văn chữ Hán là 獄中日記, đọc là Ngục trung nhật ký, nghĩa là nhật ký trong ngục. Hồ sơ Bảo vật quốc gia cũng dùng tên gốc này; còn tên Nhật ký trong tù quen thuộc với bạn đọc Việt Nam có từ các bản dịch.","nguon_ten":"Cục Di sản văn hóa – hồ sơ Bảo vật quốc gia “Tác phẩm Ngục trung nhật ký”","doc":4},{"loai":"anh","src":"textures/bang_w/G09_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản thảo Nhật ký trong tù – Bảo vật quốc gia”, nhìn từ xa."},{"loai":"doan","tieu_de":"Nơi lưu giữ hôm nay","text":"Từ nhà lao Quảng Tây năm 1943 đến tủ kính bảo tàng hôm nay là một chặng đường hơn tám mươi năm, qua hai cuộc kháng chiến. Cuốn sổ nhỏ đã vượt qua những năm tháng ấy để còn lại, dù mang nhiều vết thương của thời gian. Theo hồ sơ của Cục Di sản văn hóa, bản thảo hiện do Bảo tàng Lịch sử quốc gia ở Hà Nội lưu giữ.\n\nBảo tàng Lịch sử quốc gia được thành lập năm 2011, trên cơ sở hợp nhất Bảo tàng Lịch sử Việt Nam và Bảo tàng Cách mạng Việt Nam, hai bảo tàng lớn nằm gần nhau ở khu phố gần Nhà hát Lớn Hà Nội. Bảo tàng đã giới thiệu Ngục trung nhật ký trong loạt bài về các Bảo vật quốc gia mà mình gìn giữ. Ảnh chụp và bản sao các trang của cuốn sổ cũng thường được giới thiệu trong các cuộc trưng bày về Chủ tịch Hồ Chí Minh, để đông đảo công chúng được thấy tận mắt nét chữ của Người.","doc":5},{"loai":"doan","tieu_de":"Năm 1960: từ trang viết tay đến trang sách","text":"Năm 1960, đúng năm Người tròn bảy mươi tuổi, Viện Văn học dịch và giới thiệu tập thơ, do Nhà xuất bản Văn học ấn hành. Từ đó, cách trình bày quen thuộc của các bản in là đặt nguyên tác chữ Hán, phần phiên âm, dịch nghĩa và dịch thơ bên nhau. Nhờ vậy, người không biết chữ Hán vẫn cảm được vẻ đẹp của nguyên tác. Nhiều bản dịch thơ của Nam Trân về sau trở thành bản quen thuộc với nhiều thế hệ học sinh.\n\nNhật ký trong tù được dịch ra nhiều thứ tiếng, giới thiệu ở nhiều nước và được in đi in lại nhiều lần. Các nhà nghiên cứu trong và ngoài nước viết về tập thơ từ nhiều góc độ: văn học, lịch sử, tư tưởng, và cả sự gặp gỡ giữa truyền thống thơ Đường với tinh thần của một chiến sĩ cách mạng hiện đại. Bản thảo gốc vì thế không chỉ là một kỷ vật, mà còn là văn bản gốc để đối chiếu, hiệu đính cho các lần in và dịch.","doc":6},{"loai":"anh","src":"textures/bang_w/G09_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản thảo Nhật ký trong tù – Bảo vật quốc gia”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Thế nào là một Bảo vật quốc gia","text":"Theo Luật Di sản văn hóa, Bảo vật quốc gia là hiện vật được lưu truyền lại, có giá trị đặc biệt quý hiếm, tiêu biểu của đất nước về lịch sử, văn hóa, khoa học. Các tiêu chí gồm: là hiện vật gốc, độc bản; có hình thức độc đáo; có giá trị đặc biệt, gắn với sự kiện trọng đại hoặc nhân vật tiêu biểu của dân tộc. Hồ sơ được Hội đồng Di sản văn hóa quốc gia thẩm định trước khi trình Thủ tướng Chính phủ quyết định.\n\nNăm 2012, Thủ tướng Chính phủ ký quyết định công nhận đợt Bảo vật quốc gia đầu tiên, gồm 30 hiện vật, trong đó có bản thảo Nhật ký trong tù. Bên cạnh những trống đồng, tượng cổ hàng nghìn năm tuổi, một cuốn sổ tay giấy chưa đầy trăm năm được xếp cùng hàng. Điều đó cho thấy giá trị của hiện vật không đo bằng tuổi đời hay chất liệu, mà bằng ý nghĩa của nó đối với lịch sử và tâm hồn dân tộc.","doc":7},{"loai":"doan","tieu_de":"Bên cạnh những văn kiện khác của Người","text":"Nhật ký trong tù không phải tác phẩm duy nhất của Chủ tịch Hồ Chí Minh được công nhận Bảo vật quốc gia. Cùng hàng với nó còn có Đường Kách mệnh, Lời kêu gọi toàn quốc kháng chiến, Lời kêu gọi đồng bào và chiến sĩ cả nước ngày 17/7/1966 và bản Di chúc. Nhà xuất bản Chính trị quốc gia Sự thật đã giới thiệu năm tác phẩm này trong một ấn phẩm chung.\n\nĐặt cạnh nhau, năm văn bản trải dài từ năm 1927 đến năm 1969. Đó là những bài giảng cho thanh niên ở Quảng Châu, tập thơ viết trong ngục, lời hiệu triệu kháng chiến năm 1946. Tiếp đến là lời kêu gọi giữa mưa bom năm 1966 (xem chuyên đề Không có gì quý hơn độc lập, tự do), và những lời dặn dò cuối cùng. Trong số ấy, Nhật ký trong tù là tác phẩm duy nhất bằng thơ, và cũng là văn bản duy nhất được viết khi tác giả đang bị giam cầm.","doc":8},{"loai":"ban_co_biet","text":"Đợt công nhận Bảo vật quốc gia đầu tiên năm 2012 gồm 30 hiện vật, trong đó có trống đồng Ngọc Lũ, một trong những trống đồng Đông Sơn đẹp nhất. Qua nhiều đợt sau đó, đến nay cả nước đã có hàng trăm Bảo vật quốc gia.","nguon_ten":"Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_s_prison_diary_in_2016.jpg","chu_thich":"Bản thảo Nhật ký trong tù, Bảo vật quốc gia, trong một lần giới thiệu với công chúng; ảnh chụp năm 2016.","credit":"Ảnh: Cookie Nguyen · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Gìn giữ những trang giấy mỏng manh","text":"Là hiện vật bằng giấy, bản thảo đặc biệt nhạy cảm với ánh sáng, độ ẩm, nhiệt độ và côn trùng. Những vết ố, vết rách mà hồ sơ ghi lại là lời nhắc rằng mỗi lần mở cuốn sổ đều phải hết sức thận trọng. Luật Di sản văn hóa đặt Bảo vật quốc gia dưới chế độ quản lý đặc biệt: hiện vật phải được đăng ký và bảo quản theo quy định riêng. Việc đưa Bảo vật quốc gia ra nước ngoài để trưng bày, nghiên cứu hay bảo quản chỉ được thực hiện khi Thủ tướng Chính phủ cho phép.\n\nVới khí hậu nóng ẩm của Hà Nội, việc giữ cho một cuốn sổ giấy hơn tám mươi năm tuổi khỏi xuống cấp là công việc bền bỉ của nhiều thế hệ cán bộ bảo tàng. Nhờ công việc thầm lặng ấy, những dòng chữ viết trong ngục tối năm nào vẫn còn đó để người hôm nay được chiêm ngưỡng.","doc":10},{"loai":"moc","items":[["Cuối tháng 8/1942","Người bị bắt ở phố Túc Vinh, Quảng Tây, bắt đầu hơn một năm bị giam giữ"],["1942 – 1943","Viết tập thơ chữ Hán Ngục trung nhật ký trong cuốn sổ tay nhỏ, qua hơn mười nhà lao"],["9/1943","Được trả tự do"],["1960","Viện Văn học dịch và giới thiệu tập thơ; Nhà xuất bản Văn học ấn hành"],["2011","Thành lập Bảo tàng Lịch sử quốc gia trên cơ sở hợp nhất Bảo tàng Lịch sử Việt Nam và Bảo tàng Cách mạng Việt Nam"],["2012","Bản thảo được công nhận Bảo vật quốc gia trong đợt đầu tiên"]],"doc":11},{"loai":"anh","src":"textures/bang_w/G09_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bản thảo Nhật ký trong tù – Bảo vật quốc gia”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Trước những trang giấy viết tay","text":"Tấm ảnh chụp năm 2016 ghi lại bản thảo trong một lần được giới thiệu với công chúng. Đứng trước những trang giấy viết tay ấy, người xem hình dung được một kỷ luật tinh thần phi thường. Mỗi bài thơ được viết ra trong cảnh thiếu thốn, bị giam giữ, bị theo dõi, và không biết ngày mai sẽ bị giải đi đâu. Vậy mà hơn một trăm bài thơ vẫn được chép lại, bài nối bài, từ trang đầu đến tờ cuối (xem chuyên đề Tờ cuối bản thảo Nhật ký trong tù).\n\nCó lẽ đó là điều quý nhất mà bản thảo lưu giữ, hơn cả giá trị văn chương: dấu vết của một con người không để hoàn cảnh chi phối mình. Bốn câu thơ ở trang đầu đã nói trước điều ấy. Thân thể có thể ở trong lao, nhưng tinh thần thì ở ngoài lao. Chính tinh thần ấy đã đưa người tù năm 1943 trở về, cùng toàn dân tộc làm nên Cách mạng Tháng Tám chỉ hai năm sau.","doc":12}],"nguon":["Cục Di sản văn hóa – “Tác phẩm Ngục trung nhật ký” (hồ sơ Bảo vật quốc gia) – https://dsvh.gov.vn/tac-pham-nguc-trung-nhat-ky-3023","Hồ Chí Minh, Nhật ký trong tù (bản dịch của Viện Văn học), NXB Văn học, 1960","Bảo tàng Lịch sử quốc gia – loạt bài “Giới thiệu Bảo vật Quốc gia: Ngục trung nhật ký (Nhật ký trong tù)”","NXB Chính trị quốc gia Sự thật – “5 tác phẩm Bảo vật quốc gia” (Đường Kách mệnh, Nhật ký trong tù, Lời kêu gọi toàn quốc kháng chiến, Lời kêu gọi đồng bào và chiến sĩ cả nước, Di chúc)","Luật Di sản văn hóa"],"doc":[{"t":"Cuốn sổ 79 trang: bản thảo Nhật ký trong tù trở thành Bảo vật quốc gia. Một cuốn sổ chỉ lớn hơn bàn tay một chút, 79 trang giấy ố vàng, gáy rách, mép sờn. Hơn tám mươi năm trước, nó theo người tù Hồ Chí Minh qua các nhà lao Quảng Tây; hôm nay nó thuộc hàng những hiện vật quý giá nhất của đất nước. Điều gì làm nên giá trị của một cuốn sổ cũ như thế, và vì sao nó được xếp vào hàng Bảo vật quốc gia?"},{"t":"Hồ sơ của một cuốn sổ. Theo hồ sơ Bảo vật quốc gia do Cục Di sản văn hóa công bố, bản thảo Nhật ký trong tù là một cuốn sổ giấy gồm 79 trang, kích thước khoảng 9,5 × 12,5 cm, có niên đại 1942 – 1943. Hồ sơ ghi lại cả những thương tổn của thời gian: gáy sổ rách một đoạn khoảng 6 cm, mép giấy sờn, nhiều chỗ ố vàng, hai trang bị rách thủng. Nói cách khác, đây là một cuốn sổ tay đúng nghĩa, nhỏ gọn, đã được dùng trong những điều kiện hết sức thiếu thốn. Chính kích thước khiêm tốn ấy làm người xem xúc động. Trên chưa đầy tám mươi trang giấy nhỏ, Người đã chép hơn một trăm bài thơ chữ Hán, ghi dấu hơn một năm bị giải qua hơn mười nhà lao của tỉnh Quảng Tây. Mỗi trang giấy vì thế vừa là tác phẩm văn học, vừa là một chứng cứ lịch sử, được xác thực bằng chính nét chữ của tác giả."},{"t":"Trang đầu: hai nắm tay bị xiềng. Mở cuốn sổ, trang đầu ghi tên tập thơ, kèm hình vẽ hai nắm tay bị xiềng và bốn câu thơ chữ Hán, mỗi câu năm chữ. Bốn câu ấy là: “Thân thể tại ngục trung, / Tinh thần tại ngục ngoại; / Dục thành đại sự nghiệp, / Tinh thần cánh yếu đại.” Hình vẽ nói về hoàn cảnh; bốn câu thơ nói về thái độ của con người trước hoàn cảnh ấy. Hai câu đầu tách bạch thân thể và tinh thần: thân thể ở trong ngục, tinh thần ở ngoài ngục. Hai câu sau nâng lên thành một nguyên tắc sống: muốn làm nên sự nghiệp lớn, tinh thần càng phải lớn. Đặt ngay ở trang mở đầu, bốn câu thơ như lời đề từ cho cả tập. Đó cũng là lời tự nhủ của người tù trước những tháng ngày chưa biết sẽ kéo dài bao lâu, và chưa biết sẽ kết thúc ra sao."},{"t":"Thân thể ở trong lao, / Tinh thần ở ngoài lao; / Muốn nên sự nghiệp lớn, / Tinh thần càng phải cao. — Hồ Chí Minh (bản dịch thơ)"},{"t":"Bạn có biết? Tên tập thơ theo nguyên văn chữ Hán là 獄中日記, đọc là Ngục trung nhật ký, nghĩa là nhật ký trong ngục. Hồ sơ Bảo vật quốc gia cũng dùng tên gốc này; còn tên Nhật ký trong tù quen thuộc với bạn đọc Việt Nam có từ các bản dịch."},{"t":"Nơi lưu giữ hôm nay. Từ nhà lao Quảng Tây năm 1943 đến tủ kính bảo tàng hôm nay là một chặng đường hơn tám mươi năm, qua hai cuộc kháng chiến. Cuốn sổ nhỏ đã vượt qua những năm tháng ấy để còn lại, dù mang nhiều vết thương của thời gian. Theo hồ sơ của Cục Di sản văn hóa, bản thảo hiện do Bảo tàng Lịch sử quốc gia ở Hà Nội lưu giữ. Bảo tàng Lịch sử quốc gia được thành lập năm 2011, trên cơ sở hợp nhất Bảo tàng Lịch sử Việt Nam và Bảo tàng Cách mạng Việt Nam, hai bảo tàng lớn nằm gần nhau ở khu phố gần Nhà hát Lớn Hà Nội. Bảo tàng đã giới thiệu Ngục trung nhật ký trong loạt bài về các Bảo vật quốc gia mà mình gìn giữ. Ảnh chụp và bản sao các trang của cuốn sổ cũng thường được giới thiệu trong các cuộc trưng bày về Chủ tịch Hồ Chí Minh, để đông đảo công chúng được thấy tận mắt nét chữ của Người."},{"t":"Năm 1960: từ trang viết tay đến trang sách. Năm 1960, đúng năm Người tròn bảy mươi tuổi, Viện Văn học dịch và giới thiệu tập thơ, do Nhà xuất bản Văn học ấn hành. Từ đó, cách trình bày quen thuộc của các bản in là đặt nguyên tác chữ Hán, phần phiên âm, dịch nghĩa và dịch thơ bên nhau. Nhờ vậy, người không biết chữ Hán vẫn cảm được vẻ đẹp của nguyên tác. Nhiều bản dịch thơ của Nam Trân về sau trở thành bản quen thuộc với nhiều thế hệ học sinh. Nhật ký trong tù được dịch ra nhiều thứ tiếng, giới thiệu ở nhiều nước và được in đi in lại nhiều lần. Các nhà nghiên cứu trong và ngoài nước viết về tập thơ từ nhiều góc độ: văn học, lịch sử, tư tưởng, và cả sự gặp gỡ giữa truyền thống thơ Đường với tinh thần của một chiến sĩ cách mạng hiện đại. Bản thảo gốc vì thế không chỉ là một kỷ vật, mà còn là văn bản gốc để đối chiếu, hiệu đính cho các lần in và dịch."},{"t":"Thế nào là một Bảo vật quốc gia. Theo Luật Di sản văn hóa, Bảo vật quốc gia là hiện vật được lưu truyền lại, có giá trị đặc biệt quý hiếm, tiêu biểu của đất nước về lịch sử, văn hóa, khoa học. Các tiêu chí gồm: là hiện vật gốc, độc bản; có hình thức độc đáo; có giá trị đặc biệt, gắn với sự kiện trọng đại hoặc nhân vật tiêu biểu của dân tộc. Hồ sơ được Hội đồng Di sản văn hóa quốc gia thẩm định trước khi trình Thủ tướng Chính phủ quyết định. Năm 2012, Thủ tướng Chính phủ ký quyết định công nhận đợt Bảo vật quốc gia đầu tiên, gồm 30 hiện vật, trong đó có bản thảo Nhật ký trong tù. Bên cạnh những trống đồng, tượng cổ hàng nghìn năm tuổi, một cuốn sổ tay giấy chưa đầy trăm năm được xếp cùng hàng. Điều đó cho thấy giá trị của hiện vật không đo bằng tuổi đời hay chất liệu, mà bằng ý nghĩa của nó đối với lịch sử và tâm hồn dân tộc."},{"t":"Bên cạnh những văn kiện khác của Người. Nhật ký trong tù không phải tác phẩm duy nhất của Chủ tịch Hồ Chí Minh được công nhận Bảo vật quốc gia. Cùng hàng với nó còn có Đường Kách mệnh, Lời kêu gọi toàn quốc kháng chiến, Lời kêu gọi đồng bào và chiến sĩ cả nước ngày 17/7/1966 và bản Di chúc. Nhà xuất bản Chính trị quốc gia Sự thật đã giới thiệu năm tác phẩm này trong một ấn phẩm chung. Đặt cạnh nhau, năm văn bản trải dài từ năm 1927 đến năm 1969. Đó là những bài giảng cho thanh niên ở Quảng Châu, tập thơ viết trong ngục, lời hiệu triệu kháng chiến năm 1946. Tiếp đến là lời kêu gọi giữa mưa bom năm 1966 (xem chuyên đề Không có gì quý hơn độc lập, tự do), và những lời dặn dò cuối cùng. Trong số ấy, Nhật ký trong tù là tác phẩm duy nhất bằng thơ, và cũng là văn bản duy nhất được viết khi tác giả đang bị giam cầm."},{"t":"Bạn có biết? Đợt công nhận Bảo vật quốc gia đầu tiên năm 2012 gồm 30 hiện vật, trong đó có trống đồng Ngọc Lũ, một trong những trống đồng Đông Sơn đẹp nhất. Qua nhiều đợt sau đó, đến nay cả nước đã có hàng trăm Bảo vật quốc gia."},{"t":"Gìn giữ những trang giấy mỏng manh. Là hiện vật bằng giấy, bản thảo đặc biệt nhạy cảm với ánh sáng, độ ẩm, nhiệt độ và côn trùng. Những vết ố, vết rách mà hồ sơ ghi lại là lời nhắc rằng mỗi lần mở cuốn sổ đều phải hết sức thận trọng. Luật Di sản văn hóa đặt Bảo vật quốc gia dưới chế độ quản lý đặc biệt: hiện vật phải được đăng ký và bảo quản theo quy định riêng. Việc đưa Bảo vật quốc gia ra nước ngoài để trưng bày, nghiên cứu hay bảo quản chỉ được thực hiện khi Thủ tướng Chính phủ cho phép. Với khí hậu nóng ẩm của Hà Nội, việc giữ cho một cuốn sổ giấy hơn tám mươi năm tuổi khỏi xuống cấp là công việc bền bỉ của nhiều thế hệ cán bộ bảo tàng. Nhờ công việc thầm lặng ấy, những dòng chữ viết trong ngục tối năm nào vẫn còn đó để người hôm nay được chiêm ngưỡng."},{"t":"Các mốc thời gian. Cuối tháng 8/1942: Người bị bắt ở phố Túc Vinh, Quảng Tây, bắt đầu hơn một năm bị giam giữ. 1942 – 1943: Viết tập thơ chữ Hán Ngục trung nhật ký trong cuốn sổ tay nhỏ, qua hơn mười nhà lao. 9/1943: Được trả tự do. 1960: Viện Văn học dịch và giới thiệu tập thơ; Nhà xuất bản Văn học ấn hành. 2011: Thành lập Bảo tàng Lịch sử quốc gia trên cơ sở hợp nhất Bảo tàng Lịch sử Việt Nam và Bảo tàng Cách mạng Việt Nam. 2012: Bản thảo được công nhận Bảo vật quốc gia trong đợt đầu tiên."},{"t":"Trước những trang giấy viết tay. Tấm ảnh chụp năm 2016 ghi lại bản thảo trong một lần được giới thiệu với công chúng. Đứng trước những trang giấy viết tay ấy, người xem hình dung được một kỷ luật tinh thần phi thường. Mỗi bài thơ được viết ra trong cảnh thiếu thốn, bị giam giữ, bị theo dõi, và không biết ngày mai sẽ bị giải đi đâu. Vậy mà hơn một trăm bài thơ vẫn được chép lại, bài nối bài, từ trang đầu đến tờ cuối (xem chuyên đề Tờ cuối bản thảo Nhật ký trong tù). Có lẽ đó là điều quý nhất mà bản thảo lưu giữ, hơn cả giá trị văn chương: dấu vết của một con người không để hoàn cảnh chi phối mình. Bốn câu thơ ở trang đầu đã nói trước điều ấy. Thân thể có thể ở trong lao, nhưng tinh thần thì ở ngoài lao. Chính tinh thần ấy đã đưa người tù năm 1943 trở về, cùng toàn dân tộc làm nên Cách mạng Tháng Tám chỉ hai năm sau."}],"so_chu":1581},{"i":10,"tieu_de_bang":"Không có gì quý hơn độc lập, tự do","tieu_de":"“Không có gì quý hơn độc lập, tự do”: chín chữ vang lên giữa mùa hè bom đạn 1966","sapo":"Sáng Chủ nhật 17/7/1966, qua làn sóng Đài Tiếng nói Việt Nam, đồng bào cả nước nghe Chủ tịch Hồ Chí Minh đọc một lời kêu gọi. Người không hứa một chiến thắng dễ dàng: Người nói chiến tranh có thể kéo dài hai mươi năm hoặc lâu hơn nữa. Rồi Người nói một câu chỉ có chín chữ. Vì sao câu nói ấy trở thành chân lý của cả một dân tộc?","bia":{"src":"textures/bai/G09_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Giọng nói trên làn sóng sáng Chủ nhật","text":"Sáng 17/7/1966, Đài Tiếng nói Việt Nam phát đi Lời kêu gọi đồng bào và chiến sĩ cả nước, do chính Chủ tịch Hồ Chí Minh đọc. Cùng ngày, báo Nhân Dân số 4484 đăng toàn văn văn kiện. Khi ấy Người đã bước sang tuổi bảy mươi sáu. Lời kêu gọi không dài, không có những câu chữ hoa mỹ. Người nói với đồng bào như nói với những người trong một nhà: kẻ thù đang leo thang chiến tranh, thử thách phía trước còn rất lớn, sự hy sinh sẽ còn nhiều.\n\nGiữa những lời báo trước về mất mát ấy là một khẳng định chỉ có chín chữ: Không có gì quý hơn độc lập, tự do. Từ buổi sáng hôm ấy, câu nói theo báo chí, theo loa truyền thanh đi khắp các làng xã, nhà máy, trận địa. Nó được kẻ thành khẩu hiệu ở nhiều nơi, và trở thành lời hiệu triệu hành động của quân và dân cả nước trong suốt những năm kháng chiến chống Mỹ, cứu nước.","doc":1},{"loai":"anh","src":"textures/bang_w/G09_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Không có gì quý hơn độc lập, tự do”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mùa hè năm 1966","text":"Để hiểu sức nặng của câu nói, cần trở lại bối cảnh mùa hè năm 1966. Từ đầu năm 1965, Mỹ mở cuộc chiến tranh phá hoại bằng không quân đối với miền Bắc, đánh vào cầu cống, đường sá, nhà máy, kho tàng. Ở miền Nam, số quân Mỹ đã vượt quá hai mươi vạn và vẫn tiếp tục tăng. Cuộc chiến mà Nhà Trắng từng mong kết thúc nhanh đã trở thành một cuộc chiến tranh cục bộ quy mô lớn.\n\nNgày 29/6/1966, máy bay Mỹ đánh vào các kho xăng dầu ở vùng ven Hà Nội và Hải Phòng, đưa bom đạn tới sát hai thành phố lớn nhất miền Bắc. Đó là một bước leo thang nghiêm trọng, nhằm làm suy yếu sức chi viện cho chiến trường miền Nam và buộc Việt Nam phải khuất phục. Nhiều cơ quan, trường học, xí nghiệp đã phải sơ tán về nông thôn. Chưa đầy ba tuần sau trận đánh kho xăng dầu, Chủ tịch Hồ Chí Minh ra Lời kêu gọi, trả lời thẳng vào mưu đồ ấy bằng quyết tâm của cả một dân tộc.","doc":2},{"loai":"trich","text":"Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Lời kêu gọi đồng bào và chiến sĩ cả nước, 17/7/1966 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":3},{"loai":"doan","tieu_de":"Nói thật với dân","text":"Đọc chậm từng câu trong đoạn văn ngắn ấy, người ta nhận ra một cách nói rất riêng của Hồ Chí Minh. Người không hứa hẹn chiến thắng trong vài tháng. Người nói chiến tranh có thể kéo dài năm năm, mười năm, hai mươi năm hoặc lâu hơn nữa. Người gọi đích danh Hà Nội, Hải Phòng, những thành phố mà mọi người dân miền Bắc đều gắn bó, và nói rằng chúng có thể bị tàn phá.\n\nMột nhà lãnh đạo nói với dân những điều nặng nề như vậy là đặt trọn niềm tin vào dân. Người tin rằng khi hiểu rõ cái giá phải trả, nhân dân sẽ không nao núng. Vì thế, ngay sau lời báo trước là câu khẳng định: nhân dân Việt Nam quyết không sợ. Cách nói thẳng thắn ấy khiến lời kêu gọi không phải là một mệnh lệnh từ trên xuống, mà là lời bàn bạc với từng người dân về việc chung của đất nước. Người nghe hiểu rằng mình được nói thật, và câu trả lời thuộc về chính mình.","doc":4},{"loai":"anh","src":"textures/bang_w/G09_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Không có gì quý hơn độc lập, tự do”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chín chữ và một thang giá trị","text":"Câu “Không có gì quý hơn độc lập, tự do” được đặt ngay sau lời báo trước về mất mát, như lời giải thích vì sao dân tộc chấp nhận mất mát. Hai chữ “không có gì” gạt sang một bên mọi thứ khác: nhà cửa, của cải, thành phố, cả những năm tháng bình yên. Trên thang giá trị ấy, chỉ có độc lập và tự do đứng ở bậc cao nhất.\n\nĐộc lập là quyền của cả dân tộc được tự quyết định vận mệnh của mình, không bị nước ngoài áp đặt. Tự do là quyền của mỗi người dân được sống làm người, không bị áp bức, nô dịch. Với Hồ Chí Minh, hai điều ấy không tách rời nhau. Tháng 1/1946, trả lời các nhà báo nước ngoài, Người đã nói rõ ham muốn lớn nhất của đời mình. “Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành.” Người cũng nhiều lần nhắc rằng nước được độc lập mà dân không được hưởng hạnh phúc, tự do thì độc lập ấy chẳng có ý nghĩa gì.","doc":5},{"loai":"ban_co_biet","text":"Trong Lăng Chủ tịch Hồ Chí Minh ở Hà Nội, câu “Không có gì quý hơn độc lập, tự do” được khắc bằng chữ vàng trên nền đá, ngay nơi dòng người vào viếng đi qua. Lời hiệu triệu năm 1966 vì thế là một trong những điều đầu tiên khách nhìn thấy khi bước vào viếng Người.","nguon_ten":"Báo Petrotimes – “Không có gì quý hơn độc lập, tự do”: Từ lời hiệu triệu lịch sử đến dòng chữ vàng sáng mãi trong Lăng Bác","doc":6},{"loai":"doan","tieu_de":"Một lời hứa về ngày mai","text":"Câu cuối của đoạn trích thường ít được nhắc bằng câu giữa, nhưng không kém phần quan trọng: đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước đàng hoàng hơn, to đẹp hơn. Giữa lúc bom đang rơi, Người đã nhìn qua chiến tranh để nói về hòa bình. Độc lập, tự do không phải là đích cuối, mà là điều kiện để dân tộc dựng xây một cuộc sống tốt đẹp.\n\nÝ nguyện ấy trở lại trong bản Di chúc Người viết từ năm 1965 và sửa chữa đến năm 1969. Trong đó có hai câu thơ giản dị: “Còn non, còn nước, còn người, / Thắng giặc Mỹ, ta sẽ xây dựng hơn mười ngày nay!” Lời kêu gọi năm 1966 và Di chúc vì thế nối tiếp nhau như hai vế của một suy nghĩ. Vế đầu là quyết tâm không chịu mất nước, dù phải hy sinh đến đâu. Vế sau là niềm tin rằng một dân tộc đã giành được độc lập sẽ biết làm cho đất nước mình giàu đẹp hơn, xứng đáng với những gì đã hy sinh.","doc":7},{"loai":"anh","src":"textures/bai/G09_v1.jpg","chu_thich":"Không gian 3D gian Trung Quốc – Quảng Châu nhìn từ trên cao: nơi bắt đầu hành trình đào tạo những người chiến đấu cho độc lập, tự do.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Sợi chỉ đỏ của một đời người","text":"Câu nói năm 1966 là sự đúc kết của cả một cuộc đời. Năm 1911, người thanh niên Nguyễn Tất Thành rời bến Nhà Rồng ra đi tìm đường cứu nước. Năm 1919, bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Versailles, đòi những quyền tự do tối thiểu cho người dân thuộc địa.\n\nNgày 2/9/1945, bản Tuyên ngôn Độc lập khép lại bằng lời thề: “Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.” Hơn một năm sau, ngày 19/12/1946, Người ra Lời kêu gọi toàn quốc kháng chiến. “Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.” Đặt các văn kiện ấy cạnh Lời kêu gọi năm 1966, ta thấy một sợi chỉ đỏ không đứt. Mỗi lần đất nước đứng trước thử thách lớn, Người lại nhắc dân tộc về điều quý giá nhất. Tiêu ngữ Độc lập – Tự do – Hạnh phúc, có từ những ngày đầu của nước Việt Nam Dân chủ Cộng hòa, cũng mang chính tinh thần ấy.","doc":8},{"loai":"doan","tieu_de":"Từ lớp học phố Văn Minh đến lời kêu gọi","text":"Câu nói được đặt trong gian Quảng Châu không phải ngẫu nhiên. Mùa hè năm 1925, trên đất Quảng Châu, Nguyễn Ái Quốc lập Hội Việt Nam Cách mạng Thanh niên, mở những lớp huấn luyện đầu tiên cho thanh niên từ trong nước bí mật sang. Những bài giảng ấy, sau in thành sách Đường Kách mệnh, chỉ cho người Việt Nam con đường giành lại độc lập cho dân tộc (xem chuyên đề Nhà số 248 – 250 đường Văn Minh).\n\nMười bảy năm sau, cũng trên đất Trung Hoa, người tù Hồ Chí Minh bị giải qua các nhà lao Quảng Tây. Trong cảnh ấy, Người vẫn viết những vần thơ “vừa ngâm vừa đợi đến ngày tự do” (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Từ lớp học năm 1925 đến lời kêu gọi năm 1966 là bốn mươi mốt năm. Những thanh niên ngồi nghe giảng ở Quảng Châu năm ấy, người thì đã hy sinh, người thì đã trở thành những nhà lãnh đạo của đất nước. Lời kêu gọi năm 1966 vì thế như lời nhắc lại, với cả một dân tộc, bài học đầu tiên của con đường cách mạng.","doc":9},{"loai":"anh","src":"textures/bang_w/G09_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Không có gì quý hơn độc lập, tự do”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Tiếng vọng đến ngày toàn thắng và hôm nay","text":"Lời kêu gọi năm 1966 tiếp thêm sức cho những phong trào đang dâng lên khắp miền Bắc: thanh niên với phong trào Ba sẵn sàng, phụ nữ với phong trào Ba đảm đang, công nhân và nông dân vừa sản xuất vừa chiến đấu. Tết Kỷ Dậu 1969, trong bài thơ chúc Tết cuối cùng, Người viết: “Vì độc lập, vì tự do, / Đánh cho Mỹ cút, đánh cho ngụy nhào.” Người từ trần lúc 9 giờ 47 phút ngày 2/9/1969, không kịp chứng kiến ngày toàn thắng. Nhưng lời Người đã tiên liệu đúng: cuộc chiến còn kéo dài gần chín năm sau lời kêu gọi, cho đến ngày 30/4/1975, khi đất nước thống nhất.\n\nNgày nay, câu nói được coi là một chân lý của thời đại. Nó có mặt trong sách giáo khoa, trên pa nô, khẩu hiệu ở nhiều nơi công cộng; toàn văn Lời kêu gọi được in trong bộ Hồ Chí Minh Toàn tập. Đứng trước bảng này, khách tham quan được mời nhìn lại con đường dài từ những lớp học bí mật năm 1925 đến lời hiệu triệu năm 1966.","doc":10},{"loai":"ban_co_biet","text":"Năm 1987, Đại hội đồng UNESCO thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh (1890 – 1990), tôn vinh Người là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam.","nguon_ten":"Nghị quyết 24C/18.65 của Đại hội đồng UNESCO, khóa họp lần thứ 24, năm 1987","doc":11}],"nguon":["Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia – Lời kêu gọi đồng bào và chiến sĩ cả nước (17/7/1966); Tuyên ngôn Độc lập (2/9/1945); Lời kêu gọi toàn quốc kháng chiến (19/12/1946); Di chúc","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Thông tấn xã Việt Nam – “Lời kêu gọi đồng bào và chiến sĩ cả nước” (văn bản Chủ tịch Hồ Chí Minh đọc trên Đài Tiếng nói Việt Nam sáng 17/7/1966), https://nvsk.vnanet.vn/ho-so/loi-keu-goi-dong-bao-va-chien-si-ca-nuoc-van-ban-chu-tich-ho-chi-minh-doc-tren-dai-tieng-noi-viet-nam-sang-17-7-1966-3-112303.vna","VietnamPlus – 55 năm Ngày Bác Hồ ra lời kêu gọi “Không có gì quý hơn độc lập, tự do”, https://www.vietnamplus.vn/55-nam-ngay-bac-ho-ra-loi-keu-goi-khong-co-gi-quy-hon-doc-lap-tu-do-post727027.vnp","Nghị quyết 24C/18.65 của Đại hội đồng UNESCO, khóa họp lần thứ 24, năm 1987","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"“Không có gì quý hơn độc lập, tự do”: chín chữ vang lên giữa mùa hè bom đạn 1966. Sáng Chủ nhật 17/7/1966, qua làn sóng Đài Tiếng nói Việt Nam, đồng bào cả nước nghe Chủ tịch Hồ Chí Minh đọc một lời kêu gọi. Người không hứa một chiến thắng dễ dàng: Người nói chiến tranh có thể kéo dài hai mươi năm hoặc lâu hơn nữa. Rồi Người nói một câu chỉ có chín chữ. Vì sao câu nói ấy trở thành chân lý của cả một dân tộc?"},{"t":"Giọng nói trên làn sóng sáng Chủ nhật. Sáng 17/7/1966, Đài Tiếng nói Việt Nam phát đi Lời kêu gọi đồng bào và chiến sĩ cả nước, do chính Chủ tịch Hồ Chí Minh đọc. Cùng ngày, báo Nhân Dân số 4484 đăng toàn văn văn kiện. Khi ấy Người đã bước sang tuổi bảy mươi sáu. Lời kêu gọi không dài, không có những câu chữ hoa mỹ. Người nói với đồng bào như nói với những người trong một nhà: kẻ thù đang leo thang chiến tranh, thử thách phía trước còn rất lớn, sự hy sinh sẽ còn nhiều. Giữa những lời báo trước về mất mát ấy là một khẳng định chỉ có chín chữ: Không có gì quý hơn độc lập, tự do. Từ buổi sáng hôm ấy, câu nói theo báo chí, theo loa truyền thanh đi khắp các làng xã, nhà máy, trận địa. Nó được kẻ thành khẩu hiệu ở nhiều nơi, và trở thành lời hiệu triệu hành động của quân và dân cả nước trong suốt những năm kháng chiến chống Mỹ, cứu nước."},{"t":"Mùa hè năm 1966. Để hiểu sức nặng của câu nói, cần trở lại bối cảnh mùa hè năm 1966. Từ đầu năm 1965, Mỹ mở cuộc chiến tranh phá hoại bằng không quân đối với miền Bắc, đánh vào cầu cống, đường sá, nhà máy, kho tàng. Ở miền Nam, số quân Mỹ đã vượt quá hai mươi vạn và vẫn tiếp tục tăng. Cuộc chiến mà Nhà Trắng từng mong kết thúc nhanh đã trở thành một cuộc chiến tranh cục bộ quy mô lớn. Ngày 29/6/1966, máy bay Mỹ đánh vào các kho xăng dầu ở vùng ven Hà Nội và Hải Phòng, đưa bom đạn tới sát hai thành phố lớn nhất miền Bắc. Đó là một bước leo thang nghiêm trọng, nhằm làm suy yếu sức chi viện cho chiến trường miền Nam và buộc Việt Nam phải khuất phục. Nhiều cơ quan, trường học, xí nghiệp đã phải sơ tán về nông thôn. Chưa đầy ba tuần sau trận đánh kho xăng dầu, Chủ tịch Hồ Chí Minh ra Lời kêu gọi, trả lời thẳng vào mưu đồ ấy bằng quyết tâm của cả một dân tộc."},{"t":"Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song nhân dân Việt Nam quyết không sợ! Không có gì quý hơn độc lập, tự do. Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn! — Chủ tịch Hồ Chí Minh"},{"t":"Nói thật với dân. Đọc chậm từng câu trong đoạn văn ngắn ấy, người ta nhận ra một cách nói rất riêng của Hồ Chí Minh. Người không hứa hẹn chiến thắng trong vài tháng. Người nói chiến tranh có thể kéo dài năm năm, mười năm, hai mươi năm hoặc lâu hơn nữa. Người gọi đích danh Hà Nội, Hải Phòng, những thành phố mà mọi người dân miền Bắc đều gắn bó, và nói rằng chúng có thể bị tàn phá. Một nhà lãnh đạo nói với dân những điều nặng nề như vậy là đặt trọn niềm tin vào dân. Người tin rằng khi hiểu rõ cái giá phải trả, nhân dân sẽ không nao núng. Vì thế, ngay sau lời báo trước là câu khẳng định: nhân dân Việt Nam quyết không sợ. Cách nói thẳng thắn ấy khiến lời kêu gọi không phải là một mệnh lệnh từ trên xuống, mà là lời bàn bạc với từng người dân về việc chung của đất nước. Người nghe hiểu rằng mình được nói thật, và câu trả lời thuộc về chính mình."},{"t":"Chín chữ và một thang giá trị. Câu “Không có gì quý hơn độc lập, tự do” được đặt ngay sau lời báo trước về mất mát, như lời giải thích vì sao dân tộc chấp nhận mất mát. Hai chữ “không có gì” gạt sang một bên mọi thứ khác: nhà cửa, của cải, thành phố, cả những năm tháng bình yên. Trên thang giá trị ấy, chỉ có độc lập và tự do đứng ở bậc cao nhất. Độc lập là quyền của cả dân tộc được tự quyết định vận mệnh của mình, không bị nước ngoài áp đặt. Tự do là quyền của mỗi người dân được sống làm người, không bị áp bức, nô dịch. Với Hồ Chí Minh, hai điều ấy không tách rời nhau. Tháng 1/1946, trả lời các nhà báo nước ngoài, Người đã nói rõ ham muốn lớn nhất của đời mình. “Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành.” Người cũng nhiều lần nhắc rằng nước được độc lập mà dân không được hưởng hạnh phúc, tự do thì độc lập ấy chẳng có ý nghĩa gì."},{"t":"Bạn có biết? Trong Lăng Chủ tịch Hồ Chí Minh ở Hà Nội, câu “Không có gì quý hơn độc lập, tự do” được khắc bằng chữ vàng trên nền đá, ngay nơi dòng người vào viếng đi qua. Lời hiệu triệu năm 1966 vì thế là một trong những điều đầu tiên khách nhìn thấy khi bước vào viếng Người."},{"t":"Một lời hứa về ngày mai. Câu cuối của đoạn trích thường ít được nhắc bằng câu giữa, nhưng không kém phần quan trọng: đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước đàng hoàng hơn, to đẹp hơn. Giữa lúc bom đang rơi, Người đã nhìn qua chiến tranh để nói về hòa bình. Độc lập, tự do không phải là đích cuối, mà là điều kiện để dân tộc dựng xây một cuộc sống tốt đẹp. Ý nguyện ấy trở lại trong bản Di chúc Người viết từ năm 1965 và sửa chữa đến năm 1969. Trong đó có hai câu thơ giản dị: “Còn non, còn nước, còn người, / Thắng giặc Mỹ, ta sẽ xây dựng hơn mười ngày nay!” Lời kêu gọi năm 1966 và Di chúc vì thế nối tiếp nhau như hai vế của một suy nghĩ. Vế đầu là quyết tâm không chịu mất nước, dù phải hy sinh đến đâu. Vế sau là niềm tin rằng một dân tộc đã giành được độc lập sẽ biết làm cho đất nước mình giàu đẹp hơn, xứng đáng với những gì đã hy sinh."},{"t":"Sợi chỉ đỏ của một đời người. Câu nói năm 1966 là sự đúc kết của cả một cuộc đời. Năm 1911, người thanh niên Nguyễn Tất Thành rời bến Nhà Rồng ra đi tìm đường cứu nước. Năm 1919, bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Versailles, đòi những quyền tự do tối thiểu cho người dân thuộc địa. Ngày 2/9/1945, bản Tuyên ngôn Độc lập khép lại bằng lời thề: “Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.” Hơn một năm sau, ngày 19/12/1946, Người ra Lời kêu gọi toàn quốc kháng chiến. “Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.” Đặt các văn kiện ấy cạnh Lời kêu gọi năm 1966, ta thấy một sợi chỉ đỏ không đứt. Mỗi lần đất nước đứng trước thử thách lớn, Người lại nhắc dân tộc về điều quý giá nhất. Tiêu ngữ Độc lập – Tự do – Hạnh phúc, có từ những ngày đầu của nước Việt Nam Dân chủ Cộng hòa, cũng mang chính tinh thần ấy."},{"t":"Từ lớp học phố Văn Minh đến lời kêu gọi. Câu nói được đặt trong gian Quảng Châu không phải ngẫu nhiên. Mùa hè năm 1925, trên đất Quảng Châu, Nguyễn Ái Quốc lập Hội Việt Nam Cách mạng Thanh niên, mở những lớp huấn luyện đầu tiên cho thanh niên từ trong nước bí mật sang. Những bài giảng ấy, sau in thành sách Đường Kách mệnh, chỉ cho người Việt Nam con đường giành lại độc lập cho dân tộc (xem chuyên đề Nhà số 248 – 250 đường Văn Minh). Mười bảy năm sau, cũng trên đất Trung Hoa, người tù Hồ Chí Minh bị giải qua các nhà lao Quảng Tây. Trong cảnh ấy, Người vẫn viết những vần thơ “vừa ngâm vừa đợi đến ngày tự do” (xem chuyên đề Mười ba tháng trong các nhà lao Quảng Tây). Từ lớp học năm 1925 đến lời kêu gọi năm 1966 là bốn mươi mốt năm. Những thanh niên ngồi nghe giảng ở Quảng Châu năm ấy, người thì đã hy sinh, người thì đã trở thành những nhà lãnh đạo của đất nước. Lời kêu gọi năm 1966 vì thế như lời nhắc lại, với cả một dân tộc, bài học đầu tiên của con đường cách mạng."},{"t":"Tiếng vọng đến ngày toàn thắng và hôm nay. Lời kêu gọi năm 1966 tiếp thêm sức cho những phong trào đang dâng lên khắp miền Bắc: thanh niên với phong trào Ba sẵn sàng, phụ nữ với phong trào Ba đảm đang, công nhân và nông dân vừa sản xuất vừa chiến đấu. Tết Kỷ Dậu 1969, trong bài thơ chúc Tết cuối cùng, Người viết: “Vì độc lập, vì tự do, / Đánh cho Mỹ cút, đánh cho ngụy nhào.” Người từ trần lúc 9 giờ 47 phút ngày 2/9/1969, không kịp chứng kiến ngày toàn thắng. Nhưng lời Người đã tiên liệu đúng: cuộc chiến còn kéo dài gần chín năm sau lời kêu gọi, cho đến ngày 30/4/1975, khi đất nước thống nhất. Ngày nay, câu nói được coi là một chân lý của thời đại. Nó có mặt trong sách giáo khoa, trên pa nô, khẩu hiệu ở nhiều nơi công cộng; toàn văn Lời kêu gọi được in trong bộ Hồ Chí Minh Toàn tập. Đứng trước bảng này, khách tham quan được mời nhìn lại con đường dài từ những lớp học bí mật năm 1925 đến lời hiệu triệu năm 1966."},{"t":"Bạn có biết? Năm 1987, Đại hội đồng UNESCO thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh (1890 – 1990), tôn vinh Người là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam."}],"so_chu":1796},{"i":11,"tieu_de_bang":"Nhà số 248 – 250 đường Văn Minh","tieu_de":"Số 13 đường Văn Minh: một ngôi nhà phố vừa là trụ sở, trường học và tòa soạn","sapo":"Năm 1925, người Quảng Châu biết ngôi nhà này bằng một con số giản dị: số 13 đường Văn Minh. Không tấm biển nào cho biết bên trong là Tổng bộ của một tổ chức cách mạng Việt Nam. Ở đó, một người mang tên Lý Thụy vừa giảng bài, vừa viết báo, vừa sống cùng học trò. Trong hơn hai năm, căn nhà phố ấy đào tạo lớp cán bộ đầu tiên cho con đường cách mạng Việt Nam.","bia":{"src":"textures/bai/G09_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một địa chỉ, hai con số","text":"Địa chỉ ngày nay của di tích là số 248 – 250 đường Văn Minh, thành phố Quảng Châu, tỉnh Quảng Đông. Nhưng vào những năm 1925 – 1927, ngôi nhà mang số 13. Đó là một căn nhà phố như bao căn nhà khác trên con đường buôn bán ở khu trung tâm cũ của thành phố, lẫn giữa những dãy nhà kỵ lâu có hàng hiên cột chạy dài (xem chuyên đề Nhà kỵ lâu). Người qua đường khó đoán được rằng bên trong là Tổng bộ Hội Việt Nam Cách mạng Thanh niên.\n\nTại đây, Nguyễn Ái Quốc, khi ấy mang tên Lý Thụy, trực tiếp phụ trách và là giảng viên chính của ba lớp huấn luyện chính trị. Khoảng 75 thanh niên yêu nước đã qua các lớp học ấy. Cũng tại đây, báo Thanh Niên được biên soạn, và những bài giảng về sau được tập hợp, in thành cuốn Đường Kách mệnh. Một căn nhà nhỏ vì thế gánh cùng lúc ba vai: trụ sở của một tổ chức, trường học của một thế hệ và tòa soạn của một tờ báo.","doc":1},{"loai":"anh","src":"textures/bang_w/G09_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 248 – 250 đường Văn Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Giữa lòng một thành phố cách mạng","text":"Vì sao là một căn nhà phố giữa trung tâm Quảng Châu? Những năm giữa thập niên 1920, thành phố bên sông Châu Giang là căn cứ của chính quyền cách mạng mà Tôn Trung Sơn gây dựng. Quốc dân Đảng và những người cộng sản Trung Quốc đang hợp tác, các cố vấn Liên Xô có mặt trong nhiều cơ quan. Những người cách mạng từ Triều Tiên, Ấn Độ, Indonesia, Việt Nam tìm đến đây như tìm đến một chốn nương thân.\n\nThế nhưng mật thám Pháp vẫn có mặt ở Quảng Châu, nhất là quanh khu tô giới Sa Diện, và vẫn ráo riết theo dõi người Việt yêu nước. Một căn nhà trên phố buôn bán đông người, cửa hàng san sát, khách ra vào thường xuyên, là nơi một nhóm thanh niên có thể ăn ở, học tập mà ít bị chú ý. Khu phố quanh đó cũng là nơi hội tụ của cách mạng Trung Hoa. Cách không xa là Sở giảng tập phong trào nông dân, nơi những năm 1924 – 1926 mở các khóa huấn luyện cán bộ nông dân cho cách mạng Trung Quốc. Lớp học Việt Nam ra đời trong chính bầu không khí sôi động ấy.","doc":2},{"loai":"doan","tieu_de":"Lớp học, phòng ngủ và căn bếp","text":"Ngôi nhà được sắp xếp để cùng lúc phục vụ nhiều việc. Theo cách bài trí của di tích ngày nay, trong nhà có lớp học, phòng Bác ở, phòng ở của các học viên, bếp và gian trưng bày. Học viên không chỉ đến nghe giảng rồi về, mà ăn ở ngay trong ngôi nhà suốt thời gian khóa học. Mỗi lớp vì thế giống như một gia đình lớn, cùng học, cùng ăn, cùng sinh hoạt dưới một mái nhà.\n\nNguyễn Ái Quốc ở ngay trong ngôi nhà ấy, gần gũi với học trò hằng ngày. Người vẫn làm việc với danh nghĩa phiên dịch trong phái bộ cố vấn Borodin; thời gian còn lại dành cho lên lớp, sửa bài, viết báo. Giữ bí mật là nguyên tắc sống còn. Học viên dùng bí danh, không để lộ tên thật và quê quán, để khi trở về nước, mật thám Pháp không lần ra dấu vết. Chính trong khuôn khổ kỷ luật ấy, những người trẻ tuổi học được bài học đầu tiên về tổ chức: mỗi người là một mắt xích, và sự an toàn của cả tổ chức phụ thuộc vào từng người.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","chu_thich":"Nguyễn Ái Quốc năm 1924. Ít tháng sau, với tên Lý Thụy, Người đứng lớp trong ngôi nhà số 13 đường Văn Minh, Quảng Châu.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những người vượt biên đi học","text":"Học viên các lớp là những thanh niên yêu nước từ cả ba kỳ Bắc, Trung, Nam, bí mật rời quê sang Quảng Châu bằng nhiều ngả đường. Phần đông còn rất trẻ, nhiều người mới ngoài hai mươi tuổi. Họ đến từ những nhóm yêu nước khác nhau, có người đã tham gia các phong trào trong nước, có người là thợ thuyền, học sinh, giáo viên. Điểm chung của họ là khát vọng tìm một con đường cứu nước có hiệu quả hơn những cuộc nổi dậy đơn lẻ trước đó.\n\nNăm 1926, trong số học viên có Trần Phú, khi ấy hai mươi hai tuổi, và Phạm Văn Đồng, khi ấy hai mươi tuổi. Sau lớp học, Trần Phú được cử sang Mátxcơva học tập. Tháng 10/1930, ông được bầu làm Tổng Bí thư đầu tiên của Đảng và soạn thảo Luận cương chính trị. Phạm Văn Đồng về nước hoạt động, bị bắt, bị đày ra Côn Đảo, rồi trở thành Thủ tướng Chính phủ trong hơn ba mươi năm (xem chuyên đề Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh). Hai số phận ấy cho thấy tầm vóc của những con người đã đi ra từ ngôi nhà nhỏ trên phố Văn Minh.","doc":4},{"loai":"ban_co_biet","text":"Cách ngôi nhà không xa, cũng trên đường Văn Minh, là tòa lầu Chuông, nơi họp Đại hội đại biểu toàn quốc lần thứ nhất của Quốc dân Đảng Trung Quốc tháng 1/1924, mở ra thời kỳ hợp tác Quốc – Cộng. Năm 1927, nhà văn Lỗ Tấn từng sống ở tòa lầu này khi dạy tại Đại học Trung Sơn; nay đây là Nhà kỷ niệm Lỗ Tấn.","nguon_ten":"Nhà kỷ niệm Lỗ Tấn, Quảng Châu","doc":5},{"loai":"doan","tieu_de":"Học gì trong ngôi nhà ấy","text":"Các bài giảng của Người đi từ những điều căn bản nhất: vì sao phải làm cách mệnh, cách mệnh là việc của ai, người cách mệnh phải sống và làm việc thế nào. Từ đó, bài giảng mở ra thế giới rộng lớn: lịch sử các cuộc cách mạng Mỹ, Pháp, Nga và bài học rút ra từ mỗi cuộc. Tiếp theo là các tổ chức quốc tế của công nhân, phụ nữ, thanh niên, và cách tổ chức công hội, nông hội, hợp tác xã ở trong nước.\n\nĐiều làm nên sức hút của lớp học là cách giảng. Người dùng lời lẽ giản dị, câu ngắn, ví dụ gần gũi với đời sống người Việt, để cả những thanh niên ít học cũng hiểu và nhớ. Theo Người, lý luận cách mạng phải đi vào được đầu óc những người sẽ trở về đứng giữa nông dân, thợ thuyền. Cuối mỗi khóa, học viên không chỉ mang theo kiến thức, mà mang theo cả một phương pháp: nói cho dân hiểu, tổ chức dân lại, và kiên trì từng bước. Chính phương pháp ấy về sau giúp các cơ sở của Hội bén rễ nhanh chóng ở trong nước.","doc":6},{"loai":"trich","text":"Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mệnh nhất là chủ nghĩa Lênin.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Đường Kách mệnh, 1927 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":7},{"loai":"anh","src":"textures/bang_w/G09_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 248 – 250 đường Văn Minh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tòa soạn của báo Thanh Niên","text":"Ngày 21/6/1925, báo Thanh Niên ra số đầu tiên. Đây là cơ quan tuyên truyền của Hội Việt Nam Cách mạng Thanh niên, viết bằng chữ quốc ngữ, bài ngắn, lời lẽ dễ hiểu. Người là linh hồn của tờ báo: đặt đề tài, viết phần lớn bài, sửa bài của học viên và cộng sự. Công việc biên tập, in ấn được làm ngay trong ngôi nhà, với sự giúp sức của những cộng sự đầu tiên của Người.\n\nTừ căn nhà số 13, những số báo Thanh Niên được bí mật chuyển về nước và tới các cộng đồng người Việt ở nước ngoài bằng nhiều đường dây. Mỗi tờ báo lọt qua được vòng vây kiểm soát của thực dân là một lần tư tưởng cách mạng đến thêm với những người đang tìm đường. Tờ báo mở đầu cho nền báo chí cách mạng Việt Nam; ngày ra số đầu, 21/6, về sau được chọn làm Ngày Báo chí cách mạng Việt Nam. Những người làm báo hôm nay vẫn tìm về ngôi nhà trên phố Văn Minh như tìm về nơi khởi nguồn của nghề mình.","doc":8},{"loai":"doan","tieu_de":"Từ bài giảng đến cuốn Đường Kách mệnh","text":"Năm 1927, những bài giảng ở ngôi nhà này được tập hợp và in thành sách Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản tại Quảng Châu. Đó là một trong những tác phẩm lý luận cách mạng sớm nhất viết bằng tiếng Việt. Sách tự đặt câu hỏi: vì sao phải viết sách này? Câu trả lời là để đồng bào hiểu vì sao muốn sống thì phải cách mệnh, vì sao cách mệnh là việc chung của cả dân chúng chứ không phải việc của một hai người.\n\nNgười viết sách mong rằng đồng bào đọc rồi thì nghĩ lại, nghĩ rồi thì tỉnh dậy, tỉnh rồi thì đứng lên đoàn kết mà làm cách mệnh. Các chương sách nối tiếp nhau như các buổi học: cách mệnh Mỹ, cách mệnh Pháp, cách mệnh Nga, các tổ chức quốc tế, công hội, nông hội, hợp tác xã. Được bí mật đưa về nước, cuốn sách nhỏ trở thành cẩm nang của cả một thế hệ, được nhiều người truyền tay nhau đọc trong những năm trước khi Đảng ra đời.","doc":9},{"loai":"ban_co_biet","text":"Trang mở đầu Đường Kách mệnh là mục “Tư cách một người cách mệnh”, gồm hai mươi ba điều chia làm ba phần: tự mình phải thế nào, đối với người phải thế nào, làm việc phải thế nào. Trong đó có những điều giản dị như cần kiệm, nói thì phải làm, vị công vong tư, ít lòng tham muốn về vật chất, giữ bí mật.","nguon_ten":"Nguyễn Ái Quốc, Đường Kách mệnh (1927) – Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia","doc":10},{"loai":"doan","tieu_de":"Học xong, đi đâu","text":"Kết thúc khóa học, học viên tỏa đi nhiều ngả. Phần đông trở về nước, gây dựng cơ sở của Hội ở cả ba kỳ, trong các làng quê, nhà máy, hầm mỏ, trường học. Một số người được chọn vào học Trường Quân sự Hoàng Phố (xem chuyên đề Trường Quân sự Hoàng Phố); một số khác được cử sang Liên Xô, học tại Trường Đại học Phương Đông ở Mátxcơva.\n\nTháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản; đầu tháng 5/1927, Nguyễn Ái Quốc phải rời Quảng Châu. Lớp học trên phố Văn Minh khép lại, nhưng những hạt giống đã được gieo. Năm 1928, Hội phát động phong trào vô sản hóa, đưa hội viên vào sống và làm việc cùng công nhân, thợ mỏ, phu đồn điền. Từ những cơ sở ấy, các tổ chức cộng sản đầu tiên ra đời năm 1929. Hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng, lập ra Đảng Cộng sản Việt Nam. Người chủ trì hội nghị ấy chính là người thầy của lớp học trên phố Văn Minh năm nào.","doc":11},{"loai":"anh","src":"textures/bang_w/G09_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà số 248 – 250 đường Văn Minh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Năm 1971, ngôi nhà được công nhận là di tích lịch sử, do Bảo tàng Lịch sử Cách mạng Quảng Đông quản lý. Di tích được tu sửa và khánh thành ngày 30/4/2002, nhân dịp kỷ niệm 112 năm ngày sinh Chủ tịch Hồ Chí Minh. Khách tham quan hôm nay có thể bước vào lớp học, phòng Bác ở, phòng ở của học viên, căn bếp và gian trưng bày tư liệu về Hội Việt Nam Cách mạng Thanh niên.\n\nĐây là một trong những địa chỉ đỏ mà các đoàn đại biểu và khách Việt Nam thường tìm đến khi tới Quảng Châu. Năm 2024, Tổng Bí thư, Chủ tịch nước Tô Lâm đã đến thăm trụ sở Hội tại đây. Trong không gian 3D của bảo tàng, góc bảng này tái hiện không khí của một lớp học những năm 1920 với bàn ghế gỗ, đèn dầu, đèn treo. Đó là những đồ vật minh họa, giúp người xem hình dung các buổi học đầu tiên. Nơi ấy, một thế hệ thanh niên được chuẩn bị để trở về Tổ quốc.","doc":12},{"loai":"ban_co_biet","text":"Hội Việt Nam Cách mạng Thanh niên còn được gọi là Việt Nam Thanh niên Cách mạng Đồng chí Hội. Trong các tư liệu tiếng Trung, di tích trên đường Văn Minh được ghi là 越南青年革命同志会旧址, nghĩa là Di chỉ Việt Nam Thanh niên Cách mạng Đồng chí Hội.","nguon_ten":"Bảo tàng Hồ Chí Minh; Bảo tàng Lịch sử Cách mạng Quảng Đông","doc":13}],"nguon":["Bảo tàng Hồ Chí Minh – Di tích trụ sở Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu, Trung Quốc, https://baotanghochiminh.vn/di-tich-tru-so-hoi-viet-nam-cach-mang-thanh-nien-tai-quang-chau-trung-quoc.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Nguyễn Ái Quốc, Đường Kách mệnh (1927) – Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Nhà kỷ niệm Lỗ Tấn, Quảng Châu"],"doc":[{"t":"Số 13 đường Văn Minh: một ngôi nhà phố vừa là trụ sở, trường học và tòa soạn. Năm 1925, người Quảng Châu biết ngôi nhà này bằng một con số giản dị: số 13 đường Văn Minh. Không tấm biển nào cho biết bên trong là Tổng bộ của một tổ chức cách mạng Việt Nam. Ở đó, một người mang tên Lý Thụy vừa giảng bài, vừa viết báo, vừa sống cùng học trò. Trong hơn hai năm, căn nhà phố ấy đào tạo lớp cán bộ đầu tiên cho con đường cách mạng Việt Nam."},{"t":"Một địa chỉ, hai con số. Địa chỉ ngày nay của di tích là số 248 – 250 đường Văn Minh, thành phố Quảng Châu, tỉnh Quảng Đông. Nhưng vào những năm 1925 – 1927, ngôi nhà mang số 13. Đó là một căn nhà phố như bao căn nhà khác trên con đường buôn bán ở khu trung tâm cũ của thành phố, lẫn giữa những dãy nhà kỵ lâu có hàng hiên cột chạy dài (xem chuyên đề Nhà kỵ lâu). Người qua đường khó đoán được rằng bên trong là Tổng bộ Hội Việt Nam Cách mạng Thanh niên. Tại đây, Nguyễn Ái Quốc, khi ấy mang tên Lý Thụy, trực tiếp phụ trách và là giảng viên chính của ba lớp huấn luyện chính trị. Khoảng 75 thanh niên yêu nước đã qua các lớp học ấy. Cũng tại đây, báo Thanh Niên được biên soạn, và những bài giảng về sau được tập hợp, in thành cuốn Đường Kách mệnh. Một căn nhà nhỏ vì thế gánh cùng lúc ba vai: trụ sở của một tổ chức, trường học của một thế hệ và tòa soạn của một tờ báo."},{"t":"Giữa lòng một thành phố cách mạng. Vì sao là một căn nhà phố giữa trung tâm Quảng Châu? Những năm giữa thập niên 1920, thành phố bên sông Châu Giang là căn cứ của chính quyền cách mạng mà Tôn Trung Sơn gây dựng. Quốc dân Đảng và những người cộng sản Trung Quốc đang hợp tác, các cố vấn Liên Xô có mặt trong nhiều cơ quan. Những người cách mạng từ Triều Tiên, Ấn Độ, Indonesia, Việt Nam tìm đến đây như tìm đến một chốn nương thân. Thế nhưng mật thám Pháp vẫn có mặt ở Quảng Châu, nhất là quanh khu tô giới Sa Diện, và vẫn ráo riết theo dõi người Việt yêu nước. Một căn nhà trên phố buôn bán đông người, cửa hàng san sát, khách ra vào thường xuyên, là nơi một nhóm thanh niên có thể ăn ở, học tập mà ít bị chú ý. Khu phố quanh đó cũng là nơi hội tụ của cách mạng Trung Hoa. Cách không xa là Sở giảng tập phong trào nông dân, nơi những năm 1924 – 1926 mở các khóa huấn luyện cán bộ nông dân cho cách mạng Trung Quốc. Lớp học Việt Nam ra đời trong chính bầu không khí sôi động ấy."},{"t":"Lớp học, phòng ngủ và căn bếp. Ngôi nhà được sắp xếp để cùng lúc phục vụ nhiều việc. Theo cách bài trí của di tích ngày nay, trong nhà có lớp học, phòng Bác ở, phòng ở của các học viên, bếp và gian trưng bày. Học viên không chỉ đến nghe giảng rồi về, mà ăn ở ngay trong ngôi nhà suốt thời gian khóa học. Mỗi lớp vì thế giống như một gia đình lớn, cùng học, cùng ăn, cùng sinh hoạt dưới một mái nhà. Nguyễn Ái Quốc ở ngay trong ngôi nhà ấy, gần gũi với học trò hằng ngày. Người vẫn làm việc với danh nghĩa phiên dịch trong phái bộ cố vấn Borodin; thời gian còn lại dành cho lên lớp, sửa bài, viết báo. Giữ bí mật là nguyên tắc sống còn. Học viên dùng bí danh, không để lộ tên thật và quê quán, để khi trở về nước, mật thám Pháp không lần ra dấu vết. Chính trong khuôn khổ kỷ luật ấy, những người trẻ tuổi học được bài học đầu tiên về tổ chức: mỗi người là một mắt xích, và sự an toàn của cả tổ chức phụ thuộc vào từng người."},{"t":"Những người vượt biên đi học. Học viên các lớp là những thanh niên yêu nước từ cả ba kỳ Bắc, Trung, Nam, bí mật rời quê sang Quảng Châu bằng nhiều ngả đường. Phần đông còn rất trẻ, nhiều người mới ngoài hai mươi tuổi. Họ đến từ những nhóm yêu nước khác nhau, có người đã tham gia các phong trào trong nước, có người là thợ thuyền, học sinh, giáo viên. Điểm chung của họ là khát vọng tìm một con đường cứu nước có hiệu quả hơn những cuộc nổi dậy đơn lẻ trước đó. Năm 1926, trong số học viên có Trần Phú, khi ấy hai mươi hai tuổi, và Phạm Văn Đồng, khi ấy hai mươi tuổi. Sau lớp học, Trần Phú được cử sang Mátxcơva học tập. Tháng 10/1930, ông được bầu làm Tổng Bí thư đầu tiên của Đảng và soạn thảo Luận cương chính trị. Phạm Văn Đồng về nước hoạt động, bị bắt, bị đày ra Côn Đảo, rồi trở thành Thủ tướng Chính phủ trong hơn ba mươi năm (xem chuyên đề Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh). Hai số phận ấy cho thấy tầm vóc của những con người đã đi ra từ ngôi nhà nhỏ trên phố Văn Minh."},{"t":"Bạn có biết? Cách ngôi nhà không xa, cũng trên đường Văn Minh, là tòa lầu Chuông, nơi họp Đại hội đại biểu toàn quốc lần thứ nhất của Quốc dân Đảng Trung Quốc tháng 1/1924, mở ra thời kỳ hợp tác Quốc – Cộng. Năm 1927, nhà văn Lỗ Tấn từng sống ở tòa lầu này khi dạy tại Đại học Trung Sơn; nay đây là Nhà kỷ niệm Lỗ Tấn."},{"t":"Học gì trong ngôi nhà ấy. Các bài giảng của Người đi từ những điều căn bản nhất: vì sao phải làm cách mệnh, cách mệnh là việc của ai, người cách mệnh phải sống và làm việc thế nào. Từ đó, bài giảng mở ra thế giới rộng lớn: lịch sử các cuộc cách mạng Mỹ, Pháp, Nga và bài học rút ra từ mỗi cuộc. Tiếp theo là các tổ chức quốc tế của công nhân, phụ nữ, thanh niên, và cách tổ chức công hội, nông hội, hợp tác xã ở trong nước. Điều làm nên sức hút của lớp học là cách giảng. Người dùng lời lẽ giản dị, câu ngắn, ví dụ gần gũi với đời sống người Việt, để cả những thanh niên ít học cũng hiểu và nhớ. Theo Người, lý luận cách mạng phải đi vào được đầu óc những người sẽ trở về đứng giữa nông dân, thợ thuyền. Cuối mỗi khóa, học viên không chỉ mang theo kiến thức, mà mang theo cả một phương pháp: nói cho dân hiểu, tổ chức dân lại, và kiên trì từng bước. Chính phương pháp ấy về sau giúp các cơ sở của Hội bén rễ nhanh chóng ở trong nước."},{"t":"Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mệnh nhất là chủ nghĩa Lênin. — Nguyễn Ái Quốc"},{"t":"Tòa soạn của báo Thanh Niên. Ngày 21/6/1925, báo Thanh Niên ra số đầu tiên. Đây là cơ quan tuyên truyền của Hội Việt Nam Cách mạng Thanh niên, viết bằng chữ quốc ngữ, bài ngắn, lời lẽ dễ hiểu. Người là linh hồn của tờ báo: đặt đề tài, viết phần lớn bài, sửa bài của học viên và cộng sự. Công việc biên tập, in ấn được làm ngay trong ngôi nhà, với sự giúp sức của những cộng sự đầu tiên của Người. Từ căn nhà số 13, những số báo Thanh Niên được bí mật chuyển về nước và tới các cộng đồng người Việt ở nước ngoài bằng nhiều đường dây. Mỗi tờ báo lọt qua được vòng vây kiểm soát của thực dân là một lần tư tưởng cách mạng đến thêm với những người đang tìm đường. Tờ báo mở đầu cho nền báo chí cách mạng Việt Nam; ngày ra số đầu, 21/6, về sau được chọn làm Ngày Báo chí cách mạng Việt Nam. Những người làm báo hôm nay vẫn tìm về ngôi nhà trên phố Văn Minh như tìm về nơi khởi nguồn của nghề mình."},{"t":"Từ bài giảng đến cuốn Đường Kách mệnh. Năm 1927, những bài giảng ở ngôi nhà này được tập hợp và in thành sách Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản tại Quảng Châu. Đó là một trong những tác phẩm lý luận cách mạng sớm nhất viết bằng tiếng Việt. Sách tự đặt câu hỏi: vì sao phải viết sách này? Câu trả lời là để đồng bào hiểu vì sao muốn sống thì phải cách mệnh, vì sao cách mệnh là việc chung của cả dân chúng chứ không phải việc của một hai người. Người viết sách mong rằng đồng bào đọc rồi thì nghĩ lại, nghĩ rồi thì tỉnh dậy, tỉnh rồi thì đứng lên đoàn kết mà làm cách mệnh. Các chương sách nối tiếp nhau như các buổi học: cách mệnh Mỹ, cách mệnh Pháp, cách mệnh Nga, các tổ chức quốc tế, công hội, nông hội, hợp tác xã. Được bí mật đưa về nước, cuốn sách nhỏ trở thành cẩm nang của cả một thế hệ, được nhiều người truyền tay nhau đọc trong những năm trước khi Đảng ra đời."},{"t":"Bạn có biết? Trang mở đầu Đường Kách mệnh là mục “Tư cách một người cách mệnh”, gồm hai mươi ba điều chia làm ba phần: tự mình phải thế nào, đối với người phải thế nào, làm việc phải thế nào. Trong đó có những điều giản dị như cần kiệm, nói thì phải làm, vị công vong tư, ít lòng tham muốn về vật chất, giữ bí mật."},{"t":"Học xong, đi đâu. Kết thúc khóa học, học viên tỏa đi nhiều ngả. Phần đông trở về nước, gây dựng cơ sở của Hội ở cả ba kỳ, trong các làng quê, nhà máy, hầm mỏ, trường học. Một số người được chọn vào học Trường Quân sự Hoàng Phố (xem chuyên đề Trường Quân sự Hoàng Phố); một số khác được cử sang Liên Xô, học tại Trường Đại học Phương Đông ở Mátxcơva. Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản; đầu tháng 5/1927, Nguyễn Ái Quốc phải rời Quảng Châu. Lớp học trên phố Văn Minh khép lại, nhưng những hạt giống đã được gieo. Năm 1928, Hội phát động phong trào vô sản hóa, đưa hội viên vào sống và làm việc cùng công nhân, thợ mỏ, phu đồn điền. Từ những cơ sở ấy, các tổ chức cộng sản đầu tiên ra đời năm 1929. Hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng, lập ra Đảng Cộng sản Việt Nam. Người chủ trì hội nghị ấy chính là người thầy của lớp học trên phố Văn Minh năm nào."},{"t":"Dấu tích hôm nay. Năm 1971, ngôi nhà được công nhận là di tích lịch sử, do Bảo tàng Lịch sử Cách mạng Quảng Đông quản lý. Di tích được tu sửa và khánh thành ngày 30/4/2002, nhân dịp kỷ niệm 112 năm ngày sinh Chủ tịch Hồ Chí Minh. Khách tham quan hôm nay có thể bước vào lớp học, phòng Bác ở, phòng ở của học viên, căn bếp và gian trưng bày tư liệu về Hội Việt Nam Cách mạng Thanh niên. Đây là một trong những địa chỉ đỏ mà các đoàn đại biểu và khách Việt Nam thường tìm đến khi tới Quảng Châu. Năm 2024, Tổng Bí thư, Chủ tịch nước Tô Lâm đã đến thăm trụ sở Hội tại đây. Trong không gian 3D của bảo tàng, góc bảng này tái hiện không khí của một lớp học những năm 1920 với bàn ghế gỗ, đèn dầu, đèn treo. Đó là những đồ vật minh họa, giúp người xem hình dung các buổi học đầu tiên. Nơi ấy, một thế hệ thanh niên được chuẩn bị để trở về Tổ quốc."},{"t":"Bạn có biết? Hội Việt Nam Cách mạng Thanh niên còn được gọi là Việt Nam Thanh niên Cách mạng Đồng chí Hội. Trong các tư liệu tiếng Trung, di tích trên đường Văn Minh được ghi là 越南青年革命同志会旧址, nghĩa là Di chỉ Việt Nam Thanh niên Cách mạng Đồng chí Hội."}],"so_chu":2060},{"i":12,"tieu_de_bang":"Nhà kỵ lâu (骑楼)","tieu_de":"Kỵ lâu: những tầng lầu “cưỡi” lên vỉa hè quanh lớp học của Nguyễn Ái Quốc","sapo":"Trong gian Quảng Châu, khách bước dọc một dãy hiên có mái che, hàng cột nối nhau, phía trên là những tầng lầu vươn ra sát mép đường. Người Quảng Châu gọi kiểu nhà ấy là kỵ lâu, nghĩa là lầu cưỡi lên vỉa hè. Đó là khung cảnh mà Nguyễn Ái Quốc và các học viên đi qua mỗi ngày. Câu chuyện của những mái hiên ấy bắt đầu từ các thương cảng Đông Nam Á và từ một cuộc đổi mới đô thị đầu thế kỷ XX.","bia":{"src":"textures/bai/G09_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bước vào dưới hàng hiên","text":"Góc phố được phục dựng trong gian trưng bày có những dãy nhà ba, bốn tầng đứng sát nhau. Biển hiệu chữ Hán treo dọc trước cửa, đèn lồng giấy đỏ đung đưa, chiếc xe kéo tay dừng bên đường, và ở đầu phố là một cây đa lớn. Điều khiến khách chú ý nhất là tầng trệt: nó không chạy thẳng ra mặt đường như nhà phố thông thường, mà lùi vào trong, nhường chỗ cho một hành lang có mái che nối dài từ nhà này sang nhà khác.\n\nNhững tầng lầu phía trên thì ngược lại, vươn ra tới sát mép đường, tựa trên một hàng cột. Người đi bộ vì thế có thể đi hết cả dãy phố dưới bóng râm, không phải bước ra giữa nắng hay giữa mưa. Đó chính là kỵ lâu, kiểu nhà phố đã làm nên diện mạo của Quảng Châu đầu thế kỷ XX. Những năm 1925 – 1927, khi Nguyễn Ái Quốc mở lớp huấn luyện trên phố Văn Minh, những hàng hiên như thế là một phần quen thuộc của đời sống hằng ngày của Người và các học viên.","doc":1},{"loai":"anh","src":"textures/bang_w/G09_12_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà kỵ lâu (骑楼)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Cái tên nói lên hình dáng","text":"Hai chữ 骑楼 đọc theo âm Hán Việt là kỵ lâu. Chữ 骑, kỵ, nghĩa là cưỡi, như cưỡi ngựa; chữ 楼, lâu, nghĩa là lầu, là nhà nhiều tầng. Ghép lại, tên gọi tả đúng hình dáng ngôi nhà: phần lầu phía trên như cưỡi lên vỉa hè, hai chân là hàng cột đứng ở mép đường. Phần không gian dưới bụng lầu trở thành lối đi chung của cả khu phố.\n\nCách làm nhà ấy là một lời giải khéo léo cho hai bài toán cùng lúc. Bài toán thứ nhất là khí hậu. Vùng Lĩnh Nam nóng ẩm, mùa hè dài, nắng gắt, mưa nhiều và có bão; một dãy hiên liên tục che cho người đi đường suốt bốn mùa. Bài toán thứ hai là đất đai. Ở những phố buôn bán đắt đỏ, mặt tiền nhà nào cũng hẹp; phần lầu vươn ra trên vỉa hè giúp các tầng trên rộng thêm, còn tầng trệt vẫn giữ được mặt tiền mở ra lối đi. Người đi đường có bóng mát, chủ nhà có thêm diện tích, cửa hàng có thêm khách ghé qua.","doc":2},{"loai":"doan","tieu_de":"Từ “lối đi năm bộ” ở các thương cảng phương Nam","text":"Kiểu nhà phố có hàng hiên che lối đi không ra đời ở Quảng Châu. Năm 1822, bản quy hoạch đô thị Singapore do Stamford Raffles đặt ra yêu cầu các dãy nhà phố phải có một lối đi có mái che rộng khoảng năm bộ Anh, tức chừng một mét rưỡi, chạy dọc mặt tiền. Lối đi ấy được gọi là “five-foot way”, và dần trở thành nét quen thuộc của các thương cảng trên eo biển Malacca như Singapore, Penang, Malacca.\n\nCư dân của những dãy nhà phố ấy phần nhiều là người Hoa gốc Quảng Đông, Phúc Kiến sang làm ăn. Nhiều nhà nghiên cứu cho rằng chính những Hoa kiều trở về quê đã mang theo kiểu nhà phố có hiên này. Ở Hồng Kông, những dãy nhà có hành lang, ban công vươn ra trên vỉa hè cũng xuất hiện từ cuối thế kỷ XIX. Khi Quảng Châu bước vào thời kỳ chỉnh trang đô thị, mô hình ấy được đón nhận và phát triển thành một kiểu kiến trúc mang dấu ấn riêng của vùng Lĩnh Nam.","doc":3},{"loai":"ban_co_biet","text":"Cụm từ “five-foot way” được người Mã Lai gọi là kaki lima, nghĩa đen là “năm chân”. Ở Indonesia ngày nay, những người bán hàng rong trên vỉa hè vẫn được gọi là pedagang kaki lima, tức “người bán hàng năm chân”, một dấu vết ngôn ngữ của những lối đi có mái che thời trước.","nguon_ten":"Cơ quan Tái thiết Đô thị Singapore (URA) – tư liệu về nhà phố và lối đi five-foot way; Từ điển tiếng Indonesia KBBI, mục kaki lima","doc":4},{"loai":"doan","tieu_de":"Quảng Châu phá thành, mở đường","text":"Suốt nhiều thế kỷ, Quảng Châu bị bao bọc trong những lớp tường thành cổ, phố xá bên trong chật hẹp, quanh co. Từ cuối những năm 1910, chính quyền địa phương cho phá dỡ tường thành, mở những con đường rộng để xe cộ lưu thông. Năm 1921, Quảng Châu chính thức thành lập thành phố, với thị trưởng đầu tiên là Tôn Khoa, con trai Tôn Trung Sơn. Chính quyền mới đẩy mạnh việc làm đường, chỉnh trang phố xá theo hướng hiện đại.\n\nDọc hai bên những con đường mới ấy, kỵ lâu mọc lên thành dãy. Nhà nối nhà, hiên nối hiên, tạo thành những hành lang có mái che dài hàng trăm mét. Các tuyến phố buôn bán như Trường Đê ven sông Châu Giang, Thượng Hạ Cửu ở khu Tây Quan dần mang diện mạo mới. Khi Nguyễn Ái Quốc đến Quảng Châu cuối năm 1924, thành phố đang ở giữa đợt đổi thay ấy. Nó vừa là trung tâm của cách mạng Trung Hoa, vừa là một đô thị đang lớn nhanh, náo nhiệt, nơi kiến trúc Đông và Tây gặp nhau trên từng mặt phố.","doc":5},{"loai":"anh","src":"textures/bang_w/G09_12_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà kỵ lâu (骑楼)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ba phần của một mặt phố","text":"Nhìn một ngôi nhà kỵ lâu từ bên kia đường, có thể chia mặt đứng thành ba phần. Trên cùng là phần đỉnh, với tường chắn mái được đắp hoa văn, có khi uốn thành những đầu hồi mềm mại. Ở giữa là thân nhà, gồm các tầng ở với hàng cửa sổ cao, cửa chớp gỗ, có nhà làm thêm ban công. Dưới cùng là chân nhà, tức hàng cột và dãy hiên che lối đi.\n\nMặt tiền mỗi căn thường hẹp, nhưng nhà chạy rất sâu vào phía trong, nhiều căn có giếng trời để lấy ánh sáng và thông gió. Vật liệu ban đầu là gạch và gỗ, về sau bê tông cốt thép được dùng ngày càng nhiều. Trang trí trên mặt phố là nơi hai nền văn hóa gặp nhau. Những cột kiểu cổ điển phương Tây, những vòm cuốn và gờ chỉ đắp nổi đứng cạnh các họa tiết cát tường quen thuộc của người Hoa. Mỗi dãy phố vì thế vừa thống nhất về nhịp điệu hàng cột, vừa riêng biệt ở từng mặt nhà.","doc":6},{"loai":"doan","tieu_de":"Dưới là hàng, trên là nhà","text":"Kỵ lâu trước hết là nhà của người buôn bán. Tầng trệt mở ra hàng hiên để làm cửa hàng, các tầng trên để ở hoặc làm kho. Lối sống ấy thường được tóm gọn trong bốn chữ Hán 下铺上居, đọc là “hạ phố thượng cư”, nghĩa là dưới là cửa hàng, trên là nơi ở. Một gia đình có thể vừa bán hàng, vừa sinh sống dưới cùng một mái nhà.\n\nDãy hiên có mái che vì thế mang nhiều công năng. Nó là lối đi của khách bộ hành, là nơi cửa hàng bày hàng hóa, là chỗ người bán rong dừng chân, là nơi hàng xóm ngồi trò chuyện lúc chiều tối. Những ngày mưa dầm, cả khu phố vẫn tấp nập vì người mua kẻ bán không phải đội mưa. Có thể xem dãy hiên như một phòng khách chung của cả con phố. Với những người mới đến như các thanh niên Việt Nam sang học năm ấy, đi dưới những hàng hiên ồn ào tiếng rao, tiếng xe kéo là cách đầu tiên để làm quen với một đô thị xa lạ.","doc":7},{"loai":"ban_co_biet","text":"Phố đi bộ Thượng Hạ Cửu (上下九) ở Quảng Châu ngày nay là một trong những nơi còn giữ được nhiều dãy nhà kỵ lâu nhất, thu hút đông đảo du khách.","nguon_ten":"Tư liệu du lịch thành phố Quảng Châu","doc":8},{"loai":"doan","tieu_de":"Trên phố Văn Minh năm 1925","text":"Phố Văn Minh nằm ở khu trung tâm cũ của Quảng Châu, một khu phố buôn bán có những dãy nhà kỵ lâu kiểu Lĩnh Nam đặc trưng. Ngôi nhà mà Nguyễn Ái Quốc chọn làm Tổng bộ Hội Việt Nam Cách mạng Thanh niên, mang số 13 thời ấy và nay là số 248 – 250, nằm giữa khung cảnh ấy (xem chuyên đề Nhà số 248 – 250 đường Văn Minh).\n\nKiến trúc của phố góp phần che chở cho lớp học. Trên một con phố mà cửa hàng mở suốt ngày, khách ra vào liên tục, dưới hàng hiên lúc nào cũng có người qua lại, thì việc vài thanh niên lạ mặt ra vào một ngôi nhà không gây chú ý. Những thanh niên từ trong nước sang, sau hành trình bí mật dài ngày, bước vào dãy hiên ấy là bước vào một thế giới khác hẳn làng quê của mình. Trên đầu họ là những tầng lầu đông đúc, quanh họ là tiếng Quảng Đông và mùi hàng quán. Và ở cuối hành trình là lớp học, nơi họ sẽ nghe những bài giảng làm thay đổi cả cuộc đời mình.","doc":9},{"loai":"anh","src":"textures/bai/G09_v0.jpg","chu_thich":"Toàn cảnh không gian 3D gian Trung Quốc – Quảng Châu, nơi dựng lại một góc phố thị Quảng Châu những năm 1920.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Kỵ lâu khắp miền duyên hải phương Nam","text":"Không chỉ Quảng Châu, kỵ lâu còn trở thành gương mặt của nhiều đô thị ven biển miền Nam Trung Quốc. Ở Quảng Tây, thành phố Ngô Châu nổi tiếng với cả một khu phố kỵ lâu, còn phố cổ Bắc Hải có những dãy nhà mặt tiền trang trí kiểu phương Tây. Ở Hải Nam, phố cổ Hải Khẩu giữ được nhiều con đường kỵ lâu. Ở Phúc Kiến, đường Trung Sơn tại Hạ Môn cũng là một dãy phố có hàng hiên cột dài.\n\nBên kia eo biển, người Đài Loan gọi dãy hiên trước nhà là “đình tử cước”, tức chân của mái đình nhỏ. Xuống phía nam, các thương cảng Singapore, Penang, Malacca vẫn giữ những dãy nhà phố có lối đi năm bộ. Cùng một ý tưởng, mỗi nơi phát triển một dáng vẻ riêng, nhưng đều chung một tinh thần: nhường một phần ngôi nhà cho con phố, để con phố che chở cho người đi đường. Kỵ lâu vì thế là dấu tích của cả một vùng văn hóa thương cảng, nơi hàng hóa, con người và tư tưởng mới đi lại không ngừng.","doc":10},{"loai":"anh","src":"textures/bang_w/G09_12_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà kỵ lâu (骑楼)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Kỵ lâu hôm nay và trong gian trưng bày","text":"Qua gần một thế kỷ, nhiều dãy kỵ lâu ở Quảng Châu đã bị phá dỡ khi thành phố mở rộng đường sá, xây dựng những khu nhà mới. Những dãy còn lại ngày nay được coi là di sản kiến trúc của thành phố, được tu bổ và giữ gìn như một phần ký ức đô thị. Ở phố đi bộ Thượng Hạ Cửu, du khách vẫn có thể đi dưới những hàng hiên cột như người Quảng Châu trăm năm trước.\n\nTrong gian trưng bày, không gian 3D dựng lại một góc phố kỵ lâu những năm 1920 để khách hình dung môi trường sống của Nguyễn Ái Quốc và các học viên. Những chiếc giỏ mây đặt trong gian, cùng biển hiệu, đèn lồng, xe kéo đều là đồ vật minh họa cho đời sống phố thị thời ấy, không phải hiện vật gốc. Đi dưới hàng hiên ấy, người xem hiểu thêm rằng những bài giảng đầu tiên của con đường cách mạng Việt Nam đã vang lên giữa một con phố buôn bán náo nhiệt, chứ không phải trong một pháo đài biệt lập.","doc":11}],"nguon":["Bảo tàng Hồ Chí Minh – Di tích trụ sở Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu, Trung Quốc, https://baotanghochiminh.vn/di-tich-tru-so-hoi-viet-nam-cach-mang-thanh-nien-tai-quang-chau-trung-quoc.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Chính quyền nhân dân thành phố Quảng Châu – 百年骑楼筑老城肌理，廊下烟火延千载商脉 (Trăm năm kỵ lâu làm nên kết cấu phố cổ), cổng thông tin gz.gov.cn","Cơ quan Tái thiết Đô thị Singapore (URA) – tư liệu về nhà phố và lối đi five-foot way","Tư liệu du lịch thành phố Quảng Châu"],"doc":[{"t":"Kỵ lâu: những tầng lầu “cưỡi” lên vỉa hè quanh lớp học của Nguyễn Ái Quốc. Trong gian Quảng Châu, khách bước dọc một dãy hiên có mái che, hàng cột nối nhau, phía trên là những tầng lầu vươn ra sát mép đường. Người Quảng Châu gọi kiểu nhà ấy là kỵ lâu, nghĩa là lầu cưỡi lên vỉa hè. Đó là khung cảnh mà Nguyễn Ái Quốc và các học viên đi qua mỗi ngày. Câu chuyện của những mái hiên ấy bắt đầu từ các thương cảng Đông Nam Á và từ một cuộc đổi mới đô thị đầu thế kỷ XX."},{"t":"Bước vào dưới hàng hiên. Góc phố được phục dựng trong gian trưng bày có những dãy nhà ba, bốn tầng đứng sát nhau. Biển hiệu chữ Hán treo dọc trước cửa, đèn lồng giấy đỏ đung đưa, chiếc xe kéo tay dừng bên đường, và ở đầu phố là một cây đa lớn. Điều khiến khách chú ý nhất là tầng trệt: nó không chạy thẳng ra mặt đường như nhà phố thông thường, mà lùi vào trong, nhường chỗ cho một hành lang có mái che nối dài từ nhà này sang nhà khác. Những tầng lầu phía trên thì ngược lại, vươn ra tới sát mép đường, tựa trên một hàng cột. Người đi bộ vì thế có thể đi hết cả dãy phố dưới bóng râm, không phải bước ra giữa nắng hay giữa mưa. Đó chính là kỵ lâu, kiểu nhà phố đã làm nên diện mạo của Quảng Châu đầu thế kỷ XX. Những năm 1925 – 1927, khi Nguyễn Ái Quốc mở lớp huấn luyện trên phố Văn Minh, những hàng hiên như thế là một phần quen thuộc của đời sống hằng ngày của Người và các học viên."},{"t":"Cái tên nói lên hình dáng. Hai chữ 骑楼 đọc theo âm Hán Việt là kỵ lâu. Chữ 骑, kỵ, nghĩa là cưỡi, như cưỡi ngựa; chữ 楼, lâu, nghĩa là lầu, là nhà nhiều tầng. Ghép lại, tên gọi tả đúng hình dáng ngôi nhà: phần lầu phía trên như cưỡi lên vỉa hè, hai chân là hàng cột đứng ở mép đường. Phần không gian dưới bụng lầu trở thành lối đi chung của cả khu phố. Cách làm nhà ấy là một lời giải khéo léo cho hai bài toán cùng lúc. Bài toán thứ nhất là khí hậu. Vùng Lĩnh Nam nóng ẩm, mùa hè dài, nắng gắt, mưa nhiều và có bão; một dãy hiên liên tục che cho người đi đường suốt bốn mùa. Bài toán thứ hai là đất đai. Ở những phố buôn bán đắt đỏ, mặt tiền nhà nào cũng hẹp; phần lầu vươn ra trên vỉa hè giúp các tầng trên rộng thêm, còn tầng trệt vẫn giữ được mặt tiền mở ra lối đi. Người đi đường có bóng mát, chủ nhà có thêm diện tích, cửa hàng có thêm khách ghé qua."},{"t":"Từ “lối đi năm bộ” ở các thương cảng phương Nam. Kiểu nhà phố có hàng hiên che lối đi không ra đời ở Quảng Châu. Năm 1822, bản quy hoạch đô thị Singapore do Stamford Raffles đặt ra yêu cầu các dãy nhà phố phải có một lối đi có mái che rộng khoảng năm bộ Anh, tức chừng một mét rưỡi, chạy dọc mặt tiền. Lối đi ấy được gọi là “five-foot way”, và dần trở thành nét quen thuộc của các thương cảng trên eo biển Malacca như Singapore, Penang, Malacca. Cư dân của những dãy nhà phố ấy phần nhiều là người Hoa gốc Quảng Đông, Phúc Kiến sang làm ăn. Nhiều nhà nghiên cứu cho rằng chính những Hoa kiều trở về quê đã mang theo kiểu nhà phố có hiên này. Ở Hồng Kông, những dãy nhà có hành lang, ban công vươn ra trên vỉa hè cũng xuất hiện từ cuối thế kỷ XIX. Khi Quảng Châu bước vào thời kỳ chỉnh trang đô thị, mô hình ấy được đón nhận và phát triển thành một kiểu kiến trúc mang dấu ấn riêng của vùng Lĩnh Nam."},{"t":"Bạn có biết? Cụm từ “five-foot way” được người Mã Lai gọi là kaki lima, nghĩa đen là “năm chân”. Ở Indonesia ngày nay, những người bán hàng rong trên vỉa hè vẫn được gọi là pedagang kaki lima, tức “người bán hàng năm chân”, một dấu vết ngôn ngữ của những lối đi có mái che thời trước."},{"t":"Quảng Châu phá thành, mở đường. Suốt nhiều thế kỷ, Quảng Châu bị bao bọc trong những lớp tường thành cổ, phố xá bên trong chật hẹp, quanh co. Từ cuối những năm 1910, chính quyền địa phương cho phá dỡ tường thành, mở những con đường rộng để xe cộ lưu thông. Năm 1921, Quảng Châu chính thức thành lập thành phố, với thị trưởng đầu tiên là Tôn Khoa, con trai Tôn Trung Sơn. Chính quyền mới đẩy mạnh việc làm đường, chỉnh trang phố xá theo hướng hiện đại. Dọc hai bên những con đường mới ấy, kỵ lâu mọc lên thành dãy. Nhà nối nhà, hiên nối hiên, tạo thành những hành lang có mái che dài hàng trăm mét. Các tuyến phố buôn bán như Trường Đê ven sông Châu Giang, Thượng Hạ Cửu ở khu Tây Quan dần mang diện mạo mới. Khi Nguyễn Ái Quốc đến Quảng Châu cuối năm 1924, thành phố đang ở giữa đợt đổi thay ấy. Nó vừa là trung tâm của cách mạng Trung Hoa, vừa là một đô thị đang lớn nhanh, náo nhiệt, nơi kiến trúc Đông và Tây gặp nhau trên từng mặt phố."},{"t":"Ba phần của một mặt phố. Nhìn một ngôi nhà kỵ lâu từ bên kia đường, có thể chia mặt đứng thành ba phần. Trên cùng là phần đỉnh, với tường chắn mái được đắp hoa văn, có khi uốn thành những đầu hồi mềm mại. Ở giữa là thân nhà, gồm các tầng ở với hàng cửa sổ cao, cửa chớp gỗ, có nhà làm thêm ban công. Dưới cùng là chân nhà, tức hàng cột và dãy hiên che lối đi. Mặt tiền mỗi căn thường hẹp, nhưng nhà chạy rất sâu vào phía trong, nhiều căn có giếng trời để lấy ánh sáng và thông gió. Vật liệu ban đầu là gạch và gỗ, về sau bê tông cốt thép được dùng ngày càng nhiều. Trang trí trên mặt phố là nơi hai nền văn hóa gặp nhau. Những cột kiểu cổ điển phương Tây, những vòm cuốn và gờ chỉ đắp nổi đứng cạnh các họa tiết cát tường quen thuộc của người Hoa. Mỗi dãy phố vì thế vừa thống nhất về nhịp điệu hàng cột, vừa riêng biệt ở từng mặt nhà."},{"t":"Dưới là hàng, trên là nhà. Kỵ lâu trước hết là nhà của người buôn bán. Tầng trệt mở ra hàng hiên để làm cửa hàng, các tầng trên để ở hoặc làm kho. Lối sống ấy thường được tóm gọn trong bốn chữ Hán 下铺上居, đọc là “hạ phố thượng cư”, nghĩa là dưới là cửa hàng, trên là nơi ở. Một gia đình có thể vừa bán hàng, vừa sinh sống dưới cùng một mái nhà. Dãy hiên có mái che vì thế mang nhiều công năng. Nó là lối đi của khách bộ hành, là nơi cửa hàng bày hàng hóa, là chỗ người bán rong dừng chân, là nơi hàng xóm ngồi trò chuyện lúc chiều tối. Những ngày mưa dầm, cả khu phố vẫn tấp nập vì người mua kẻ bán không phải đội mưa. Có thể xem dãy hiên như một phòng khách chung của cả con phố. Với những người mới đến như các thanh niên Việt Nam sang học năm ấy, đi dưới những hàng hiên ồn ào tiếng rao, tiếng xe kéo là cách đầu tiên để làm quen với một đô thị xa lạ."},{"t":"Bạn có biết? Phố đi bộ Thượng Hạ Cửu (上下九) ở Quảng Châu ngày nay là một trong những nơi còn giữ được nhiều dãy nhà kỵ lâu nhất, thu hút đông đảo du khách."},{"t":"Trên phố Văn Minh năm 1925. Phố Văn Minh nằm ở khu trung tâm cũ của Quảng Châu, một khu phố buôn bán có những dãy nhà kỵ lâu kiểu Lĩnh Nam đặc trưng. Ngôi nhà mà Nguyễn Ái Quốc chọn làm Tổng bộ Hội Việt Nam Cách mạng Thanh niên, mang số 13 thời ấy và nay là số 248 – 250, nằm giữa khung cảnh ấy (xem chuyên đề Nhà số 248 – 250 đường Văn Minh). Kiến trúc của phố góp phần che chở cho lớp học. Trên một con phố mà cửa hàng mở suốt ngày, khách ra vào liên tục, dưới hàng hiên lúc nào cũng có người qua lại, thì việc vài thanh niên lạ mặt ra vào một ngôi nhà không gây chú ý. Những thanh niên từ trong nước sang, sau hành trình bí mật dài ngày, bước vào dãy hiên ấy là bước vào một thế giới khác hẳn làng quê của mình. Trên đầu họ là những tầng lầu đông đúc, quanh họ là tiếng Quảng Đông và mùi hàng quán. Và ở cuối hành trình là lớp học, nơi họ sẽ nghe những bài giảng làm thay đổi cả cuộc đời mình."},{"t":"Kỵ lâu khắp miền duyên hải phương Nam. Không chỉ Quảng Châu, kỵ lâu còn trở thành gương mặt của nhiều đô thị ven biển miền Nam Trung Quốc. Ở Quảng Tây, thành phố Ngô Châu nổi tiếng với cả một khu phố kỵ lâu, còn phố cổ Bắc Hải có những dãy nhà mặt tiền trang trí kiểu phương Tây. Ở Hải Nam, phố cổ Hải Khẩu giữ được nhiều con đường kỵ lâu. Ở Phúc Kiến, đường Trung Sơn tại Hạ Môn cũng là một dãy phố có hàng hiên cột dài. Bên kia eo biển, người Đài Loan gọi dãy hiên trước nhà là “đình tử cước”, tức chân của mái đình nhỏ. Xuống phía nam, các thương cảng Singapore, Penang, Malacca vẫn giữ những dãy nhà phố có lối đi năm bộ. Cùng một ý tưởng, mỗi nơi phát triển một dáng vẻ riêng, nhưng đều chung một tinh thần: nhường một phần ngôi nhà cho con phố, để con phố che chở cho người đi đường. Kỵ lâu vì thế là dấu tích của cả một vùng văn hóa thương cảng, nơi hàng hóa, con người và tư tưởng mới đi lại không ngừng."},{"t":"Kỵ lâu hôm nay và trong gian trưng bày. Qua gần một thế kỷ, nhiều dãy kỵ lâu ở Quảng Châu đã bị phá dỡ khi thành phố mở rộng đường sá, xây dựng những khu nhà mới. Những dãy còn lại ngày nay được coi là di sản kiến trúc của thành phố, được tu bổ và giữ gìn như một phần ký ức đô thị. Ở phố đi bộ Thượng Hạ Cửu, du khách vẫn có thể đi dưới những hàng hiên cột như người Quảng Châu trăm năm trước. Trong gian trưng bày, không gian 3D dựng lại một góc phố kỵ lâu những năm 1920 để khách hình dung môi trường sống của Nguyễn Ái Quốc và các học viên. Những chiếc giỏ mây đặt trong gian, cùng biển hiệu, đèn lồng, xe kéo đều là đồ vật minh họa cho đời sống phố thị thời ấy, không phải hiện vật gốc. Đi dưới hàng hiên ấy, người xem hiểu thêm rằng những bài giảng đầu tiên của con đường cách mạng Việt Nam đã vang lên giữa một con phố buôn bán náo nhiệt, chứ không phải trong một pháo đài biệt lập."}],"so_chu":1880},{"i":13,"tieu_de_bang":"Trường Quân sự Hoàng Phố","tieu_de":"Những học trò Việt Nam ở Hoàng Phố: từ đảo Trường Châu về chiến trường Tổ quốc","sapo":"Hai con người cùng được gọi là “vị tướng đầu tiên” của quân đội cách mạng Việt Nam, và cả hai từng học ở một ngôi trường trên hòn đảo giữa sông Châu Giang. Ngôi trường ấy do chính quyền Tôn Trung Sơn lập ra, hiệu trưởng là Tưởng Giới Thạch. Vì sao những thanh niên Việt Nam được Nguyễn Ái Quốc lựa chọn lại có mặt ở đó? Và họ đã mang những gì từ Hoàng Phố về cho Tổ quốc?","bia":{"src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Những người học trò nói tiếng Việt","text":"Từ trung tâm Quảng Châu những năm 1920, muốn đến Trường Quân sự Hoàng Phố phải xuôi dòng Châu Giang về phía đông, tới đảo Trường Châu. Ngôi trường khai giảng khóa đầu tiên từ tháng 6/1924. Lịch sử hình thành ngôi trường và cánh cổng nổi tiếng của nó được kể trong một chuyên đề riêng (xem chuyên đề Cổng Trường Quân sự Hoàng Phố, Quảng Châu). Bài này đi theo một nhóm người ít được biết đến hơn: những học viên Việt Nam.\n\nHọ không đến Hoàng Phố một cách ngẫu nhiên. Nhiều người trong số họ đã qua các lớp huấn luyện chính trị của Nguyễn Ái Quốc ở ngôi nhà trên đường Văn Minh, rồi được Người lựa chọn, giới thiệu vào trường. Trong số đó có những cái tên về sau đi vào lịch sử: Lê Hồng Phong, Phùng Chí Kiên, Lê Thiết Hùng. Một người trở thành người đứng đầu Ban Chấp hành Trung ương Đảng. Hai người kia đều được hậu thế gọi là vị tướng đầu tiên của quân đội cách mạng Việt Nam. Câu chuyện của họ bắt đầu từ một câu hỏi: vì sao một dân tộc mất nước lại phải gửi con em sang tận đất người để học nghề binh?","doc":1},{"loai":"anh","src":"textures/bang_w/G09_13_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quân sự Hoàng Phố”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một dân tộc chưa có trường võ bị của mình","text":"Suốt mấy chục năm sau khi thực dân Pháp đặt ách đô hộ, các cuộc đấu tranh vũ trang của người Việt Nam đều thiếu một điều: những người chỉ huy được đào tạo bài bản. Phong trào Cần Vương, cuộc khởi nghĩa Yên Thế của Hoàng Hoa Thám đã chiến đấu rất anh dũng, nhưng dựa chủ yếu vào kinh nghiệm và lòng quả cảm. Đầu thế kỷ XX, Phan Bội Châu phát động phong trào Đông Du, đưa thanh niên sang Nhật Bản học tập, trong đó có người theo học quân sự. Chỉ vài năm sau, chính phủ Nhật bắt tay với Pháp, trục xuất các du học sinh Việt Nam, và con đường ấy khép lại.\n\nỞ trong nước, người Việt chỉ có thể vào quân đội thuộc địa, làm lính khố xanh, khố đỏ phục vụ bộ máy cai trị. Không có trường nào dạy người Việt cầm quân vì độc lập của đất nước mình. Vì thế, khi Nguyễn Ái Quốc đến Quảng Châu tháng 11/1924, một trường sĩ quan hiện đại do chính quyền cách mạng Trung Hoa lập ra, lại đang hợp tác với Liên Xô, là cơ hội hiếm có. Làm việc trong phái bộ cố vấn Borodin, Người có điều kiện giới thiệu những thanh niên Việt Nam tin cậy vào học bên cạnh học viên Trung Quốc.","doc":2},{"loai":"doan","tieu_de":"Những ngày trên đảo Trường Châu","text":"Đời sống ở Hoàng Phố khác hẳn những buổi học trong ngôi nhà phố đường Văn Minh. Học viên ăn ở trong doanh trại, học binh khí, chiến thuật, cách chỉ huy một đơn vị nhỏ, xen với những giờ giảng chính trị. Bài giảng và khẩu lệnh đều bằng tiếng Hoa, nên những thanh niên Việt Nam phải vượt qua cả rào cản ngôn ngữ. Kỷ luật rất nghiêm, và người học phải sẵn sàng ra trận bất cứ lúc nào.\n\nHọc đi đôi với chiến đấu là nét riêng của Hoàng Phố những năm ấy. Năm 1925, học viên và sĩ quan của trường làm nòng cốt cho hai cuộc Đông chinh, đánh lực lượng của Trần Quýnh Minh ở miền đông Quảng Đông. Từ mùa hè năm 1926, họ lại là lực lượng chủ chốt của cuộc Bắc phạt nhằm thống nhất Trung Hoa. Những thanh niên Việt Nam học ở đây vì thế không chỉ học trên thao trường. Họ được chứng kiến một quân đội cách mạng hình thành và chiến đấu ra sao, và thấy tận mắt vai trò của công tác chính trị trong việc giữ vững tinh thần binh sĩ.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","chu_thich":"Cổng Trường Quân sự Hoàng Phố trên đảo Trường Châu, ảnh chụp năm 2009. Giữa những năm 1920, một số thanh niên Việt Nam do Nguyễn Ái Quốc giới thiệu đã qua cánh cổng này vào học nghề binh.","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Cả hai người thường được gọi là “vị tướng đầu tiên” của quân đội cách mạng Việt Nam đều từng học ở Hoàng Phố. Phùng Chí Kiên là liệt sĩ được Chủ tịch Hồ Chí Minh ký sắc lệnh truy phong cấp tướng; Lê Thiết Hùng được mang cấp thiếu tướng từ năm 1946.","nguon_ten":"Bộ Công an – Đề cương tuyên truyền kỷ niệm 120 năm ngày sinh đồng chí Phùng Chí Kiên; Báo Thanh Niên – Những vị tướng đầu tiên của QĐND Việt Nam: Lê Thiết Hùng – Vị tướng đầu tiên","doc":4},{"loai":"doan","tieu_de":"Lê Hồng Phong: từ Hoàng Phố đến trường phi công","text":"Lê Hồng Phong tên thật là Lê Huy Doãn, quê xã Hưng Thông, huyện Hưng Nguyên, tỉnh Nghệ An. Giữa những năm 1920, ông có mặt ở Quảng Châu, sớm được Nguyễn Ái Quốc tin tưởng và đào tạo. Sau thời gian học Trường Quân sự Hoàng Phố, năm 1926 ông được cử sang Liên Xô học tiếp. Ở đó, ông theo học các trường quân sự của Hồng quân, trong đó có trường đào tạo phi công, rồi học Trường Đại học Phương Đông ở Mátxcơva.\n\nĐầu những năm 1930, khi phong trào trong nước bị khủng bố dữ dội sau cao trào 1930 – 1931, Lê Hồng Phong trở về gần Tổ quốc, góp phần khôi phục tổ chức Đảng từ ngoài nước. Tại Đại hội đại biểu lần thứ nhất của Đảng, họp ở Ma Cao tháng 3/1935, ông được bầu đứng đầu Ban Chấp hành Trung ương. Cùng năm, ông dẫn đầu đoàn đại biểu của Đảng dự Đại hội VII Quốc tế Cộng sản và được bầu vào Ban Chấp hành Quốc tế Cộng sản. Tháng 6/1939, ông bị bắt ở Sài Gòn, rồi bị đày ra Côn Đảo. Ông mất tại đó ngày 6/9/1942, sau những năm tháng bị tra tấn, đày ải. Người vợ của ông, Nguyễn Thị Minh Khai, đã bị thực dân xử bắn ở Hóc Môn một năm trước đó.","doc":5},{"loai":"doan","tieu_de":"Phùng Chí Kiên: người học trò trở về cùng thầy","text":"Phùng Chí Kiên tên thật là Nguyễn Vĩ, quê làng Mỹ Quan, xã Diễn Yên, huyện Diễn Châu, tỉnh Nghệ An. Tháng 10/1926, ông được cử sang Quảng Châu dự lớp huấn luyện chính trị do Nguyễn Ái Quốc tổ chức, rồi được chọn vào học Trường Quân sự Hoàng Phố. Sau biến cố năm 1927, ông ở lại trong hàng ngũ cách mạng Trung Quốc, gia nhập Đảng Cộng sản Trung Quốc và chiến đấu trong Hồng quân. Tháng 1/1931, ông sang Liên Xô học Trường Đại học Phương Đông của Quốc tế Cộng sản.\n\nTháng 3/1935, tại Đại hội lần thứ nhất của Đảng ở Ma Cao, Phùng Chí Kiên được bầu vào Ban Chấp hành Trung ương. Năm 1940, ông là một trong những cán bộ của Đảng hoạt động ở Côn Minh, nơi Nguyễn Ái Quốc đang chuẩn bị về nước (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Mười bốn năm sau lớp học ở Quảng Châu, người học trò lại đi bên người thầy: ngày 28/1/1941, ông theo Nguyễn Ái Quốc về Pác Bó. Tại Hội nghị Trung ương lần thứ tám tháng 5/1941, ông được phân công phụ trách công tác quân sự, chỉ huy Cứu quốc quân bảo vệ căn cứ Bắc Sơn – Võ Nhai. Cuối tháng 8/1941, trên đường về Cao Bằng, ông hy sinh khi mới bốn mươi tuổi.","doc":6},{"loai":"anh","src":"textures/bang_w/G09_13_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quân sự Hoàng Phố”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Lê Thiết Hùng: người trở về từ quân ngũ nước bạn","text":"Lê Thiết Hùng tên thật là Lê Văn Nghiêm, sinh năm 1908, cũng quê xã Hưng Thông, huyện Hưng Nguyên, tỉnh Nghệ An. Còn rất trẻ, ông sang Quảng Châu theo con đường của Hội Việt Nam Cách mạng Thanh niên, rồi học và tốt nghiệp Trường Quân sự Hoàng Phố. Khác với nhiều bạn học, ông ở lại Trung Quốc suốt một thời gian dài, phục vụ trong quân đội Trung Hoa Dân quốc và từng giữ cấp bậc tương đương đại tá. Những năm tháng ấy cho ông vốn hiểu biết sâu về tổ chức, huấn luyện và chỉ huy một quân đội chính quy.\n\nSau Cách mạng Tháng Tám năm 1945, ông về nước phục vụ quân đội cách mạng còn non trẻ. Năm 1946, ông được Chủ tịch Hồ Chí Minh giao trọng trách và mang cấp thiếu tướng, vì thế nhiều tư liệu gọi ông là vị tướng đầu tiên của Quân đội nhân dân Việt Nam. Năm 1948, ông có tên trong sắc lệnh phong quân hàm Thiếu tướng cùng một số tướng lĩnh khác. Trên cương vị Cục trưởng Cục Quân huấn, rồi Tư lệnh Pháo binh, ông góp nhiều công sức vào việc đào tạo cán bộ và xây dựng binh chủng. Những năm 1960, ông làm Đại sứ Việt Nam tại Triều Tiên. Ông mất năm 1986 và được truy tặng Huân chương Hồ Chí Minh.","doc":7},{"loai":"ban_co_biet","text":"Lê Hồng Phong và Lê Thiết Hùng cùng quê xã Hưng Thông, huyện Hưng Nguyên; Phùng Chí Kiên quê huyện Diễn Châu. Ba học viên Hoàng Phố tiêu biểu nhất của cách mạng Việt Nam đều là người xứ Nghệ.","nguon_ten":"Tư liệu Văn kiện Đảng – Đồng chí Lê Hồng Phong; Báo Thanh Niên – Lê Thiết Hùng; Bộ Công an – Đề cương tuyên truyền về đồng chí Phùng Chí Kiên","doc":8},{"loai":"doan","tieu_de":"Năm 1927: những ngả đường rẽ","text":"Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản, hợp tác Quốc – Cộng tan vỡ. Với những học viên Việt Nam ở Hoàng Phố, đó là một bước ngoặt. Ngôi trường từng mở cửa cho họ nay nằm trong tay những người coi cộng sản là kẻ thù. Đầu tháng 5/1927, Nguyễn Ái Quốc cũng phải rời Quảng Châu. Mỗi người phải tự tìm lối đi của mình trong hoàn cảnh hiểm nghèo.\n\nCó người trở về nước, hòa vào phong trào đang lên của Hội Việt Nam Cách mạng Thanh niên. Có người ở lại, chiến đấu trong hàng ngũ cách mạng Trung Quốc, như Phùng Chí Kiên. Cũng có người, như Lê Thiết Hùng, ở lại trong quân đội Trung Hoa Dân quốc, tích lũy kinh nghiệm chỉ huy suốt nhiều năm. Trước đó, từ năm 1926, Lê Hồng Phong đã được gửi sang Liên Xô để học tiếp. Những ngả đường rất khác nhau, nhưng về sau đều quy tụ về một mối. Khi thời cơ đến, nhiều người học Hoàng Phố năm nào lại có mặt trong đội ngũ cán bộ quân sự đầu tiên của cách mạng Việt Nam.","doc":9},{"loai":"doan","tieu_de":"Từ Hoàng Phố đến Quân đội nhân dân","text":"Điều Nguyễn Ái Quốc gieo ở Quảng Châu không chỉ là một số cán bộ biết cầm quân. Đó còn là một cách nghĩ: người chỉ huy quân sự trước hết phải là người cách mạng, được giác ngộ chính trị và gắn bó với dân. Các học viên Việt Nam đến Hoàng Phố sau khi đã qua lớp học chính trị ở đường Văn Minh; ở trường, họ lại thấy công tác chính trị giữ vai trò thế nào trong một quân đội. Kinh nghiệm ấy theo họ trở về.\n\nTháng 12/1944, theo chỉ thị của Nguyễn Ái Quốc, lúc này đã mang tên Hồ Chí Minh, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời ngày 22/12 tại khu rừng Trần Hưng Đạo, Cao Bằng. Đội có 34 chiến sĩ, do Võ Nguyên Giáp chỉ huy. Sau Cách mạng Tháng Tám, những người như Lê Thiết Hùng đem vốn liếng học được để xây dựng các cơ quan huấn luyện của quân đội. Chỉ khoảng hai mươi năm sau ngày những thanh niên Việt Nam phải sang đất người học nghề binh, đất nước đã có những trường đào tạo cán bộ quân sự của riêng mình.","doc":10},{"loai":"trich","text":"Đội Việt Nam Tuyên truyền Giải phóng quân là khởi điểm của giải phóng quân, nó có thể đi suốt từ Nam chí Bắc, khắp đất nước Việt Nam.","nguoi":"Hồ Chí Minh","nguon_ten":"Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, tháng 12/1944 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia","doc":11},{"loai":"anh","src":"textures/bang_w/G09_13_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quân sự Hoàng Phố”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khu di tích Trường Quân sự Hoàng Phố trên đảo Trường Châu ngày nay là một nhà kỷ niệm mở cửa đón khách. Các phòng học, phòng ở của học viên được tái hiện trong tòa nhà hiệu bộ dựng lại theo kiến trúc cũ. Nhiều đoàn khách Việt Nam khi đến Quảng Châu vẫn tìm về đây, như tìm lại dấu chân các bậc tiền bối. Ở Việt Nam, ký ức về những học viên Hoàng Phố gắn với nhiều địa chỉ. Quê hương Hưng Nguyên có khu lưu niệm Tổng Bí thư Lê Hồng Phong, và nhiều đường phố, trường học trên cả nước mang tên ông. Thủ đô Hà Nội có phố mang tên Phùng Chí Kiên.\n\nTrong gian trưng bày, gần bảng này có một chiếc giỏ mây. Đó là đồ vật minh họa cho đời sống thường ngày của phố thị Quảng Châu thời ấy, không phải hiện vật gốc. Đứng trước bảng, khách có thể hình dung con đường mà những thanh niên Việt Nam đã đi. Họ rời làng quê xứ Nghệ, vượt biên sang Quảng Châu, ngồi nghe giảng trong ngôi nhà đường Văn Minh, rồi xuôi dòng Châu Giang tới đảo Trường Châu. Từ đó, họ lại lên đường, mang những gì học được trở về phục vụ Tổ quốc.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia – Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân (12/1944)","Tư liệu Văn kiện Đảng Cộng sản Việt Nam – Đồng chí Lê Hồng Phong, https://tulieuvankien.dangcongsan.vn/lanh-dao-dang-nha-nuoc/tong-bi-thu/dong-chi-le-hong-phong-77","Bộ Công an – Đề cương tuyên truyền kỷ niệm 120 năm ngày sinh đồng chí Phùng Chí Kiên, https://dhannd.bocongan.gov.vn/de-cuong-tuyen-truyen-ky-niem-120-nam-ngay-sinh-dong-chi-phung-chi-kien-a-998","Báo Thanh Niên – Những vị tướng đầu tiên của QĐND Việt Nam: Lê Thiết Hùng – Vị tướng đầu tiên, https://thanhnien.vn/nhung-vi-tuong-dau-tien-cua-qdnd-viet-nam-le-thiet-hung-vi-tuong-dau-tien-1851022095.htm","Tư liệu Nhà kỷ niệm di chỉ Trường Quân sự Hoàng Phố, Quảng Châu"],"doc":[{"t":"Những học trò Việt Nam ở Hoàng Phố: từ đảo Trường Châu về chiến trường Tổ quốc. Hai con người cùng được gọi là “vị tướng đầu tiên” của quân đội cách mạng Việt Nam, và cả hai từng học ở một ngôi trường trên hòn đảo giữa sông Châu Giang. Ngôi trường ấy do chính quyền Tôn Trung Sơn lập ra, hiệu trưởng là Tưởng Giới Thạch. Vì sao những thanh niên Việt Nam được Nguyễn Ái Quốc lựa chọn lại có mặt ở đó? Và họ đã mang những gì từ Hoàng Phố về cho Tổ quốc?"},{"t":"Những người học trò nói tiếng Việt. Từ trung tâm Quảng Châu những năm 1920, muốn đến Trường Quân sự Hoàng Phố phải xuôi dòng Châu Giang về phía đông, tới đảo Trường Châu. Ngôi trường khai giảng khóa đầu tiên từ tháng 6/1924. Lịch sử hình thành ngôi trường và cánh cổng nổi tiếng của nó được kể trong một chuyên đề riêng (xem chuyên đề Cổng Trường Quân sự Hoàng Phố, Quảng Châu). Bài này đi theo một nhóm người ít được biết đến hơn: những học viên Việt Nam. Họ không đến Hoàng Phố một cách ngẫu nhiên. Nhiều người trong số họ đã qua các lớp huấn luyện chính trị của Nguyễn Ái Quốc ở ngôi nhà trên đường Văn Minh, rồi được Người lựa chọn, giới thiệu vào trường. Trong số đó có những cái tên về sau đi vào lịch sử: Lê Hồng Phong, Phùng Chí Kiên, Lê Thiết Hùng. Một người trở thành người đứng đầu Ban Chấp hành Trung ương Đảng. Hai người kia đều được hậu thế gọi là vị tướng đầu tiên của quân đội cách mạng Việt Nam. Câu chuyện của họ bắt đầu từ một câu hỏi: vì sao một dân tộc mất nước lại phải gửi con em sang tận đất người để học nghề binh?"},{"t":"Một dân tộc chưa có trường võ bị của mình. Suốt mấy chục năm sau khi thực dân Pháp đặt ách đô hộ, các cuộc đấu tranh vũ trang của người Việt Nam đều thiếu một điều: những người chỉ huy được đào tạo bài bản. Phong trào Cần Vương, cuộc khởi nghĩa Yên Thế của Hoàng Hoa Thám đã chiến đấu rất anh dũng, nhưng dựa chủ yếu vào kinh nghiệm và lòng quả cảm. Đầu thế kỷ XX, Phan Bội Châu phát động phong trào Đông Du, đưa thanh niên sang Nhật Bản học tập, trong đó có người theo học quân sự. Chỉ vài năm sau, chính phủ Nhật bắt tay với Pháp, trục xuất các du học sinh Việt Nam, và con đường ấy khép lại. Ở trong nước, người Việt chỉ có thể vào quân đội thuộc địa, làm lính khố xanh, khố đỏ phục vụ bộ máy cai trị. Không có trường nào dạy người Việt cầm quân vì độc lập của đất nước mình. Vì thế, khi Nguyễn Ái Quốc đến Quảng Châu tháng 11/1924, một trường sĩ quan hiện đại do chính quyền cách mạng Trung Hoa lập ra, lại đang hợp tác với Liên Xô, là cơ hội hiếm có. Làm việc trong phái bộ cố vấn Borodin, Người có điều kiện giới thiệu những thanh niên Việt Nam tin cậy vào học bên cạnh học viên Trung Quốc."},{"t":"Những ngày trên đảo Trường Châu. Đời sống ở Hoàng Phố khác hẳn những buổi học trong ngôi nhà phố đường Văn Minh. Học viên ăn ở trong doanh trại, học binh khí, chiến thuật, cách chỉ huy một đơn vị nhỏ, xen với những giờ giảng chính trị. Bài giảng và khẩu lệnh đều bằng tiếng Hoa, nên những thanh niên Việt Nam phải vượt qua cả rào cản ngôn ngữ. Kỷ luật rất nghiêm, và người học phải sẵn sàng ra trận bất cứ lúc nào. Học đi đôi với chiến đấu là nét riêng của Hoàng Phố những năm ấy. Năm 1925, học viên và sĩ quan của trường làm nòng cốt cho hai cuộc Đông chinh, đánh lực lượng của Trần Quýnh Minh ở miền đông Quảng Đông. Từ mùa hè năm 1926, họ lại là lực lượng chủ chốt của cuộc Bắc phạt nhằm thống nhất Trung Hoa. Những thanh niên Việt Nam học ở đây vì thế không chỉ học trên thao trường. Họ được chứng kiến một quân đội cách mạng hình thành và chiến đấu ra sao, và thấy tận mắt vai trò của công tác chính trị trong việc giữ vững tinh thần binh sĩ."},{"t":"Bạn có biết? Cả hai người thường được gọi là “vị tướng đầu tiên” của quân đội cách mạng Việt Nam đều từng học ở Hoàng Phố. Phùng Chí Kiên là liệt sĩ được Chủ tịch Hồ Chí Minh ký sắc lệnh truy phong cấp tướng; Lê Thiết Hùng được mang cấp thiếu tướng từ năm 1946."},{"t":"Lê Hồng Phong: từ Hoàng Phố đến trường phi công. Lê Hồng Phong tên thật là Lê Huy Doãn, quê xã Hưng Thông, huyện Hưng Nguyên, tỉnh Nghệ An. Giữa những năm 1920, ông có mặt ở Quảng Châu, sớm được Nguyễn Ái Quốc tin tưởng và đào tạo. Sau thời gian học Trường Quân sự Hoàng Phố, năm 1926 ông được cử sang Liên Xô học tiếp. Ở đó, ông theo học các trường quân sự của Hồng quân, trong đó có trường đào tạo phi công, rồi học Trường Đại học Phương Đông ở Mátxcơva. Đầu những năm 1930, khi phong trào trong nước bị khủng bố dữ dội sau cao trào 1930 – 1931, Lê Hồng Phong trở về gần Tổ quốc, góp phần khôi phục tổ chức Đảng từ ngoài nước. Tại Đại hội đại biểu lần thứ nhất của Đảng, họp ở Ma Cao tháng 3/1935, ông được bầu đứng đầu Ban Chấp hành Trung ương. Cùng năm, ông dẫn đầu đoàn đại biểu của Đảng dự Đại hội VII Quốc tế Cộng sản và được bầu vào Ban Chấp hành Quốc tế Cộng sản. Tháng 6/1939, ông bị bắt ở Sài Gòn, rồi bị đày ra Côn Đảo. Ông mất tại đó ngày 6/9/1942, sau những năm tháng bị tra tấn, đày ải. Người vợ của ông, Nguyễn Thị Minh Khai, đã bị thực dân xử bắn ở Hóc Môn một năm trước đó."},{"t":"Phùng Chí Kiên: người học trò trở về cùng thầy. Phùng Chí Kiên tên thật là Nguyễn Vĩ, quê làng Mỹ Quan, xã Diễn Yên, huyện Diễn Châu, tỉnh Nghệ An. Tháng 10/1926, ông được cử sang Quảng Châu dự lớp huấn luyện chính trị do Nguyễn Ái Quốc tổ chức, rồi được chọn vào học Trường Quân sự Hoàng Phố. Sau biến cố năm 1927, ông ở lại trong hàng ngũ cách mạng Trung Quốc, gia nhập Đảng Cộng sản Trung Quốc và chiến đấu trong Hồng quân. Tháng 1/1931, ông sang Liên Xô học Trường Đại học Phương Đông của Quốc tế Cộng sản. Tháng 3/1935, tại Đại hội lần thứ nhất của Đảng ở Ma Cao, Phùng Chí Kiên được bầu vào Ban Chấp hành Trung ương. Năm 1940, ông là một trong những cán bộ của Đảng hoạt động ở Côn Minh, nơi Nguyễn Ái Quốc đang chuẩn bị về nước (xem chuyên đề Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam). Mười bốn năm sau lớp học ở Quảng Châu, người học trò lại đi bên người thầy: ngày 28/1/1941, ông theo Nguyễn Ái Quốc về Pác Bó. Tại Hội nghị Trung ương lần thứ tám tháng 5/1941, ông được phân công phụ trách công tác quân sự, chỉ huy Cứu quốc quân bảo vệ căn cứ Bắc Sơn – Võ Nhai. Cuối tháng 8/1941, trên đường về Cao Bằng, ông hy sinh khi mới bốn mươi tuổi."},{"t":"Lê Thiết Hùng: người trở về từ quân ngũ nước bạn. Lê Thiết Hùng tên thật là Lê Văn Nghiêm, sinh năm 1908, cũng quê xã Hưng Thông, huyện Hưng Nguyên, tỉnh Nghệ An. Còn rất trẻ, ông sang Quảng Châu theo con đường của Hội Việt Nam Cách mạng Thanh niên, rồi học và tốt nghiệp Trường Quân sự Hoàng Phố. Khác với nhiều bạn học, ông ở lại Trung Quốc suốt một thời gian dài, phục vụ trong quân đội Trung Hoa Dân quốc và từng giữ cấp bậc tương đương đại tá. Những năm tháng ấy cho ông vốn hiểu biết sâu về tổ chức, huấn luyện và chỉ huy một quân đội chính quy. Sau Cách mạng Tháng Tám năm 1945, ông về nước phục vụ quân đội cách mạng còn non trẻ. Năm 1946, ông được Chủ tịch Hồ Chí Minh giao trọng trách và mang cấp thiếu tướng, vì thế nhiều tư liệu gọi ông là vị tướng đầu tiên của Quân đội nhân dân Việt Nam. Năm 1948, ông có tên trong sắc lệnh phong quân hàm Thiếu tướng cùng một số tướng lĩnh khác. Trên cương vị Cục trưởng Cục Quân huấn, rồi Tư lệnh Pháo binh, ông góp nhiều công sức vào việc đào tạo cán bộ và xây dựng binh chủng. Những năm 1960, ông làm Đại sứ Việt Nam tại Triều Tiên. Ông mất năm 1986 và được truy tặng Huân chương Hồ Chí Minh."},{"t":"Bạn có biết? Lê Hồng Phong và Lê Thiết Hùng cùng quê xã Hưng Thông, huyện Hưng Nguyên; Phùng Chí Kiên quê huyện Diễn Châu. Ba học viên Hoàng Phố tiêu biểu nhất của cách mạng Việt Nam đều là người xứ Nghệ."},{"t":"Năm 1927: những ngả đường rẽ. Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản, hợp tác Quốc – Cộng tan vỡ. Với những học viên Việt Nam ở Hoàng Phố, đó là một bước ngoặt. Ngôi trường từng mở cửa cho họ nay nằm trong tay những người coi cộng sản là kẻ thù. Đầu tháng 5/1927, Nguyễn Ái Quốc cũng phải rời Quảng Châu. Mỗi người phải tự tìm lối đi của mình trong hoàn cảnh hiểm nghèo. Có người trở về nước, hòa vào phong trào đang lên của Hội Việt Nam Cách mạng Thanh niên. Có người ở lại, chiến đấu trong hàng ngũ cách mạng Trung Quốc, như Phùng Chí Kiên. Cũng có người, như Lê Thiết Hùng, ở lại trong quân đội Trung Hoa Dân quốc, tích lũy kinh nghiệm chỉ huy suốt nhiều năm. Trước đó, từ năm 1926, Lê Hồng Phong đã được gửi sang Liên Xô để học tiếp. Những ngả đường rất khác nhau, nhưng về sau đều quy tụ về một mối. Khi thời cơ đến, nhiều người học Hoàng Phố năm nào lại có mặt trong đội ngũ cán bộ quân sự đầu tiên của cách mạng Việt Nam."},{"t":"Từ Hoàng Phố đến Quân đội nhân dân. Điều Nguyễn Ái Quốc gieo ở Quảng Châu không chỉ là một số cán bộ biết cầm quân. Đó còn là một cách nghĩ: người chỉ huy quân sự trước hết phải là người cách mạng, được giác ngộ chính trị và gắn bó với dân. Các học viên Việt Nam đến Hoàng Phố sau khi đã qua lớp học chính trị ở đường Văn Minh; ở trường, họ lại thấy công tác chính trị giữ vai trò thế nào trong một quân đội. Kinh nghiệm ấy theo họ trở về. Tháng 12/1944, theo chỉ thị của Nguyễn Ái Quốc, lúc này đã mang tên Hồ Chí Minh, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời ngày 22/12 tại khu rừng Trần Hưng Đạo, Cao Bằng. Đội có 34 chiến sĩ, do Võ Nguyên Giáp chỉ huy. Sau Cách mạng Tháng Tám, những người như Lê Thiết Hùng đem vốn liếng học được để xây dựng các cơ quan huấn luyện của quân đội. Chỉ khoảng hai mươi năm sau ngày những thanh niên Việt Nam phải sang đất người học nghề binh, đất nước đã có những trường đào tạo cán bộ quân sự của riêng mình."},{"t":"Đội Việt Nam Tuyên truyền Giải phóng quân là khởi điểm của giải phóng quân, nó có thể đi suốt từ Nam chí Bắc, khắp đất nước Việt Nam. — Hồ Chí Minh"},{"t":"Dấu tích hôm nay. Khu di tích Trường Quân sự Hoàng Phố trên đảo Trường Châu ngày nay là một nhà kỷ niệm mở cửa đón khách. Các phòng học, phòng ở của học viên được tái hiện trong tòa nhà hiệu bộ dựng lại theo kiến trúc cũ. Nhiều đoàn khách Việt Nam khi đến Quảng Châu vẫn tìm về đây, như tìm lại dấu chân các bậc tiền bối. Ở Việt Nam, ký ức về những học viên Hoàng Phố gắn với nhiều địa chỉ. Quê hương Hưng Nguyên có khu lưu niệm Tổng Bí thư Lê Hồng Phong, và nhiều đường phố, trường học trên cả nước mang tên ông. Thủ đô Hà Nội có phố mang tên Phùng Chí Kiên. Trong gian trưng bày, gần bảng này có một chiếc giỏ mây. Đó là đồ vật minh họa cho đời sống thường ngày của phố thị Quảng Châu thời ấy, không phải hiện vật gốc. Đứng trước bảng, khách có thể hình dung con đường mà những thanh niên Việt Nam đã đi. Họ rời làng quê xứ Nghệ, vượt biên sang Quảng Châu, ngồi nghe giảng trong ngôi nhà đường Văn Minh, rồi xuôi dòng Châu Giang tới đảo Trường Châu. Từ đó, họ lại lên đường, mang những gì học được trở về phục vụ Tổ quốc."}],"so_chu":2162}],"do_vat":[{"id":"table@-9.5,-16.1","x":-9.5,"y":0.2,"z":-16.15,"loai":"table","ten":"Bàn giảng","tieu_de":"Nơi những bài giảng thành sách Đường Kách mệnh","text":"Chiếc bàn gỗ đặt ở đầu gian lớp học là đồ vật minh họa, dựng lại đúng vị trí người thầy đứng giảng bài trong ngôi nhà số 248 – 250 phố Văn Minh, thành phố Quảng Châu, những năm 1925 – 1927. Trên mặt bàn phục dựng chỉ có vài trang giấy viết tay và một ngọn bút lông — không phải hiện vật gốc, mà là chi tiết tái hiện không khí một lớp huấn luyện cách mạng họp kín giữa đất khách, nơi thầy trò đều mang bí danh để giữ an toàn cho nhau.\n\nTháng 6 năm 1925, cũng tại căn nhà này, Nguyễn Ái Quốc sáng lập Hội Việt Nam Cách mạng Thanh niên — tổ chức cách mạng đầu tiên theo khuynh hướng cộng sản của người Việt Nam. Từ đây, trong hai năm 1925 – 1927, Người trực tiếp mở liên tiếp ba lớp huấn luyện chính trị, đào tạo khoảng 75 học viên. Đó là những thanh niên yêu nước từ trong nước bí mật vượt biên sang, mang theo khát vọng tìm một con đường cứu nước mới, sau khi các phong trào Đông Du, Duy Tân, các cuộc khởi nghĩa vũ trang đầu thế kỷ đã lần lượt thất bại. Lớp học không văn bằng, không giấy chứng nhận, chỉ có người thầy đứng sau chiếc bàn gỗ đơn sơ, nói bằng thứ tiếng Việt bình dị, dễ hiểu, dễ nhớ.\n\nNội dung bài giảng xoay quanh những câu hỏi cốt lõi: một người làm cách mệnh cần tư cách gì, các cuộc cách mạng Mỹ, Pháp, Nga đã đi qua những chặng đường nào, và vì sao con đường giải phóng dân tộc Việt Nam cần hướng tới cách mạng vô sản chứ không dừng lại ở cách mạng tư sản. Người giảng giải bằng những ví dụ gắn liền với thân phận người dân mất nước, để những học viên phần lớn mới học hết chữ Quốc ngữ vẫn có thể nắm được những vấn đề chính trị vốn xa lạ và phức tạp với họ.\n\nNăm 1927, những bài giảng ấy được tập hợp, biên soạn lại và in bí mật thành cuốn Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức xuất bản — một trong những văn kiện lý luận cách mạng bằng tiếng Việt sớm nhất. Sách mở đầu bằng chương “Tư cách một người cách mệnh”, dặn người làm cách mạng phải cần kiệm, hòa mà không tư, cả quyết sửa lỗi mình, đối với người phải khoan thứ, có lòng bày vẽ cho người. Sách được đưa lén về nước qua nhiều ngả, truyền tay nhau trong các cơ sở cách mạng, trở thành cẩm nang gối đầu giường của cả một thế hệ thanh niên yêu nước. Trong số những học viên từng ngồi nghe giảng ở lớp học này có Trần Phú, người sau đó được cử sang học tại Trường Đại học Phương Đông ở Mátxcơva, trở về nước năm 1930 và soạn thảo Luận cương chính trị, trở thành Tổng Bí thư đầu tiên của Đảng (xem chuyên đề Trần Phú – từ lớp học Quảng Châu đến Tổng Bí thư).\n\nBản gốc Đường Kách mệnh ngày nay được công nhận là Bảo vật quốc gia, do Bảo tàng Lịch sử Quốc gia lưu giữ và từng đưa ra trưng bày để công chúng chiêm ngưỡng những trang in litô đã mờ theo năm tháng nhưng vẫn giữ nguyên tinh thần buổi đầu cách mạng. Chiếc bàn giảng trong không gian phục dựng, vì vậy, không đơn thuần là một món đồ nội thất: nó đánh dấu điểm khởi đầu của một dòng tư tưởng đã theo chân những người học trò Quảng Châu trở về, len lỏi vào phong trào công nhân, nông dân trong nước suốt những năm sau đó, và góp phần chuẩn bị trực tiếp cho sự ra đời của Đảng Cộng sản Việt Nam năm 1930.","nguon":"Nguyễn Ái Quốc, Đường Kách mệnh (1927) – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia; Bảo tàng Lịch sử Quốc gia, trưng bày Bảo vật quốc gia Đường Kách mệnh; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Nơi những bài giảng thành sách Đường Kách mệnh. Chiếc bàn gỗ đặt ở đầu gian lớp học là đồ vật minh họa, dựng lại đúng vị trí người thầy đứng giảng bài trong ngôi nhà số 248 – 250 phố Văn Minh, thành phố Quảng Châu, những năm 1925 – 1927. Trên mặt bàn phục dựng chỉ có vài trang giấy viết tay và một ngọn bút lông — không phải hiện vật gốc, mà là chi tiết tái hiện không khí một lớp huấn luyện cách mạng họp kín giữa đất khách, nơi thầy trò đều mang bí danh để giữ an toàn cho nhau."},{"t":"Tháng 6 năm 1925, cũng tại căn nhà này, Nguyễn Ái Quốc sáng lập Hội Việt Nam Cách mạng Thanh niên — tổ chức cách mạng đầu tiên theo khuynh hướng cộng sản của người Việt Nam. Từ đây, trong hai năm 1925 – 1927, Người trực tiếp mở liên tiếp ba lớp huấn luyện chính trị, đào tạo khoảng 75 học viên. Đó là những thanh niên yêu nước từ trong nước bí mật vượt biên sang, mang theo khát vọng tìm một con đường cứu nước mới, sau khi các phong trào Đông Du, Duy Tân, các cuộc khởi nghĩa vũ trang đầu thế kỷ đã lần lượt thất bại. Lớp học không văn bằng, không giấy chứng nhận, chỉ có người thầy đứng sau chiếc bàn gỗ đơn sơ, nói bằng thứ tiếng Việt bình dị, dễ hiểu, dễ nhớ."},{"t":"Nội dung bài giảng xoay quanh những câu hỏi cốt lõi: một người làm cách mệnh cần tư cách gì, các cuộc cách mạng Mỹ, Pháp, Nga đã đi qua những chặng đường nào, và vì sao con đường giải phóng dân tộc Việt Nam cần hướng tới cách mạng vô sản chứ không dừng lại ở cách mạng tư sản. Người giảng giải bằng những ví dụ gắn liền với thân phận người dân mất nước, để những học viên phần lớn mới học hết chữ Quốc ngữ vẫn có thể nắm được những vấn đề chính trị vốn xa lạ và phức tạp với họ."},{"t":"Năm 1927, những bài giảng ấy được tập hợp, biên soạn lại và in bí mật thành cuốn Đường Kách mệnh, do Bộ Tuyên truyền của Hội Liên hiệp các dân tộc bị áp bức xuất bản — một trong những văn kiện lý luận cách mạng bằng tiếng Việt sớm nhất. Sách mở đầu bằng chương “Tư cách một người cách mệnh”, dặn người làm cách mạng phải cần kiệm, hòa mà không tư, cả quyết sửa lỗi mình, đối với người phải khoan thứ, có lòng bày vẽ cho người. Sách được đưa lén về nước qua nhiều ngả, truyền tay nhau trong các cơ sở cách mạng, trở thành cẩm nang gối đầu giường của cả một thế hệ thanh niên yêu nước. Trong số những học viên từng ngồi nghe giảng ở lớp học này có Trần Phú, người sau đó được cử sang học tại Trường Đại học Phương Đông ở Mátxcơva, trở về nước năm 1930 và soạn thảo Luận cương chính trị, trở thành Tổng Bí thư đầu tiên của Đảng (xem chuyên đề Trần Phú – từ lớp học Quảng Châu đến Tổng Bí thư)."},{"t":"Bản gốc Đường Kách mệnh ngày nay được công nhận là Bảo vật quốc gia, do Bảo tàng Lịch sử Quốc gia lưu giữ và từng đưa ra trưng bày để công chúng chiêm ngưỡng những trang in litô đã mờ theo năm tháng nhưng vẫn giữ nguyên tinh thần buổi đầu cách mạng. Chiếc bàn giảng trong không gian phục dựng, vì vậy, không đơn thuần là một món đồ nội thất: nó đánh dấu điểm khởi đầu của một dòng tư tưởng đã theo chân những người học trò Quảng Châu trở về, len lỏi vào phong trào công nhân, nông dân trong nước suốt những năm sau đó, và góp phần chuẩn bị trực tiếp cho sự ra đời của Đảng Cộng sản Việt Nam năm 1930."},{"t":"Bạn có biết? Theo Bảo tàng Lịch sử Quốc gia, bản gốc Đường Kách mệnh là một trong số ít văn kiện lý luận cách mạng từ những năm 1920 của Việt Nam còn được bảo tồn và được công nhận là Bảo vật quốc gia."}],"ban_co_biet":"Theo Bảo tàng Lịch sử Quốc gia, bản gốc Đường Kách mệnh là một trong số ít văn kiện lý luận cách mạng từ những năm 1920 của Việt Nam còn được bảo tồn và được công nhận là Bảo vật quốc gia."},{"id":"blackboard@-9.5,-17.5","x":-9.5,"y":1,"z":-17.49,"loai":"blackboard","ten":"Tấm bảng đen","tieu_de":"Bài học về các cuộc cách mạng","text":"Tấm bảng đen dựng trong góc lớp phục dựng là đồ vật minh họa, gợi lại công cụ giảng dạy giản dị nhất của một lớp học không giáo trình in sẵn: một tấm bảng, viên phấn và trí nhớ của người thầy. Tại đây, giữa những buổi học bí mật ban ngày và những đêm canh chừng mật thám, Nguyễn Ái Quốc đã dùng chính tấm bảng ấy để vẽ lại cả một dòng chảy lịch sử thế giới cho những học viên chưa từng ra khỏi lũy tre làng.\n\nTrong Đường Kách mệnh, phần dành riêng cho các cuộc cách mạng lớn trên thế giới được trình bày với một cách nhìn rất riêng. Người điểm lại cách mạng Mỹ năm 1776 và cách mạng Pháp năm 1789, gọi đó là “cách mệnh tư bản”, “cách mệnh không đến nơi”: tiếng là cộng hòa, dân chủ, nhưng bên trong vẫn bóc lột công nông, bên ngoài vẫn áp bức thuộc địa. Đối chiếu với đó, cách mạng Nga tháng Mười năm 1917 được nhìn nhận là cuộc cách mạng triệt để nhất, đưa chính quyền thật sự về tay công nông.\n\nCách đặt vấn đề ấy không phải ngẫu nhiên. Năm 1920, tại Pháp, Nguyễn Ái Quốc đọc được Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, và tìm thấy ở đó con đường giải phóng cho các dân tộc bị áp bức như Việt Nam. Từ Paris đến Quảng Châu, hành trình tư tưởng ấy được Người chắt lọc lại thành những bài giảng ngắn gọn, dễ nhớ, đủ sức thuyết phục một lớp học viên vốn chỉ quen với sách thánh hiền hay văn chương yêu nước truyền thống. Trước đó, ngay tại Pháp, Người cũng đã viết Bản án chế độ thực dân Pháp, xuất bản năm 1925, phê phán một cách hệ thống chính sách áp bức, bóc lột của thực dân ở các thuộc địa — một mạch tư tưởng nhất quán mà Người tiếp tục truyền đạt qua những bài giảng ở Quảng Châu.\n\nTrên tấm bảng đen, hẳn không ít lần hiện lên những cái tên như Hoa Thịnh Đốn, Ba Lê, hay các mốc năm 1776, 1789, 1917 được viết bằng phấn trắng, xóa đi viết lại qua từng buổi giảng. Phương pháp dạy học vừa giảng vừa hỏi, khuyến khích học viên tự rút ra kết luận, được nhiều người từng dự lớp nhắc lại như một cách học sinh động, gần gũi, khác hẳn lối học từ chương thời ấy. Không ít học viên, vốn quen nhìn thực dân Pháp chỉ qua cảnh sưu cao thuế nặng nơi làng quê mình, lần đầu được tiếp cận một cách nhìn mang tầm vóc thế giới như vậy, nối liền số phận Việt Nam với phong trào giải phóng dân tộc đang dâng lên khắp các thuộc địa.\n\nBài học về các cuộc cách mạng trên bảng đen năm xưa, sau khi được in trong Đường Kách mệnh, đã trở thành một trong những văn bản đầu tiên phổ biến tư tưởng Mác – Lênin theo cách gần gũi với người Việt Nam, chuẩn bị nền tảng lý luận cho sự ra đời của Đảng Cộng sản Việt Nam năm 1930. Ngôi nhà số 248 – 250 phố Văn Minh, nơi từng đặt tấm bảng ấy, ngày nay vẫn được gìn giữ như một địa chỉ lưu niệm gắn với những năm tháng hoạt động của Nguyễn Ái Quốc tại Quảng Châu, đón nhiều đoàn khách, trong đó có không ít đoàn Việt Nam, tới tìm hiểu. Nhiều nhà nghiên cứu sau này coi đây là một trong những nỗ lực sớm nhất nhằm Việt hóa lý luận Mác – Lênin, trình bày những vấn đề vốn trừu tượng bằng ngôn ngữ gần gũi với người lao động Việt Nam.","nguon":"Nguyễn Ái Quốc, Đường Kách mệnh (1927); Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia; Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":[{"t":"Bài học về các cuộc cách mạng. Tấm bảng đen dựng trong góc lớp phục dựng là đồ vật minh họa, gợi lại công cụ giảng dạy giản dị nhất của một lớp học không giáo trình in sẵn: một tấm bảng, viên phấn và trí nhớ của người thầy. Tại đây, giữa những buổi học bí mật ban ngày và những đêm canh chừng mật thám, Nguyễn Ái Quốc đã dùng chính tấm bảng ấy để vẽ lại cả một dòng chảy lịch sử thế giới cho những học viên chưa từng ra khỏi lũy tre làng."},{"t":"Trong Đường Kách mệnh, phần dành riêng cho các cuộc cách mạng lớn trên thế giới được trình bày với một cách nhìn rất riêng. Người điểm lại cách mạng Mỹ năm 1776 và cách mạng Pháp năm 1789, gọi đó là “cách mệnh tư bản”, “cách mệnh không đến nơi”: tiếng là cộng hòa, dân chủ, nhưng bên trong vẫn bóc lột công nông, bên ngoài vẫn áp bức thuộc địa. Đối chiếu với đó, cách mạng Nga tháng Mười năm 1917 được nhìn nhận là cuộc cách mạng triệt để nhất, đưa chính quyền thật sự về tay công nông."},{"t":"Cách đặt vấn đề ấy không phải ngẫu nhiên. Năm 1920, tại Pháp, Nguyễn Ái Quốc đọc được Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, và tìm thấy ở đó con đường giải phóng cho các dân tộc bị áp bức như Việt Nam. Từ Paris đến Quảng Châu, hành trình tư tưởng ấy được Người chắt lọc lại thành những bài giảng ngắn gọn, dễ nhớ, đủ sức thuyết phục một lớp học viên vốn chỉ quen với sách thánh hiền hay văn chương yêu nước truyền thống. Trước đó, ngay tại Pháp, Người cũng đã viết Bản án chế độ thực dân Pháp, xuất bản năm 1925, phê phán một cách hệ thống chính sách áp bức, bóc lột của thực dân ở các thuộc địa — một mạch tư tưởng nhất quán mà Người tiếp tục truyền đạt qua những bài giảng ở Quảng Châu."},{"t":"Trên tấm bảng đen, hẳn không ít lần hiện lên những cái tên như Hoa Thịnh Đốn, Ba Lê, hay các mốc năm 1776, 1789, 1917 được viết bằng phấn trắng, xóa đi viết lại qua từng buổi giảng. Phương pháp dạy học vừa giảng vừa hỏi, khuyến khích học viên tự rút ra kết luận, được nhiều người từng dự lớp nhắc lại như một cách học sinh động, gần gũi, khác hẳn lối học từ chương thời ấy. Không ít học viên, vốn quen nhìn thực dân Pháp chỉ qua cảnh sưu cao thuế nặng nơi làng quê mình, lần đầu được tiếp cận một cách nhìn mang tầm vóc thế giới như vậy, nối liền số phận Việt Nam với phong trào giải phóng dân tộc đang dâng lên khắp các thuộc địa."},{"t":"Bài học về các cuộc cách mạng trên bảng đen năm xưa, sau khi được in trong Đường Kách mệnh, đã trở thành một trong những văn bản đầu tiên phổ biến tư tưởng Mác – Lênin theo cách gần gũi với người Việt Nam, chuẩn bị nền tảng lý luận cho sự ra đời của Đảng Cộng sản Việt Nam năm 1930. Ngôi nhà số 248 – 250 phố Văn Minh, nơi từng đặt tấm bảng ấy, ngày nay vẫn được gìn giữ như một địa chỉ lưu niệm gắn với những năm tháng hoạt động của Nguyễn Ái Quốc tại Quảng Châu, đón nhiều đoàn khách, trong đó có không ít đoàn Việt Nam, tới tìm hiểu. Nhiều nhà nghiên cứu sau này coi đây là một trong những nỗ lực sớm nhất nhằm Việt hóa lý luận Mác – Lênin, trình bày những vấn đề vốn trừu tượng bằng ngôn ngữ gần gũi với người lao động Việt Nam."},{"t":"Bạn có biết? Trong Đường Kách mệnh, Nguyễn Ái Quốc gọi cách mạng Mỹ và cách mạng Pháp là “cách mệnh không đến nơi”, còn cách mạng Nga là cách mạng “đến nơi”, vì đã đưa chính quyền và ruộng đất về tay công nông."}],"ban_co_biet":"Trong Đường Kách mệnh, Nguyễn Ái Quốc gọi cách mạng Mỹ và cách mạng Pháp là “cách mệnh không đến nơi”, còn cách mạng Nga là cách mạng “đến nơi”, vì đã đưa chính quyền và ruộng đất về tay công nông."},{"id":"vintage_oil_lamp@-8.8,-16.1","x":-8.85,"y":1,"z":-16.05,"loai":"vintage_oil_lamp","ten":"Ngọn đèn dầu","tieu_de":"Những số báo Thanh Niên","text":"Ngọn đèn dầu đặt trên góc bàn là đồ vật minh họa, gợi lại ánh sáng gần như duy nhất trong những đêm tòa soạn báo Thanh Niên làm việc tại ngôi nhà số 248 – 250 phố Văn Minh. Không có điện thắp sáng ổn định, không có nhà in hiện đại, phần lớn bài vở, khuôn chữ litô được soạn, khắc, in dưới ánh đèn dầu le lói, trong một căn phòng vừa là lớp học ban ngày, vừa là nơi làm báo bí mật ban đêm.\n\nSố báo Thanh Niên đầu tiên ra đời ngày 21 tháng 6 năm 1925, do Nguyễn Ái Quốc sáng lập và trực tiếp chỉ đạo nội dung; nhiều bài viết trên báo do chính Người chấp bút. Báo viết bằng tiếng Việt, câu văn ngắn gọn, giản dị, tránh những từ Hán Việt cầu kỳ, để một người nông dân hay công nhân ít học vẫn đọc hiểu được. Đây cũng là tờ báo cách mạng đầu tiên của người Việt Nam theo khuynh hướng vô sản, ra đời trước khi Đảng Cộng sản Việt Nam được thành lập gần năm năm.\n\nMỗi số báo in xong phải tìm cách đưa trót lọt qua biên giới Việt – Trung, qua đường biển từ Hương Cảng, qua các cơ sở bí mật của Việt kiều ở Xiêm, rồi từ đó lọt vào trong nước, chuyền tay nhau đọc trong những nhóm nhỏ đáng tin cậy. Không ít số báo bị mật thám Pháp tịch thu, người giữ báo có thể bị bắt, nhưng dòng chảy thông tin ấy vẫn không ngừng, năm này qua năm khác, nuôi dưỡng tinh thần yêu nước trong những người chưa từng biết mặt người sáng lập ra tờ báo. Việc in ấn hoàn toàn thủ công: chữ phải sắp từng con, khuôn in phải khắc tay, và toàn bộ công đoạn ấy phải hoàn tất trong đêm để kịp sáng hôm sau ngụy trang, cất giấu trước con mắt dò xét của mật thám và tay sai.\n\nNội dung báo Thanh Niên không chỉ vạch trần chính sách bóc lột, đàn áp của thực dân Pháp ở Đông Dương, mà còn giới thiệu bước đầu những nguyên lý của chủ nghĩa Mác – Lênin, kinh nghiệm các cuộc cách mạng trên thế giới, kêu gọi đoàn kết trong Hội Việt Nam Cách mạng Thanh niên. Cùng với các lớp huấn luyện và cuốn Đường Kách mệnh, tờ báo là một trong những công cụ chính Nguyễn Ái Quốc dùng để gieo mầm tư tưởng cách mạng vào trong nước những năm 1925 – 1927 (xem chuyên đề Nơi những bài giảng thành sách Đường Kách mệnh). Một số học viên trong các lớp huấn luyện cũng được giao phụ giúp việc in ấn, chuyển phát báo — vừa học lý luận ban ngày, vừa học nghề làm báo cách mạng bí mật vào buổi tối, một hình thức rèn luyện gắn liền nhận thức với hành động.\n\nNgày 21 tháng 6 sau này được lấy làm Ngày Báo chí Cách mạng Việt Nam, để ghi nhớ cột mốc ra đời của tờ báo cách mạng đầu tiên ấy. Bản gốc những số báo Thanh Niên còn sót lại rất hiếm, một số bản được lưu giữ, giới thiệu tại các bảo tàng lịch sử và báo chí cách mạng Việt Nam như những chứng tích quý giá của một thời làm báo giữa gông cùm và bí mật. Ngọn đèn dầu nhỏ bé trong gian trưng bày, vì thế, là hình ảnh cô đọng cho biết bao đêm thức trắng của một tòa soạn không tên, không địa chỉ công khai, nhưng đã kịp thắp lên ngọn lửa đầu tiên của báo chí cách mạng Việt Nam.","nguon":"Báo Thanh Niên (1925), theo Bảo tàng Lịch sử Quốc gia và tư liệu báo chí cách mạng Việt Nam; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; baotanghochiminh.vn","doc":[{"t":"Những số báo Thanh Niên. Ngọn đèn dầu đặt trên góc bàn là đồ vật minh họa, gợi lại ánh sáng gần như duy nhất trong những đêm tòa soạn báo Thanh Niên làm việc tại ngôi nhà số 248 – 250 phố Văn Minh. Không có điện thắp sáng ổn định, không có nhà in hiện đại, phần lớn bài vở, khuôn chữ litô được soạn, khắc, in dưới ánh đèn dầu le lói, trong một căn phòng vừa là lớp học ban ngày, vừa là nơi làm báo bí mật ban đêm."},{"t":"Số báo Thanh Niên đầu tiên ra đời ngày 21 tháng 6 năm 1925, do Nguyễn Ái Quốc sáng lập và trực tiếp chỉ đạo nội dung; nhiều bài viết trên báo do chính Người chấp bút. Báo viết bằng tiếng Việt, câu văn ngắn gọn, giản dị, tránh những từ Hán Việt cầu kỳ, để một người nông dân hay công nhân ít học vẫn đọc hiểu được. Đây cũng là tờ báo cách mạng đầu tiên của người Việt Nam theo khuynh hướng vô sản, ra đời trước khi Đảng Cộng sản Việt Nam được thành lập gần năm năm."},{"t":"Mỗi số báo in xong phải tìm cách đưa trót lọt qua biên giới Việt – Trung, qua đường biển từ Hương Cảng, qua các cơ sở bí mật của Việt kiều ở Xiêm, rồi từ đó lọt vào trong nước, chuyền tay nhau đọc trong những nhóm nhỏ đáng tin cậy. Không ít số báo bị mật thám Pháp tịch thu, người giữ báo có thể bị bắt, nhưng dòng chảy thông tin ấy vẫn không ngừng, năm này qua năm khác, nuôi dưỡng tinh thần yêu nước trong những người chưa từng biết mặt người sáng lập ra tờ báo. Việc in ấn hoàn toàn thủ công: chữ phải sắp từng con, khuôn in phải khắc tay, và toàn bộ công đoạn ấy phải hoàn tất trong đêm để kịp sáng hôm sau ngụy trang, cất giấu trước con mắt dò xét của mật thám và tay sai."},{"t":"Nội dung báo Thanh Niên không chỉ vạch trần chính sách bóc lột, đàn áp của thực dân Pháp ở Đông Dương, mà còn giới thiệu bước đầu những nguyên lý của chủ nghĩa Mác – Lênin, kinh nghiệm các cuộc cách mạng trên thế giới, kêu gọi đoàn kết trong Hội Việt Nam Cách mạng Thanh niên. Cùng với các lớp huấn luyện và cuốn Đường Kách mệnh, tờ báo là một trong những công cụ chính Nguyễn Ái Quốc dùng để gieo mầm tư tưởng cách mạng vào trong nước những năm 1925 – 1927 (xem chuyên đề Nơi những bài giảng thành sách Đường Kách mệnh). Một số học viên trong các lớp huấn luyện cũng được giao phụ giúp việc in ấn, chuyển phát báo — vừa học lý luận ban ngày, vừa học nghề làm báo cách mạng bí mật vào buổi tối, một hình thức rèn luyện gắn liền nhận thức với hành động."},{"t":"Ngày 21 tháng 6 sau này được lấy làm Ngày Báo chí Cách mạng Việt Nam, để ghi nhớ cột mốc ra đời của tờ báo cách mạng đầu tiên ấy. Bản gốc những số báo Thanh Niên còn sót lại rất hiếm, một số bản được lưu giữ, giới thiệu tại các bảo tàng lịch sử và báo chí cách mạng Việt Nam như những chứng tích quý giá của một thời làm báo giữa gông cùm và bí mật. Ngọn đèn dầu nhỏ bé trong gian trưng bày, vì thế, là hình ảnh cô đọng cho biết bao đêm thức trắng của một tòa soạn không tên, không địa chỉ công khai, nhưng đã kịp thắp lên ngọn lửa đầu tiên của báo chí cách mạng Việt Nam."},{"t":"Bạn có biết? Ngày 21 tháng 6 năm 1925 — ngày ra số đầu tiên của báo Thanh Niên — sau này được chọn làm Ngày Báo chí Cách mạng Việt Nam."}],"ban_co_biet":"Ngày 21 tháng 6 năm 1925 — ngày ra số đầu tiên của báo Thanh Niên — sau này được chọn làm Ngày Báo chí Cách mạng Việt Nam."},{"id":"table@-11.4,-10.6","x":-11.4,"y":0.2,"z":-10.6,"loai":"table","ten":"Bàn học viên","tieu_de":"Những người học trò đầu tiên","text":"Những dãy bàn ghế đơn sơ trong gian phục dựng gợi lại lớp huấn luyện trên phố Văn Minh, nơi khoảng 75 học viên qua ba khóa đã ngồi học trong hai năm 1925 – 1927. Đây đều là những thanh niên yêu nước từ trong nước — phần lớn từ Bắc Kỳ và Trung Kỳ, có cả một số từ Nam Kỳ — bí mật tìm đường vượt biên giới sang Quảng Châu, dưới danh nghĩa đi buôn, đi học nghề hay tị nạn.\n\nMỗi khóa học kéo dài chỉ vài tuần đến vài tháng, tổ chức kín đáo để tránh sự theo dõi của cả mật thám Pháp lẫn chính quyền sở tại. Học viên ăn ở tập trung ngay trong hoặc gần ngôi nhà số 248 – 250, sinh hoạt giản dị, học chữ Quốc ngữ nếu chưa thạo, học lý luận cách mạng, học cả cách hoạt động bí mật, giữ liên lạc, viết báo cáo, tổ chức quần chúng — những kỹ năng cần thiết cho công tác gây dựng cơ sở khi trở về nước. Để giữ bí mật, nhiều học viên phải đổi tên, mang theo giấy tờ giả, tự nhận là người đi làm công hay học nghề tại Quảng Châu; cộng đồng người Việt yêu nước đang sinh sống tại thành phố này cũng âm thầm giúp đỡ chỗ ở, che giấu tung tích cho những gương mặt mới sang.\n\nSau khi hoàn thành khóa học, học viên chia thành nhiều ngả. Có người trở về nước ngay, len lỏi qua các cửa khẩu biên giới hoặc theo đường biển, để gây dựng cơ sở của Hội Việt Nam Cách mạng Thanh niên ở cả ba kỳ. Có người được giữ lại Quảng Châu hoặc gửi sang Trường Quân sự Hoàng Phố gần đó để học quân sự (xem chuyên đề Trường Quân sự Hoàng Phố). Một số ít, sau này được chọn cử tiếp sang Liên Xô học tại Trường Đại học Phương Đông ở Mátxcơva, trong đó có những người sau trở thành cán bộ lãnh đạo cấp cao của Đảng.\n\nKhông phải ai trong số học viên cũng còn giữ được tên thật trong hồ sơ mật thám hay trong ký ức người đời sau; nhiều người sinh hoạt dưới bí danh, và không ít người đã hy sinh trước khi cách mạng thành công, tên tuổi chỉ còn được nhắc trong vài dòng biên niên sử. Có người trong số họ về sau trở thành liệt sĩ khi tuổi đời còn rất trẻ, chỉ được nhắc tới trong vài dòng ngắn ngủi của các bộ sử Đảng. Nhưng chính từ những dãy bàn ghế đơn sơ ấy, hạt giống của một mạng lưới cách mạng bí mật đã được gieo khắp trong nước, để chỉ vài năm sau, khi ba tổ chức cộng sản ra đời rồi hợp nhất thành Đảng Cộng sản Việt Nam đầu năm 1930, phần lớn cán bộ chủ chốt đều mang trong mình dấu ấn của lớp học Quảng Châu.\n\nNgôi nhà số 248 – 250 phố Văn Minh, nơi từng vang lên tiếng giảng bài và bước chân rón rén của học viên mỗi khi có động, ngày nay được giữ gìn như một địa chỉ lưu niệm về những năm tháng hoạt động của Nguyễn Ái Quốc tại Quảng Châu. Những dãy bàn trong không gian phục dựng của bảo tàng là hình ảnh minh họa, không phải hiện vật gốc, nhưng đủ để gợi lại không khí một lớp học đặc biệt — nơi không có bảng điểm, không có lễ tốt nghiệp, chỉ có lời thề âm thầm sẽ trở về phụng sự đất nước.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia; baotanghochiminh.vn","doc":[{"t":"Những người học trò đầu tiên. Những dãy bàn ghế đơn sơ trong gian phục dựng gợi lại lớp huấn luyện trên phố Văn Minh, nơi khoảng 75 học viên qua ba khóa đã ngồi học trong hai năm 1925 – 1927. Đây đều là những thanh niên yêu nước từ trong nước — phần lớn từ Bắc Kỳ và Trung Kỳ, có cả một số từ Nam Kỳ — bí mật tìm đường vượt biên giới sang Quảng Châu, dưới danh nghĩa đi buôn, đi học nghề hay tị nạn."},{"t":"Mỗi khóa học kéo dài chỉ vài tuần đến vài tháng, tổ chức kín đáo để tránh sự theo dõi của cả mật thám Pháp lẫn chính quyền sở tại. Học viên ăn ở tập trung ngay trong hoặc gần ngôi nhà số 248 – 250, sinh hoạt giản dị, học chữ Quốc ngữ nếu chưa thạo, học lý luận cách mạng, học cả cách hoạt động bí mật, giữ liên lạc, viết báo cáo, tổ chức quần chúng — những kỹ năng cần thiết cho công tác gây dựng cơ sở khi trở về nước. Để giữ bí mật, nhiều học viên phải đổi tên, mang theo giấy tờ giả, tự nhận là người đi làm công hay học nghề tại Quảng Châu; cộng đồng người Việt yêu nước đang sinh sống tại thành phố này cũng âm thầm giúp đỡ chỗ ở, che giấu tung tích cho những gương mặt mới sang."},{"t":"Sau khi hoàn thành khóa học, học viên chia thành nhiều ngả. Có người trở về nước ngay, len lỏi qua các cửa khẩu biên giới hoặc theo đường biển, để gây dựng cơ sở của Hội Việt Nam Cách mạng Thanh niên ở cả ba kỳ. Có người được giữ lại Quảng Châu hoặc gửi sang Trường Quân sự Hoàng Phố gần đó để học quân sự (xem chuyên đề Trường Quân sự Hoàng Phố). Một số ít, sau này được chọn cử tiếp sang Liên Xô học tại Trường Đại học Phương Đông ở Mátxcơva, trong đó có những người sau trở thành cán bộ lãnh đạo cấp cao của Đảng."},{"t":"Không phải ai trong số học viên cũng còn giữ được tên thật trong hồ sơ mật thám hay trong ký ức người đời sau; nhiều người sinh hoạt dưới bí danh, và không ít người đã hy sinh trước khi cách mạng thành công, tên tuổi chỉ còn được nhắc trong vài dòng biên niên sử. Có người trong số họ về sau trở thành liệt sĩ khi tuổi đời còn rất trẻ, chỉ được nhắc tới trong vài dòng ngắn ngủi của các bộ sử Đảng. Nhưng chính từ những dãy bàn ghế đơn sơ ấy, hạt giống của một mạng lưới cách mạng bí mật đã được gieo khắp trong nước, để chỉ vài năm sau, khi ba tổ chức cộng sản ra đời rồi hợp nhất thành Đảng Cộng sản Việt Nam đầu năm 1930, phần lớn cán bộ chủ chốt đều mang trong mình dấu ấn của lớp học Quảng Châu."},{"t":"Ngôi nhà số 248 – 250 phố Văn Minh, nơi từng vang lên tiếng giảng bài và bước chân rón rén của học viên mỗi khi có động, ngày nay được giữ gìn như một địa chỉ lưu niệm về những năm tháng hoạt động của Nguyễn Ái Quốc tại Quảng Châu. Những dãy bàn trong không gian phục dựng của bảo tàng là hình ảnh minh họa, không phải hiện vật gốc, nhưng đủ để gợi lại không khí một lớp học đặc biệt — nơi không có bảng điểm, không có lễ tốt nghiệp, chỉ có lời thề âm thầm sẽ trở về phụng sự đất nước."},{"t":"Bạn có biết? Theo Lịch sử Đảng Cộng sản Việt Nam, phần lớn cán bộ chủ chốt của các tổ chức cộng sản ra đời năm 1929 đều từng qua các lớp huấn luyện của Nguyễn Ái Quốc ở Quảng Châu."}],"ban_co_biet":"Theo Lịch sử Đảng Cộng sản Việt Nam, phần lớn cán bộ chủ chốt của các tổ chức cộng sản ra đời năm 1929 đều từng qua các lớp huấn luyện của Nguyễn Ái Quốc ở Quảng Châu."},{"id":"table@-7.6,-10.6","x":-7.6,"y":0.2,"z":-10.6,"loai":"table","ten":"Bàn học viên","tieu_de":"Trần Phú – từ lớp học Quảng Châu đến Tổng Bí thư","text":"Trong số những dãy bàn học viên phục dựng ở gian trưng bày, có một chiếc gắn với câu chuyện của một trong những người học trò nổi bật nhất của lớp huấn luyện Quảng Châu: Trần Phú. Sinh năm 1904, từng tham gia hoạt động yêu nước trong nước trước khi tìm đường sang Trung Quốc, Trần Phú đến Quảng Châu năm 1926 và dự lớp huấn luyện do Nguyễn Ái Quốc trực tiếp giảng dạy. Trước đó, ông từng tham gia hoạt động trong một nhóm thanh niên yêu nước ở Trung Kỳ, cùng chung khát vọng tìm một hướng đi mới cho phong trào cứu nước sau khi nhận thấy những cách làm cũ chưa mang lại kết quả.\n\nCũng như nhiều học viên khác, Trần Phú học ở đây những bài học vỡ lòng về lý luận cách mạng, về tổ chức, về cách nhìn nhận các phong trào giải phóng dân tộc trên thế giới. Nhận thấy khả năng của người học trò trẻ tuổi, tổ chức đã cử Trần Phú sang học tiếp tại Trường Đại học Phương Đông ở Mátxcơva — nơi Quốc tế Cộng sản đào tạo cán bộ cho các nước thuộc địa và phụ thuộc.\n\nTrở về nước năm 1930, ngay sau khi Đảng Cộng sản Việt Nam vừa được thành lập, Trần Phú được giao soạn thảo Luận cương chính trị của Đảng, thông qua tại Hội nghị Ban Chấp hành Trung ương tháng 10 năm 1930. Cũng tại hội nghị này, Trần Phú được bầu làm Tổng Bí thư đầu tiên của Đảng, khi mới ngoài hai mươi tuổi — một trong những nhà lãnh đạo trẻ tuổi nhất trong lịch sử Đảng Cộng sản Việt Nam. Luận cương xác định cách mạng Việt Nam phải trải qua cách mạng tư sản dân quyền rồi tiến thẳng lên cách mạng xã hội chủ nghĩa, đặt vấn đề ruộng đất là vấn đề cốt lõi, đồng thời khẳng định vai trò lãnh đạo của giai cấp công nhân thông qua chính đảng của mình — văn kiện lý luận quan trọng thứ hai của Đảng, sau Cương lĩnh chính trị đầu tiên do Nguyễn Ái Quốc soạn thảo đầu năm 1930.\n\nChưa đầy một năm sau, tháng 4 năm 1931, Trần Phú bị mật thám Pháp bắt tại Sài Gòn. Trong nhà tù, theo các tài liệu lịch sử Đảng, dù bị tra tấn hiểm nghèo, Trần Phú vẫn giữ vững khí tiết người cộng sản cho đến khi hy sinh ngày 6 tháng 9 năm 1931 tại Nhà thương Chợ Quán, Sài Gòn, khi mới 27 tuổi. Lời nhắn gửi đồng chí trước lúc hy sinh — giữ vững ý chí chiến đấu — được các thế hệ sau nhắc lại như một biểu tượng của lòng trung kiên cách mạng. Sự hy sinh khi tuổi đời còn rất trẻ khiến cương vị Tổng Bí thư đầu tiên gắn liền với hình ảnh một người cộng sản kiên trung, dâng hiến trọn vẹn tuổi thanh xuân cho sự nghiệp cách mạng.\n\nTừ chiếc bàn học viên đơn sơ trên phố Văn Minh đến cương vị Tổng Bí thư đầu tiên của Đảng, chỉ vỏn vẹn bốn năm — một hành trình ngắn ngủi nhưng để lại dấu ấn sâu đậm trong lịch sử cách mạng Việt Nam. Câu chuyện của Trần Phú, cùng với nhiều học viên khác từng ngồi trên những chiếc bàn tương tự, cho thấy lớp huấn luyện Quảng Châu không chỉ truyền đạt lý luận, mà thực sự đã ươm mầm cho cả một thế hệ lãnh đạo cách mạng Việt Nam sau này.","nguon":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Trần Phú – từ lớp học Quảng Châu đến Tổng Bí thư. Trong số những dãy bàn học viên phục dựng ở gian trưng bày, có một chiếc gắn với câu chuyện của một trong những người học trò nổi bật nhất của lớp huấn luyện Quảng Châu: Trần Phú. Sinh năm 1904, từng tham gia hoạt động yêu nước trong nước trước khi tìm đường sang Trung Quốc, Trần Phú đến Quảng Châu năm 1926 và dự lớp huấn luyện do Nguyễn Ái Quốc trực tiếp giảng dạy. Trước đó, ông từng tham gia hoạt động trong một nhóm thanh niên yêu nước ở Trung Kỳ, cùng chung khát vọng tìm một hướng đi mới cho phong trào cứu nước sau khi nhận thấy những cách làm cũ chưa mang lại kết quả."},{"t":"Cũng như nhiều học viên khác, Trần Phú học ở đây những bài học vỡ lòng về lý luận cách mạng, về tổ chức, về cách nhìn nhận các phong trào giải phóng dân tộc trên thế giới. Nhận thấy khả năng của người học trò trẻ tuổi, tổ chức đã cử Trần Phú sang học tiếp tại Trường Đại học Phương Đông ở Mátxcơva — nơi Quốc tế Cộng sản đào tạo cán bộ cho các nước thuộc địa và phụ thuộc."},{"t":"Trở về nước năm 1930, ngay sau khi Đảng Cộng sản Việt Nam vừa được thành lập, Trần Phú được giao soạn thảo Luận cương chính trị của Đảng, thông qua tại Hội nghị Ban Chấp hành Trung ương tháng 10 năm 1930. Cũng tại hội nghị này, Trần Phú được bầu làm Tổng Bí thư đầu tiên của Đảng, khi mới ngoài hai mươi tuổi — một trong những nhà lãnh đạo trẻ tuổi nhất trong lịch sử Đảng Cộng sản Việt Nam. Luận cương xác định cách mạng Việt Nam phải trải qua cách mạng tư sản dân quyền rồi tiến thẳng lên cách mạng xã hội chủ nghĩa, đặt vấn đề ruộng đất là vấn đề cốt lõi, đồng thời khẳng định vai trò lãnh đạo của giai cấp công nhân thông qua chính đảng của mình — văn kiện lý luận quan trọng thứ hai của Đảng, sau Cương lĩnh chính trị đầu tiên do Nguyễn Ái Quốc soạn thảo đầu năm 1930."},{"t":"Chưa đầy một năm sau, tháng 4 năm 1931, Trần Phú bị mật thám Pháp bắt tại Sài Gòn. Trong nhà tù, theo các tài liệu lịch sử Đảng, dù bị tra tấn hiểm nghèo, Trần Phú vẫn giữ vững khí tiết người cộng sản cho đến khi hy sinh ngày 6 tháng 9 năm 1931 tại Nhà thương Chợ Quán, Sài Gòn, khi mới 27 tuổi. Lời nhắn gửi đồng chí trước lúc hy sinh — giữ vững ý chí chiến đấu — được các thế hệ sau nhắc lại như một biểu tượng của lòng trung kiên cách mạng. Sự hy sinh khi tuổi đời còn rất trẻ khiến cương vị Tổng Bí thư đầu tiên gắn liền với hình ảnh một người cộng sản kiên trung, dâng hiến trọn vẹn tuổi thanh xuân cho sự nghiệp cách mạng."},{"t":"Từ chiếc bàn học viên đơn sơ trên phố Văn Minh đến cương vị Tổng Bí thư đầu tiên của Đảng, chỉ vỏn vẹn bốn năm — một hành trình ngắn ngủi nhưng để lại dấu ấn sâu đậm trong lịch sử cách mạng Việt Nam. Câu chuyện của Trần Phú, cùng với nhiều học viên khác từng ngồi trên những chiếc bàn tương tự, cho thấy lớp huấn luyện Quảng Châu không chỉ truyền đạt lý luận, mà thực sự đã ươm mầm cho cả một thế hệ lãnh đạo cách mạng Việt Nam sau này."},{"t":"Bạn có biết? Trần Phú là một trong những học viên trẻ được Nguyễn Ái Quốc trực tiếp dìu dắt ở Quảng Châu, sau trở thành Tổng Bí thư đầu tiên của Đảng khi mới ngoài hai mươi tuổi."}],"ban_co_biet":"Trần Phú là một trong những học viên trẻ được Nguyễn Ái Quốc trực tiếp dìu dắt ở Quảng Châu, sau trở thành Tổng Bí thư đầu tiên của Đảng khi mới ngoài hai mươi tuổi."},{"id":"table@-11.4,-11.9","x":-11.4,"y":0.2,"z":-11.95,"loai":"table","ten":"Bàn học viên","tieu_de":"Phong trào “vô sản hóa”","text":"Chiếc bàn học viên này gợi nhắc một chặng tiếp theo trong hành trình của những người từng học ở Quảng Châu: phong trào “vô sản hóa”. Không phải mọi học viên tốt nghiệp lớp huấn luyện đều tiếp tục con đường học vấn hay quân sự; nhiều người trở về nước mang theo một nhiệm vụ khác — hòa mình vào đời sống công nhân để rèn luyện và gây dựng phong trào từ gốc rễ.\n\nNăm 1928, Hội Việt Nam Cách mạng Thanh niên phát động chủ trương “vô sản hóa”: hội viên, phần đông xuất thân trí thức, học sinh, chủ động xin vào làm việc trong các hầm mỏ, đồn điền cao su, nhà máy dệt, nhà máy xi măng. Họ cùng ăn, cùng ở, cùng làm những công việc nặng nhọc như bất kỳ người thợ nào khác, để từ đó hiểu đời sống công nhân, đồng thời từng bước tuyên truyền, giác ngộ, tổ chức họ. Không ít người trong số họ phải học lại từ đầu những kỹ năng lao động chân tay hoàn toàn xa lạ với xuất thân trí thức của mình, chấp nhận đồng lương rẻ mạt và điều kiện sống thiếu thốn để có thể ở lại lâu dài, gây dựng lòng tin trong anh em công nhân.\n\nĐây là một cách làm cách mạng khác hẳn với những buổi giảng bài lý luận trên phố Văn Minh: không có bàn ghế, không có bảng đen, chỉ có mồ hôi, tiếng máy và những buổi nói chuyện chớp nhoáng giữa ca làm việc. Chính từ phong trào này, nhiều cơ sở cách mạng đầu tiên trong công nhân đã hình thành ở các trung tâm công nghiệp như Hải Phòng, Nam Định, vùng mỏ, đồn điền cao su Nam Kỳ.\n\nTừ những cơ sở công nhân được gây dựng qua phong trào “vô sản hóa”, cùng với ảnh hưởng ngày càng lan rộng của tư tưởng do lớp huấn luyện Quảng Châu gieo mầm, chỉ trong năm 1929, liên tiếp ba tổ chức cộng sản ra đời trong nước: Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn. Sự xuất hiện gần như đồng thời của ba tổ chức cho thấy phong trào cách mạng trong nước đã chín muồi, đòi hỏi một chính đảng thống nhất. Trong số những địa bàn được phong trào nhắm tới, có vùng mỏ than Hồng Gai – Cẩm Phả, các đồn điền cao su ở Nam Kỳ, cùng những nhà máy dệt, nhà máy xi măng ở Nam Định, Hải Phòng — nơi tập trung đông công nhân, điều kiện làm việc khắc nghiệt, dễ nảy sinh tinh thần đấu tranh khi được giác ngộ đúng cách.\n\nĐầu năm 1930, tại Cửu Long, Hương Cảng, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất ba tổ chức thành Đảng Cộng sản Việt Nam. Nhìn lại, có thể thấy một đường thẳng nối từ chiếc bàn học viên trên phố Văn Minh, qua những năm tháng “vô sản hóa” trong hầm mỏ, nhà máy, đến hội nghị thành lập Đảng — một hành trình cho thấy lý luận cách mạng chỉ thực sự có sức sống khi được những người mang nó đi vào tận cùng đời sống của quần chúng lao động. Bài học rút ra từ phong trào ấy — rằng lý luận cách mạng phải bắt rễ từ chính đời sống của người lao động — vẫn thường được các nhà nghiên cứu lịch sử Đảng nhắc tới khi nhìn lại chặng đường vận động quần chúng trước năm 1930.","nguon":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Phong trào “vô sản hóa”. Chiếc bàn học viên này gợi nhắc một chặng tiếp theo trong hành trình của những người từng học ở Quảng Châu: phong trào “vô sản hóa”. Không phải mọi học viên tốt nghiệp lớp huấn luyện đều tiếp tục con đường học vấn hay quân sự; nhiều người trở về nước mang theo một nhiệm vụ khác — hòa mình vào đời sống công nhân để rèn luyện và gây dựng phong trào từ gốc rễ."},{"t":"Năm 1928, Hội Việt Nam Cách mạng Thanh niên phát động chủ trương “vô sản hóa”: hội viên, phần đông xuất thân trí thức, học sinh, chủ động xin vào làm việc trong các hầm mỏ, đồn điền cao su, nhà máy dệt, nhà máy xi măng. Họ cùng ăn, cùng ở, cùng làm những công việc nặng nhọc như bất kỳ người thợ nào khác, để từ đó hiểu đời sống công nhân, đồng thời từng bước tuyên truyền, giác ngộ, tổ chức họ. Không ít người trong số họ phải học lại từ đầu những kỹ năng lao động chân tay hoàn toàn xa lạ với xuất thân trí thức của mình, chấp nhận đồng lương rẻ mạt và điều kiện sống thiếu thốn để có thể ở lại lâu dài, gây dựng lòng tin trong anh em công nhân."},{"t":"Đây là một cách làm cách mạng khác hẳn với những buổi giảng bài lý luận trên phố Văn Minh: không có bàn ghế, không có bảng đen, chỉ có mồ hôi, tiếng máy và những buổi nói chuyện chớp nhoáng giữa ca làm việc. Chính từ phong trào này, nhiều cơ sở cách mạng đầu tiên trong công nhân đã hình thành ở các trung tâm công nghiệp như Hải Phòng, Nam Định, vùng mỏ, đồn điền cao su Nam Kỳ."},{"t":"Từ những cơ sở công nhân được gây dựng qua phong trào “vô sản hóa”, cùng với ảnh hưởng ngày càng lan rộng của tư tưởng do lớp huấn luyện Quảng Châu gieo mầm, chỉ trong năm 1929, liên tiếp ba tổ chức cộng sản ra đời trong nước: Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn. Sự xuất hiện gần như đồng thời của ba tổ chức cho thấy phong trào cách mạng trong nước đã chín muồi, đòi hỏi một chính đảng thống nhất. Trong số những địa bàn được phong trào nhắm tới, có vùng mỏ than Hồng Gai – Cẩm Phả, các đồn điền cao su ở Nam Kỳ, cùng những nhà máy dệt, nhà máy xi măng ở Nam Định, Hải Phòng — nơi tập trung đông công nhân, điều kiện làm việc khắc nghiệt, dễ nảy sinh tinh thần đấu tranh khi được giác ngộ đúng cách."},{"t":"Đầu năm 1930, tại Cửu Long, Hương Cảng, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất ba tổ chức thành Đảng Cộng sản Việt Nam. Nhìn lại, có thể thấy một đường thẳng nối từ chiếc bàn học viên trên phố Văn Minh, qua những năm tháng “vô sản hóa” trong hầm mỏ, nhà máy, đến hội nghị thành lập Đảng — một hành trình cho thấy lý luận cách mạng chỉ thực sự có sức sống khi được những người mang nó đi vào tận cùng đời sống của quần chúng lao động. Bài học rút ra từ phong trào ấy — rằng lý luận cách mạng phải bắt rễ từ chính đời sống của người lao động — vẫn thường được các nhà nghiên cứu lịch sử Đảng nhắc tới khi nhìn lại chặng đường vận động quần chúng trước năm 1930."},{"t":"Bạn có biết? Phong trào “vô sản hóa” do Hội Việt Nam Cách mạng Thanh niên phát động từ năm 1928 được xem là một trong những bước chuẩn bị trực tiếp cho sự ra đời của các tổ chức cộng sản năm 1929."}],"ban_co_biet":"Phong trào “vô sản hóa” do Hội Việt Nam Cách mạng Thanh niên phát động từ năm 1928 được xem là một trong những bước chuẩn bị trực tiếp cho sự ra đời của các tổ chức cộng sản năm 1929."}]};
